{"id":"pastafrola","type":"snack","country":"AR","group":"grain","tags":["tart"],"name":{"en":"Quince Pastafrola","es":"Pastafrola de membrillo"},"ing":{"en":["2 cups flour","100 g butter","⅓ cup sugar","1 egg","1 tsp baking powder","400 g quince paste"],"es":["2 tazas harina","100 g manteca","⅓ taza azúcar","1 huevo","1 cdita polvo para hornear","400 g dulce de membrillo"]},"steps":{"en":["Rub butter, sugar and flour together, add the egg and baking powder; chill 20 min.","Line a tart tin, spread with the quince paste softened with a splash of water.","Make a lattice with the leftover dough; bake at 180°C for 35 min."],"es":["Uní la manteca, el azúcar y la harina, sumá el huevo y el polvo de hornear; enfriá 20 min.","Forrá una tartera y cubrí con el membrillo ablandado con un chorrito de agua.","Hacé un enrejado con la masa que sobra; horneá a 180°C 35 min."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"yogur-con-frutillas","type":"snack","country":"AR","group":"dairy","tags":["yogurt"],"name":{"en":"Yogurt with Strawberries","es":"Yogur con frutillas"},"ing":{"en":["3 cups plain yogurt","2 cups strawberries","2 tbsp oats"],"es":["3 tazas yogur natural","2 tazas frutillas","2 cdas avena"]},"steps":{"en":["Slice the strawberries.","Layer with the yogurt in glasses.","Sprinkle with oats."],"es":["Cortá las frutillas.","Armá capas con el yogur en vasos.","Espolvoreá con avena."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"galletitas-de-avena-y-banana","type":"snack","country":"AR","group":"grain","tags":["cookies"],"name":{"en":"Two-Ingredient Oat & Banana Cookies","es":"Galletitas de avena y banana"},"ing":{"en":["2 ripe bananas","1½ cups rolled oats","2 tbsp raisins (optional)","½ tsp cinnamon"],"es":["2 bananas maduras","1½ tazas avena arrollada","2 cdas pasas de uva (opcional)","½ cdita canela"]},"steps":{"en":["Mash the bananas and stir in the oats and cinnamon.","Shape small mounds on a lined tray.","Bake at 180°C for 15 min."],"es":["Pisá las bananas y mezclá con la avena y la canela.","Formá montoncitos sobre una placa con papel.","Horneá a 180°C 15 min."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"frutillas-con-crema","type":"snack","country":"AR","group":"fruit","name":{"en":"Strawberries & Cream","es":"Frutillas con crema"},"ing":{"en":["3 cups strawberries","½ cup cream","1 tsp sugar (optional)"],"es":["3 tazas frutillas","½ taza crema de leche","1 cdita azúcar (opcional)"]},"steps":{"en":["Halve the strawberries.","Whip the cream to soft peaks.","Spoon over the strawberries."],"es":["Cortá las frutillas al medio.","Batí la crema a medio punto.","Serví la crema sobre las frutillas."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"palitos-de-zanahoria-con-dip","type":"snack","country":"AR","group":"veg","name":{"en":"Carrot & Celery Sticks with Cheese Dip","es":"Palitos de zanahoria y apio con dip de queso"},"ing":{"en":["3 carrots","2 celery stalks","½ cup cream cheese","2 tbsp plain yogurt","1 tbsp fresh chives, chopped"],"es":["3 zanahorias","2 tallos de apio","½ taza queso crema","2 cdas yogur natural","1 cda ciboulette picada"]},"steps":{"en":["Cut the carrots and celery into sticks.","Mix the cream cheese, yogurt and chives.","Serve for dipping."],"es":["Cortá la zanahoria y el apio en bastones.","Mezclá el queso crema con el yogur y la ciboulette.","Serví para mojar."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"choclo-con-manteca","type":"snack","country":"AR","group":"veg","name":{"en":"Buttered Corn on the Cob","es":"Choclo con manteca"},"ing":{"en":["4 corn cobs","1 tbsp butter","1 lime"],"es":["4 choclos","1 cda manteca","1 lima"]},"steps":{"en":["Boil the corn for 8 min.","Brush with butter and a squeeze of lime.","Cut into rounds for small hands."],"es":["Herví los choclos 8 min.","Pincelá con manteca y un chorrito de lima.","Cortá en rodajas para manos chicas."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"budin-de-limon","type":"snack","country":"AR","group":"grain","tags":["cake"],"name":{"en":"Lemon Loaf","es":"Budín de limón"},"ing":{"en":["2 eggs","½ cup sugar","½ cup plain yogurt","⅓ cup sunflower oil","1½ cups flour","2 tsp baking powder","2 lemons (zest and juice)"],"es":["2 huevos","½ taza azúcar","½ taza yogur natural","⅓ taza aceite de girasol","1½ tazas harina","2 cditas polvo para hornear","2 limones (ralladura y jugo)"]},"steps":{"en":["Whisk eggs, sugar, yogurt, oil, zest and juice.","Fold in the flour and baking powder.","Bake in a loaf tin at 180°C for 40 min."],"es":["Batí los huevos, el azúcar, el yogur, el aceite, la ralladura y el jugo.","Incorporá la harina y el polvo de hornear.","Horneá en molde de budín a 180°C 40 min."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"sandwiches-de-miga","type":"snack","country":"AR","group":"grain","name":{"en":"Crustless Ham & Cheese Sandwiches","es":"Sándwiches de miga de jamón y queso"},"ing":{"en":["8 slices crustless sandwich bread","100 g cooked ham","100 g mild cheese, sliced","2 tbsp mayonnaise","1 tomato, thinly sliced"],"es":["8 rebanadas de pan de miga","100 g jamón cocido","100 g queso de máquina en fetas","2 cdas mayonesa","1 tomate en rodajas finas"]},"steps":{"en":["Spread the bread thinly with mayonnaise.","Fill with ham, cheese and tomato.","Cut into triangles."],"es":["Untá el pan con una capa fina de mayonesa.","Rellená con jamón, queso y tomate.","Cortá en triángulos."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"ensalada-de-durazno-y-banana","type":"snack","country":"AR","group":"fruit","name":{"en":"Peach, Banana & Orange Salad","es":"Ensalada de durazno, banana y naranja"},"ing":{"en":["2 peaches","2 bananas","2 oranges","1 tbsp fresh mint (optional)"],"es":["2 duraznos","2 bananas","2 naranjas","1 cda menta fresca (opcional)"]},"steps":{"en":["Peel and dice the fruit.","Squeeze one orange over to keep it fresh.","Serve chilled."],"es":["Pelá y cortá la fruta en cubos.","Exprimí una naranja por encima para que no se oscurezca.","Serví bien fría."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"tomates-cherry-con-mozzarella","type":"snack","country":"AR","group":"veg","tags":["skewers"],"name":{"en":"Cherry Tomatoes with Mozzarella & Oregano","es":"Tomates cherry con mozzarella y orégano"},"ing":{"en":["2 cups cherry tomatoes","150 g mozzarella pearls","1 tsp dried oregano","1 tbsp olive oil"],"es":["2 tazas tomates cherry","150 g bocconcini de mozzarella","1 cdita orégano","1 cda aceite de oliva"]},"steps":{"en":["Halve the tomatoes (quarter them for little ones).","Toss with the mozzarella, oil and oregano.","Serve in small bowls."],"es":["Cortá los tomates al medio (en cuartos para los más chicos).","Mezclá con la mozzarella, el aceite y el orégano.","Serví en compoteras."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"milanesas-de-merluza-con-pure","type":"lunch","country":"AR","protein":"fish","base":"potato","tags":["breaded-fish"],"name":{"en":"Breaded Hake with Mashed Potatoes","es":"Milanesas de merluza con puré"},"ing":{"en":["600 g hake fillets","2 eggs","1½ cups breadcrumbs","1 kg potatoes","½ cup milk","1 tbsp butter","1 lemon"],"es":["600 g filet de merluza","2 huevos","1½ tazas pan rallado","1 kg papas","½ taza leche","1 cda manteca","1 limón"]},"steps":{"en":["Dip the hake in beaten egg, then breadcrumbs; bake on an oiled tray at 210°C for 15 min, turning once.","Boil the potatoes until tender and mash with the milk and butter.","Serve with lemon wedges."],"es":["Pasá la merluza por huevo batido y pan rallado; horneá en placa aceitada a 210°C 15 min, dando vuelta una vez.","Herví las papas hasta que estén tiernas y pisalas con la leche y la manteca.","Serví con gajos de limón."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"tarta-de-atun","type":"lunch","country":"AR","protein":"fish","base":"bread","tags":["tart"],"name":{"en":"Tuna Tart","es":"Tarta de atún"},"ing":{"en":["2 pie crusts","2 cans tuna, drained","1 onion, chopped","1 red bell pepper, chopped","3 eggs","½ cup tomato sauce","1 tbsp olive oil"],"es":["2 tapas de tarta","2 latas atún escurrido","1 cebolla picada","1 morrón rojo picado","3 huevos","½ taza salsa de tomate","1 cda aceite de oliva"]},"steps":{"en":["Soften the onion and pepper in the oil for 8 min.","Mix with the tuna, tomato sauce and 2 eggs.","Fill a lined tart tin, cover with the second crust, brush with the last egg and bake at 200°C for 35 min."],"es":["Rehogá la cebolla y el morrón en el aceite 8 min.","Mezclá con el atún, la salsa y 2 huevos.","Rellená la tartera forrada, tapá con la otra masa, pincelá con el huevo restante y horneá a 200°C 35 min."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"empanadas-de-carne","type":"lunch","country":"AR","protein":"beef","base":"bread","tags":["empanadas"],"name":{"en":"Beef Empanadas","es":"Empanadas de carne"},"ing":{"en":["12 empanada discs","500 g ground beef","2 onions, chopped","2 spring onions, sliced","2 eggs, boiled and chopped","1 tsp ground cumin","1 tsp paprika","1 tbsp sunflower oil"],"es":["12 tapas de empanadas","500 g carne picada","2 cebollas picadas","2 cebollas de verdeo en rodajas","2 huevos duros picados","1 cdita comino","1 cdita pimentón","1 cda aceite de girasol"]},"steps":{"en":["Soften the onions in the oil, add the beef and spices and cook until browned; cool.","Stir in the spring onion and egg; fill the discs and seal with a repulgue or a fork.","Bake at 220°C for 15 min until golden."],"es":["Rehogá las cebollas en el aceite, sumá la carne y las especias y cociná hasta que se dore; enfriá.","Agregá el verdeo y el huevo; rellená las tapas y cerrá con repulgue o tenedor.","Horneá a 220°C 15 min, hasta que estén doradas."]},"tip":{"en":"","es":""},"prep":["brown-beef"]},
{"id":"humita-en-olla","type":"lunch","country":"AR","protein":"plant","base":"none","tags":["stew"],"name":{"en":"Humita: Creamy Corn Stew","es":"Humita en olla"},"ing":{"en":["6 corn cobs (or 4 cups frozen corn)","1 onion, chopped","1 red bell pepper, chopped","2 cups pumpkin, diced","1 cup milk","100 g fresh cheese, diced","1 tsp paprika","1 tbsp olive oil"],"es":["6 choclos (o 4 tazas choclo congelado)","1 cebolla picada","1 morrón rojo picado","2 tazas zapallo en cubos","1 taza leche","100 g queso fresco en cubos","1 cdita pimentón","1 cda aceite de oliva"]},"steps":{"en":["Grate the corn off the cobs (or blend the frozen corn with the milk).","Soften the onion, pepper and pumpkin in the oil for 10 min; add the corn, milk and paprika.","Simmer 15 min, stirring, until thick; serve with the cheese on top."],"es":["Rallá los choclos (o licuá el choclo congelado con la leche).","Rehogá la cebolla, el morrón y el zapallo 10 min; sumá el choclo, la leche y el pimentón.","Cociná 15 min, revolviendo, hasta que espese; serví con el queso arriba."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"tarta-de-acelga","type":"lunch","country":"AR","protein":"plant","base":"bread","tags":["tart"],"name":{"en":"Swiss Chard & Ricotta Tart","es":"Tarta de acelga y ricota"},"ing":{"en":["2 pie crusts","1 bunch Swiss chard","1 onion, chopped","250 g ricotta","3 eggs","½ cup grated cheese","¼ tsp nutmeg"],"es":["2 tapas de tarta","1 atado de acelga","1 cebolla picada","250 g ricota","3 huevos","½ taza queso rallado","¼ cdita nuez moscada"]},"steps":{"en":["Blanch the chard for 2 min, squeeze dry and chop.","Soften the onion, then mix with chard, ricotta, eggs, cheese and nutmeg.","Fill the lined tin, cover and bake at 200°C for 35 min."],"es":["Blanqueá la acelga 2 min, escurrila bien y picala.","Rehogá la cebolla y mezclá con la acelga, la ricota, los huevos, el queso y la nuez moscada.","Rellená la tartera forrada, tapá y horneá a 200°C 35 min."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"ensalada-de-arroz-con-atun","type":"lunch","country":"AR","protein":"fish","base":"rice","tags":["tuna"],"name":{"en":"Rice Salad with Tuna & Egg","es":"Ensalada de arroz con atún y huevo"},"ing":{"en":["1½ cups rice","2 cans tuna, drained","3 eggs","1 cup frozen peas","1 carrot, grated","2 tbsp mayonnaise","1 lemon"],"es":["1½ tazas arroz","2 latas atún escurrido","3 huevos","1 taza arvejas congeladas","1 zanahoria rallada","2 cdas mayonesa","1 limón"]},"steps":{"en":["Cook the rice and the peas; cool.","Boil the eggs for 9 min and chop.","Mix everything with mayonnaise and lemon juice."],"es":["Cociná el arroz y las arvejas; enfriá.","Herví los huevos 9 min y picalos.","Mezclá todo con la mayonesa y el jugo de limón."]},"tip":{"en":"","es":""},"prep":["rice"]},
{"id":"revuelto-gramajo","type":"lunch","country":"AR","protein":"egg","base":"potato","name":{"en":"Revuelto Gramajo","es":"Revuelto gramajo"},"ing":{"en":["4 potatoes, cut into thin sticks","6 eggs","100 g cooked ham, cut into strips","1 onion, sliced","1 cup frozen peas","2 tbsp sunflower oil"],"es":["4 papas en bastones finos","6 huevos","100 g jamón cocido en tiras","1 cebolla en pluma","1 taza arvejas congeladas","2 cdas aceite de girasol"]},"steps":{"en":["Toss the potato sticks in oil and bake at 220°C for 25 min until crisp.","Soften the onion in a pan, add the ham and peas.","Add the potatoes and beaten eggs; stir until just set."],"es":["Mezclá los bastones con el aceite y horneá a 220°C 25 min, hasta que estén crocantes.","Rehogá la cebolla en una sartén y sumá el jamón y las arvejas.","Agregá las papas y los huevos batidos; revolvé hasta que apenas cuajen."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"choripan-con-chimichurri","type":"lunch","country":"AR","protein":"pork","base":"bread","name":{"en":"Choripán with Chimichurri & Salad","es":"Choripán con chimichurri y ensalada"},"ing":{"en":["4 pork sausages (chorizos)","4 crusty rolls","3 tbsp fresh parsley, chopped","1 garlic clove, minced","1 tsp dried oregano","3 tbsp olive oil","1 tbsp vinegar","1 head lettuce","2 tomatoes"],"es":["4 chorizos de cerdo","4 panes franceses","3 cdas perejil fresco picado","1 diente de ajo picado","1 cdita orégano","3 cdas aceite de oliva","1 cda vinagre","1 planta de lechuga","2 tomates"]},"steps":{"en":["Grill the chorizos over medium heat for 20 min, turning, until cooked through.","Mix parsley, garlic, oregano, oil and vinegar into chimichurri.","Split the chorizos into the rolls, spoon chimichurri over and serve with lettuce and tomato."],"es":["Cociná los chorizos a fuego medio 20 min, dándolos vuelta, hasta que estén bien cocidos.","Mezclá perejil, ajo, orégano, aceite y vinagre para el chimichurri.","Abrí los chorizos en los panes, sumá chimichurri y serví con lechuga y tomate."]},"tip":{"en":"For little ones, slice the chorizo lengthwise and keep the bread soft.","es":"Para los más chicos, cortá el chorizo a lo largo y usá pan blando."},"prep":[]},
{"id":"sandwich-de-milanesa","type":"lunch","country":"AR","protein":"beef","base":"bread","tags":["milanesa"],"name":{"en":"Beef Milanesa Sandwich","es":"Sándwich de milanesa"},"ing":{"en":["600 g thin beef cutlets","2 eggs","1½ cups breadcrumbs","4 crusty rolls","1 head lettuce","2 tomatoes, sliced","2 tbsp mayonnaise"],"es":["600 g milanesas de nalga","2 huevos","1½ tazas pan rallado","4 panes franceses","1 planta de lechuga","2 tomates en rodajas","2 cdas mayonesa"]},"steps":{"en":["Dip the cutlets in egg, then breadcrumbs; bake at 210°C for 15 min, turning once.","Split the rolls and spread with mayonnaise.","Fill with milanesa, lettuce and tomato."],"es":["Pasá la carne por huevo y pan rallado; horneá a 210°C 15 min, dando vuelta una vez.","Abrí los panes y untalos con mayonesa.","Rellená con milanesa, lechuga y tomate."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"ravioles-de-verdura-con-filetto","type":"lunch","country":"AR","protein":"plant","base":"pasta","tags":["ravioli"],"name":{"en":"Spinach Ravioli with Tomato Sauce","es":"Ravioles de verdura con salsa fileto"},"ing":{"en":["600 g spinach ravioli","1 can crushed tomatoes","1 onion, chopped","2 garlic cloves, minced","1 tbsp olive oil","4 tbsp grated parmesan","Fresh basil (optional)"],"es":["600 g ravioles de verdura","1 lata tomate triturado","1 cebolla picada","2 dientes de ajo picados","1 cda aceite de oliva","4 cdas queso parmesano rallado","Albahaca fresca (opcional)"]},"steps":{"en":["Soften the onion and garlic in the oil; add the tomatoes and simmer 15 min.","Cook the ravioli in salted water as the packet says.","Toss with the sauce and top with parmesan and basil."],"es":["Rehogá la cebolla y el ajo en el aceite; sumá el tomate y cociná 15 min.","Cociná los ravioles en agua con sal según el paquete.","Mezclá con la salsa y terminá con parmesano y albahaca."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"ensalada-de-lentejas","type":"lunch","country":"AR","protein":"plant","base":"none","tags":["lentil"],"name":{"en":"Lentil Salad with Egg & Tomato","es":"Ensalada de lentejas, huevo y tomate"},"ing":{"en":["1½ cups lentils (dry)","3 eggs","2 tomatoes, diced","1 red onion, finely chopped","2 tbsp fresh parsley, chopped","3 tbsp olive oil","1 lemon"],"es":["1½ tazas lentejas secas","3 huevos","2 tomates en cubos","1 cebolla morada picada fina","2 cdas perejil fresco picado","3 cdas aceite de oliva","1 limón"]},"steps":{"en":["Simmer the lentils for 20 min until just tender; drain and cool.","Boil the eggs for 9 min and quarter.","Toss lentils with tomato, onion, parsley, oil and lemon; top with the eggs."],"es":["Cociná las lentejas 20 min, hasta que estén tiernas; escurrí y enfriá.","Herví los huevos 9 min y cortalos en cuartos.","Mezclá las lentejas con el tomate, la cebolla, el perejil, el aceite y el limón; poné los huevos arriba."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"pejerrey-con-ensalada-de-papas","type":"lunch","country":"AR","protein":"fish","base":"potato","name":{"en":"Pan-Fried Silverside with Potato Salad","es":"Pejerrey a la plancha con ensalada de papas"},"ing":{"en":["600 g silverside or white fish fillets","2 tbsp flour","1 tbsp butter","800 g potatoes","2 tbsp mayonnaise","2 tbsp fresh parsley, chopped","1 lemon"],"es":["600 g filet de pejerrey o pescado blanco","2 cdas harina","1 cda manteca","800 g papas","2 cdas mayonesa","2 cdas perejil fresco picado","1 limón"]},"steps":{"en":["Boil the potatoes in chunks until tender; cool and mix with mayonnaise and parsley.","Dust the fish with flour and fry in butter 3 min a side.","Serve with lemon."],"es":["Herví las papas en trozos hasta que estén tiernas; enfriá y mezclá con mayonesa y perejil.","Pasá el pescado por harina y cocinalo en manteca 3 min por lado.","Serví con limón."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"sorrentinos-de-jamon-y-queso","type":"lunch","country":"AR","protein":"pork","base":"pasta","tags":["ravioli"],"name":{"en":"Ham & Cheese Sorrentinos with Butter & Sage","es":"Sorrentinos de jamón y queso con manteca y salvia"},"ing":{"en":["600 g ham and cheese sorrentinos","2 tbsp butter","6 sage leaves","4 tbsp grated parmesan","2 cups baby spinach"],"es":["600 g sorrentinos de jamón y queso","2 cdas manteca","6 hojas de salvia","4 cdas queso parmesano rallado","2 tazas espinaca baby"]},"steps":{"en":["Cook the sorrentinos in salted water as the packet says.","Melt the butter with the sage until fragrant.","Toss the pasta and spinach in the butter; finish with parmesan."],"es":["Cociná los sorrentinos en agua con sal según el paquete.","Derretí la manteca con la salvia hasta que perfume.","Mezclá la pasta y la espinaca con la manteca; terminá con parmesano."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"locro","type":"lunch","country":"AR","protein":"beef","base":"none","tags":["stew"],"name":{"en":"Locro: Corn, Bean & Squash Stew","es":"Locro"},"ing":{"en":["1 cup white hominy corn, soaked overnight","1 can white beans, drained","400 g beef chuck, diced","1 chorizo sausage, sliced","3 cups pumpkin, diced","1 onion, chopped","1 tsp ground cumin","1 tsp paprika","6 cups water"],"es":["1 taza maíz blanco pisado, remojado de la noche anterior","1 lata porotos blancos escurridos","400 g carne para guiso en cubos","1 chorizo en rodajas","3 tazas zapallo en cubos","1 cebolla picada","1 cdita comino","1 cdita pimentón","6 tazas agua"]},"steps":{"en":["Simmer the hominy in the water for 1 hour.","Brown the beef, chorizo and onion; add to the pot with pumpkin, beans and spices.","Simmer 1 more hour, stirring, until thick and the pumpkin melts."],"es":["Cociná el maíz en el agua 1 hora.","Dorá la carne, el chorizo y la cebolla; sumá a la olla con el zapallo, los porotos y las especias.","Cociná 1 hora más, revolviendo, hasta que espese y el zapallo se deshaga."]},"tip":{"en":"","es":""},"prep":["cook-ahead","soak"]},
{"id":"salpicon-de-pollo","type":"lunch","country":"AR","protein":"poultry","base":"none","name":{"en":"Salpicón: Chicken & Vegetable Salad","es":"Salpicón de pollo"},"ing":{"en":["500 g chicken breast","2 tomatoes, diced","1 red bell pepper, diced","1 cup corn","1 head lettuce","3 eggs","2 tbsp mayonnaise","1 lemon"],"es":["500 g pechuga de pollo","2 tomates en cubos","1 morrón rojo en cubos","1 taza choclo","1 planta de lechuga","3 huevos","2 cdas mayonesa","1 limón"]},"steps":{"en":["Poach the chicken for 15 min; cool and shred.","Boil the eggs for 9 min and chop.","Toss chicken, vegetables and eggs with mayonnaise and lemon; serve on lettuce."],"es":["Herví la pechuga 15 min; enfriala y desmenuzala.","Herví los huevos 9 min y picalos.","Mezclá pollo, verduras y huevo con mayonesa y limón; serví sobre lechuga."]},"tip":{"en":"","es":""},"prep":["cook-chicken"]},
{"id":"sopa-de-verduras-con-fideos","type":"lunch","country":"AR","protein":"plant","base":"pasta","tags":["soup"],"name":{"en":"Vegetable Soup with Little Noodles","es":"Sopa de verduras con fideos"},"ing":{"en":["2 carrots, diced","2 potatoes, diced","1 zucchini, diced","1 onion, chopped","1 cup pasta (small shapes)","6 cups vegetable broth","4 tbsp grated cheese"],"es":["2 zanahorias en cubos","2 papas en cubos","1 zapallito en cubos","1 cebolla picada","1 taza fideos chicos (municiones)","6 tazas caldo de verduras","4 cdas queso rallado"]},"steps":{"en":["Simmer the vegetables in the broth for 20 min.","Add the noodles and cook 8 min more.","Serve with grated cheese."],"es":["Cociná las verduras en el caldo 20 min.","Sumá los fideos y cociná 8 min más.","Serví con queso rallado."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"ensalada-de-pollo-arroz-y-choclo","type":"lunch","country":"AR","protein":"poultry","base":"rice","name":{"en":"Chicken, Rice & Corn Salad","es":"Ensalada de pollo, arroz y choclo"},"ing":{"en":["500 g chicken breast","1½ cups rice","1 cup corn","1 cup cherry tomatoes, halved","1 avocado, diced","3 tbsp olive oil","1 lemon"],"es":["500 g pechuga de pollo","1½ tazas arroz","1 taza choclo","1 taza tomates cherry en mitades","1 palta en cubos","3 cdas aceite de oliva","1 limón"]},"steps":{"en":["Cook the rice; cool. Grill the chicken 6 min a side and slice.","Toss rice with corn, tomatoes, oil and lemon.","Top with the chicken and avocado."],"es":["Cociná el arroz y enfrialo. Cociná la pechuga a la plancha 6 min por lado y cortala en tiras.","Mezclá el arroz con el choclo, los tomates, el aceite y el limón.","Poné el pollo y la palta arriba."]},"tip":{"en":"","es":""},"prep":["rice","cook-chicken"]},
{"id":"milanesa-a-la-napolitana","type":"dinner","country":"AR","protein":"beef","base":"potato","tags":["milanesa"],"name":{"en":"Milanesa Napolitana with Mash","es":"Milanesa a la napolitana con puré"},"ing":{"en":["600 g thin beef cutlets","2 eggs","1½ cups breadcrumbs","½ cup tomato sauce","150 g mozzarella, sliced","50 g cooked ham","1 kg potatoes","½ cup milk"],"es":["600 g milanesas de nalga","2 huevos","1½ tazas pan rallado","½ taza salsa de tomate","150 g mozzarella en fetas","50 g jamón cocido","1 kg papas","½ taza leche"]},"steps":{"en":["Bread the cutlets in egg and breadcrumbs; bake at 210°C for 12 min.","Top with tomato sauce, ham and mozzarella; bake 6 min more until melted.","Boil and mash the potatoes with the milk."],"es":["Empaná la carne con huevo y pan rallado; horneá a 210°C 12 min.","Cubrí con salsa, jamón y mozzarella; horneá 6 min más hasta que se derrita.","Herví las papas y hacé puré con la leche."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"merluza-a-la-romana-con-ensalada-rusa","type":"dinner","country":"AR","protein":"fish","base":"potato","tags":["breaded-fish"],"name":{"en":"Battered Hake with Russian Salad","es":"Merluza a la romana con ensalada rusa"},"ing":{"en":["600 g hake fillets","1 cup flour","1 egg","¾ cup sparkling water","Sunflower oil for frying","3 potatoes, diced","2 carrots, diced","1 cup frozen peas","3 tbsp mayonnaise"],"es":["600 g filet de merluza","1 taza harina","1 huevo","¾ taza agua con gas","Aceite de girasol para freír","3 papas en cubos","2 zanahorias en cubos","1 taza arvejas congeladas","3 cdas mayonesa"]},"steps":{"en":["Boil potatoes, carrots and peas until tender; cool and mix with mayonnaise.","Whisk flour, egg and sparkling water into a batter.","Dip the fish and fry 3 min a side; drain well."],"es":["Herví las papas, las zanahorias y las arvejas; enfriá y mezclá con mayonesa.","Batí la harina, el huevo y el agua con gas.","Pasá el pescado por el rebozador y freí 3 min por lado; escurrí bien."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"trucha-a-la-manteca","type":"dinner","country":"AR","protein":"fish","base":"potato","name":{"en":"Patagonian Trout with Lemon Butter & Potatoes","es":"Trucha patagónica a la manteca con papas"},"ing":{"en":["4 trout fillets","2 tbsp butter","2 lemons","2 tbsp capers (optional)","800 g baby potatoes","2 tbsp fresh parsley, chopped"],"es":["4 filetes de trucha","2 cdas manteca","2 limones","2 cdas alcaparras (opcional)","800 g papines","2 cdas perejil fresco picado"]},"steps":{"en":["Boil the potatoes until tender.","Cook the trout skin side down in half the butter for 4 min, turn and cook 2 min.","Melt the rest of the butter with lemon juice and capers; spoon over with the parsley."],"es":["Herví los papines hasta que estén tiernos.","Cociná la trucha del lado de la piel en la mitad de la manteca 4 min, da vuelta y cociná 2 min.","Derretí el resto de la manteca con jugo de limón y alcaparras; volcá por encima con el perejil."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"pollo-al-disco","type":"dinner","country":"AR","protein":"poultry","base":"potato","tags":["stew"],"name":{"en":"Chicken al Disco with Vegetables","es":"Pollo al disco con verduras"},"ing":{"en":["1 kg chicken thighs","2 onions, sliced","2 bell peppers, sliced","4 potatoes, diced","1 cup chicken broth","1 tsp paprika","2 tbsp olive oil"],"es":["1 kg muslos de pollo","2 cebollas en pluma","2 morrones en tiras","4 papas en cubos","1 taza caldo de pollo","1 cdita pimentón","2 cdas aceite de oliva"]},"steps":{"en":["Brown the chicken in the oil in a wide pan.","Add onions and peppers and cook 10 min; add potatoes, paprika and broth.","Cover and simmer 30 min until the potatoes are tender."],"es":["Dorá el pollo en el aceite en una sartén grande.","Sumá la cebolla y los morrones y cociná 10 min; agregá las papas, el pimentón y el caldo.","Tapá y cociná 30 min, hasta que las papas estén tiernas."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"bife-a-la-criolla","type":"dinner","country":"AR","protein":"beef","base":"potato","tags":["stew"],"name":{"en":"Bife a la Criolla","es":"Bife a la criolla"},"ing":{"en":["600 g beef steaks, thin","2 onions, sliced","2 bell peppers, sliced","3 tomatoes, sliced","4 potatoes, sliced","1 cup beef broth","1 tsp dried oregano"],"es":["600 g bifes finos","2 cebollas en pluma","2 morrones en tiras","3 tomates en rodajas","4 papas en rodajas","1 taza caldo de carne","1 cdita orégano"]},"steps":{"en":["Layer potatoes, beef, onion, pepper and tomato in a pot.","Season with oregano and pour in the broth.","Cover and cook gently for 40 min."],"es":["Armá capas de papa, carne, cebolla, morrón y tomate en una olla.","Condimentá con orégano y volcá el caldo.","Tapá y cociná a fuego suave 40 min."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"noquis-de-calabaza","type":"dinner","country":"AR","protein":"plant","base":"pasta","tags":["gnocchi"],"name":{"en":"Pumpkin Gnocchi with Butter & Cheese","es":"Ñoquis de calabaza con manteca y queso"},"ing":{"en":["600 g pumpkin, roasted and mashed","1½ cups flour","1 egg","¼ tsp nutmeg","2 tbsp butter","4 tbsp grated parmesan"],"es":["600 g calabaza asada y hecha puré","1½ tazas harina","1 huevo","¼ cdita nuez moscada","2 cdas manteca","4 cdas queso parmesano rallado"]},"steps":{"en":["Mix the pumpkin, egg, nutmeg and enough flour for a soft dough.","Roll into ropes, cut 2 cm pieces and boil until they float.","Toss in butter and parmesan."],"es":["Mezclá la calabaza, el huevo, la nuez moscada y la harina necesaria para una masa blanda.","Formá cilindros, cortá trozos de 2 cm y herví hasta que floten.","Mezclá con manteca y parmesano."]},"tip":{"en":"","es":""},"prep":["roast-pumpkin"]},
{"id":"polenta-con-queso-y-salsa","type":"dinner","country":"AR","protein":"plant","base":"grain","name":{"en":"Cheesy Polenta with Tomato Sauce","es":"Polenta con queso y salsa"},"ing":{"en":["1½ cups polenta","5 cups milk and water","150 g mozzarella, diced","1 can crushed tomatoes","1 onion, chopped","1 tbsp olive oil"],"es":["1½ tazas polenta","5 tazas leche y agua","150 g mozzarella en cubos","1 lata tomate triturado","1 cebolla picada","1 cda aceite de oliva"]},"steps":{"en":["Make a quick sauce: soften the onion in oil, add tomatoes and simmer 15 min.","Whisk the polenta into the boiling milk and water; stir 8 min.","Stir in the mozzarella and serve with the sauce."],"es":["Hacé una salsa rápida: rehogá la cebolla en el aceite, sumá el tomate y cociná 15 min.","Volcá la polenta en lluvia sobre la leche y el agua hirviendo; revolvé 8 min.","Incorporá la mozzarella y serví con la salsa."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"berenjenas-a-la-napolitana","type":"dinner","country":"AR","protein":"plant","base":"none","name":{"en":"Baked Eggplant Napolitana","es":"Berenjenas a la napolitana"},"ing":{"en":["3 eggplants, sliced lengthwise","1 cup tomato sauce","200 g mozzarella, sliced","2 tomatoes, sliced","1 tsp dried oregano","2 tbsp olive oil","1 cup cooked rice (optional)"],"es":["3 berenjenas en láminas","1 taza salsa de tomate","200 g mozzarella en fetas","2 tomates en rodajas","1 cdita orégano","2 cdas aceite de oliva","1 taza arroz cocido (opcional)"]},"steps":{"en":["Brush the eggplant with oil and roast at 200°C for 15 min.","Top with sauce, tomato, mozzarella and oregano.","Bake 10 min more until bubbling."],"es":["Pincelá las berenjenas con aceite y horneá a 200°C 15 min.","Cubrí con salsa, tomate, mozzarella y orégano.","Horneá 10 min más hasta que gratine."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"cazuela-de-mariscos","type":"dinner","country":"AR","protein":"fish","base":"rice","tags":["stew"],"name":{"en":"Seafood Cazuela with Rice","es":"Cazuela de mariscos con arroz"},"ing":{"en":["300 g white fish fillets, diced","300 g shrimp, peeled","300 g squid rings","1 onion, chopped","1 red bell pepper, chopped","1 can crushed tomatoes","½ cup white wine","1½ cups rice"],"es":["300 g filet de pescado blanco en cubos","300 g langostinos pelados","300 g rabas de calamar","1 cebolla picada","1 morrón rojo picado","1 lata tomate triturado","½ taza vino blanco","1½ tazas arroz"]},"steps":{"en":["Soften the onion and pepper; add wine and tomatoes and simmer 10 min.","Add the seafood and cook 5 min, just until done.","Serve over boiled rice."],"es":["Rehogá la cebolla y el morrón; sumá el vino y el tomate y cociná 10 min.","Agregá los mariscos y cociná 5 min, solo hasta que estén.","Serví sobre arroz blanco."]},"tip":{"en":"","es":""},"prep":["rice"]},
{"id":"chupin-de-pescado","type":"dinner","country":"AR","protein":"fish","base":"potato","tags":["stew"],"name":{"en":"Chupín: River Fish Stew","es":"Chupín de pescado"},"ing":{"en":["700 g firm white fish fillets","3 potatoes, sliced","2 onions, sliced","1 red bell pepper, sliced","1 can crushed tomatoes","1 cup fish or vegetable broth","1 bay leaf"],"es":["700 g filet de pescado de río o blanco","3 papas en rodajas","2 cebollas en pluma","1 morrón rojo en tiras","1 lata tomate triturado","1 taza caldo de pescado o de verduras","1 hoja de laurel"]},"steps":{"en":["Layer potatoes, onion and pepper in a pot with the tomatoes, broth and bay leaf.","Simmer 20 min until the potatoes are almost tender.","Lay the fish on top, cover and cook 10 min more."],"es":["Armá capas de papa, cebolla y morrón con el tomate, el caldo y el laurel.","Cociná 20 min, hasta que las papas estén casi tiernas.","Acomodá el pescado arriba, tapá y cociná 10 min más."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"puchero","type":"dinner","country":"AR","protein":"beef","base":"potato","tags":["stew"],"name":{"en":"Puchero: Boiled Beef & Vegetables","es":"Puchero"},"ing":{"en":["800 g beef shin (osobuco)","4 potatoes","2 sweet potatoes","2 corn cobs, halved","2 carrots","¼ cabbage","1 onion","1 can chickpeas, drained"],"es":["800 g osobuco","4 papas","2 batatas","2 choclos en mitades","2 zanahorias","¼ repollo","1 cebolla","1 lata garbanzos escurridos"]},"steps":{"en":["Cover the beef and onion with water and simmer 1½ hours, skimming.","Add potatoes, sweet potatoes, carrots and corn; cook 25 min.","Add cabbage and chickpeas for the last 10 min; serve the broth first as soup."],"es":["Cubrí la carne y la cebolla con agua y cociná 1½ horas, espumando.","Sumá las papas, las batatas, las zanahorias y el choclo; cociná 25 min.","Agregá el repollo y los garbanzos los últimos 10 min; serví primero el caldo como sopa."]},"tip":{"en":"","es":""},"prep":["cook-ahead"]},
{"id":"carbonada","type":"dinner","country":"AR","protein":"beef","base":"potato","tags":["stew"],"name":{"en":"Carbonada: Beef Stew with Squash & Peaches","es":"Carbonada criolla"},"ing":{"en":["600 g beef chuck, diced","2 cups pumpkin, diced","2 potatoes, diced","2 sweet potatoes, diced","1 corn cob, sliced","2 peaches, diced","1 onion, chopped","1 can crushed tomatoes","2 cups beef broth"],"es":["600 g carne para guiso en cubos","2 tazas zapallo en cubos","2 papas en cubos","2 batatas en cubos","1 choclo en rodajas","2 duraznos en cubos","1 cebolla picada","1 lata tomate triturado","2 tazas caldo de carne"]},"steps":{"en":["Brown the beef with the onion.","Add tomatoes, broth, potatoes, sweet potatoes and corn; simmer 40 min.","Add pumpkin and peaches and cook 15 min more."],"es":["Dorá la carne con la cebolla.","Sumá el tomate, el caldo, las papas, las batatas y el choclo; cociná 40 min.","Agregá el zapallo y los duraznos y cociná 15 min más."]},"tip":{"en":"","es":""},"prep":["cook-ahead"]},
{"id":"pizza-fugazzeta","type":"dinner","country":"AR","protein":"plant","base":"bread","tags":["pizza"],"name":{"en":"Fugazzeta: Onion & Cheese Pizza","es":"Fugazzeta"},"ing":{"en":["500 g pizza dough","3 onions, thinly sliced","300 g mozzarella, sliced","1 tsp dried oregano","2 tbsp olive oil","1 head lettuce"],"es":["500 g masa de pizza","3 cebollas en pluma fina","300 g mozzarella en fetas","1 cdita orégano","2 cdas aceite de oliva","1 planta de lechuga"]},"steps":{"en":["Stretch the dough into an oiled tin and pre-bake at 220°C for 8 min.","Cover with mozzarella, then the onions; drizzle with oil and oregano.","Bake 15 min until the onions are golden; serve with a green salad."],"es":["Estirá la masa en una pizzera aceitada y precociná a 220°C 8 min.","Cubrí con mozzarella y después con la cebolla; rociá con aceite y orégano.","Horneá 15 min hasta que la cebolla se dore; serví con ensalada verde."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"bondiola-braseada-con-batatas","type":"dinner","country":"AR","protein":"pork","base":"potato","name":{"en":"Braised Pork Shoulder with Sweet Potatoes","es":"Bondiola braseada con batatas"},"ing":{"en":["1 kg pork shoulder","2 onions, sliced","1 cup beef broth","2 tbsp honey","1 tbsp Dijon mustard","4 sweet potatoes"],"es":["1 kg bondiola de cerdo","2 cebollas en pluma","1 taza caldo de carne","2 cdas miel","1 cda mostaza Dijon","4 batatas"]},"steps":{"en":["Brown the pork on all sides; add onions, broth, honey and mustard.","Cover and cook at 170°C for 2 hours.","Roast the sweet potatoes alongside for the last 45 min; slice the pork and spoon the sauce over."],"es":["Dorá la bondiola de todos lados; sumá la cebolla, el caldo, la miel y la mostaza.","Tapá y cociná en el horno a 170°C 2 horas.","Asá las batatas al lado los últimos 45 min; cortá la carne y bañala con la salsa."]},"tip":{"en":"","es":""},"prep":["cook-ahead"]},
{"id":"pescado-al-horno-con-papas","type":"dinner","country":"AR","protein":"fish","base":"potato","name":{"en":"Baked Fish with Potatoes, Lemon & Garlic","es":"Pescado al horno con papas, limón y ajo"},"ing":{"en":["700 g white fish fillets","800 g potatoes, thinly sliced","1 onion, sliced","2 garlic cloves, minced","2 lemons","3 tbsp olive oil","2 tbsp fresh parsley, chopped"],"es":["700 g filet de pescado blanco","800 g papas en rodajas finas","1 cebolla en pluma","2 dientes de ajo picados","2 limones","3 cdas aceite de oliva","2 cdas perejil fresco picado"]},"steps":{"en":["Toss potatoes and onion with oil; roast at 200°C for 25 min.","Lay the fish on top with garlic and lemon slices.","Roast 12 min more; finish with parsley."],"es":["Mezclá las papas y la cebolla con aceite; horneá a 200°C 25 min.","Acomodá el pescado encima con el ajo y rodajas de limón.","Horneá 12 min más; terminá con perejil."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"canelones-de-verdura","type":"dinner","country":"AR","protein":"plant","base":"pasta","tags":["lasagna"],"name":{"en":"Spinach Cannelloni with White Sauce","es":"Canelones de verdura con salsa blanca"},"ing":{"en":["12 crêpes or cannelloni tubes","2 bunches spinach","250 g ricotta","1 onion, chopped","2 cups milk","2 tbsp butter","2 tbsp flour","1 cup tomato sauce","4 tbsp grated parmesan"],"es":["12 panqueques o canelones","2 atados de espinaca","250 g ricota","1 cebolla picada","2 tazas leche","2 cdas manteca","2 cdas harina","1 taza salsa de tomate","4 cdas queso parmesano rallado"]},"steps":{"en":["Wilt the spinach with the onion, chop and mix with ricotta.","Make a white sauce: melt butter, stir in flour, whisk in milk until thick.","Fill and roll the crêpes, cover with tomato and white sauce and parmesan; bake at 200°C for 20 min."],"es":["Rehogá la espinaca con la cebolla, picala y mezclala con la ricota.","Hacé una salsa blanca: derretí la manteca, sumá la harina y la leche batiendo hasta que espese.","Rellená y enrollá, cubrí con salsa de tomate, salsa blanca y parmesano; horneá a 200°C 20 min."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"tarta-de-calabaza-y-queso","type":"dinner","country":"AR","protein":"plant","base":"bread","tags":["tart"],"name":{"en":"Pumpkin & Cheese Tart","es":"Tarta de calabaza y queso"},"ing":{"en":["2 pie crusts","800 g pumpkin, roasted and mashed","1 onion, chopped","150 g mozzarella, diced","3 eggs","¼ tsp nutmeg"],"es":["2 tapas de tarta","800 g calabaza asada y hecha puré","1 cebolla picada","150 g mozzarella en cubos","3 huevos","¼ cdita nuez moscada"]},"steps":{"en":["Soften the onion and mix with the pumpkin, eggs, cheese and nutmeg.","Fill the lined tin and cover with the second crust.","Bake at 200°C for 35 min."],"es":["Rehogá la cebolla y mezclá con la calabaza, los huevos, el queso y la nuez moscada.","Rellená la tartera forrada y tapá con la otra masa.","Horneá a 200°C 35 min."]},"tip":{"en":"","es":""},"prep":["roast-pumpkin"]},
{"id":"pastel-de-papas","type":"dinner","country":"AR","protein":"beef","base":"potato","tags":["mince-pie"],"name":{"en":"Pastel de Papas","es":"Pastel de papas"},"ing":{"en":["600 g ground beef","1 onion, chopped","1 red bell pepper, chopped","2 eggs, boiled","¼ cup green olives, sliced (optional)","1 kg potatoes","½ cup milk","1 tbsp butter","1 tsp paprika"],"es":["600 g carne picada","1 cebolla picada","1 morrón rojo picado","2 huevos duros","¼ taza aceitunas verdes en rodajas (opcional)","1 kg papas","½ taza leche","1 cda manteca","1 cdita pimentón"]},"steps":{"en":["Brown the beef with the onion, pepper and paprika; stir in the chopped eggs and olives.","Mash the potatoes with the milk and butter.","Spread the meat in a dish, cover with the mash and bake at 200°C for 20 min."],"es":["Dorá la carne con la cebolla, el morrón y el pimentón; sumá los huevos picados y las aceitunas.","Hacé puré con las papas, la leche y la manteca.","Poné la carne en una fuente, cubrí con el puré y horneá a 200°C 20 min."]},"tip":{"en":"","es":""},"prep":["brown-beef"]},
{"id":"matambre-a-la-pizza","type":"dinner","country":"AR","protein":"beef","base":"potato","name":{"en":"Matambre a la Pizza with Roast Potatoes","es":"Matambre a la pizza con papas al horno"},"ing":{"en":["1 kg flank steak (matambre), tenderised","1 cup tomato sauce","200 g mozzarella, sliced","1 tsp dried oregano","1 kg potatoes, cut into wedges","2 tbsp olive oil"],"es":["1 kg matambre tiernizado","1 taza salsa de tomate","200 g mozzarella en fetas","1 cdita orégano","1 kg papas en gajos","2 cdas aceite de oliva"]},"steps":{"en":["Simmer the matambre in milky water for 45 min until tender (or use a pressure cooker for 20).","Roast the potatoes with oil at 220°C for 35 min.","Top the matambre with sauce, mozzarella and oregano and grill 8 min until melted."],"es":["Herví el matambre en agua con leche 45 min hasta que esté tierno (o 20 en olla a presión).","Asá las papas con aceite a 220°C 35 min.","Cubrí el matambre con salsa, mozzarella y orégano y gratiná 8 min."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"asado-con-ensalada-mixta","type":"dinner","country":"AR","protein":"beef","base":"none","name":{"en":"Family Asado with Mixed Salad","es":"Asado con ensalada mixta"},"ing":{"en":["1 kg beef short ribs (tira de asado)","2 pork sausages (chorizos)","1 head lettuce","3 tomatoes","1 onion","2 tbsp olive oil","1 tbsp vinegar","4 tbsp chimichurri (optional)"],"es":["1 kg tira de asado","2 chorizos de cerdo","1 planta de lechuga","3 tomates","1 cebolla","2 cdas aceite de oliva","1 cda vinagre","4 cdas chimichurri (opcional)"]},"steps":{"en":["Grill the ribs and chorizos over medium coals, about 40 min for the ribs and 20 for the chorizos.","Slice lettuce, tomato and onion and dress with oil, vinegar and salt.","Serve the meat with the salad and chimichurri."],"es":["Asá la tira y los chorizos a brasa media, unos 40 min la tira y 20 los chorizos.","Cortá la lechuga, el tomate y la cebolla y condimentá con aceite, vinagre y sal.","Serví la carne con la ensalada y el chimichurri."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"pascualina","type":"lunch","country":"UY","protein":"plant","base":"bread","tags":["tart"],"name":{"en":"Pascualina: Spinach Pie with Whole Eggs","es":"Pascualina"},"ing":{"en":["2 pie crusts","2 bunches spinach","1 onion, chopped","6 eggs","½ cup grated cheese","¼ tsp nutmeg"],"es":["2 tapas de tarta","2 atados de espinaca","1 cebolla picada","6 huevos","½ taza queso rallado","¼ cdita nuez moscada"]},"steps":{"en":["Wilt the spinach with the onion, squeeze dry, chop and mix with 2 eggs, cheese and nutmeg.","Spread in the lined tin and make 4 hollows; crack an egg into each.","Cover with the second crust and bake at 200°C for 35 min."],"es":["Rehogá la espinaca con la cebolla, escurrila, picala y mezclá con 2 huevos, el queso y la nuez moscada.","Poné el relleno en la tartera forrada y hacé 4 huecos; rompé un huevo en cada uno.","Tapá con la otra masa y horneá a 200°C 35 min."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"chivito-uruguayo","type":"lunch","country":"UY","protein":"beef","base":"bread","name":{"en":"Chivito Steak Sandwich","es":"Chivito uruguayo"},"ing":{"en":["4 thin beef steaks","4 burger buns","4 slices cooked ham","4 slices mozzarella","4 eggs","1 head lettuce","2 tomatoes, sliced","2 tbsp mayonnaise"],"es":["4 bifes finos de lomo","4 panes de hamburguesa","4 fetas de jamón cocido","4 fetas de mozzarella","4 huevos","1 planta de lechuga","2 tomates en rodajas","2 cdas mayonesa"]},"steps":{"en":["Sear the steaks 2 min a side; top each with ham and mozzarella until melted.","Fry the eggs.","Build the sandwiches with mayonnaise, lettuce, tomato, steak and egg."],"es":["Cociná los bifes 2 min por lado; poné jamón y mozzarella arriba hasta que se derrita.","Freí los huevos.","Armá los sándwiches con mayonesa, lechuga, tomate, la carne y el huevo."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"capeletis-a-la-caruso","type":"dinner","country":"UY","protein":"pork","base":"pasta","tags":["ravioli"],"name":{"en":"Cappelletti Caruso (Ham, Mushroom & Cream)","es":"Capeletis a la Caruso"},"ing":{"en":["600 g cappelletti","150 g cooked ham, diced","200 g mushrooms, sliced","1 cup cream","1 onion, chopped","4 tbsp grated parmesan","1 tbsp butter"],"es":["600 g capeletis","150 g jamón cocido en cubos","200 g champiñones en láminas","1 taza crema de leche","1 cebolla picada","4 cdas queso parmesano rallado","1 cda manteca"]},"steps":{"en":["Soften the onion and mushrooms in the butter for 6 min; add the ham.","Pour in the cream and simmer 5 min.","Cook the pasta, toss with the sauce and parmesan."],"es":["Rehogá la cebolla y los champiñones en la manteca 6 min; sumá el jamón.","Agregá la crema y cociná 5 min.","Cociná la pasta y mezclala con la salsa y el parmesano."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"postre-chaja","type":"snack","country":"UY","group":"grain","tags":["cake"],"name":{"en":"Chajá: Sponge, Cream & Peach Pots","es":"Vasitos de chajá"},"ing":{"en":["200 g sponge cake","1 cup cream","4 canned peach halves, diced","4 meringue cookies, crushed"],"es":["200 g bizcochuelo","1 taza crema de leche","4 mitades de durazno en almíbar en cubos","4 merenguitos triturados"]},"steps":{"en":["Whip the cream to soft peaks.","Layer sponge, peaches and cream in small glasses.","Top with the crushed meringue just before serving."],"es":["Batí la crema a medio punto.","Armá capas de bizcochuelo, durazno y crema en vasitos.","Terminá con el merengue triturado justo antes de servir."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"pastel-de-choclo","type":"dinner","country":"CL","protein":"beef","base":"none","tags":["mince-pie"],"name":{"en":"Pastel de Choclo: Beef & Corn Bake","es":"Pastel de choclo"},"ing":{"en":["500 g ground beef","2 onions, chopped","1 tsp ground cumin","2 eggs, boiled and sliced","500 g chicken breast, poached and shredded","5 cups corn","½ cup milk","6 basil leaves"],"es":["500 g carne picada","2 cebollas picadas","1 cdita comino","2 huevos duros en rodajas","500 g pechuga de pollo hervida y desmenuzada","5 tazas choclo","½ taza leche","6 hojas de albahaca"]},"steps":{"en":["Brown the beef with the onions and cumin; spread in a dish with the chicken and eggs.","Blend the corn with the milk and basil and cook 10 min, stirring, until thick.","Spread the corn over the filling and bake at 200°C for 25 min until golden."],"es":["Dorá la carne con la cebolla y el comino; poné en una fuente con el pollo y los huevos.","Licuá el choclo con la leche y la albahaca y cociná 10 min, revolviendo, hasta que espese.","Cubrí el relleno con la pasta de choclo y horneá a 200°C 25 min, hasta que dore."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"cazuela-de-ave","type":"lunch","country":"CL","protein":"poultry","base":"potato","tags":["soup"],"name":{"en":"Chilean Chicken Cazuela","es":"Cazuela de ave"},"ing":{"en":["4 chicken thighs","4 potatoes, halved","4 pieces pumpkin","2 corn cobs, cut in rounds","½ cup rice","1 carrot, sliced","6 cups chicken broth","2 tbsp fresh cilantro, chopped"],"es":["4 muslos de pollo","4 papas en mitades","4 trozos de zapallo","2 choclos en rodajas","½ taza arroz","1 zanahoria en rodajas","6 tazas caldo de pollo","2 cdas cilantro fresco picado"]},"steps":{"en":["Brown the chicken, then cover with the broth and simmer 20 min.","Add potatoes, pumpkin, carrot, corn and rice; cook 20 min.","Serve one piece of everything in each bowl with cilantro."],"es":["Dorá el pollo, cubrí con el caldo y cociná 20 min.","Sumá las papas, el zapallo, la zanahoria, el choclo y el arroz; cociná 20 min.","Serví un trozo de cada cosa por plato con cilantro."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"porotos-granados","type":"lunch","country":"CL","protein":"plant","base":"none","tags":["stew"],"name":{"en":"Porotos Granados: Bean, Squash & Corn Stew","es":"Porotos granados"},"ing":{"en":["2 cans white beans, drained","3 cups pumpkin, diced","2 cups corn","1 onion, chopped","1 tsp paprika","6 basil leaves","3 cups vegetable broth"],"es":["2 latas porotos blancos escurridos","3 tazas zapallo en cubos","2 tazas choclo","1 cebolla picada","1 cdita pimentón","6 hojas de albahaca","3 tazas caldo de verduras"]},"steps":{"en":["Soften the onion with the paprika.","Add pumpkin and broth and simmer 15 min until the squash melts.","Add beans and corn, cook 10 min and finish with basil."],"es":["Rehogá la cebolla con el pimentón.","Sumá el zapallo y el caldo y cociná 15 min, hasta que el zapallo se deshaga.","Agregá los porotos y el choclo, cociná 10 min y terminá con albahaca."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"charquican","type":"dinner","country":"CL","protein":"beef","base":"potato","tags":["stew"],"name":{"en":"Charquicán: Beef & Vegetable Mash","es":"Charquicán"},"ing":{"en":["400 g ground beef","4 potatoes, diced","3 cups pumpkin, diced","1 cup corn","1 cup frozen peas","1 onion, chopped","4 eggs","1 cup beef broth"],"es":["400 g carne picada","4 papas en cubos","3 tazas zapallo en cubos","1 taza choclo","1 taza arvejas congeladas","1 cebolla picada","4 huevos","1 taza caldo de carne"]},"steps":{"en":["Brown the beef with the onion.","Add potatoes, pumpkin and broth; simmer 20 min, then roughly mash.","Stir in corn and peas; serve each plate topped with a fried egg."],"es":["Dorá la carne con la cebolla.","Sumá las papas, el zapallo y el caldo; cociná 20 min y pisá un poco.","Incorporá el choclo y las arvejas; serví cada plato con un huevo frito."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"sopaipillas","type":"snack","country":"CL","group":"grain","name":{"en":"Sopaipillas (Pumpkin Fried Bread)","es":"Sopaipillas"},"ing":{"en":["1 cup pumpkin, cooked and mashed","2 cups flour","1 tsp baking powder","2 tbsp butter, melted","Sunflower oil for frying"],"es":["1 taza zapallo cocido y pisado","2 tazas harina","1 cdita polvo para hornear","2 cdas manteca derretida","Aceite de girasol para freír"]},"steps":{"en":["Knead the pumpkin, flour, baking powder, butter and a pinch of salt.","Roll out 5 mm thick and cut rounds; prick with a fork.","Fry until puffed and golden; drain."],"es":["Amasá el zapallo con la harina, el polvo de hornear, la manteca y una pizca de sal.","Estirá de 5 mm y cortá círculos; pinchalos con un tenedor.","Freí hasta que se inflen y doren; escurrí."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"marraqueta-con-palta","type":"breakfast","country":"CL","group":"grain","tags":["toast"],"name":{"en":"Marraqueta with Avocado & Tomato","es":"Marraqueta con palta y tomate"},"ing":{"en":["4 crusty rolls","2 ripe avocados","2 tomatoes, sliced","1 lemon","2 cups milk"],"es":["4 marraquetas o panes franceses","2 paltas maduras","2 tomates en rodajas","1 limón","2 tazas leche"]},"steps":{"en":["Split and toast the rolls.","Mash the avocado with lemon and salt and spread thickly.","Top with tomato; serve with warm milk."],"es":["Abrí y tostá los panes.","Pisá la palta con limón y sal y untá bien.","Poné tomate arriba y serví con leche tibia."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"lomo-saltado","type":"dinner","country":"PE","protein":"beef","base":"potato","tags":["stir-fry"],"name":{"en":"Lomo Saltado","es":"Lomo saltado"},"ing":{"en":["600 g beef sirloin, cut into strips","2 red onions, cut into wedges","3 tomatoes, cut into wedges","2 tbsp soy sauce","1 tbsp vinegar","800 g potatoes, cut into fries","1 cup rice","2 tbsp fresh cilantro, chopped"],"es":["600 g lomo en tiras","2 cebollas moradas en gajos","3 tomates en gajos","2 cdas salsa de soja","1 cda vinagre","800 g papas en bastones","1 taza arroz","2 cdas cilantro fresco picado"]},"steps":{"en":["Bake the potato fries at 220°C for 30 min; cook the rice.","Sear the beef very hot in batches; add onion, then tomato, soy sauce and vinegar for 2 min.","Toss in the fries and cilantro; serve with rice."],"es":["Horneá las papas a 220°C 30 min; cociná el arroz.","Saltá la carne a fuego fuerte de a poco; sumá la cebolla y después el tomate, la soja y el vinagre 2 min.","Agregá las papas y el cilantro; serví con arroz."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"aji-de-gallina","type":"dinner","country":"PE","protein":"poultry","base":"rice","name":{"en":"Ají de Gallina: Creamy Chicken","es":"Ají de gallina"},"ing":{"en":["600 g chicken breast","2 slices white bread","1 cup milk","1 onion, chopped","2 tbsp ají amarillo paste (or ½ yellow pepper)","¼ cup walnuts, ground","4 tbsp grated parmesan","1½ cups rice","2 eggs, boiled"],"es":["600 g pechuga de pollo","2 rebanadas de pan blanco","1 taza leche","1 cebolla picada","2 cdas pasta de ají amarillo (o ½ morrón amarillo)","¼ taza nueces molidas","4 cdas queso parmesano rallado","1½ tazas arroz","2 huevos duros"]},"steps":{"en":["Poach and shred the chicken; keep 1 cup of the broth.","Soak the bread in milk and blend; cook the onion and ají, add the bread, broth, walnuts and cheese and simmer 5 min.","Stir in the chicken; serve with rice and egg halves."],"es":["Herví y desmenuzá el pollo; guardá 1 taza del caldo.","Remojá el pan en la leche y licuá; rehogá la cebolla con el ají, sumá el pan, el caldo, las nueces y el queso y cociná 5 min.","Incorporá el pollo; serví con arroz y huevo duro."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"causa-de-atun","type":"lunch","country":"PE","protein":"fish","base":"potato","tags":["tuna"],"name":{"en":"Causa Limeña with Tuna","es":"Causa limeña de atún"},"ing":{"en":["1 kg yellow potatoes","2 limes","2 tbsp ají amarillo paste (or ½ yellow pepper)","3 tbsp sunflower oil","2 cans tuna, drained","3 tbsp mayonnaise","1 avocado, sliced","2 eggs, boiled"],"es":["1 kg papas amarillas","2 limas","2 cdas pasta de ají amarillo (o ½ morrón amarillo)","3 cdas aceite de girasol","2 latas atún escurrido","3 cdas mayonesa","1 palta en rodajas","2 huevos duros"]},"steps":{"en":["Boil and mash the potatoes with lime juice, ají, oil and salt; cool.","Mix the tuna with mayonnaise.","Layer potato, tuna, avocado and potato in a dish; top with egg slices and chill."],"es":["Herví las papas y pisalas con jugo de lima, ají, aceite y sal; enfriá.","Mezclá el atún con la mayonesa.","Armá capas de papa, atún, palta y papa en una fuente; terminá con huevo y enfriá."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"ceviche-de-pescado","type":"lunch","country":"PE","protein":"fish","base":"none","tags":["raw"],"name":{"en":"Fish Ceviche with Sweet Potato & Corn","es":"Ceviche de pescado con batata y choclo"},"ing":{"en":["600 g very fresh white fish, diced","10 limes","1 red onion, thinly sliced","2 tbsp fresh cilantro, chopped","2 sweet potatoes","2 corn cobs","1 head lettuce"],"es":["600 g pescado blanco bien fresco en cubos","10 limas","1 cebolla morada en pluma fina","2 cdas cilantro fresco picado","2 batatas","2 choclos","1 planta de lechuga"]},"steps":{"en":["Boil the sweet potatoes and corn; slice.","Cover the fish with lime juice, onion, cilantro and salt for 10 min.","Serve on lettuce with the sweet potato and corn."],"es":["Herví las batatas y los choclos; cortá en rodajas.","Cubrí el pescado con jugo de lima, cebolla, cilantro y sal 10 min.","Serví sobre lechuga con la batata y el choclo."]},"tip":{"en":"The fish is not cooked by heat — only for older kids and adults, and only with very fresh fish.","es":"El pescado no se cocina con calor: solo para chicos grandes y adultos, y con pescado muy fresco."},"prep":[]},
{"id":"papa-a-la-huancaina","type":"lunch","country":"PE","protein":"plant","base":"potato","name":{"en":"Papa a la Huancaína","es":"Papa a la huancaína"},"ing":{"en":["1 kg potatoes","200 g fresh cheese","½ cup milk","2 tbsp ají amarillo paste (or ½ yellow pepper)","4 crackers","4 eggs","1 head lettuce","8 black olives (optional)"],"es":["1 kg papas","200 g queso fresco","½ taza leche","2 cdas pasta de ají amarillo (o ½ morrón amarillo)","4 galletitas","4 huevos","1 planta de lechuga","8 aceitunas negras (opcional)"]},"steps":{"en":["Boil the potatoes and the eggs; slice.","Blend cheese, milk, ají and crackers into a smooth sauce.","Lay potatoes on lettuce, pour the sauce over and add egg and olives."],"es":["Herví las papas y los huevos; cortá en rodajas.","Licuá el queso, la leche, el ají y las galletitas hasta tener una salsa lisa.","Acomodá las papas sobre lechuga, bañá con la salsa y sumá huevo y aceitunas."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"quinua-con-leche","type":"breakfast","country":"PE","group":"grain","tags":["oats"],"name":{"en":"Quinoa Porridge with Apple & Cinnamon","es":"Quinua con leche, manzana y canela"},"ing":{"en":["1 cup quinoa, rinsed","3 cups milk","2 apples, diced","1 cinnamon stick","2 tbsp raisins"],"es":["1 taza quinoa lavada","3 tazas leche","2 manzanas en cubos","1 rama de canela","2 cdas pasas de uva"]},"steps":{"en":["Simmer the quinoa in 2 cups water for 12 min.","Add the milk, apple and cinnamon and cook 10 min until creamy.","Stir in the raisins and serve warm."],"es":["Cociná la quinoa en 2 tazas de agua 12 min.","Sumá la leche, la manzana y la canela y cociná 10 min, hasta que esté cremosa.","Incorporá las pasas y serví tibio."]},"tip":{"en":"","es":""},"prep":["quinoa"]},
{"id":"mazamorra-morada","type":"snack","country":"PE","group":"fruit","name":{"en":"Mazamorra Morada: Purple Corn & Fruit Pudding","es":"Mazamorra morada"},"ing":{"en":["200 g purple corn (or 4 cups purple corn drink)","Peel and core of 1 pineapple (or 1 cup pineapple)","2 apples, diced","½ cup dried apricots, chopped","3 tbsp sweet potato starch or cornstarch","1 cinnamon stick","¼ cup sugar"],"es":["200 g maíz morado (o 4 tazas de chicha morada)","Cáscara y centro de 1 ananá (o 1 taza de ananá)","2 manzanas en cubos","½ taza orejones picados","3 cdas almidón de batata o maicena","1 rama de canela","¼ taza azúcar"]},"steps":{"en":["Boil the purple corn with the pineapple peel and cinnamon in 6 cups water for 40 min; strain.","Add apple, apricots and sugar and simmer 10 min.","Thicken with the starch mixed in a little cold water; serve warm or cold."],"es":["Herví el maíz morado con la cáscara de ananá y la canela en 6 tazas de agua 40 min; colá.","Sumá la manzana, los orejones y el azúcar y cociná 10 min.","Espesá con el almidón disuelto en un poco de agua fría; serví tibia o fría."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"saltenas","type":"lunch","country":"BO","protein":"beef","base":"bread","tags":["empanadas"],"name":{"en":"Salteñas (Juicy Baked Empanadas)","es":"Salteñas"},"ing":{"en":["12 empanada discs","400 g beef, finely diced","2 potatoes, finely diced","½ cup frozen peas","1 onion, chopped","1 tsp paprika","1 tsp ground cumin","1 cup beef broth","1 tbsp gelatine powder"],"es":["12 tapas de empanadas","400 g carne picada a cuchillo","2 papas en cubitos","½ taza arvejas congeladas","1 cebolla picada","1 cdita pimentón","1 cdita comino","1 taza caldo de carne","1 cda gelatina sin sabor"]},"steps":{"en":["Cook the beef, onion and spices; add potatoes, peas and broth and simmer 15 min.","Stir in the gelatine and chill until set.","Fill the discs, seal on top and bake at 220°C for 18 min."],"es":["Cociná la carne con la cebolla y las especias; sumá papas, arvejas y caldo y cociná 15 min.","Incorporá la gelatina y enfriá hasta que tome cuerpo.","Rellená las tapas, cerrá arriba con repulgue y horneá a 220°C 18 min."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"sopa-de-mani","type":"dinner","country":"BO","protein":"beef","base":"potato","tags":["soup"],"name":{"en":"Bolivian Peanut Soup","es":"Sopa de maní boliviana"},"ing":{"en":["400 g beef, diced","½ cup raw peanuts, blended with 1 cup water","2 potatoes, diced","1 carrot, diced","½ cup frozen peas","½ cup pasta (small shapes)","6 cups beef broth","2 tbsp fresh parsley, chopped"],"es":["400 g carne en cubos","½ taza maní crudo licuado con 1 taza de agua","2 papas en cubos","1 zanahoria en cubos","½ taza arvejas congeladas","½ taza fideos chicos","6 tazas caldo de carne","2 cdas perejil fresco picado"]},"steps":{"en":["Simmer the beef in the broth for 40 min.","Add the peanut milk, potatoes and carrot; cook 15 min, stirring.","Add peas and pasta for 8 min; serve with parsley."],"es":["Cociná la carne en el caldo 40 min.","Sumá la leche de maní, las papas y la zanahoria; cociná 15 min, revolviendo.","Agregá las arvejas y los fideos 8 min; serví con perejil."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"api-morado","type":"breakfast","country":"BO","group":"grain","name":{"en":"Api Morado (Warm Purple Corn Drink) with Cheese Pastries","es":"Api morado con pastelitos de queso"},"ing":{"en":["1 cup purple corn flour (or cornflour)","1 cinnamon stick","2 tbsp sugar","4 cups water","4 cheese empanadas (or cheese scones)","2 oranges"],"es":["1 taza harina de maíz morado (o maicena)","1 rama de canela","2 cdas azúcar","4 tazas agua","4 empanadas o scones de queso","2 naranjas"]},"steps":{"en":["Simmer the water with cinnamon.","Whisk in the corn flour mixed with cold water; cook 10 min, stirring, until thick; sweeten lightly.","Serve warm with the cheese pastries and orange."],"es":["Herví el agua con la canela.","Sumá la harina disuelta en agua fría y cociná 10 min revolviendo, hasta que espese; endulzá apenas.","Serví caliente con los pastelitos y naranja."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"chipa","type":"snack","country":"PY","group":"grain","name":{"en":"Chipá (Cheese Bread Rings)","es":"Chipá"},"ing":{"en":["2 cups tapioca starch","200 g hard cheese, grated","2 eggs","50 g butter, soft","¼ cup milk","1 tsp anise seeds (optional)"],"es":["2 tazas almidón de mandioca","200 g queso duro rallado","2 huevos","50 g manteca blanda","¼ taza leche","1 cdita anís en grano (opcional)"]},"steps":{"en":["Mix the butter and eggs, then the cheese, starch and anise.","Add milk until it forms a soft dough; shape small rings or balls.","Bake at 200°C for 20 min."],"es":["Mezclá la manteca con los huevos y después el queso, el almidón y el anís.","Sumá leche hasta formar una masa blanda; formá roscas o bolitas.","Horneá a 200°C 20 min."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"sopa-paraguaya","type":"lunch","country":"PY","protein":"plant","base":"bread","name":{"en":"Sopa Paraguaya (Cheesy Cornbread) with Salad","es":"Sopa paraguaya con ensalada"},"ing":{"en":["2 cups cornmeal","2 onions, chopped","200 g fresh cheese, crumbled","4 eggs","1½ cups milk","50 g butter","1 head lettuce","2 tomatoes"],"es":["2 tazas harina de maíz","2 cebollas picadas","200 g queso fresco desmenuzado","4 huevos","1½ tazas leche","50 g manteca","1 planta de lechuga","2 tomates"]},"steps":{"en":["Soften the onions in the butter.","Mix with the cornmeal, cheese, eggs and milk into a thick batter.","Bake in a buttered tin at 200°C for 40 min; serve with salad."],"es":["Rehogá las cebollas en la manteca.","Mezclá con la harina de maíz, el queso, los huevos y la leche hasta tener una pasta espesa.","Horneá en fuente enmantecada a 200°C 40 min; serví con ensalada."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"vori-vori","type":"dinner","country":"PY","protein":"poultry","base":"none","tags":["soup"],"name":{"en":"Vori Vori: Chicken Soup with Corn & Cheese Dumplings","es":"Vori vori"},"ing":{"en":["4 chicken thighs","1 onion, chopped","1 carrot, diced","6 cups chicken broth","1 cup cornmeal","100 g fresh cheese, grated","1 egg","2 tbsp fresh parsley, chopped"],"es":["4 muslos de pollo","1 cebolla picada","1 zanahoria en cubos","6 tazas caldo de pollo","1 taza harina de maíz","100 g queso fresco rallado","1 huevo","2 cdas perejil fresco picado"]},"steps":{"en":["Simmer the chicken, onion and carrot in the broth for 30 min; shred the chicken.","Mix cornmeal, cheese, egg and a splash of hot broth; roll into small balls.","Drop the balls into the simmering soup for 10 min; add parsley."],"es":["Cociná el pollo, la cebolla y la zanahoria en el caldo 30 min; desmenuzá el pollo.","Mezclá la harina de maíz, el queso, el huevo y un chorrito de caldo caliente; formá bolitas.","Echá las bolitas en la sopa 10 min; sumá perejil."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"feijoada","type":"dinner","country":"BR","protein":"pork","base":"rice","tags":["stew"],"name":{"en":"Feijoada (Black Bean & Pork Stew)","es":"Feijoada"},"ing":{"en":["2 cans black beans","400 g pork shoulder, diced","2 pork sausages, sliced","1 onion, chopped","3 garlic cloves, minced","2 bay leaves","1½ cups rice","2 oranges","1 bunch kale"],"es":["2 latas porotos negros","400 g bondiola de cerdo en cubos","2 chorizos en rodajas","1 cebolla picada","3 dientes de ajo picados","2 hojas de laurel","1½ tazas arroz","2 naranjas","1 atado de kale o col"]},"steps":{"en":["Brown the pork and sausage with onion and garlic.","Add the beans with their liquid, bay leaves and 1 cup water; simmer 1 hour.","Serve with rice, sautéed shredded kale and orange slices."],"es":["Dorá el cerdo y el chorizo con la cebolla y el ajo.","Sumá los porotos con su líquido, el laurel y 1 taza de agua; cociná 1 hora.","Serví con arroz, col salteada en tiras y rodajas de naranja."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"moqueca-de-peixe","type":"dinner","country":"BR","protein":"fish","base":"rice","tags":["stew"],"name":{"en":"Moqueca: Brazilian Fish & Coconut Stew","es":"Moqueca de pescado"},"ing":{"en":["700 g firm white fish, in chunks","1 can coconut milk","1 onion, sliced","2 bell peppers, sliced","3 tomatoes, sliced","2 limes","2 tbsp fresh cilantro, chopped","1½ cups rice"],"es":["700 g pescado blanco firme en trozos","1 lata leche de coco","1 cebolla en pluma","2 morrones en tiras","3 tomates en rodajas","2 limas","2 cdas cilantro fresco picado","1½ tazas arroz"]},"steps":{"en":["Marinate the fish in lime juice and salt for 15 min.","Layer onion, peppers, tomato and fish in a pot; pour the coconut milk over.","Cover and simmer 15 min; add cilantro and serve with rice."],"es":["Mariná el pescado con jugo de lima y sal 15 min.","Armá capas de cebolla, morrón, tomate y pescado; volcá la leche de coco.","Tapá y cociná 15 min; sumá cilantro y serví con arroz."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"pao-de-queijo","type":"snack","country":"BR","group":"grain","name":{"en":"Pão de Queijo","es":"Pão de queijo"},"ing":{"en":["2 cups tapioca starch","½ cup milk","¼ cup sunflower oil","2 eggs","1 cup grated parmesan"],"es":["2 tazas almidón de mandioca","½ taza leche","¼ taza aceite de girasol","2 huevos","1 taza queso parmesano rallado"]},"steps":{"en":["Bring the milk, oil and a pinch of salt to a boil and pour over the starch; stir.","When warm, beat in the eggs and cheese.","Roll into small balls and bake at 200°C for 20 min."],"es":["Herví la leche con el aceite y una pizca de sal y volcá sobre el almidón; mezclá.","Cuando esté tibio, incorporá los huevos y el queso.","Formá bolitas y horneá a 200°C 20 min."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"arroz-feijao-e-bife","type":"lunch","country":"BR","protein":"beef","base":"rice","name":{"en":"Rice, Beans & Steak with Salad","es":"Arroz, porotos y bife con ensalada"},"ing":{"en":["1½ cups rice","2 cans black beans","2 garlic cloves, minced","4 thin beef steaks","1 head lettuce","2 tomatoes","1 tbsp olive oil"],"es":["1½ tazas arroz","2 latas porotos negros","2 dientes de ajo picados","4 bifes finos","1 planta de lechuga","2 tomates","1 cda aceite de oliva"]},"steps":{"en":["Cook the rice.","Warm the beans with the garlic and a little of their liquid.","Sear the steaks 2 min a side; serve with rice, beans and salad."],"es":["Cociná el arroz.","Calentá los porotos con el ajo y un poco de su líquido.","Cociná los bifes 2 min por lado; serví con arroz, porotos y ensalada."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"frango-ensopado","type":"lunch","country":"BR","protein":"poultry","base":"rice","tags":["stew"],"name":{"en":"Brazilian Chicken Stew","es":"Pollo ensopado brasileño"},"ing":{"en":["800 g chicken thighs","1 onion, chopped","2 tomatoes, chopped","2 potatoes, diced","1 carrot, diced","1 tsp turmeric","2 tbsp fresh parsley, chopped","1½ cups rice"],"es":["800 g muslos de pollo","1 cebolla picada","2 tomates picados","2 papas en cubos","1 zanahoria en cubos","1 cdita cúrcuma","2 cdas perejil fresco picado","1½ tazas arroz"]},"steps":{"en":["Brown the chicken with onion and turmeric.","Add tomatoes, potatoes, carrot and 1 cup water; simmer 30 min.","Serve with rice and parsley."],"es":["Dorá el pollo con la cebolla y la cúrcuma.","Sumá el tomate, las papas, la zanahoria y 1 taza de agua; cociná 30 min.","Serví con arroz y perejil."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"tapioca-com-queijo","type":"breakfast","country":"BR","group":"grain","name":{"en":"Tapioca Crêpes with Cheese & Tomato","es":"Tapioca con queso y tomate"},"ing":{"en":["2 cups tapioca starch","½ cup water","150 g mozzarella, grated","2 tomatoes, sliced","2 bananas"],"es":["2 tazas almidón de mandioca","½ taza agua","150 g mozzarella rallada","2 tomates en rodajas","2 bananas"]},"steps":{"en":["Sprinkle the starch with the water and rub until it looks like damp sand; sieve.","Spread a thin layer in a dry pan; cook 1 min until it sets.","Fill with cheese and tomato, fold and serve with banana."],"es":["Humedecé el almidón con el agua y frotá hasta que parezca arena húmeda; tamizá.","Esparcí una capa fina en una sartén seca; cociná 1 min hasta que se una.","Rellená con queso y tomate, doblá y serví con banana."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"bolo-de-cenoura","type":"snack","country":"BR","group":"grain","tags":["cake"],"name":{"en":"Brazilian Carrot Cake","es":"Torta de zanahoria brasileña"},"ing":{"en":["3 carrots","3 eggs","½ cup sunflower oil","¾ cup sugar","2 cups flour","1 tbsp baking powder","2 tbsp cocoa powder"],"es":["3 zanahorias","3 huevos","½ taza aceite de girasol","¾ taza azúcar","2 tazas harina","1 cda polvo para hornear","2 cdas cacao en polvo"]},"steps":{"en":["Blend the carrots, eggs, oil and sugar until smooth.","Fold in the flour and baking powder; bake at 180°C for 35 min.","Dust with cocoa."],"es":["Licuá las zanahorias, los huevos, el aceite y el azúcar.","Incorporá la harina y el polvo de hornear; horneá a 180°C 35 min.","Espolvoreá con cacao."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"vitamina-de-abacate","type":"breakfast","country":"BR","group":"fruit","tags":["smoothie"],"name":{"en":"Avocado & Banana Vitamina with Toast","es":"Vitamina de palta y banana con tostadas"},"ing":{"en":["1 ripe avocado","2 bananas","3 cups milk","1 tbsp honey (optional)","8 slices bread"],"es":["1 palta madura","2 bananas","3 tazas leche","1 cda miel (opcional)","8 rebanadas de pan"]},"steps":{"en":["Blend the avocado, bananas and milk until creamy.","Sweeten with honey if you like.","Serve with toast."],"es":["Licuá la palta, las bananas y la leche hasta que esté cremoso.","Endulzá con miel si querés.","Serví con tostadas."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"arepas-con-queso","type":"breakfast","country":"CO","group":"grain","tags":["arepa"],"name":{"en":"Arepas with Cheese","es":"Arepas con queso"},"ing":{"en":["2 cups precooked corn flour (arepa flour)","2½ cups warm water","150 g mozzarella, grated","1 tbsp butter","2 cups milk"],"es":["2 tazas harina de maíz precocida","2½ tazas agua tibia","150 g mozzarella rallada","1 cda manteca","2 tazas leche"]},"steps":{"en":["Mix the flour, water and a pinch of salt into a soft dough; rest 5 min.","Shape 8 thick discs and cook in a buttered pan 6 min a side.","Split and fill with cheese; serve with warm milk."],"es":["Mezclá la harina, el agua y una pizca de sal hasta tener una masa blanda; dejá reposar 5 min.","Formá 8 discos gruesos y cociná en sartén con manteca 6 min por lado.","Abrilas y rellená con queso; serví con leche tibia."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"changua","type":"breakfast","country":"CO","group":"egg","name":{"en":"Changua: Milk & Egg Breakfast Soup","es":"Changua"},"ing":{"en":["2 cups milk","2 cups water","4 eggs","2 spring onions, sliced","2 tbsp fresh cilantro, chopped","4 slices bread"],"es":["2 tazas leche","2 tazas agua","4 huevos","2 cebollas de verdeo en rodajas","2 cdas cilantro fresco picado","4 rebanadas de pan"]},"steps":{"en":["Bring the milk, water and spring onion to a simmer.","Crack the eggs in one by one and poach 4 min.","Serve over torn bread with cilantro."],"es":["Calentá la leche, el agua y el verdeo hasta que hierva suave.","Rompé los huevos de a uno y cocinalos 4 min.","Serví sobre pan en trozos con cilantro."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"ajiaco","type":"lunch","country":"CO","protein":"poultry","base":"potato","tags":["soup"],"name":{"en":"Ajiaco: Chicken & Three-Potato Soup","es":"Ajiaco"},"ing":{"en":["600 g chicken breast","1 kg mixed potatoes (yellow and white)","2 corn cobs, in rounds","6 cups chicken broth","1 tbsp dried guascas or oregano","½ cup cream","1 avocado"],"es":["600 g pechuga de pollo","1 kg papas variadas (amarillas y blancas)","2 choclos en rodajas","6 tazas caldo de pollo","1 cda guascas secas u orégano","½ taza crema de leche","1 palta"]},"steps":{"en":["Simmer the chicken in the broth for 20 min; shred.","Add the potatoes, corn and herbs and simmer 30 min until some potatoes melt.","Return the chicken; serve with cream and avocado."],"es":["Cociná el pollo en el caldo 20 min; desmenuzalo.","Sumá las papas, el choclo y las hierbas y cociná 30 min, hasta que parte de las papas se deshaga.","Volvé a poner el pollo; serví con crema y palta."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"pescado-frito-con-arroz-con-coco","type":"dinner","country":"CO","protein":"fish","base":"rice","name":{"en":"Crispy Fish with Coconut Rice & Plantain","es":"Pescado con arroz con coco y patacón"},"ing":{"en":["4 white fish fillets","2 tbsp flour","1½ cups rice","1 can coconut milk","2 green plantains","2 limes","3 tbsp sunflower oil"],"es":["4 filetes de pescado blanco","2 cdas harina","1½ tazas arroz","1 lata leche de coco","2 plátanos verdes","2 limas","3 cdas aceite de girasol"]},"steps":{"en":["Cook the rice in the coconut milk plus 1 cup water for 18 min.","Fry thick plantain rounds, flatten and fry again until crisp.","Dust the fish in flour and fry 3 min a side; serve with lime."],"es":["Cociná el arroz en la leche de coco más 1 taza de agua 18 min.","Freí rodajas gruesas de plátano, aplastalas y freilas otra vez hasta que estén crocantes.","Pasá el pescado por harina y freí 3 min por lado; serví con lima."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"patacones-con-hogao","type":"snack","country":"CO","group":"veg","name":{"en":"Patacones with Hogao (Tomato & Onion Sauce)","es":"Patacones con hogao"},"ing":{"en":["3 green plantains","2 tomatoes, chopped","3 spring onions, sliced","3 tbsp sunflower oil"],"es":["3 plátanos verdes","2 tomates picados","3 cebollas de verdeo en rodajas","3 cdas aceite de girasol"]},"steps":{"en":["Fry thick plantain rounds 3 min, flatten with a plate and fry again until golden.","Cook the tomato and spring onion in a little oil for 10 min into a sauce.","Serve the patacones with the hogao on top."],"es":["Freí rodajas gruesas de plátano 3 min, aplastalas con un plato y freilas de nuevo hasta dorar.","Cociná el tomate y el verdeo en un poco de aceite 10 min, hasta formar una salsa.","Serví los patacones con el hogao arriba."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"arepa-reina-pepiada","type":"lunch","country":"VE","protein":"poultry","base":"bread","tags":["arepa"],"name":{"en":"Arepas Reina Pepiada (Chicken & Avocado)","es":"Arepas reina pepiada"},"ing":{"en":["2 cups precooked corn flour (arepa flour)","2½ cups warm water","400 g chicken breast, poached and shredded","2 ripe avocados","2 tbsp mayonnaise","1 lime","2 tbsp fresh cilantro, chopped"],"es":["2 tazas harina de maíz precocida","2½ tazas agua tibia","400 g pechuga de pollo hervida y desmenuzada","2 paltas maduras","2 cdas mayonesa","1 lima","2 cdas cilantro fresco picado"]},"steps":{"en":["Make 8 arepas: knead flour, water and salt, shape discs and cook 6 min a side in a pan.","Mash the avocado with mayonnaise, lime and cilantro; stir in the chicken.","Split the arepas and fill generously."],"es":["Hacé 8 arepas: amasá la harina con el agua y sal, formá discos y cociná 6 min por lado.","Pisá la palta con la mayonesa, la lima y el cilantro; sumá el pollo.","Abrí las arepas y rellenalas bien."]},"tip":{"en":"","es":""},"prep":["cook-chicken"]},
{"id":"pabellon-criollo","type":"dinner","country":"VE","protein":"beef","base":"rice","name":{"en":"Pabellón Criollo","es":"Pabellón criollo"},"ing":{"en":["600 g beef chuck","1 onion, chopped","1 red bell pepper, chopped","1 can crushed tomatoes","2 cans black beans","1½ cups rice","2 ripe plantains"],"es":["600 g carne para guiso","1 cebolla picada","1 morrón rojo picado","1 lata tomate triturado","2 latas porotos negros","1½ tazas arroz","2 plátanos maduros"]},"steps":{"en":["Simmer the beef in water for 1½ hours until it shreds; shred.","Cook the onion, pepper and tomato, add the beef and simmer 15 min.","Serve with rice, warm black beans and fried ripe plantain."],"es":["Herví la carne 1½ horas, hasta que se deshilache; desmechala.","Rehogá la cebolla, el morrón y el tomate, sumá la carne y cociná 15 min.","Serví con arroz, porotos negros calientes y plátano maduro frito."]},"tip":{"en":"","es":""},"prep":["cook-ahead"]},
{"id":"cachapas","type":"breakfast","country":"VE","group":"grain","tags":["pancakes"],"name":{"en":"Cachapas (Sweet Corn Pancakes) with Cheese","es":"Cachapas con queso"},"ing":{"en":["4 cups corn","½ cup cornmeal","1 egg","¼ cup milk","1 tbsp butter","150 g fresh cheese, sliced"],"es":["4 tazas choclo","½ taza harina de maíz","1 huevo","¼ taza leche","1 cda manteca","150 g queso fresco en fetas"]},"steps":{"en":["Blend the corn, cornmeal, egg and milk into a thick batter.","Cook large pancakes in a buttered pan, 3 min a side.","Fold over slices of cheese."],"es":["Licuá el choclo, la harina de maíz, el huevo y la leche hasta tener una pasta espesa.","Cociná panqueques grandes en sartén con manteca, 3 min por lado.","Doblalos sobre fetas de queso."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"tequenos","type":"snack","country":"VE","group":"grain","name":{"en":"Baked Tequeños (Cheese Sticks)","es":"Tequeños al horno"},"ing":{"en":["300 g puff pastry","250 g mozzarella or fresh cheese, in sticks","1 egg"],"es":["300 g masa de hojaldre","250 g mozzarella o queso fresco en bastones","1 huevo"]},"steps":{"en":["Cut the pastry into long strips.","Wrap each cheese stick in a spiral of pastry and brush with egg.","Bake at 210°C for 15 min until golden."],"es":["Cortá la masa en tiras largas.","Envolvé cada bastón de queso en espiral y pincelá con huevo.","Horneá a 210°C 15 min, hasta dorar."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"locro-de-papa","type":"lunch","country":"EC","protein":"plant","base":"potato","tags":["soup"],"name":{"en":"Locro de Papa: Potato & Cheese Soup","es":"Locro de papa"},"ing":{"en":["1 kg potatoes, diced","1 onion, chopped","1 tsp paprika","4 cups vegetable broth","1 cup milk","150 g fresh cheese, diced","1 avocado"],"es":["1 kg papas en cubos","1 cebolla picada","1 cdita pimentón","4 tazas caldo de verduras","1 taza leche","150 g queso fresco en cubos","1 palta"]},"steps":{"en":["Soften the onion with the paprika.","Add potatoes and broth and simmer 25 min; mash half the potatoes.","Stir in milk and cheese; serve with avocado."],"es":["Rehogá la cebolla con el pimentón.","Sumá las papas y el caldo y cociná 25 min; pisá la mitad de las papas.","Agregá la leche y el queso; serví con palta."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"encebollado","type":"dinner","country":"EC","protein":"fish","base":"potato","tags":["soup"],"name":{"en":"Encebollado: Tuna, Cassava & Onion Soup","es":"Encebollado"},"ing":{"en":["600 g fresh tuna or bonito","600 g cassava (yuca), peeled and diced","2 tomatoes","1 tsp ground cumin","2 red onions, thinly sliced","3 limes","2 tbsp fresh cilantro, chopped"],"es":["600 g atún fresco o bonito","600 g mandioca pelada en cubos","2 tomates","1 cdita comino","2 cebollas moradas en pluma fina","3 limas","2 cdas cilantro fresco picado"]},"steps":{"en":["Simmer the fish with tomatoes, cumin and 6 cups water for 15 min; lift the fish out and flake.","Cook the cassava in the broth until tender.","Return the fish; serve topped with onion pickled in lime and cilantro."],"es":["Cociná el pescado con los tomates, el comino y 6 tazas de agua 15 min; sacalo y desmenuzalo.","Cociná la mandioca en el caldo hasta que esté tierna.","Volvé a poner el pescado; serví con cebolla curtida en lima y cilantro."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"bolon-de-verde","type":"breakfast","country":"EC","group":"grain","name":{"en":"Bolón de Verde (Plantain & Cheese Balls) with Eggs","es":"Bolón de verde con huevo"},"ing":{"en":["4 green plantains","150 g fresh cheese, crumbled","1 tbsp butter","4 eggs"],"es":["4 plátanos verdes","150 g queso fresco desmenuzado","1 cda manteca","4 huevos"]},"steps":{"en":["Boil the plantains in chunks for 20 min; mash with butter and cheese.","Shape 8 balls and brown in a pan.","Serve with fried eggs."],"es":["Herví los plátanos en trozos 20 min; pisalos con la manteca y el queso.","Formá 8 bolas y doralas en sartén.","Serví con huevos fritos."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"chilaquiles-verdes","type":"breakfast","country":"MX","group":"egg","tags":["tortilla"],"name":{"en":"Chilaquiles Verdes with Egg","es":"Chilaquiles verdes con huevo"},"ing":{"en":["12 corn tortillas, cut into triangles","1½ cups green salsa (tomatillo)","4 eggs","½ cup sour cream","100 g fresh cheese, crumbled","1 red onion, thinly sliced","2 tbsp sunflower oil"],"es":["12 tortillas de maíz en triángulos","1½ tazas salsa verde","4 huevos","½ taza crema agria","100 g queso fresco desmenuzado","1 cebolla morada en pluma fina","2 cdas aceite de girasol"]},"steps":{"en":["Toss the tortilla triangles in oil and bake at 200°C for 12 min until crisp.","Warm the salsa and toss the chips in it briefly.","Top with fried eggs, cream, cheese and onion."],"es":["Mezclá los triángulos con aceite y horneá a 200°C 12 min, hasta que estén crocantes.","Calentá la salsa y pasá los totopos un momento.","Terminá con huevos fritos, crema, queso y cebolla."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"huevos-rancheros","type":"breakfast","country":"MX","group":"egg","tags":["tortilla"],"name":{"en":"Huevos Rancheros","es":"Huevos rancheros"},"ing":{"en":["8 corn tortillas","4 eggs","1 can black beans","1 can crushed tomatoes","1 onion, chopped","1 avocado","2 tbsp fresh cilantro, chopped"],"es":["8 tortillas de maíz","4 huevos","1 lata porotos negros","1 lata tomate triturado","1 cebolla picada","1 palta","2 cdas cilantro fresco picado"]},"steps":{"en":["Simmer the onion and tomatoes for 10 min into a ranchera sauce.","Warm the tortillas and beans; fry the eggs.","Layer tortilla, beans, egg and sauce; add avocado and cilantro."],"es":["Cociná la cebolla con el tomate 10 min para la salsa ranchera.","Calentá las tortillas y los porotos; freí los huevos.","Armá tortilla, porotos, huevo y salsa; sumá palta y cilantro."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"pozole-verde-de-pollo","type":"lunch","country":"MX","protein":"poultry","base":"none","tags":["soup"],"name":{"en":"Green Chicken Pozole","es":"Pozole verde de pollo"},"ing":{"en":["600 g chicken breast","2 cans hominy, drained","1½ cups green salsa (tomatillo)","6 cups chicken broth","¼ cabbage, shredded","4 radishes, sliced","2 limes"],"es":["600 g pechuga de pollo","2 latas maíz pozolero escurrido","1½ tazas salsa verde","6 tazas caldo de pollo","¼ repollo en juliana","4 rabanitos en rodajas","2 limas"]},"steps":{"en":["Simmer the chicken in the broth for 20 min; shred.","Add the hominy and salsa and simmer 15 min.","Serve with cabbage, radish and lime on top."],"es":["Cociná el pollo en el caldo 20 min; desmenuzalo.","Sumá el maíz y la salsa verde y cociná 15 min.","Serví con repollo, rabanito y lima arriba."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"tostadas-de-tinga","type":"lunch","country":"MX","protein":"poultry","base":"bread","tags":["tortilla"],"name":{"en":"Chicken Tinga Tostadas","es":"Tostadas de tinga de pollo"},"ing":{"en":["500 g chicken breast","1 onion, sliced","1 can crushed tomatoes","1 tsp smoked paprika","8 corn tortillas","1 can black beans","2 cups lettuce, shredded","½ cup sour cream"],"es":["500 g pechuga de pollo","1 cebolla en pluma","1 lata tomate triturado","1 cdita pimentón ahumado","8 tortillas de maíz","1 lata porotos negros","2 tazas lechuga en tiras","½ taza crema agria"]},"steps":{"en":["Poach and shred the chicken.","Cook the onion, add tomatoes and paprika, then the chicken; simmer 10 min.","Bake the tortillas until crisp; spread with beans and top with tinga, lettuce and cream."],"es":["Herví y desmenuzá el pollo.","Rehogá la cebolla, sumá el tomate y el pimentón y después el pollo; cociná 10 min.","Horneá las tortillas hasta que estén crocantes; untá con porotos y cubrí con tinga, lechuga y crema."]},"tip":{"en":"","es":""},"prep":["cook-chicken"]},
{"id":"sopa-de-tortilla","type":"lunch","country":"MX","protein":"plant","base":"bread","tags":["soup"],"name":{"en":"Tortilla Soup","es":"Sopa de tortilla"},"ing":{"en":["8 corn tortillas, cut into strips","1 can crushed tomatoes","1 onion, chopped","2 garlic cloves","6 cups vegetable broth","1 avocado, diced","100 g fresh cheese, diced","½ cup sour cream"],"es":["8 tortillas de maíz en tiras","1 lata tomate triturado","1 cebolla picada","2 dientes de ajo","6 tazas caldo de verduras","1 palta en cubos","100 g queso fresco en cubos","½ taza crema agria"]},"steps":{"en":["Bake the tortilla strips at 200°C for 10 min until crisp.","Blend tomato, onion and garlic, fry 5 min, add the broth and simmer 15 min.","Serve over the tortilla strips with avocado, cheese and cream."],"es":["Horneá las tiras de tortilla a 200°C 10 min, hasta que estén crocantes.","Licuá el tomate, la cebolla y el ajo, freí 5 min, sumá el caldo y cociná 15 min.","Serví sobre las tiras con palta, queso y crema."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"cochinita-pibil","type":"dinner","country":"MX","protein":"pork","base":"bread","tags":["tacos"],"name":{"en":"Cochinita Pibil Tacos","es":"Tacos de cochinita pibil"},"ing":{"en":["1 kg pork shoulder, in chunks","3 tbsp achiote paste","2 oranges (juice)","2 limes","2 garlic cloves","1 tsp ground cumin","12 corn tortillas","1 red onion, thinly sliced"],"es":["1 kg bondiola en trozos","3 cdas pasta de achiote","2 naranjas (jugo)","2 limas","2 dientes de ajo","1 cdita comino","12 tortillas de maíz","1 cebolla morada en pluma fina"]},"steps":{"en":["Blend the achiote with orange and lime juice, garlic and cumin; rub over the pork and marinate 2 hours.","Cover tightly and bake at 160°C for 3 hours until it falls apart.","Shred and serve in warm tortillas with onion pickled in lime."],"es":["Licuá el achiote con el jugo de naranja y lima, el ajo y el comino; untá el cerdo y dejá marinar 2 horas.","Tapá bien y horneá a 160°C 3 horas, hasta que se deshaga.","Desmenuzá y serví en tortillas calientes con cebolla curtida en lima."]},"tip":{"en":"","es":""},"prep":["marinate","cook-ahead"]},
{"id":"pescado-a-la-veracruzana","type":"dinner","country":"MX","protein":"fish","base":"rice","name":{"en":"Fish Veracruz-Style","es":"Pescado a la veracruzana"},"ing":{"en":["4 white fish fillets","1 onion, sliced","2 garlic cloves, minced","1 can crushed tomatoes","¼ cup green olives","1 tbsp capers","2 bay leaves","1½ cups rice"],"es":["4 filetes de pescado blanco","1 cebolla en pluma","2 dientes de ajo picados","1 lata tomate triturado","¼ taza aceitunas verdes","1 cda alcaparras","2 hojas de laurel","1½ tazas arroz"]},"steps":{"en":["Soften onion and garlic, add tomatoes, olives, capers and bay; simmer 10 min.","Nestle the fish in the sauce, cover and cook 8 min.","Serve with rice."],"es":["Rehogá la cebolla y el ajo, sumá el tomate, las aceitunas, las alcaparras y el laurel; cociná 10 min.","Acomodá el pescado en la salsa, tapá y cociná 8 min.","Serví con arroz."]},"tip":{"en":"","es":""},"prep":["rice"]},
{"id":"mole-con-pollo","type":"dinner","country":"MX","protein":"poultry","base":"rice","name":{"en":"Chicken in Mole Sauce","es":"Pollo con mole"},"ing":{"en":["1 kg chicken thighs","½ cup mole paste","3 cups chicken broth","1 tbsp sesame seeds","1½ cups rice","8 corn tortillas"],"es":["1 kg muslos de pollo","½ taza pasta de mole","3 tazas caldo de pollo","1 cda semillas de sésamo","1½ tazas arroz","8 tortillas de maíz"]},"steps":{"en":["Simmer the chicken in the broth for 25 min.","Dissolve the mole paste in 2 cups of the hot broth and simmer 10 min until glossy.","Pour over the chicken, sprinkle with sesame and serve with rice and tortillas."],"es":["Cociná el pollo en el caldo 25 min.","Disolvé la pasta de mole en 2 tazas del caldo caliente y cociná 10 min, hasta que brille.","Bañá el pollo, espolvoreá con sésamo y serví con arroz y tortillas."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"esquites","type":"snack","country":"MX","group":"veg","name":{"en":"Esquites (Corn Cups with Lime & Cheese)","es":"Esquites"},"ing":{"en":["4 cups corn","1 tbsp butter","2 tbsp mayonnaise","2 limes","4 tbsp fresh cheese, crumbled","½ tsp chili powder (optional)"],"es":["4 tazas choclo","1 cda manteca","2 cdas mayonesa","2 limas","4 cdas queso fresco desmenuzado","½ cdita ají molido (opcional)"]},"steps":{"en":["Sauté the corn in the butter for 5 min.","Stir in mayonnaise and lime juice.","Serve in cups topped with cheese and a pinch of chili."],"es":["Salteá el choclo en la manteca 5 min.","Incorporá la mayonesa y el jugo de lima.","Serví en vasitos con queso y una pizca de ají."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"fruta-con-chile-y-limon","type":"snack","country":"MX","group":"fruit","name":{"en":"Mango, Cucumber & Jícama with Lime","es":"Mango, pepino y jícama con limón"},"ing":{"en":["2 mangoes","1 cucumber","1 jícama or 4 radishes","2 limes","½ tsp chili powder (optional)"],"es":["2 mangos","1 pepino","1 jícama o 4 rabanitos","2 limas","½ cdita ají molido (opcional)"]},"steps":{"en":["Cut the fruit and vegetables into sticks.","Squeeze lime over.","Sprinkle chili for the grown-ups."],"es":["Cortá la fruta y las verduras en bastones.","Exprimí lima por encima.","Espolvoreá ají para los grandes."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"ropa-vieja","type":"dinner","country":"CU","protein":"beef","base":"rice","name":{"en":"Ropa Vieja with Rice & Black Beans","es":"Ropa vieja con arroz y porotos negros"},"ing":{"en":["700 g beef flank or chuck","1 onion, sliced","2 bell peppers, sliced","1 can crushed tomatoes","1 tsp ground cumin","1½ cups rice","1 can black beans"],"es":["700 g falda o carne para guiso","1 cebolla en pluma","2 morrones en tiras","1 lata tomate triturado","1 cdita comino","1½ tazas arroz","1 lata porotos negros"]},"steps":{"en":["Simmer the beef in water for 1½ hours; shred.","Cook the onion and peppers, add tomatoes, cumin and the beef; simmer 20 min.","Serve with rice and warm black beans."],"es":["Herví la carne 1½ horas; desmechala.","Rehogá la cebolla y los morrones, sumá el tomate, el comino y la carne; cociná 20 min.","Serví con arroz y porotos negros calientes."]},"tip":{"en":"","es":""},"prep":["cook-ahead"]},
{"id":"congri-con-maduros","type":"lunch","country":"CU","protein":"plant","base":"rice","name":{"en":"Congrí (Rice & Black Beans) with Sweet Plantains","es":"Congrí con plátanos maduros"},"ing":{"en":["1½ cups rice","2 cans black beans","1 onion, chopped","1 green bell pepper, chopped","2 garlic cloves, minced","1 tsp ground cumin","3 ripe plantains"],"es":["1½ tazas arroz","2 latas porotos negros","1 cebolla picada","1 morrón verde picado","2 dientes de ajo picados","1 cdita comino","3 plátanos maduros"]},"steps":{"en":["Soften the onion, pepper and garlic with the cumin.","Add rice, beans with their liquid and 2 cups water; cover and cook 20 min.","Fry thick slices of ripe plantain until caramelised and serve alongside."],"es":["Rehogá la cebolla, el morrón y el ajo con el comino.","Sumá el arroz, los porotos con su líquido y 2 tazas de agua; tapá y cociná 20 min.","Freí rodajas gruesas de plátano maduro hasta que se caramelicen y serví al lado."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"jerk-chicken","type":"dinner","country":"JM","protein":"poultry","base":"rice","name":{"en":"Jerk Chicken with Rice & Peas","es":"Pollo jerk con arroz y porotos"},"ing":{"en":["1 kg chicken thighs","4 spring onions","2 garlic cloves","1 tsp ground allspice","1 tsp dried thyme","2 tbsp soy sauce","1 lime","1½ cups rice","1 can kidney beans","1 can coconut milk"],"es":["1 kg muslos de pollo","4 cebollas de verdeo","2 dientes de ajo","1 cdita pimienta de Jamaica molida","1 cdita tomillo seco","2 cdas salsa de soja","1 lima","1½ tazas arroz","1 lata porotos colorados","1 lata leche de coco"]},"steps":{"en":["Blend spring onion, garlic, allspice, thyme, soy and lime; marinate the chicken 1 hour.","Roast at 200°C for 35 min.","Cook the rice with the beans, coconut milk and 1 cup water for 20 min."],"es":["Licuá el verdeo, el ajo, la pimienta de Jamaica, el tomillo, la soja y la lima; mariná el pollo 1 hora.","Horneá a 200°C 35 min.","Cociná el arroz con los porotos, la leche de coco y 1 taza de agua 20 min."]},"tip":{"en":"","es":""},"prep":["marinate"]},
{"id":"cornmeal-porridge","type":"breakfast","country":"JM","group":"grain","tags":["oats"],"name":{"en":"Jamaican Cornmeal Porridge","es":"Porridge jamaiquino de harina de maíz"},"ing":{"en":["1 cup fine cornmeal","3 cups milk","1 cup water","1 cinnamon stick","¼ tsp nutmeg","2 bananas"],"es":["1 taza harina de maíz fina","3 tazas leche","1 taza agua","1 rama de canela","¼ cdita nuez moscada","2 bananas"]},"steps":{"en":["Whisk the cornmeal into the cold water.","Bring the milk and cinnamon to a simmer, whisk in the cornmeal and cook 10 min, stirring.","Finish with nutmeg and sliced banana."],"es":["Disolvé la harina de maíz en el agua fría.","Calentá la leche con la canela, sumá la harina y cociná 10 min revolviendo.","Terminá con nuez moscada y banana en rodajas."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"banana-fritters","type":"snack","country":"JM","group":"fruit","name":{"en":"Banana Fritters","es":"Buñuelos de banana"},"ing":{"en":["3 ripe bananas","¾ cup flour","1 egg","½ tsp cinnamon","1 tsp baking powder","2 tbsp sunflower oil"],"es":["3 bananas maduras","¾ taza harina","1 huevo","½ cdita canela","1 cdita polvo para hornear","2 cdas aceite de girasol"]},"steps":{"en":["Mash the bananas and mix in the egg, flour, cinnamon and baking powder.","Fry spoonfuls in a little oil, 2 min a side.","Drain and serve warm."],"es":["Pisá las bananas y mezclá con el huevo, la harina, la canela y el polvo de hornear.","Freí cucharadas en poco aceite, 2 min por lado.","Escurrí y serví tibios."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"new-england-fish-chowder","type":"lunch","country":"US","protein":"fish","base":"potato","tags":["soup"],"name":{"en":"New England Fish Chowder","es":"Chowder de pescado estilo Nueva Inglaterra"},"ing":{"en":["500 g white fish fillets, in chunks","3 potatoes, diced","1 onion, chopped","2 celery stalks, sliced","2 cups milk","2 cups vegetable broth","1 tbsp butter","1 cup corn","8 crackers"],"es":["500 g filet de pescado blanco en trozos","3 papas en cubos","1 cebolla picada","2 tallos de apio en rodajas","2 tazas leche","2 tazas caldo de verduras","1 cda manteca","1 taza choclo","8 galletitas"]},"steps":{"en":["Soften onion and celery in the butter; add potatoes and broth and simmer 12 min.","Add the milk, corn and fish and simmer gently 6 min.","Serve with crackers."],"es":["Rehogá la cebolla y el apio en la manteca; sumá las papas y el caldo y cociná 12 min.","Agregá la leche, el choclo y el pescado y cociná suave 6 min.","Serví con galletitas."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"cobb-salad","type":"lunch","country":"US","protein":"poultry","base":"none","name":{"en":"Cobb Salad","es":"Ensalada Cobb"},"ing":{"en":["500 g chicken breast","4 eggs","1 head lettuce","2 tomatoes, diced","1 avocado, diced","100 g cheddar cheese, diced","4 slices bacon (optional)","3 tbsp olive oil","1 tbsp vinegar"],"es":["500 g pechuga de pollo","4 huevos","1 planta de lechuga","2 tomates en cubos","1 palta en cubos","100 g queso cheddar en cubos","4 fetas de panceta (opcional)","3 cdas aceite de oliva","1 cda vinagre"]},"steps":{"en":["Grill the chicken 6 min a side and dice; boil the eggs 9 min and chop.","Arrange lettuce with rows of chicken, egg, tomato, avocado, cheese and bacon.","Dress with oil and vinegar."],"es":["Cociná la pechuga a la plancha 6 min por lado y cortala en cubos; herví los huevos 9 min y picalos.","Acomodá la lechuga con filas de pollo, huevo, tomate, palta, queso y panceta.","Condimentá con aceite y vinagre."]},"tip":{"en":"","es":""},"prep":["cook-chicken"]},
{"id":"sloppy-joes","type":"dinner","country":"US","protein":"beef","base":"bread","name":{"en":"Sloppy Joes with Coleslaw","es":"Sloppy joes con ensalada de repollo"},"ing":{"en":["500 g ground beef","1 onion, chopped","1 green bell pepper, chopped","1 can crushed tomatoes","1 tbsp Worcestershire sauce","1 tbsp Dijon mustard","4 burger buns","2 cups coleslaw mix","2 tbsp mayonnaise"],"es":["500 g carne picada","1 cebolla picada","1 morrón verde picado","1 lata tomate triturado","1 cda salsa inglesa","1 cda mostaza Dijon","4 panes de hamburguesa","2 tazas repollo y zanahoria rallados","2 cdas mayonesa"]},"steps":{"en":["Brown the beef with onion and pepper.","Add tomatoes, Worcestershire and mustard; simmer 15 min until thick.","Spoon into buns; serve with coleslaw dressed with mayonnaise."],"es":["Dorá la carne con la cebolla y el morrón.","Sumá el tomate, la salsa inglesa y la mostaza; cociná 15 min, hasta que espese.","Rellená los panes; serví con el repollo condimentado con mayonesa."]},"tip":{"en":"","es":""},"prep":["brown-beef"]},
{"id":"chicken-pot-pie","type":"dinner","country":"US","protein":"poultry","base":"bread","tags":["pie"],"name":{"en":"Chicken Pot Pie","es":"Pastel de pollo y verduras"},"ing":{"en":["600 g chicken breast, diced","2 carrots, diced","1 cup frozen peas","1 onion, chopped","2 tbsp butter","3 tbsp flour","1½ cups chicken broth","½ cup milk","1 pie crust"],"es":["600 g pechuga de pollo en cubos","2 zanahorias en cubos","1 taza arvejas congeladas","1 cebolla picada","2 cdas manteca","3 cdas harina","1½ tazas caldo de pollo","½ taza leche","1 tapa de tarta"]},"steps":{"en":["Cook onion and carrot in butter; add chicken and brown lightly.","Stir in flour, then broth and milk; simmer until thick and add peas.","Pour into a dish, cover with the crust and bake at 200°C for 25 min."],"es":["Rehogá la cebolla y la zanahoria en manteca; sumá el pollo y dorá apenas.","Incorporá la harina, después el caldo y la leche; cociná hasta que espese y sumá las arvejas.","Volcá en una fuente, tapá con la masa y horneá a 200°C 25 min."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"ants-on-a-log","type":"snack","country":"US","group":"veg","tags":["nut-butter"],"name":{"en":"Ants on a Log","es":"Hormiguitas en el tronco"},"ing":{"en":["4 celery stalks","4 tbsp peanut butter","2 tbsp raisins"],"es":["4 tallos de apio","4 cdas mantequilla de maní","2 cdas pasas de uva"]},"steps":{"en":["Cut the celery into 8 cm lengths.","Fill the groove with peanut butter.","Dot with raisins."],"es":["Cortá el apio en trozos de 8 cm.","Rellená la canaleta con mantequilla de maní.","Poné pasas encima."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"sweet-potato-hash-with-eggs","type":"breakfast","country":"US","group":"egg","name":{"en":"Sweet Potato Hash with Eggs","es":"Salteado de batata con huevos"},"ing":{"en":["2 sweet potatoes, diced small","1 red bell pepper, diced","1 onion, diced","4 eggs","2 tbsp olive oil","1 tsp paprika"],"es":["2 batatas en cubitos","1 morrón rojo en cubitos","1 cebolla en cubitos","4 huevos","2 cdas aceite de oliva","1 cdita pimentón"]},"steps":{"en":["Fry the sweet potato in the oil for 12 min, stirring, until tender.","Add pepper, onion and paprika and cook 5 min.","Make 4 hollows, crack in the eggs, cover and cook until set."],"es":["Freí la batata en el aceite 12 min, revolviendo, hasta que esté tierna.","Sumá el morrón, la cebolla y el pimentón y cociná 5 min.","Hacé 4 huecos, rompé los huevos, tapá y cociná hasta que cuajen."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"grilled-cheese-and-tomato-soup","type":"lunch","country":"US","protein":"plant","base":"bread","tags":["soup"],"name":{"en":"Grilled Cheese & Tomato Soup","es":"Sándwich de queso con sopa de tomate"},"ing":{"en":["2 cans crushed tomatoes","1 onion, chopped","2 cups vegetable broth","½ cup milk","8 slices bread","200 g cheddar cheese, sliced","1 tbsp butter"],"es":["2 latas tomate triturado","1 cebolla picada","2 tazas caldo de verduras","½ taza leche","8 rebanadas de pan","200 g queso cheddar en fetas","1 cda manteca"]},"steps":{"en":["Soften the onion, add tomatoes and broth and simmer 15 min; blend with the milk.","Make cheese sandwiches, butter the outside and toast in a pan until melted.","Cut into strips for dipping."],"es":["Rehogá la cebolla, sumá el tomate y el caldo y cociná 15 min; licuá con la leche.","Armá sándwiches de queso, untá con manteca por fuera y tostá en sartén hasta que se derrita.","Cortá en tiras para mojar."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"maple-glazed-salmon","type":"dinner","country":"CA","protein":"fish","base":"rice","tags":["salmon"],"name":{"en":"Maple-Glazed Salmon with Rice & Green Beans","es":"Salmón glaseado con arce, arroz y chauchas"},"ing":{"en":["4 salmon fillets","3 tbsp maple syrup","2 tbsp soy sauce","1 tbsp Dijon mustard","1½ cups rice","300 g green beans"],"es":["4 filetes de salmón","3 cdas jarabe de arce","2 cdas salsa de soja","1 cda mostaza Dijon","1½ tazas arroz","300 g chauchas"]},"steps":{"en":["Whisk maple syrup, soy and mustard; brush over the salmon.","Roast at 200°C for 12 min.","Serve with rice and steamed green beans."],"es":["Batí el jarabe de arce, la soja y la mostaza; pincelá el salmón.","Horneá a 200°C 12 min.","Serví con arroz y chauchas al vapor."]},"tip":{"en":"","es":""},"prep":["rice"]},
{"id":"habitant-pea-soup","type":"lunch","country":"CA","protein":"pork","base":"bread","tags":["soup"],"name":{"en":"Québec Yellow Pea Soup with Ham","es":"Sopa de arvejas amarillas con jamón"},"ing":{"en":["2 cups yellow split peas","150 g cooked ham, diced","1 onion, chopped","2 carrots, diced","2 celery stalks, diced","8 cups water","1 bay leaf","4 slices bread"],"es":["2 tazas arvejas partidas amarillas","150 g jamón cocido en cubos","1 cebolla picada","2 zanahorias en cubos","2 tallos de apio en cubos","8 tazas agua","1 hoja de laurel","4 rebanadas de pan"]},"steps":{"en":["Rinse the peas and simmer with the vegetables, bay leaf and water for 1½ hours.","Stir in the ham for the last 10 min.","Serve with bread."],"es":["Lavá las arvejas y cociná con las verduras, el laurel y el agua 1½ horas.","Sumá el jamón los últimos 10 min.","Serví con pan."]},"tip":{"en":"","es":""},"prep":["cook-ahead"]},
{"id":"blueberry-maple-oats","type":"breakfast","country":"CA","group":"grain","tags":["oats"],"name":{"en":"Blueberry Maple Oatmeal","es":"Avena con arándanos y jarabe de arce"},"ing":{"en":["1½ cups rolled oats","3 cups milk","1 cup blueberries","2 tbsp maple syrup","2 tbsp seeds (sunflower or pumpkin)"],"es":["1½ tazas avena arrollada","3 tazas leche","1 taza arándanos","2 cdas jarabe de arce","2 cdas semillas (girasol o zapallo)"]},"steps":{"en":["Simmer the oats in the milk for 5 min.","Stir in half the blueberries until they burst.","Top with the rest, maple syrup and seeds."],"es":["Cociná la avena en la leche 5 min.","Incorporá la mitad de los arándanos hasta que revienten.","Terminá con el resto, el jarabe de arce y las semillas."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"bangers-and-mash","type":"dinner","country":"GB","protein":"pork","base":"potato","tags":["sausages"],"name":{"en":"Bangers & Mash with Onion Gravy","es":"Salchichas con puré y salsa de cebolla"},"ing":{"en":["8 pork sausages","1 kg potatoes","½ cup milk","1 tbsp butter","2 onions, sliced","1 tbsp flour","1½ cups beef broth","2 cups frozen peas"],"es":["8 salchichas de cerdo","1 kg papas","½ taza leche","1 cda manteca","2 cebollas en pluma","1 cda harina","1½ tazas caldo de carne","2 tazas arvejas congeladas"]},"steps":{"en":["Bake the sausages at 200°C for 25 min.","Boil and mash the potatoes with milk and butter; cook the peas.","Cook the onions slowly for 15 min, stir in flour and broth and simmer into gravy."],"es":["Horneá las salchichas a 200°C 25 min.","Herví las papas y hacé puré con la leche y la manteca; cociná las arvejas.","Cociná las cebollas despacio 15 min, sumá la harina y el caldo y cociná hasta tener una salsa."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"kedgeree","type":"lunch","country":"GB","protein":"fish","base":"rice","name":{"en":"Kedgeree (Smoked Fish & Egg Rice)","es":"Kedgeree: arroz con pescado ahumado y huevo"},"ing":{"en":["400 g smoked or white fish fillets","1½ cups rice","1 onion, chopped","1 tbsp curry powder","4 eggs","1 tbsp butter","2 tbsp fresh parsley, chopped","1 lemon"],"es":["400 g filet de pescado ahumado o blanco","1½ tazas arroz","1 cebolla picada","1 cda curry en polvo","4 huevos","1 cda manteca","2 cdas perejil fresco picado","1 limón"]},"steps":{"en":["Poach the fish in water for 6 min; flake. Boil the eggs 8 min and quarter.","Soften the onion in butter with the curry; stir in the rice and 3 cups of the fish water; cook 18 min.","Fold in fish, eggs, parsley and lemon juice."],"es":["Cociná el pescado en agua 6 min y desmenuzalo. Herví los huevos 8 min y cortalos en cuartos.","Rehogá la cebolla en manteca con el curry; sumá el arroz y 3 tazas del agua del pescado; cociná 18 min.","Incorporá el pescado, los huevos, el perejil y el jugo de limón."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"beans-on-toast","type":"breakfast","country":"GB","group":"grain","tags":["toast"],"name":{"en":"Beans on Toast with Grilled Tomatoes","es":"Porotos sobre tostadas con tomates grillados"},"ing":{"en":["2 cans baked beans","8 slices whole-grain bread","4 tomatoes, halved","1 tbsp butter","50 g cheddar cheese, grated"],"es":["2 latas porotos en salsa de tomate","8 rebanadas de pan integral","4 tomates en mitades","1 cda manteca","50 g queso cheddar rallado"]},"steps":{"en":["Grill the tomatoes cut side up for 6 min.","Warm the beans.","Spoon over buttered toast and sprinkle with cheddar."],"es":["Grillá los tomates con el corte hacia arriba 6 min.","Calentá los porotos.","Serví sobre tostadas con manteca y espolvoreá con cheddar."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"scones-with-jam","type":"snack","country":"GB","group":"grain","name":{"en":"Scones with Jam & Cream","es":"Scones con mermelada y crema"},"ing":{"en":["2 cups flour","1 tbsp baking powder","50 g butter, cold","2 tbsp sugar","¾ cup milk","4 tbsp strawberry jam","½ cup cream"],"es":["2 tazas harina","1 cda polvo para hornear","50 g manteca fría","2 cdas azúcar","¾ taza leche","4 cdas mermelada de frutilla","½ taza crema de leche"]},"steps":{"en":["Rub butter into flour, baking powder and sugar; stir in milk to a soft dough.","Pat out 3 cm thick, cut rounds and bake at 220°C for 12 min.","Serve split with a little jam and whipped cream."],"es":["Desmenuzá la manteca con la harina, el polvo de hornear y el azúcar; sumá la leche hasta tener una masa blanda.","Aplaná de 3 cm, cortá círculos y horneá a 220°C 12 min.","Serví abiertos con un poco de mermelada y crema batida."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"irish-stew","type":"dinner","country":"IE","protein":"beef","base":"potato","tags":["stew"],"name":{"en":"Irish Stew","es":"Estofado irlandés"},"ing":{"en":["700 g lamb or beef stewing meat, diced","1 kg potatoes, in chunks","3 carrots, sliced","2 onions, sliced","4 cups beef broth","1 tsp dried thyme","2 tbsp fresh parsley, chopped"],"es":["700 g cordero o carne para guiso en cubos","1 kg papas en trozos","3 zanahorias en rodajas","2 cebollas en pluma","4 tazas caldo de carne","1 cdita tomillo seco","2 cdas perejil fresco picado"]},"steps":{"en":["Brown the meat; add onions, carrots, thyme and broth.","Simmer covered for 1 hour.","Add potatoes and cook 30 min more; finish with parsley."],"es":["Dorá la carne; sumá la cebolla, la zanahoria, el tomillo y el caldo.","Cociná tapado 1 hora.","Agregá las papas y cociná 30 min más; terminá con perejil."]},"tip":{"en":"","es":""},"prep":["cook-ahead"]},
{"id":"colcannon-with-sausages","type":"lunch","country":"IE","protein":"pork","base":"potato","tags":["sausages"],"name":{"en":"Colcannon with Sausages","es":"Colcannon con salchichas"},"ing":{"en":["1 kg potatoes","¼ cabbage, finely shredded","3 spring onions, sliced","½ cup milk","2 tbsp butter","8 pork sausages"],"es":["1 kg papas","¼ repollo en juliana fina","3 cebollas de verdeo en rodajas","½ taza leche","2 cdas manteca","8 salchichas de cerdo"]},"steps":{"en":["Boil the potatoes and mash with milk and butter.","Soften the cabbage and spring onion in a little butter; fold into the mash.","Serve with oven-baked sausages."],"es":["Herví las papas y pisalas con la leche y la manteca.","Rehogá el repollo y el verdeo con un poco de manteca; incorporalos al puré.","Serví con salchichas al horno."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"irish-soda-bread","type":"snack","country":"IE","group":"grain","name":{"en":"Soda Bread with Cheese","es":"Pan de soda irlandés con queso"},"ing":{"en":["3 cups flour","1 tsp baking soda","1½ cups plain yogurt","½ cup milk","100 g cheddar cheese, sliced"],"es":["3 tazas harina","1 cdita bicarbonato de sodio","1½ tazas yogur natural","½ taza leche","100 g queso cheddar en fetas"]},"steps":{"en":["Mix flour, soda and a pinch of salt; stir in yogurt and milk to a sticky dough.","Shape a round, cut a deep cross and bake at 210°C for 35 min.","Serve slices with cheese."],"es":["Mezclá la harina, el bicarbonato y una pizca de sal; sumá el yogur y la leche hasta tener una masa pegajosa.","Formá un pan redondo, hacé una cruz profunda y horneá a 210°C 35 min.","Serví en rebanadas con queso."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"ratatouille","type":"lunch","country":"FR","protein":"plant","base":"bread","name":{"en":"Ratatouille with Crusty Bread","es":"Ratatouille con pan"},"ing":{"en":["1 eggplant, diced","2 zucchini, diced","2 bell peppers, diced","1 onion, chopped","2 garlic cloves, minced","1 can crushed tomatoes","1 tsp dried thyme","3 tbsp olive oil","1 baguette"],"es":["1 berenjena en cubos","2 zapallitos en cubos","2 morrones en cubos","1 cebolla picada","2 dientes de ajo picados","1 lata tomate triturado","1 cdita tomillo seco","3 cdas aceite de oliva","1 baguette"]},"steps":{"en":["Soften onion and garlic in the oil; add eggplant and peppers and cook 10 min.","Add zucchini, tomatoes and thyme and simmer 25 min.","Serve warm with bread."],"es":["Rehogá la cebolla y el ajo en el aceite; sumá la berenjena y los morrones y cociná 10 min.","Agregá los zapallitos, el tomate y el tomillo y cociná 25 min.","Serví tibio con pan."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"quiche-lorraine","type":"lunch","country":"FR","protein":"pork","base":"bread","tags":["tart"],"name":{"en":"Quiche Lorraine with Green Salad","es":"Quiche lorraine con ensalada verde"},"ing":{"en":["1 pie crust","150 g bacon, diced","4 eggs","1 cup cream","½ cup milk","100 g gruyère or mild cheese, grated","¼ tsp nutmeg","1 head lettuce"],"es":["1 tapa de tarta","150 g panceta en cubos","4 huevos","1 taza crema de leche","½ taza leche","100 g queso gruyère o de máquina rallado","¼ cdita nuez moscada","1 planta de lechuga"]},"steps":{"en":["Line a tart tin with the crust and bake blind at 200°C for 10 min.","Fry the bacon; scatter over the base with the cheese.","Whisk eggs, cream, milk and nutmeg, pour in and bake at 180°C for 30 min; serve with salad."],"es":["Forrá una tartera con la masa y precociná a 200°C 10 min.","Dorá la panceta; repartila sobre la base con el queso.","Batí los huevos, la crema, la leche y la nuez moscada, volcá y horneá a 180°C 30 min; serví con ensalada."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"salade-nicoise","type":"lunch","country":"FR","protein":"fish","base":"potato","tags":["tuna"],"name":{"en":"Salade Niçoise","es":"Ensalada nizarda"},"ing":{"en":["2 cans tuna, drained","500 g baby potatoes","300 g green beans","4 eggs","2 tomatoes, in wedges","¼ cup black olives","1 head lettuce","3 tbsp olive oil","1 tsp Dijon mustard"],"es":["2 latas atún escurrido","500 g papines","300 g chauchas","4 huevos","2 tomates en gajos","¼ taza aceitunas negras","1 planta de lechuga","3 cdas aceite de oliva","1 cdita mostaza Dijon"]},"steps":{"en":["Boil the potatoes 15 min, the green beans 4 min and the eggs 8 min.","Whisk oil, mustard and a splash of vinegar or lemon.","Arrange everything on lettuce and dress."],"es":["Herví los papines 15 min, las chauchas 4 min y los huevos 8 min.","Batí el aceite con la mostaza y un chorrito de vinagre o limón.","Acomodá todo sobre lechuga y condimentá."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"moules-frites","type":"dinner","country":"FR","protein":"fish","base":"potato","name":{"en":"Moules-Frites (Mussels with Oven Fries)","es":"Mejillones con papas fritas al horno"},"ing":{"en":["1.5 kg mussels, cleaned","2 shallots, chopped","2 garlic cloves, minced","½ cup white wine","2 tbsp butter","3 tbsp fresh parsley, chopped","1 kg potatoes, cut into fries","2 tbsp sunflower oil"],"es":["1,5 kg mejillones limpios","2 echalotes picados","2 dientes de ajo picados","½ taza vino blanco","2 cdas manteca","3 cdas perejil fresco picado","1 kg papas en bastones","2 cdas aceite de girasol"]},"steps":{"en":["Toss the fries in oil and bake at 220°C for 35 min.","Soften shallot and garlic in butter, add wine and mussels, cover and steam 5 min until open (discard closed ones).","Sprinkle with parsley and serve with the fries."],"es":["Mezclá las papas con el aceite y horneá a 220°C 35 min.","Rehogá el echalote y el ajo en manteca, sumá el vino y los mejillones, tapá y cociná 5 min hasta que se abran (descartá los cerrados).","Espolvoreá con perejil y serví con las papas."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"poulet-basquaise","type":"dinner","country":"FR","protein":"poultry","base":"rice","tags":["stew"],"name":{"en":"Basque Chicken with Peppers","es":"Pollo a la vasca con morrones"},"ing":{"en":["1 kg chicken thighs","3 bell peppers (mixed colours), sliced","1 onion, sliced","2 garlic cloves, minced","1 can crushed tomatoes","1 tsp paprika","1½ cups rice"],"es":["1 kg muslos de pollo","3 morrones de colores en tiras","1 cebolla en pluma","2 dientes de ajo picados","1 lata tomate triturado","1 cdita pimentón","1½ tazas arroz"]},"steps":{"en":["Brown the chicken and set aside.","Soften onion, peppers and garlic; add tomatoes, paprika and the chicken.","Cover and simmer 35 min; serve with rice."],"es":["Dorá el pollo y reservá.","Rehogá la cebolla, los morrones y el ajo; sumá el tomate, el pimentón y el pollo.","Tapá y cociná 35 min; serví con arroz."]},"tip":{"en":"","es":""},"prep":["rice"]},
{"id":"soupe-a-loignon","type":"dinner","country":"FR","protein":"plant","base":"bread","tags":["soup"],"name":{"en":"French Onion Soup with Cheese Toasts","es":"Sopa de cebolla gratinada"},"ing":{"en":["1 kg onions, thinly sliced","2 tbsp butter","1 tbsp flour","6 cups vegetable broth","1 tsp dried thyme","1 baguette, sliced","150 g gruyère or mild cheese, grated"],"es":["1 kg cebollas en pluma fina","2 cdas manteca","1 cda harina","6 tazas caldo de verduras","1 cdita tomillo seco","1 baguette en rodajas","150 g queso gruyère o de máquina rallado"]},"steps":{"en":["Cook the onions in butter over low heat for 40 min until deep golden.","Stir in flour, then broth and thyme; simmer 20 min.","Ladle into bowls, float bread topped with cheese and grill until bubbling."],"es":["Cociná las cebollas en manteca a fuego bajo 40 min, hasta que estén bien doradas.","Sumá la harina, después el caldo y el tomillo; cociná 20 min.","Serví en cazuelas, poné pan con queso arriba y gratiná."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"clafoutis-aux-cerises","type":"snack","country":"FR","group":"fruit","name":{"en":"Cherry (or Peach) Clafoutis","es":"Clafoutis de cerezas (o duraznos)"},"ing":{"en":["2 cups cherries, pitted (or peaches, sliced)","3 eggs","1 cup milk","½ cup flour","3 tbsp sugar","1 tsp vanilla extract"],"es":["2 tazas cerezas sin carozo (o duraznos en láminas)","3 huevos","1 taza leche","½ taza harina","3 cdas azúcar","1 cdita esencia de vainilla"]},"steps":{"en":["Scatter the fruit in a buttered dish.","Whisk eggs, milk, flour, sugar and vanilla into a batter and pour over.","Bake at 190°C for 30 min until puffed."],"es":["Repartí la fruta en una fuente enmantecada.","Batí los huevos, la leche, la harina, el azúcar y la vainilla y volcá encima.","Horneá a 190°C 30 min, hasta que se infle."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"tartine-et-chocolat-chaud","type":"breakfast","country":"FR","group":"grain","tags":["toast"],"name":{"en":"Tartines & Hot Chocolate","es":"Tartines con chocolate caliente"},"ing":{"en":["1 baguette","2 tbsp butter","4 tbsp apricot jam","3 cups milk","2 tbsp cocoa powder","2 pears"],"es":["1 baguette","2 cdas manteca","4 cdas mermelada de damasco","3 tazas leche","2 cdas cacao en polvo","2 peras"]},"steps":{"en":["Split the baguette into lengths and toast.","Spread with butter and a little jam.","Whisk the cocoa into hot milk; serve with pear slices."],"es":["Cortá la baguette a lo largo y tostala.","Untá con manteca y un poco de mermelada.","Batí el cacao en la leche caliente; serví con peras en rodajas."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"tortilla-espanola","type":"lunch","country":"ES","protein":"egg","base":"potato","name":{"en":"Spanish Tortilla with Tomato Salad","es":"Tortilla española con ensalada de tomate"},"ing":{"en":["6 eggs","800 g potatoes, thinly sliced","1 onion, thinly sliced","½ cup olive oil","3 tomatoes"],"es":["6 huevos","800 g papas en láminas finas","1 cebolla en pluma fina","½ taza aceite de oliva","3 tomates"]},"steps":{"en":["Cook the potatoes and onion slowly in the oil for 20 min until soft; drain.","Mix with the beaten eggs and pour into a hot pan with a little oil; cook 5 min.","Flip with a plate, cook 3 min more and serve with sliced tomatoes."],"es":["Cociná las papas y la cebolla despacio en el aceite 20 min, hasta que estén tiernas; escurrí.","Mezclá con los huevos batidos y volcá en una sartén caliente con un poco de aceite; cociná 5 min.","Dala vuelta con un plato, cociná 3 min más y serví con tomates en rodajas."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"gazpacho-con-pan","type":"lunch","country":"ES","protein":"plant","base":"bread","tags":["soup"],"name":{"en":"Gazpacho with Bread & Boiled Eggs","es":"Gazpacho con pan y huevo duro"},"ing":{"en":["1 kg ripe tomatoes","1 cucumber","1 green bell pepper","1 garlic clove","2 slices bread","4 tbsp olive oil","1 tbsp vinegar","4 eggs"],"es":["1 kg tomates maduros","1 pepino","1 morrón verde","1 diente de ajo","2 rebanadas de pan","4 cdas aceite de oliva","1 cda vinagre","4 huevos"]},"steps":{"en":["Blend tomatoes, cucumber, pepper, garlic and soaked bread until smooth.","Blend in oil, vinegar and salt; chill well.","Serve with chopped boiled egg and more bread."],"es":["Licuá los tomates, el pepino, el morrón, el ajo y el pan remojado hasta que quede liso.","Licuá con el aceite, el vinagre y sal; enfriá bien.","Serví con huevo duro picado y más pan."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"paella-de-mariscos","type":"dinner","country":"ES","protein":"fish","base":"rice","name":{"en":"Seafood Paella","es":"Paella de mariscos"},"ing":{"en":["2 cups short-grain rice","300 g shrimp","300 g mussels, cleaned","300 g squid rings","1 onion, chopped","1 red bell pepper, chopped","2 tomatoes, grated","1 tsp paprika","5 cups fish or vegetable broth","1 pinch saffron or turmeric"],"es":["2 tazas arroz de grano corto","300 g langostinos","300 g mejillones limpios","300 g rabas de calamar","1 cebolla picada","1 morrón rojo picado","2 tomates rallados","1 cdita pimentón","5 tazas caldo de pescado o de verduras","1 pizca de azafrán o cúrcuma"]},"steps":{"en":["Fry onion, pepper and squid in a wide pan; add tomato and paprika.","Add the rice, stir, then the hot broth and saffron; cook 15 min without stirring.","Press in the shrimp and mussels and cook 6 min more; rest 5 min."],"es":["Saltá la cebolla, el morrón y el calamar en una paellera; sumá el tomate y el pimentón.","Sumá el arroz, revolvé y agregá el caldo caliente con el azafrán; cociná 15 min sin revolver.","Acomodá los langostinos y los mejillones y cociná 6 min más; dejá reposar 5 min."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"merluza-en-salsa-verde","type":"dinner","country":"ES","protein":"fish","base":"potato","name":{"en":"Hake in Green Sauce with Potatoes","es":"Merluza en salsa verde con papas"},"ing":{"en":["4 hake fillets","3 garlic cloves, sliced","1 tbsp flour","½ cup white wine","1 cup fish or vegetable broth","4 tbsp fresh parsley, chopped","3 tbsp olive oil","800 g potatoes"],"es":["4 filetes de merluza","3 dientes de ajo en láminas","1 cda harina","½ taza vino blanco","1 taza caldo de pescado o de verduras","4 cdas perejil fresco picado","3 cdas aceite de oliva","800 g papas"]},"steps":{"en":["Boil the potatoes in thick slices.","Warm garlic in the oil, stir in flour, then wine and broth; simmer 3 min.","Add the hake and parsley, shake the pan gently and cook 6 min; serve with the potatoes."],"es":["Herví las papas en rodajas gruesas.","Calentá el ajo en el aceite, sumá la harina y después el vino y el caldo; cociná 3 min.","Agregá la merluza y el perejil, mové la sartén suavemente y cociná 6 min; serví con las papas."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"albondigas-en-salsa","type":"dinner","country":"ES","protein":"beef","base":"potato","tags":["meatballs"],"name":{"en":"Spanish Meatballs in Tomato Sauce with Potatoes","es":"Albóndigas en salsa con papas"},"ing":{"en":["500 g ground beef","1 egg","½ cup breadcrumbs","2 garlic cloves, minced","1 onion, chopped","1 can crushed tomatoes","1 tsp paprika","800 g potatoes"],"es":["500 g carne picada","1 huevo","½ taza pan rallado","2 dientes de ajo picados","1 cebolla picada","1 lata tomate triturado","1 cdita pimentón","800 g papas"]},"steps":{"en":["Mix beef, egg, breadcrumbs and garlic; roll into small balls and brown.","Soften the onion, add tomatoes and paprika, then the meatballs; simmer 20 min.","Serve with boiled or roast potatoes."],"es":["Mezclá la carne con el huevo, el pan rallado y el ajo; formá bolitas y doralas.","Rehogá la cebolla, sumá el tomate y el pimentón y después las albóndigas; cociná 20 min.","Serví con papas hervidas o al horno."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"pan-con-tomate","type":"breakfast","country":"ES","group":"grain","tags":["toast"],"name":{"en":"Pan con Tomate & Fresh Cheese","es":"Pan con tomate y queso fresco"},"ing":{"en":["8 slices crusty bread","3 ripe tomatoes","3 tbsp olive oil","150 g fresh cheese","2 cups milk"],"es":["8 rebanadas de pan de campo","3 tomates maduros","3 cdas aceite de oliva","150 g queso fresco","2 tazas leche"]},"steps":{"en":["Toast the bread.","Grate the tomatoes and spoon the pulp over with oil and a pinch of salt.","Serve with fresh cheese and milk."],"es":["Tostá el pan.","Rallá los tomates y poné la pulpa encima con aceite y una pizca de sal.","Serví con queso fresco y leche."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"churros-con-chocolate","type":"snack","country":"ES","group":"grain","name":{"en":"Baked Churros with Hot Chocolate","es":"Churros al horno con chocolate"},"ing":{"en":["1 cup water","50 g butter","1 cup flour","2 eggs","1 tsp cinnamon","2 tbsp sugar","2 cups milk","2 tbsp cocoa powder"],"es":["1 taza agua","50 g manteca","1 taza harina","2 huevos","1 cdita canela","2 cdas azúcar","2 tazas leche","2 cdas cacao en polvo"]},"steps":{"en":["Boil water and butter, beat in the flour, then the eggs one at a time.","Pipe strips onto a tray and bake at 200°C for 20 min; roll in cinnamon sugar.","Whisk the cocoa into hot milk for dipping."],"es":["Herví el agua con la manteca, sumá la harina batiendo y después los huevos de a uno.","Formá tiras con manga sobre una placa y horneá a 200°C 20 min; pasalos por azúcar con canela.","Batí el cacao en la leche caliente para mojar."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"croquetas-de-jamon","type":"lunch","country":"ES","protein":"pork","base":"bread","name":{"en":"Ham Croquettes with Salad","es":"Croquetas de jamón con ensalada"},"ing":{"en":["3 tbsp butter","½ cup flour","2 cups milk","150 g cooked ham, finely chopped","2 eggs","1½ cups breadcrumbs","¼ tsp nutmeg","1 head lettuce"],"es":["3 cdas manteca","½ taza harina","2 tazas leche","150 g jamón cocido bien picado","2 huevos","1½ tazas pan rallado","¼ cdita nuez moscada","1 planta de lechuga"]},"steps":{"en":["Make a thick white sauce with butter, flour, milk and nutmeg; stir in the ham and chill 2 hours.","Shape croquettes, dip in egg and breadcrumbs.","Bake at 210°C for 18 min, turning once; serve with salad."],"es":["Hacé una salsa blanca espesa con la manteca, la harina, la leche y la nuez moscada; sumá el jamón y enfriá 2 horas.","Formá croquetas y pasalas por huevo y pan rallado.","Horneá a 210°C 18 min, dando vuelta una vez; serví con ensalada."]},"tip":{"en":"","es":""},"prep":["chill-ahead"]},
{"id":"bacalhau-a-bras","type":"dinner","country":"PT","protein":"fish","base":"potato","name":{"en":"Bacalhau à Brás (Cod, Potato & Egg)","es":"Bacalao a la Brás"},"ing":{"en":["500 g salt cod, soaked 24 h (or fresh cod)","500 g potatoes, cut into very thin sticks","1 onion, sliced","6 eggs","3 tbsp olive oil","¼ cup black olives","2 tbsp fresh parsley, chopped"],"es":["500 g bacalao desalado 24 h (o bacalao fresco)","500 g papas en bastones muy finos","1 cebolla en pluma","6 huevos","3 cdas aceite de oliva","¼ taza aceitunas negras","2 cdas perejil fresco picado"]},"steps":{"en":["Bake the potato sticks with a little oil at 220°C for 20 min until crisp.","Soften the onion in oil, add the flaked cod and cook 5 min; add the potatoes.","Stir in the beaten eggs until just creamy; finish with olives and parsley."],"es":["Horneá los bastones con un poco de aceite a 220°C 20 min, hasta que estén crocantes.","Rehogá la cebolla en aceite, sumá el bacalao desmenuzado y cociná 5 min; agregá las papas.","Incorporá los huevos batidos hasta que estén apenas cremosos; terminá con aceitunas y perejil."]},"tip":{"en":"","es":""},"prep":["soak"]},
{"id":"caldo-verde","type":"lunch","country":"PT","protein":"pork","base":"potato","tags":["soup"],"name":{"en":"Caldo Verde (Potato & Kale Soup)","es":"Caldo verde"},"ing":{"en":["800 g potatoes, diced","1 onion, chopped","2 garlic cloves","1 bunch kale, finely shredded","1 chorizo sausage, sliced","6 cups water","2 tbsp olive oil","4 slices bread"],"es":["800 g papas en cubos","1 cebolla picada","2 dientes de ajo","1 atado de kale o col en juliana fina","1 chorizo en rodajas","6 tazas agua","2 cdas aceite de oliva","4 rebanadas de pan"]},"steps":{"en":["Simmer potatoes, onion and garlic in the water for 20 min; blend smooth.","Add the kale and cook 5 min.","Fry the chorizo slices and float them on top; serve with bread."],"es":["Cociná las papas, la cebolla y el ajo en el agua 20 min; licuá.","Sumá la col y cociná 5 min.","Dorá el chorizo y ponelo arriba; serví con pan."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"pasteis-de-nata","type":"snack","country":"PT","group":"dairy","name":{"en":"Custard Tarts (Pastéis de Nata)","es":"Pastelitos de nata"},"ing":{"en":["300 g puff pastry","1 cup milk","½ cup cream","4 egg yolks","⅓ cup sugar","2 tbsp cornstarch","1 tsp cinnamon"],"es":["300 g masa de hojaldre","1 taza leche","½ taza crema de leche","4 yemas","⅓ taza azúcar","2 cdas maicena","1 cdita canela"]},"steps":{"en":["Roll the pastry into a log, slice and press each slice into a muffin cup.","Cook milk, cream, yolks, sugar and cornstarch, stirring, until thick.","Fill the cups and bake at 240°C for 12 min until spotted brown; dust with cinnamon."],"es":["Enrollá la masa, cortá rodajas y estiralas en moldes de muffin.","Cociná la leche, la crema, las yemas, el azúcar y la maicena, revolviendo, hasta que espese.","Rellená los moldes y horneá a 240°C 12 min, hasta que se manchen de dorado; espolvoreá con canela."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"lasagna-alla-bolognese","type":"dinner","country":"IT","protein":"beef","base":"pasta","tags":["lasagna"],"name":{"en":"Lasagna alla Bolognese","es":"Lasaña a la boloñesa"},"ing":{"en":["12 lasagna sheets","500 g ground beef","1 onion, chopped","1 carrot, grated","2 cans crushed tomatoes","3 tbsp butter","3 tbsp flour","3 cups milk","½ cup grated parmesan"],"es":["12 láminas de lasaña","500 g carne picada","1 cebolla picada","1 zanahoria rallada","2 latas tomate triturado","3 cdas manteca","3 cdas harina","3 tazas leche","½ taza queso parmesano rallado"]},"steps":{"en":["Brown the beef with onion and carrot; add tomatoes and simmer 30 min.","Make a white sauce with butter, flour and milk.","Layer sheets, meat sauce and white sauce; top with parmesan and bake at 190°C for 40 min."],"es":["Dorá la carne con la cebolla y la zanahoria; sumá el tomate y cociná 30 min.","Hacé una salsa blanca con la manteca, la harina y la leche.","Armá capas de láminas, salsa de carne y salsa blanca; terminá con parmesano y horneá a 190°C 40 min."]},"tip":{"en":"","es":""},"prep":["brown-beef"]},
{"id":"pasta-e-fagioli","type":"lunch","country":"IT","protein":"plant","base":"pasta","tags":["soup"],"name":{"en":"Pasta e Fagioli (Bean & Pasta Soup)","es":"Pasta e fagioli: sopa de porotos y fideos"},"ing":{"en":["2 cans white beans","1 cup pasta (small shapes)","1 onion, chopped","1 carrot, diced","1 celery stalk, diced","1 can crushed tomatoes","5 cups vegetable broth","4 tbsp grated parmesan"],"es":["2 latas porotos blancos","1 taza fideos chicos","1 cebolla picada","1 zanahoria en cubos","1 tallo de apio en cubos","1 lata tomate triturado","5 tazas caldo de verduras","4 cdas queso parmesano rallado"]},"steps":{"en":["Soften onion, carrot and celery; add tomatoes, broth and beans and simmer 15 min.","Mash a ladle of beans to thicken; add the pasta and cook 10 min.","Serve with parmesan."],"es":["Rehogá la cebolla, la zanahoria y el apio; sumá el tomate, el caldo y los porotos y cociná 15 min.","Pisá un cucharón de porotos para espesar; sumá los fideos y cociná 10 min.","Serví con parmesano."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"pasta-al-pomodoro","type":"lunch","country":"IT","protein":"plant","base":"pasta","name":{"en":"Pasta al Pomodoro with Basil","es":"Pasta al pomodoro con albahaca"},"ing":{"en":["400 g pasta","2 cans crushed tomatoes","3 garlic cloves, sliced","4 tbsp olive oil","1 handful fresh basil","4 tbsp grated parmesan","2 cups green salad"],"es":["400 g fideos","2 latas tomate triturado","3 dientes de ajo en láminas","4 cdas aceite de oliva","1 puñado de albahaca fresca","4 cdas queso parmesano rallado","2 tazas ensalada verde"]},"steps":{"en":["Warm garlic in the oil, add tomatoes and simmer 20 min.","Cook the pasta and toss with the sauce and torn basil.","Serve with parmesan and a green salad."],"es":["Calentá el ajo en el aceite, sumá el tomate y cociná 20 min.","Cociná la pasta y mezclala con la salsa y la albahaca en trozos.","Serví con parmesano y ensalada verde."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"spaghetti-tonno-e-pomodoro","type":"lunch","country":"IT","protein":"fish","base":"pasta","tags":["tuna"],"name":{"en":"Spaghetti with Tuna & Tomato","es":"Spaghetti con atún y tomate"},"ing":{"en":["400 g spaghetti","2 cans tuna, drained","1 can crushed tomatoes","2 garlic cloves, minced","1 tbsp capers (optional)","2 tbsp olive oil","2 tbsp fresh parsley, chopped"],"es":["400 g spaghetti","2 latas atún escurrido","1 lata tomate triturado","2 dientes de ajo picados","1 cda alcaparras (opcional)","2 cdas aceite de oliva","2 cdas perejil fresco picado"]},"steps":{"en":["Warm garlic in the oil, add the tomatoes and simmer 12 min.","Stir in the tuna and capers.","Toss with the cooked spaghetti and parsley."],"es":["Calentá el ajo en el aceite, sumá el tomate y cociná 12 min.","Incorporá el atún y las alcaparras.","Mezclá con los spaghetti cocidos y el perejil."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"pollo-alla-cacciatora","type":"dinner","country":"IT","protein":"poultry","base":"potato","tags":["stew"],"name":{"en":"Chicken Cacciatore with Potatoes","es":"Pollo a la cazadora con papas"},"ing":{"en":["1 kg chicken thighs","1 onion, sliced","2 bell peppers, sliced","200 g mushrooms, sliced","1 can crushed tomatoes","1 sprig fresh rosemary","800 g potatoes, in chunks"],"es":["1 kg muslos de pollo","1 cebolla en pluma","2 morrones en tiras","200 g champiñones en láminas","1 lata tomate triturado","1 rama de romero fresco","800 g papas en trozos"]},"steps":{"en":["Brown the chicken; add onion, peppers and mushrooms and cook 8 min.","Add tomatoes and rosemary, cover and simmer 35 min.","Serve with boiled potatoes."],"es":["Dorá el pollo; sumá la cebolla, los morrones y los champiñones y cociná 8 min.","Agregá el tomate y el romero, tapá y cociná 35 min.","Serví con papas hervidas."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"pesce-allacqua-pazza","type":"dinner","country":"IT","protein":"fish","base":"bread","name":{"en":"Fish in \"Crazy Water\" (Tomato Broth)","es":"Pescado en \"agua loca\""},"ing":{"en":["4 white fish fillets","2 cups cherry tomatoes, halved","3 garlic cloves, sliced","3 tbsp olive oil","1 cup water","2 tbsp fresh parsley, chopped","1 baguette"],"es":["4 filetes de pescado blanco","2 tazas tomates cherry en mitades","3 dientes de ajo en láminas","3 cdas aceite de oliva","1 taza agua","2 cdas perejil fresco picado","1 baguette"]},"steps":{"en":["Warm garlic in the oil, add tomatoes and water and simmer 8 min.","Lay the fish in, cover and poach 7 min.","Sprinkle with parsley; serve with bread for the broth."],"es":["Calentá el ajo en el aceite, sumá los tomates y el agua y cociná 8 min.","Acomodá el pescado, tapá y cociná 7 min.","Espolvoreá con perejil; serví con pan para el caldo."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"panzanella","type":"lunch","country":"IT","protein":"plant","base":"bread","name":{"en":"Panzanella with White Beans","es":"Panzanella con porotos blancos"},"ing":{"en":["4 cups day-old bread, in cubes","4 tomatoes, in chunks","1 cucumber, sliced","1 red onion, thinly sliced","1 can white beans, drained","1 handful fresh basil","4 tbsp olive oil","2 tbsp vinegar"],"es":["4 tazas pan del día anterior en cubos","4 tomates en trozos","1 pepino en rodajas","1 cebolla morada en pluma fina","1 lata porotos blancos escurridos","1 puñado de albahaca fresca","4 cdas aceite de oliva","2 cdas vinagre"]},"steps":{"en":["Toast the bread cubes at 200°C for 8 min.","Toss tomatoes, cucumber, onion and beans with oil, vinegar and salt.","Add bread and basil and rest 10 min so the bread soaks up the juices."],"es":["Tostá los cubos de pan a 200°C 8 min.","Mezclá el tomate, el pepino, la cebolla y los porotos con aceite, vinagre y sal.","Sumá el pan y la albahaca y dejá reposar 10 min para que el pan absorba los jugos."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"ricotta-pancakes","type":"breakfast","country":"IT","group":"dairy","tags":["pancakes"],"name":{"en":"Ricotta Pancakes with Berries","es":"Panqueques de ricota con frutos rojos"},"ing":{"en":["250 g ricotta","3 eggs","¾ cup flour","1 tsp baking powder","½ cup milk","1 tbsp butter","2 cups mixed berries"],"es":["250 g ricota","3 huevos","¾ taza harina","1 cdita polvo para hornear","½ taza leche","1 cda manteca","2 tazas frutos rojos"]},"steps":{"en":["Whisk the ricotta, eggs and milk; fold in flour and baking powder.","Cook small pancakes in butter, 2 min a side.","Serve with berries."],"es":["Batí la ricota, los huevos y la leche; incorporá la harina y el polvo de hornear.","Cociná panqueques chicos en manteca, 2 min por lado.","Serví con frutos rojos."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"bruschetta-al-pomodoro","type":"snack","country":"IT","group":"veg","name":{"en":"Tomato Bruschetta","es":"Bruschetta de tomate"},"ing":{"en":["1 baguette, sliced","4 tomatoes, diced","1 garlic clove","1 handful fresh basil","2 tbsp olive oil"],"es":["1 baguette en rodajas","4 tomates en cubitos","1 diente de ajo","1 puñado de albahaca fresca","2 cdas aceite de oliva"]},"steps":{"en":["Toast the bread and rub with the cut garlic.","Mix tomatoes, torn basil, oil and salt.","Spoon onto the toasts."],"es":["Tostá el pan y frotalo con el ajo cortado.","Mezclá el tomate, la albahaca, el aceite y sal.","Poné la mezcla sobre las tostadas."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"panna-cotta-ai-frutti-di-bosco","type":"snack","country":"IT","group":"dairy","name":{"en":"Yogurt Panna Cotta with Berries","es":"Panna cotta de yogur con frutos rojos"},"ing":{"en":["1 cup cream","1 cup plain yogurt","3 tbsp sugar","2 tsp gelatine powder","1 tsp vanilla extract","1 cup mixed berries"],"es":["1 taza crema de leche","1 taza yogur natural","3 cdas azúcar","2 cditas gelatina sin sabor","1 cdita esencia de vainilla","1 taza frutos rojos"]},"steps":{"en":["Warm the cream with the sugar and dissolve the softened gelatine in it.","Whisk in the yogurt and vanilla; pour into glasses and chill 4 hours.","Top with berries."],"es":["Calentá la crema con el azúcar y disolvé la gelatina hidratada.","Batí con el yogur y la vainilla; volcá en vasitos y enfriá 4 horas.","Terminá con frutos rojos."]},"tip":{"en":"","es":""},"prep":["chill-ahead"]},
{"id":"melone-e-prosciutto","type":"snack","country":"IT","group":"fruit","name":{"en":"Melon with Prosciutto & Breadsticks","es":"Melón con jamón crudo y grisines"},"ing":{"en":["1 melon","100 g prosciutto","8 breadsticks"],"es":["1 melón","100 g jamón crudo","8 grisines"]},"steps":{"en":["Cut the melon into wedges and remove the skin.","Wrap half the wedges in prosciutto.","Serve with breadsticks."],"es":["Cortá el melón en gajos y sacale la cáscara.","Envolvé la mitad de los gajos con jamón crudo.","Serví con grisines."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"moussaka","type":"dinner","country":"GR","protein":"beef","base":"potato","name":{"en":"Moussaka","es":"Musaka"},"ing":{"en":["3 eggplants, sliced","3 potatoes, sliced","500 g ground beef","1 onion, chopped","1 can crushed tomatoes","1 tsp cinnamon","3 tbsp butter","3 tbsp flour","2 cups milk","1 egg"],"es":["3 berenjenas en rodajas","3 papas en rodajas","500 g carne picada","1 cebolla picada","1 lata tomate triturado","1 cdita canela","3 cdas manteca","3 cdas harina","2 tazas leche","1 huevo"]},"steps":{"en":["Roast the eggplant and potato slices with a little oil at 200°C for 20 min.","Brown the beef with onion, add tomatoes and cinnamon and simmer 20 min; make a white sauce and beat in the egg.","Layer potato, eggplant and meat, cover with the sauce and bake at 180°C for 40 min."],"es":["Asá las rodajas de berenjena y papa con un poco de aceite a 200°C 20 min.","Dorá la carne con la cebolla, sumá el tomate y la canela y cociná 20 min; hacé una salsa blanca y sumale el huevo.","Armá capas de papa, berenjena y carne, cubrí con la salsa y horneá a 180°C 40 min."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"spanakopita","type":"lunch","country":"GR","protein":"plant","base":"bread","tags":["tart"],"name":{"en":"Spanakopita (Spinach & Feta Pie)","es":"Spanakopita: tarta de espinaca y feta"},"ing":{"en":["10 sheets filo pastry","2 bunches spinach","200 g feta cheese, crumbled","4 spring onions, sliced","2 eggs","2 tbsp fresh dill, chopped","4 tbsp olive oil"],"es":["10 hojas de masa filo","2 atados de espinaca","200 g queso feta desmenuzado","4 cebollas de verdeo en rodajas","2 huevos","2 cdas eneldo fresco picado","4 cdas aceite de oliva"]},"steps":{"en":["Wilt the spinach, squeeze dry and chop; mix with feta, spring onion, eggs and dill.","Layer 5 oiled filo sheets in a tin, add the filling, top with 5 more.","Score the top and bake at 190°C for 40 min."],"es":["Rehogá la espinaca, escurrila y picala; mezclá con el feta, el verdeo, los huevos y el eneldo.","Poné 5 hojas de filo aceitadas en una fuente, sumá el relleno y cubrí con 5 más.","Marcá la superficie y horneá a 190°C 40 min."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"souvlaki-de-cerdo","type":"dinner","country":"GR","protein":"pork","base":"bread","tags":["skewers"],"name":{"en":"Pork Souvlaki with Pita & Tzatziki","es":"Souvlaki de cerdo con pan pita y tzatziki"},"ing":{"en":["600 g pork shoulder, in cubes","2 lemons","2 tsp dried oregano","3 tbsp olive oil","4 pita breads","1 cup plain yogurt","1 cucumber, grated","1 garlic clove, minced","2 tomatoes, sliced"],"es":["600 g bondiola en cubos","2 limones","2 cditas orégano","3 cdas aceite de oliva","4 panes pita","1 taza yogur natural","1 pepino rallado","1 diente de ajo picado","2 tomates en rodajas"]},"steps":{"en":["Marinate the pork in lemon, oregano and oil for 1 hour; thread on skewers.","Grill 10–12 min, turning, until cooked through.","Mix yogurt, squeezed cucumber and garlic; serve in warm pitas with tomato."],"es":["Mariná el cerdo con limón, orégano y aceite 1 hora; ensartalo en brochetas.","Cociná a la parrilla 10–12 min, dando vuelta, hasta que esté bien cocido.","Mezclá el yogur, el pepino escurrido y el ajo; serví en pitas calientes con tomate."]},"tip":{"en":"","es":""},"prep":["marinate"]},
{"id":"fasolada","type":"lunch","country":"GR","protein":"plant","base":"bread","tags":["soup"],"name":{"en":"Fasolada (Greek Bean Soup)","es":"Fasolada: sopa griega de porotos"},"ing":{"en":["2 cans white beans","1 onion, chopped","2 carrots, sliced","2 celery stalks, sliced","2 tbsp tomato paste","4 tbsp olive oil","5 cups water","4 slices bread"],"es":["2 latas porotos blancos","1 cebolla picada","2 zanahorias en rodajas","2 tallos de apio en rodajas","2 cdas extracto de tomate","4 cdas aceite de oliva","5 tazas agua","4 rebanadas de pan"]},"steps":{"en":["Soften the vegetables in the oil for 10 min.","Add tomato paste, beans and water; simmer 30 min.","Serve with bread and a drizzle of oil."],"es":["Rehogá las verduras en el aceite 10 min.","Sumá el extracto, los porotos y el agua; cociná 30 min.","Serví con pan y un hilo de aceite."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"strapatsada","type":"breakfast","country":"GR","group":"egg","name":{"en":"Strapatsada (Eggs with Tomato & Feta)","es":"Strapatsada: huevos con tomate y feta"},"ing":{"en":["8 eggs","3 ripe tomatoes, grated","100 g feta cheese, crumbled","2 tbsp olive oil","1 tsp dried oregano","4 slices bread"],"es":["8 huevos","3 tomates maduros rallados","100 g queso feta desmenuzado","2 cdas aceite de oliva","1 cdita orégano","4 rebanadas de pan"]},"steps":{"en":["Cook the grated tomato in the oil for 8 min until thick.","Add beaten eggs and stir gently until just set.","Finish with feta and oregano; serve with bread."],"es":["Cociná el tomate rallado en el aceite 8 min, hasta que espese.","Agregá los huevos batidos y revolvé despacio hasta que cuajen.","Terminá con feta y orégano; serví con pan."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"horiatiki-with-chickpeas","type":"lunch","country":"GR","protein":"plant","base":"bread","name":{"en":"Greek Village Salad with Chickpeas & Pita","es":"Ensalada griega con garbanzos y pita"},"ing":{"en":["4 tomatoes, in chunks","1 cucumber, in chunks","1 green bell pepper, sliced","1 red onion, sliced","1 can chickpeas, drained","200 g feta cheese","¼ cup black olives","4 tbsp olive oil","4 pita breads"],"es":["4 tomates en trozos","1 pepino en trozos","1 morrón verde en tiras","1 cebolla morada en pluma","1 lata garbanzos escurridos","200 g queso feta","¼ taza aceitunas negras","4 cdas aceite de oliva","4 panes pita"]},"steps":{"en":["Toss the vegetables and chickpeas with oil, oregano and salt.","Top with a slab of feta and the olives.","Serve with warm pita."],"es":["Mezclá las verduras y los garbanzos con aceite, orégano y sal.","Poné encima el feta en bloque y las aceitunas.","Serví con pita caliente."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"kartoffelsuppe","type":"lunch","country":"DE","protein":"pork","base":"potato","tags":["soup"],"name":{"en":"German Potato Soup with Sausage","es":"Sopa alemana de papa con salchicha"},"ing":{"en":["1 kg potatoes, diced","2 carrots, diced","1 leek, sliced","1 onion, chopped","6 cups vegetable broth","4 frankfurters, sliced","1 tsp dried marjoram or oregano"],"es":["1 kg papas en cubos","2 zanahorias en cubos","1 puerro en rodajas","1 cebolla picada","6 tazas caldo de verduras","4 salchichas tipo viena en rodajas","1 cdita mejorana u orégano"]},"steps":{"en":["Soften onion and leek; add potatoes, carrots, broth and marjoram and simmer 20 min.","Mash roughly to thicken.","Add the sausages and heat 5 min."],"es":["Rehogá la cebolla y el puerro; sumá las papas, las zanahorias, el caldo y la mejorana y cociná 20 min.","Pisá un poco para espesar.","Agregá las salchichas y calentá 5 min."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"schnitzel-mit-kartoffelsalat","type":"dinner","country":"DE","protein":"pork","base":"potato","tags":["milanesa"],"name":{"en":"Pork Schnitzel with Potato Salad","es":"Schnitzel de cerdo con ensalada de papas"},"ing":{"en":["4 pork cutlets, thin","2 eggs","1½ cups breadcrumbs","1 kg potatoes","1 onion, finely chopped","1 cup vegetable broth","2 tbsp vinegar","2 tbsp sunflower oil","1 lemon"],"es":["4 escalopes finos de cerdo","2 huevos","1½ tazas pan rallado","1 kg papas","1 cebolla picada fina","1 taza caldo de verduras","2 cdas vinagre","2 cdas aceite de girasol","1 limón"]},"steps":{"en":["Boil the potatoes, slice warm and pour over hot broth with onion, vinegar and oil; rest.","Bread the cutlets in egg and breadcrumbs.","Bake at 210°C for 15 min, turning once; serve with lemon."],"es":["Herví las papas, cortalas tibias y bañalas con el caldo caliente con cebolla, vinagre y aceite; dejá reposar.","Empaná los escalopes con huevo y pan rallado.","Horneá a 210°C 15 min, dando vuelta una vez; serví con limón."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"kasespatzle","type":"dinner","country":"DE","protein":"plant","base":"pasta","tags":["mac-cheese"],"name":{"en":"Käsespätzle (Cheese Noodles with Onions)","es":"Käsespätzle: fideos con queso y cebolla"},"ing":{"en":["2 cups flour","4 eggs","½ cup milk","200 g gruyère or mild cheese, grated","2 onions, sliced","1 tbsp butter","1 head lettuce"],"es":["2 tazas harina","4 huevos","½ taza leche","200 g queso gruyère o de máquina rallado","2 cebollas en pluma","1 cda manteca","1 planta de lechuga"]},"steps":{"en":["Beat flour, eggs, milk and salt into a thick batter; press through a colander into boiling water and cook until they float.","Fry the onions in butter until golden.","Layer spätzle with cheese, top with onions; serve with salad."],"es":["Batí la harina, los huevos, la leche y sal; pasá por un colador sobre agua hirviendo y cociná hasta que floten.","Dorá las cebollas en manteca.","Armá capas de spätzle con queso y la cebolla arriba; serví con ensalada."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"apfelpfannkuchen","type":"breakfast","country":"DE","group":"grain","tags":["pancakes"],"name":{"en":"German Apple Pancakes","es":"Panqueques alemanes de manzana"},"ing":{"en":["1 cup flour","3 eggs","1 cup milk","2 apples, thinly sliced","1 tbsp butter","1 tsp cinnamon"],"es":["1 taza harina","3 huevos","1 taza leche","2 manzanas en láminas finas","1 cda manteca","1 cdita canela"]},"steps":{"en":["Whisk flour, eggs and milk into a batter.","Fry apple slices in butter for 2 min, pour batter over and cook until set; flip.","Dust with cinnamon."],"es":["Batí la harina, los huevos y la leche.","Saltá las láminas de manzana en manteca 2 min, volcá la mezcla y cociná hasta que se una; da vuelta.","Espolvoreá con canela."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"bircher-muesli","type":"breakfast","country":"CH","group":"grain","tags":["oats"],"name":{"en":"Bircher Muesli","es":"Muesli Bircher"},"ing":{"en":["1½ cups rolled oats","1 cup milk","1 cup plain yogurt","2 apples, grated","1 lemon","1 cup mixed berries","2 tbsp seeds (sunflower or pumpkin)"],"es":["1½ tazas avena arrollada","1 taza leche","1 taza yogur natural","2 manzanas ralladas","1 limón","1 taza frutos rojos","2 cdas semillas (girasol o zapallo)"]},"steps":{"en":["Soak the oats in milk overnight.","Stir in yogurt, grated apple and a squeeze of lemon.","Top with berries and seeds."],"es":["Remojá la avena en la leche toda la noche.","Incorporá el yogur, la manzana rallada y un chorrito de limón.","Terminá con frutos rojos y semillas."]},"tip":{"en":"","es":""},"prep":["overnight-oats"]},
{"id":"rosti-with-egg","type":"lunch","country":"CH","protein":"egg","base":"potato","name":{"en":"Rösti with Fried Egg & Salad","es":"Rösti con huevo frito y ensalada"},"ing":{"en":["1 kg potatoes, parboiled and cooled","2 tbsp butter","4 eggs","1 head lettuce","1 cucumber","50 g gruyère or mild cheese, grated"],"es":["1 kg papas hervidas a medias y frías","2 cdas manteca","4 huevos","1 planta de lechuga","1 pepino","50 g queso gruyère o de máquina rallado"]},"steps":{"en":["Coarsely grate the potatoes and season.","Press into a buttered pan and cook 10 min a side until golden.","Top with cheese and fried eggs; serve with salad."],"es":["Rallá las papas gruesas y condimentá.","Aplastá en una sartén con manteca y cociná 10 min por lado, hasta dorar.","Poné queso y huevos fritos arriba; serví con ensalada."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"stamppot-met-worst","type":"dinner","country":"NL","protein":"pork","base":"potato","tags":["sausages"],"name":{"en":"Stamppot (Kale Mash) with Sausage","es":"Stamppot: puré con col y salchicha"},"ing":{"en":["1 kg potatoes","1 bunch kale, finely chopped","½ cup milk","1 tbsp butter","1 smoked sausage","1 tbsp Dijon mustard"],"es":["1 kg papas","1 atado de kale o col picado fino","½ taza leche","1 cda manteca","1 salchicha ahumada","1 cda mostaza Dijon"]},"steps":{"en":["Boil the potatoes with the kale on top for the last 10 min.","Mash together with milk and butter.","Heat the sausage in simmering water 10 min; slice over the mash with mustard."],"es":["Herví las papas con la col arriba los últimos 10 min.","Pisá todo junto con la leche y la manteca.","Calentá la salchicha en agua 10 min; cortala sobre el puré con mostaza."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"poffertjes","type":"snack","country":"NL","group":"grain","tags":["pancakes"],"name":{"en":"Poffertjes (Mini Puffed Pancakes)","es":"Poffertjes: mini panqueques"},"ing":{"en":["1 cup flour","1 tsp baking powder","1 egg","¾ cup milk","1 tbsp butter","2 cups strawberries"],"es":["1 taza harina","1 cdita polvo para hornear","1 huevo","¾ taza leche","1 cda manteca","2 tazas frutillas"]},"steps":{"en":["Whisk flour, baking powder, egg and milk.","Drop teaspoons into a buttered pan and cook 1 min a side.","Serve with strawberries."],"es":["Batí la harina, el polvo de hornear, el huevo y la leche.","Echá cucharaditas en sartén con manteca y cociná 1 min por lado.","Serví con frutillas."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"kottbullar","type":"dinner","country":"SE","protein":"beef","base":"potato","tags":["meatballs"],"name":{"en":"Swedish Meatballs with Mash & Lingonberry","es":"Albóndigas suecas con puré y mermelada de frutos rojos"},"ing":{"en":["500 g ground beef","1 onion, grated","1 egg","½ cup breadcrumbs","¼ tsp allspice or nutmeg","1 cup beef broth","½ cup cream","1 kg potatoes","4 tbsp lingonberry or cranberry jam"],"es":["500 g carne picada","1 cebolla rallada","1 huevo","½ taza pan rallado","¼ cdita pimienta de Jamaica o nuez moscada","1 taza caldo de carne","½ taza crema de leche","1 kg papas","4 cdas mermelada de arándanos rojos"]},"steps":{"en":["Mix beef, onion, egg, breadcrumbs and spice; roll small balls and brown.","Add broth and cream and simmer 10 min.","Serve with mashed potatoes and a spoon of jam."],"es":["Mezclá la carne con la cebolla, el huevo, el pan rallado y la especia; formá bolitas y doralas.","Sumá el caldo y la crema y cociná 10 min.","Serví con puré y una cucharadita de mermelada."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"laxpotatissallad","type":"lunch","country":"SE","protein":"fish","base":"potato","tags":["salmon"],"name":{"en":"Salmon & Dill Potato Salad","es":"Ensalada de papas con salmón y eneldo"},"ing":{"en":["4 salmon fillets","800 g baby potatoes","½ cup plain yogurt","3 tbsp fresh dill, chopped","1 cucumber, diced","1 lemon","1 tbsp Dijon mustard"],"es":["4 filetes de salmón","800 g papines","½ taza yogur natural","3 cdas eneldo fresco picado","1 pepino en cubos","1 limón","1 cda mostaza Dijon"]},"steps":{"en":["Boil the potatoes and halve.","Bake the salmon at 200°C for 12 min; flake.","Mix yogurt, dill, mustard and lemon; toss with potatoes, cucumber and salmon."],"es":["Herví los papines y cortalos al medio.","Horneá el salmón a 200°C 12 min; desmenuzalo.","Mezclá el yogur con el eneldo, la mostaza y el limón; uní con las papas, el pepino y el salmón."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"kanelbullar","type":"snack","country":"SE","group":"grain","name":{"en":"Cinnamon Buns","es":"Rollos de canela suecos"},"ing":{"en":["3 cups flour","10 g dry yeast","1 cup milk, warm","60 g butter, soft","¼ cup sugar","2 tsp cinnamon","1 egg"],"es":["3 tazas harina","10 g levadura seca","1 taza leche tibia","60 g manteca blanda","¼ taza azúcar","2 cditas canela","1 huevo"]},"steps":{"en":["Knead flour, yeast, milk, half the butter and half the sugar; rise 1 hour.","Roll out, spread with the rest of the butter, sugar and cinnamon; roll up and slice.","Rise 30 min, brush with egg and bake at 220°C for 10 min."],"es":["Amasá la harina, la levadura, la leche, la mitad de la manteca y la mitad del azúcar; dejá levar 1 hora.","Estirá, untá con el resto de la manteca, el azúcar y la canela; enrollá y cortá.","Dejá levar 30 min, pincelá con huevo y horneá a 220°C 10 min."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"pierogi-ruskie","type":"lunch","country":"PL","protein":"plant","base":"pasta","tags":["ravioli"],"name":{"en":"Pierogi with Potato & Cheese","es":"Pierogi de papa y queso"},"ing":{"en":["2½ cups flour","1 egg","¾ cup warm water","500 g potatoes, boiled and mashed","200 g cottage cheese or ricotta","2 onions, chopped","2 tbsp butter","½ cup sour cream"],"es":["2½ tazas harina","1 huevo","¾ taza agua tibia","500 g papas hervidas y pisadas","200 g queso blanco o ricota","2 cebollas picadas","2 cdas manteca","½ taza crema agria"]},"steps":{"en":["Knead flour, egg and water; rest 20 min. Fry the onions in butter until golden.","Mix potato, cheese and half the onion; fill rounds of rolled dough and seal.","Boil until they float, 3 min; serve with the rest of the onion and sour cream."],"es":["Amasá la harina, el huevo y el agua; dejá reposar 20 min. Dorá las cebollas en manteca.","Mezclá la papa, el queso y la mitad de la cebolla; rellená círculos de masa estirada y cerrá.","Herví hasta que floten, 3 min; serví con el resto de la cebolla y crema agria."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"golabki","type":"dinner","country":"PL","protein":"beef","base":"rice","name":{"en":"Gołąbki (Cabbage Rolls in Tomato Sauce)","es":"Gołąbki: niños envueltos en repollo"},"ing":{"en":["1 cabbage","400 g ground beef","1 cup rice, cooked","1 onion, chopped","1 egg","2 cans crushed tomatoes","1 cup beef broth"],"es":["1 repollo","400 g carne picada","1 taza arroz cocido","1 cebolla picada","1 huevo","2 latas tomate triturado","1 taza caldo de carne"]},"steps":{"en":["Blanch the cabbage leaves 3 min to soften.","Mix beef, rice, onion and egg; roll in the leaves.","Pack into a pot, cover with tomatoes and broth and simmer 1 hour."],"es":["Blanqueá las hojas de repollo 3 min para ablandarlas.","Mezclá la carne, el arroz, la cebolla y el huevo; envolvé en las hojas.","Acomodá en una olla, cubrí con tomate y caldo y cociná 1 hora."]},"tip":{"en":"","es":""},"prep":["rice"]},
{"id":"placki-ziemniaczane","type":"breakfast","country":"PL","group":"grain","tags":["pancakes"],"name":{"en":"Potato Pancakes with Apple Sauce","es":"Panqueques de papa con puré de manzana"},"ing":{"en":["800 g potatoes, grated","1 onion, grated","2 eggs","3 tbsp flour","3 tbsp sunflower oil","3 apples","½ cup sour cream"],"es":["800 g papas ralladas","1 cebolla rallada","2 huevos","3 cdas harina","3 cdas aceite de girasol","3 manzanas","½ taza crema agria"]},"steps":{"en":["Squeeze the grated potato and onion dry; mix with eggs and flour.","Fry spoonfuls in oil, 3 min a side.","Cook the apples with a splash of water into a sauce; serve with sour cream."],"es":["Escurrí bien la papa y la cebolla ralladas; mezclá con los huevos y la harina.","Freí cucharadas en aceite, 3 min por lado.","Cociná las manzanas con un chorrito de agua hasta hacer puré; serví con crema agria."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"gulyas","type":"dinner","country":"HU","protein":"beef","base":"potato","tags":["soup"],"name":{"en":"Hungarian Goulash Soup","es":"Gulash húngaro"},"ing":{"en":["600 g beef chuck, diced","2 onions, chopped","2 tbsp sweet paprika","1 red bell pepper, diced","2 tomatoes, chopped","3 potatoes, diced","1 tsp caraway seeds (optional)","6 cups beef broth","4 slices bread"],"es":["600 g carne para guiso en cubos","2 cebollas picadas","2 cdas pimentón dulce","1 morrón rojo en cubos","2 tomates picados","3 papas en cubos","1 cdita alcaravea (opcional)","6 tazas caldo de carne","4 rebanadas de pan"]},"steps":{"en":["Soften the onions, stir in paprika off the heat, then brown the beef.","Add pepper, tomato, caraway and broth; simmer 1 hour.","Add potatoes and cook 25 min more; serve with bread."],"es":["Rehogá la cebolla, sumá el pimentón fuera del fuego y después dorá la carne.","Agregá el morrón, el tomate, la alcaravea y el caldo; cociná 1 hora.","Sumá las papas y cociná 25 min más; serví con pan."]},"tip":{"en":"","es":""},"prep":["cook-ahead"]},
{"id":"csirkepaprikas","type":"dinner","country":"HU","protein":"poultry","base":"pasta","name":{"en":"Chicken Paprikash with Egg Noodles","es":"Pollo al paprika con fideos de huevo"},"ing":{"en":["1 kg chicken thighs","2 onions, chopped","2 tbsp sweet paprika","1 red bell pepper, diced","1 cup chicken broth","½ cup sour cream","1 tbsp flour","400 g egg noodles"],"es":["1 kg muslos de pollo","2 cebollas picadas","2 cdas pimentón dulce","1 morrón rojo en cubos","1 taza caldo de pollo","½ taza crema agria","1 cda harina","400 g fideos de huevo"]},"steps":{"en":["Soften the onions, add paprika and the chicken and brown.","Add pepper and broth, cover and simmer 30 min.","Stir flour into the sour cream and add to thicken; serve over noodles."],"es":["Rehogá la cebolla, sumá el pimentón y el pollo y dorá.","Agregá el morrón y el caldo, tapá y cociná 30 min.","Mezclá la harina con la crema agria y sumala para espesar; serví sobre fideos."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"borscht","type":"lunch","country":"UA","protein":"plant","base":"bread","tags":["soup"],"name":{"en":"Borscht (Beet & Vegetable Soup)","es":"Borsch: sopa de remolacha y verduras"},"ing":{"en":["3 beets, grated","2 potatoes, diced","¼ cabbage, shredded","1 carrot, grated","1 onion, chopped","2 tbsp tomato paste","6 cups vegetable broth","½ cup sour cream","2 tbsp fresh dill, chopped","4 slices rye or whole-grain bread"],"es":["3 remolachas ralladas","2 papas en cubos","¼ repollo en juliana","1 zanahoria rallada","1 cebolla picada","2 cdas extracto de tomate","6 tazas caldo de verduras","½ taza crema agria","2 cdas eneldo fresco picado","4 rebanadas de pan de centeno o integral"]},"steps":{"en":["Soften onion, carrot and beet with the tomato paste for 10 min.","Add broth and potatoes and simmer 15 min; add cabbage for 10 min more.","Serve with sour cream, dill and bread."],"es":["Rehogá la cebolla, la zanahoria y la remolacha con el extracto 10 min.","Sumá el caldo y las papas y cociná 15 min; agregá el repollo 10 min más.","Serví con crema agria, eneldo y pan."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"syrniki","type":"breakfast","country":"UA","group":"dairy","tags":["pancakes"],"name":{"en":"Syrniki (Cottage Cheese Pancakes)","es":"Syrniki: panqueques de queso blanco"},"ing":{"en":["500 g cottage cheese or ricotta","2 eggs","5 tbsp flour","1 tbsp sugar","1 tbsp butter","½ cup sour cream","1 cup mixed berries"],"es":["500 g queso blanco o ricota","2 huevos","5 cdas harina","1 cda azúcar","1 cda manteca","½ taza crema agria","1 taza frutos rojos"]},"steps":{"en":["Mix the cheese, eggs, flour and sugar into a soft dough.","Shape small patties, dust with flour and fry in butter 3 min a side.","Serve with sour cream and berries."],"es":["Mezclá el queso, los huevos, la harina y el azúcar hasta tener una masa blanda.","Formá medallones, pasalos por harina y cocinalos en manteca 3 min por lado.","Serví con crema agria y frutos rojos."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"pelmeni","type":"dinner","country":"RU","protein":"beef","base":"pasta","tags":["ravioli"],"name":{"en":"Pelmeni (Meat Dumplings) with Sour Cream","es":"Pelmeni con crema agria"},"ing":{"en":["2½ cups flour","1 egg","¾ cup water","400 g ground beef","1 onion, grated","½ cup sour cream","2 tbsp fresh dill, chopped","2 cups green salad"],"es":["2½ tazas harina","1 huevo","¾ taza agua","400 g carne picada","1 cebolla rallada","½ taza crema agria","2 cdas eneldo fresco picado","2 tazas ensalada verde"]},"steps":{"en":["Knead flour, egg and water; rest 20 min. Mix beef and onion.","Roll thin, cut rounds, fill and fold into little hats.","Boil 6 min after they float; serve with sour cream, dill and salad."],"es":["Amasá la harina, el huevo y el agua; dejá reposar 20 min. Mezclá la carne con la cebolla.","Estirá fino, cortá círculos, rellená y cerrá en forma de sombrerito.","Herví 6 min desde que flotan; serví con crema agria, eneldo y ensalada."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"blini-with-sour-cream","type":"breakfast","country":"RU","group":"grain","tags":["pancakes"],"name":{"en":"Blini with Sour Cream & Apple","es":"Blinis con crema agria y manzana"},"ing":{"en":["1 cup flour","2 eggs","2 cups milk","1 tbsp butter","½ cup sour cream","2 apples, grated"],"es":["1 taza harina","2 huevos","2 tazas leche","1 cda manteca","½ taza crema agria","2 manzanas ralladas"]},"steps":{"en":["Whisk flour, eggs and milk into a thin batter.","Cook thin pancakes in butter, 1 min a side.","Fill with grated apple and serve with sour cream."],"es":["Batí la harina, los huevos y la leche.","Cociná panqueques finos en manteca, 1 min por lado.","Rellená con manzana rallada y serví con crema agria."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"menemen","type":"breakfast","country":"TR","group":"egg","name":{"en":"Menemen (Turkish Eggs with Peppers & Tomato)","es":"Menemen: huevos con morrón y tomate"},"ing":{"en":["6 eggs","2 green bell peppers, chopped","3 tomatoes, chopped","2 tbsp olive oil","50 g feta cheese (optional)","4 slices bread"],"es":["6 huevos","2 morrones verdes picados","3 tomates picados","2 cdas aceite de oliva","50 g queso feta (opcional)","4 rebanadas de pan"]},"steps":{"en":["Soften the peppers in the oil for 5 min.","Add the tomatoes and cook 8 min until saucy.","Stir in the beaten eggs until softly set; crumble feta over and serve with bread."],"es":["Rehogá los morrones en el aceite 5 min.","Sumá el tomate y cociná 8 min hasta que haga salsa.","Incorporá los huevos batidos hasta que cuajen suave; desmenuzá el feta y serví con pan."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"simit-kahvalti","type":"breakfast","country":"TR","group":"grain","name":{"en":"Turkish Breakfast Plate with Sesame Bread","es":"Desayuno turco con pan de sésamo"},"ing":{"en":["4 sesame bagels or rolls","150 g feta cheese","2 tomatoes, sliced","1 cucumber, sliced","¼ cup black olives","4 eggs","2 tbsp honey (optional)"],"es":["4 roscas o panes con sésamo","150 g queso feta","2 tomates en rodajas","1 pepino en rodajas","¼ taza aceitunas negras","4 huevos","2 cdas miel (opcional)"]},"steps":{"en":["Boil the eggs for 8 min.","Arrange cheese, tomato, cucumber and olives on a platter.","Serve with the warm bread and a little honey."],"es":["Herví los huevos 8 min.","Acomodá el queso, el tomate, el pepino y las aceitunas en una fuente.","Serví con el pan tibio y un poco de miel."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"kofte-with-bulgur","type":"dinner","country":"TR","protein":"beef","base":"grain","tags":["meatballs"],"name":{"en":"Köfte with Bulgur Pilaf & Yogurt","es":"Köfte con pilaf de bulgur y yogur"},"ing":{"en":["500 g ground beef","1 onion, grated","1 tsp ground cumin","3 tbsp fresh parsley, chopped","1½ cups bulgur","1 tbsp tomato paste","1 cup plain yogurt","1 cucumber"],"es":["500 g carne picada","1 cebolla rallada","1 cdita comino","3 cdas perejil fresco picado","1½ tazas trigo burgol","1 cda extracto de tomate","1 taza yogur natural","1 pepino"]},"steps":{"en":["Mix beef, onion, cumin and parsley; shape small fingers and grill 8 min.","Fry the tomato paste in a little oil, add bulgur and 3 cups water; cover 15 min.","Serve with yogurt and cucumber."],"es":["Mezclá la carne, la cebolla, el comino y el perejil; formá deditos y cocinalos a la plancha 8 min.","Dorá el extracto en un poco de aceite, sumá el burgol y 3 tazas de agua; tapá 15 min.","Serví con yogur y pepino."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"imam-bayildi","type":"lunch","country":"TR","protein":"plant","base":"bread","name":{"en":"İmam Bayıldı (Stuffed Eggplant)","es":"Imam bayildi: berenjenas rellenas"},"ing":{"en":["4 eggplants","2 onions, sliced","3 garlic cloves, sliced","3 tomatoes, chopped","3 tbsp fresh parsley, chopped","5 tbsp olive oil","4 pita breads"],"es":["4 berenjenas","2 cebollas en pluma","3 dientes de ajo en láminas","3 tomates picados","3 cdas perejil fresco picado","5 cdas aceite de oliva","4 panes pita"]},"steps":{"en":["Halve the eggplants, score and roast cut side down at 200°C for 20 min.","Cook onion and garlic slowly in the oil, add tomato and parsley.","Press a hollow in each eggplant, fill and bake 25 min more; serve warm with pita."],"es":["Cortá las berenjenas al medio, marcá la pulpa y horneá boca abajo a 200°C 20 min.","Cociná la cebolla y el ajo despacio en el aceite, sumá el tomate y el perejil.","Hundí la pulpa de cada berenjena, rellená y horneá 25 min más; serví tibio con pita."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"mercimek-koftesi","type":"lunch","country":"TR","protein":"plant","base":"grain","tags":["lentil"],"name":{"en":"Red Lentil & Bulgur Patties in Lettuce","es":"Croquetas de lentejas y burgol en lechuga"},"ing":{"en":["1 cup red lentils","¾ cup fine bulgur","1 onion, chopped","2 tbsp tomato paste","1 tsp ground cumin","4 spring onions, sliced","3 tbsp fresh parsley, chopped","1 head lettuce","1 lemon"],"es":["1 taza lentejas rojas","¾ taza trigo burgol fino","1 cebolla picada","2 cdas extracto de tomate","1 cdita comino","4 cebollas de verdeo en rodajas","3 cdas perejil fresco picado","1 planta de lechuga","1 limón"]},"steps":{"en":["Simmer the lentils in 2½ cups water for 15 min; stir in the bulgur, cover and rest 15 min.","Fry onion with tomato paste and cumin; knead into the lentils with spring onion and parsley.","Shape small patties and serve in lettuce leaves with lemon."],"es":["Cociná las lentejas en 2½ tazas de agua 15 min; sumá el burgol, tapá y dejá reposar 15 min.","Rehogá la cebolla con el extracto y el comino; amasá con las lentejas, el verdeo y el perejil.","Formá croquetas chicas y serví en hojas de lechuga con limón."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"fattoush","type":"lunch","country":"LB","protein":"plant","base":"bread","name":{"en":"Fattoush with Chickpeas","es":"Fattoush con garbanzos"},"ing":{"en":["3 pita breads","1 head lettuce","3 tomatoes, diced","1 cucumber, diced","4 radishes, sliced","1 can chickpeas, drained","2 tbsp fresh mint, chopped","1 lemon","4 tbsp olive oil","1 tsp sumac (optional)"],"es":["3 panes pita","1 planta de lechuga","3 tomates en cubos","1 pepino en cubos","4 rabanitos en rodajas","1 lata garbanzos escurridos","2 cdas menta fresca picada","1 limón","4 cdas aceite de oliva","1 cdita zumaque (opcional)"]},"steps":{"en":["Tear the pitas and bake at 200°C for 8 min until crisp.","Toss the vegetables, chickpeas and mint with lemon, oil and sumac.","Add the pita chips just before serving."],"es":["Cortá las pitas en trozos y horneá a 200°C 8 min, hasta que estén crocantes.","Mezclá las verduras, los garbanzos y la menta con limón, aceite y zumaque.","Sumá la pita crocante justo antes de servir."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"chicken-shawarma-wraps","type":"dinner","country":"LB","protein":"poultry","base":"bread","name":{"en":"Chicken Shawarma Wraps with Garlic Sauce","es":"Shawarma de pollo con salsa de ajo"},"ing":{"en":["800 g chicken thighs","2 tsp ground cumin","2 tsp paprika","1 tsp turmeric","1 lemon","1 cup plain yogurt","1 garlic clove, minced","4 pita breads","2 tomatoes, sliced","1 cucumber, sliced"],"es":["800 g muslos de pollo","2 cditas comino","2 cditas pimentón","1 cdita cúrcuma","1 limón","1 taza yogur natural","1 diente de ajo picado","4 panes pita","2 tomates en rodajas","1 pepino en rodajas"]},"steps":{"en":["Rub the chicken with the spices, lemon and a little oil; roast at 220°C for 25 min and slice.","Mix yogurt and garlic.","Roll the chicken in warm pitas with tomato, cucumber and garlic sauce."],"es":["Untá el pollo con las especias, el limón y un poco de aceite; horneá a 220°C 25 min y cortá en tiras.","Mezclá el yogur con el ajo.","Enrollá el pollo en pitas calientes con tomate, pepino y la salsa de ajo."]},"tip":{"en":"","es":""},"prep":["marinate"]},
{"id":"mujadara","type":"dinner","country":"LB","protein":"plant","base":"rice","tags":["lentil"],"name":{"en":"Mujadara (Lentils & Rice with Crispy Onions)","es":"Mujadara: lentejas y arroz con cebolla crocante"},"ing":{"en":["1 cup lentils (dry)","1 cup rice","3 onions, thinly sliced","4 tbsp olive oil","1 tsp ground cumin","1 cup plain yogurt","1 cucumber, diced"],"es":["1 taza lentejas secas","1 taza arroz","3 cebollas en pluma fina","4 cdas aceite de oliva","1 cdita comino","1 taza yogur natural","1 pepino en cubos"]},"steps":{"en":["Cook the onions slowly in the oil for 25 min until deep brown.","Simmer lentils 10 min, add rice, cumin and water to cover by 2 cm; cook 18 min.","Top with the onions; serve with cucumber yogurt."],"es":["Cociná las cebollas despacio en el aceite 25 min, hasta que estén bien doradas.","Cociná las lentejas 10 min, sumá el arroz, el comino y agua hasta 2 cm por encima; cociná 18 min.","Poné la cebolla arriba; serví con yogur con pepino."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"manakish-zaatar","type":"breakfast","country":"LB","group":"grain","name":{"en":"Manakish Za'atar Flatbreads","es":"Manakish: panes con za'atar"},"ing":{"en":["500 g pizza dough","4 tbsp za'atar","5 tbsp olive oil","2 tomatoes","1 cucumber","100 g labneh or cream cheese"],"es":["500 g masa de pizza","4 cdas za'atar","5 cdas aceite de oliva","2 tomates","1 pepino","100 g labneh o queso crema"]},"steps":{"en":["Divide the dough into 4 and stretch into rounds.","Spread with za'atar mixed with the oil.","Bake at 230°C for 8 min; serve with tomato, cucumber and labneh."],"es":["Dividí la masa en 4 y estirá círculos.","Untá con el za'atar mezclado con el aceite.","Horneá a 230°C 8 min; serví con tomate, pepino y labneh."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"labneh-with-cucumber","type":"snack","country":"LB","group":"dairy","name":{"en":"Labneh with Cucumber, Mint & Olive Oil","es":"Labneh con pepino, menta y aceite de oliva"},"ing":{"en":["2 cups plain yogurt, strained overnight","1 cucumber, in sticks","1 tbsp fresh mint, chopped","2 tbsp olive oil","2 pita breads"],"es":["2 tazas yogur natural colado toda la noche","1 pepino en bastones","1 cda menta fresca picada","2 cdas aceite de oliva","2 panes pita"]},"steps":{"en":["Spread the thick strained yogurt on a plate.","Drizzle with oil and scatter the mint.","Serve with cucumber sticks and pita."],"es":["Esparcí el yogur colado espeso en un plato.","Rociá con aceite y espolvoreá la menta.","Serví con bastones de pepino y pita."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"sabich","type":"lunch","country":"IL","protein":"egg","base":"bread","name":{"en":"Sabich (Eggplant & Egg Pita)","es":"Sabich: pita con berenjena y huevo"},"ing":{"en":["2 eggplants, sliced","4 eggs","4 pita breads","½ cup hummus","2 tbsp tahini","2 tomatoes, diced","1 cucumber, diced","3 tbsp olive oil"],"es":["2 berenjenas en rodajas","4 huevos","4 panes pita","½ taza hummus","2 cdas tahini","2 tomates en cubos","1 pepino en cubos","3 cdas aceite de oliva"]},"steps":{"en":["Brush the eggplant with oil and roast at 220°C for 20 min.","Boil the eggs for 9 min and slice.","Fill pitas with hummus, eggplant, egg and salad; drizzle with tahini."],"es":["Pincelá la berenjena con aceite y horneá a 220°C 20 min.","Herví los huevos 9 min y cortalos en rodajas.","Rellená las pitas con hummus, berenjena, huevo y ensalada; rociá con tahini."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"falafel-pita","type":"dinner","country":"IL","protein":"plant","base":"bread","name":{"en":"Baked Falafel in Pita with Tahini","es":"Falafel al horno en pita con tahini"},"ing":{"en":["2 cans chickpeas, drained","1 onion, chopped","2 garlic cloves","4 tbsp fresh parsley","1 tsp ground cumin","3 tbsp flour","4 pita breads","3 tbsp tahini","2 tomatoes, diced","1 cucumber, diced"],"es":["2 latas garbanzos escurridos","1 cebolla picada","2 dientes de ajo","4 cdas perejil fresco","1 cdita comino","3 cdas harina","4 panes pita","3 cdas tahini","2 tomates en cubos","1 pepino en cubos"]},"steps":{"en":["Pulse chickpeas, onion, garlic, parsley, cumin and flour into a coarse paste.","Shape small patties, brush with oil and bake at 210°C for 25 min, turning once.","Serve in pitas with salad and tahini thinned with lemon and water."],"es":["Procesá los garbanzos, la cebolla, el ajo, el perejil, el comino y la harina hasta tener una pasta gruesa.","Formá medallones, pincelalos con aceite y horneá a 210°C 25 min, dando vuelta una vez.","Serví en pitas con ensalada y tahini aligerado con limón y agua."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"israeli-breakfast-salad","type":"breakfast","country":"IL","group":"dairy","name":{"en":"Israeli Breakfast: Chopped Salad & Cottage Cheese","es":"Desayuno israelí: ensalada picada y queso blanco"},"ing":{"en":["3 tomatoes, finely diced","2 cucumbers, finely diced","1 red bell pepper, finely diced","1 lemon","2 tbsp olive oil","2 cups cottage cheese","4 slices whole-grain bread"],"es":["3 tomates en cubitos","2 pepinos en cubitos","1 morrón rojo en cubitos","1 limón","2 cdas aceite de oliva","2 tazas queso blanco","4 rebanadas de pan integral"]},"steps":{"en":["Dice the vegetables very small.","Dress with lemon, oil and salt.","Serve with cottage cheese and bread."],"es":["Cortá las verduras en cubitos bien chicos.","Condimentá con limón, aceite y sal.","Serví con queso blanco y pan."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"kuku-sabzi","type":"lunch","country":"IR","protein":"egg","base":"bread","name":{"en":"Kuku Sabzi (Herb Frittata) with Flatbread & Yogurt","es":"Kuku sabzi: tortilla de hierbas con pan y yogur"},"ing":{"en":["8 eggs","2 cups fresh parsley, chopped","1 cup fresh cilantro, chopped","4 spring onions, sliced","¼ cup walnuts, chopped (optional)","1 tsp turmeric","4 pita breads","1 cup plain yogurt"],"es":["8 huevos","2 tazas perejil fresco picado","1 taza cilantro fresco picado","4 cebollas de verdeo en rodajas","¼ taza nueces picadas (opcional)","1 cdita cúrcuma","4 panes pita","1 taza yogur natural"]},"steps":{"en":["Beat the eggs with turmeric and salt; stir in the herbs, spring onion and walnuts.","Pour into an oiled pan, cover and cook on low for 15 min; flip and cook 5 min.","Serve in wedges with flatbread and yogurt."],"es":["Batí los huevos con cúrcuma y sal; sumá las hierbas, el verdeo y las nueces.","Volcá en una sartén aceitada, tapá y cociná a fuego bajo 15 min; da vuelta y cociná 5 min.","Serví en porciones con pan y yogur."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"joojeh-kabab","type":"dinner","country":"IR","protein":"poultry","base":"rice","tags":["skewers"],"name":{"en":"Joojeh Kabab (Saffron Chicken Skewers) with Rice","es":"Joojeh kabab: brochetas de pollo con azafrán y arroz"},"ing":{"en":["800 g chicken breast, in cubes","1 cup plain yogurt","1 pinch saffron or turmeric","1 onion, grated","1 lemon","1½ cups rice","4 tomatoes, halved"],"es":["800 g pechuga de pollo en cubos","1 taza yogur natural","1 pizca de azafrán o cúrcuma","1 cebolla rallada","1 limón","1½ tazas arroz","4 tomates en mitades"]},"steps":{"en":["Marinate the chicken in yogurt, saffron, onion and lemon for 2 hours.","Thread on skewers with tomato halves and grill 12 min, turning.","Serve with fluffy rice."],"es":["Mariná el pollo con el yogur, el azafrán, la cebolla y el limón 2 horas.","Ensartá con los tomates y cociná a la parrilla 12 min, dando vuelta.","Serví con arroz graneado."]},"tip":{"en":"","es":""},"prep":["marinate","rice"]},
{"id":"ash-reshteh","type":"lunch","country":"IR","protein":"plant","base":"pasta","tags":["soup"],"name":{"en":"Ash Reshteh (Herb, Bean & Noodle Soup)","es":"Ash reshteh: sopa de hierbas, legumbres y fideos"},"ing":{"en":["1 can chickpeas, drained","1 can kidney beans, drained","½ cup lentils (dry)","2 cups spinach","1 cup fresh parsley, chopped","100 g linguine, broken","2 onions, sliced","1 tsp turmeric","½ cup plain yogurt"],"es":["1 lata garbanzos escurridos","1 lata porotos colorados escurridos","½ taza lentejas secas","2 tazas espinaca","1 taza perejil fresco picado","100 g tallarines partidos","2 cebollas en pluma","1 cdita cúrcuma","½ taza yogur natural"]},"steps":{"en":["Simmer lentils, chickpeas and beans with turmeric in 7 cups water for 25 min.","Add herbs, spinach and noodles and cook 10 min.","Top with onions fried until golden and a swirl of yogurt."],"es":["Cociná las lentejas, los garbanzos y los porotos con cúrcuma en 7 tazas de agua 25 min.","Sumá las hierbas, la espinaca y los fideos y cociná 10 min.","Terminá con cebolla dorada y un poco de yogur."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"chicken-tagine","type":"dinner","country":"MA","protein":"poultry","base":"grain","tags":["stew"],"name":{"en":"Chicken Tagine with Lemon & Olives","es":"Tajín de pollo con limón y aceitunas"},"ing":{"en":["1 kg chicken thighs","2 onions, sliced","2 garlic cloves, minced","1 tsp ground ginger","1 tsp turmeric","1 tsp ground cumin","1 lemon, in wedges","½ cup green olives","1½ cups couscous"],"es":["1 kg muslos de pollo","2 cebollas en pluma","2 dientes de ajo picados","1 cdita jengibre en polvo","1 cdita cúrcuma","1 cdita comino","1 limón en gajos","½ taza aceitunas verdes","1½ tazas cuscús"]},"steps":{"en":["Brown the chicken; add onions, garlic and spices.","Add 1 cup water and the lemon; cover and simmer 35 min.","Add olives for 5 min; serve with couscous."],"es":["Dorá el pollo; sumá la cebolla, el ajo y las especias.","Agregá 1 taza de agua y el limón; tapá y cociná 35 min.","Sumá las aceitunas 5 min; serví con cuscús."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"couscous-aux-legumes","type":"lunch","country":"MA","protein":"plant","base":"grain","name":{"en":"Seven-Vegetable Couscous","es":"Cuscús de siete verduras"},"ing":{"en":["1½ cups couscous","2 carrots, in chunks","2 zucchini, in chunks","2 cups pumpkin, in chunks","1 onion, chopped","1 can chickpeas, drained","2 tomatoes, chopped","1 tsp ground cinnamon","4 cups vegetable broth"],"es":["1½ tazas cuscús","2 zanahorias en trozos","2 zapallitos en trozos","2 tazas zapallo en trozos","1 cebolla picada","1 lata garbanzos escurridos","2 tomates picados","1 cdita canela","4 tazas caldo de verduras"]},"steps":{"en":["Simmer onion, tomato, carrot and spices in the broth for 15 min.","Add pumpkin, zucchini and chickpeas and cook 15 min more.","Pour boiling water over the couscous, cover 5 min; serve the vegetables and broth on top."],"es":["Cociná la cebolla, el tomate, la zanahoria y las especias en el caldo 15 min.","Sumá el zapallo, los zapallitos y los garbanzos y cociná 15 min más.","Volcá agua hirviendo sobre el cuscús, tapá 5 min; serví con las verduras y el caldo encima."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"harira","type":"dinner","country":"MA","protein":"plant","base":"bread","tags":["soup"],"name":{"en":"Harira (Tomato, Lentil & Chickpea Soup)","es":"Harira: sopa de tomate, lentejas y garbanzos"},"ing":{"en":["¾ cup lentils (dry)","1 can chickpeas, drained","1 can crushed tomatoes","1 onion, chopped","2 celery stalks, chopped","1 tsp turmeric","1 tsp ground cinnamon","4 tbsp fresh cilantro, chopped","4 slices bread","1 lemon"],"es":["¾ taza lentejas secas","1 lata garbanzos escurridos","1 lata tomate triturado","1 cebolla picada","2 tallos de apio picados","1 cdita cúrcuma","1 cdita canela","4 cdas cilantro fresco picado","4 rebanadas de pan","1 limón"]},"steps":{"en":["Soften onion and celery with the spices.","Add lentils, tomatoes and 6 cups water; simmer 30 min.","Add chickpeas and cilantro for 5 min; serve with lemon and bread."],"es":["Rehogá la cebolla y el apio con las especias.","Sumá las lentejas, el tomate y 6 tazas de agua; cociná 30 min.","Agregá los garbanzos y el cilantro 5 min; serví con limón y pan."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"moroccan-orange-salad","type":"snack","country":"MA","group":"fruit","name":{"en":"Moroccan Orange Slices with Cinnamon","es":"Naranjas a la marroquí con canela"},"ing":{"en":["6 oranges","1 tsp ground cinnamon","1 tbsp fresh mint, chopped","4 dates, chopped"],"es":["6 naranjas","1 cdita canela","1 cda menta fresca picada","4 dátiles picados"]},"steps":{"en":["Peel the oranges and slice into rounds.","Dust with cinnamon.","Scatter dates and mint over."],"es":["Pelá las naranjas a vivo y cortalas en rodajas.","Espolvoreá con canela.","Repartí los dátiles y la menta."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"koshari","type":"dinner","country":"EG","protein":"plant","base":"rice","tags":["lentil"],"name":{"en":"Koshari (Lentils, Rice & Pasta with Tomato Sauce)","es":"Koshari: lentejas, arroz y fideos con salsa de tomate"},"ing":{"en":["1 cup lentils (dry)","1 cup rice","1 cup pasta (small shapes)","1 can chickpeas, drained","1 can crushed tomatoes","2 garlic cloves, minced","1 tsp ground cumin","2 onions, thinly sliced","1 tbsp vinegar"],"es":["1 taza lentejas secas","1 taza arroz","1 taza fideos chicos","1 lata garbanzos escurridos","1 lata tomate triturado","2 dientes de ajo picados","1 cdita comino","2 cebollas en pluma fina","1 cda vinagre"]},"steps":{"en":["Cook lentils 15 min, add rice and cook 18 min more; cook the pasta separately.","Simmer tomatoes with garlic, cumin and vinegar for 15 min.","Layer rice-lentils, pasta and chickpeas; top with sauce and crisp fried onions."],"es":["Cociná las lentejas 15 min, sumá el arroz y cociná 18 min más; cociná los fideos aparte.","Cociná el tomate con el ajo, el comino y el vinagre 15 min.","Armá capas de arroz con lentejas, fideos y garbanzos; terminá con la salsa y cebolla frita crocante."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"ful-medames","type":"breakfast","country":"EG","group":"grain","name":{"en":"Ful Medames (Spiced Fava Beans) with Pita","es":"Ful medames: habas condimentadas con pita"},"ing":{"en":["2 cans fava or white beans","2 garlic cloves, minced","1 tsp ground cumin","1 lemon","3 tbsp olive oil","2 tomatoes, diced","4 pita breads","4 eggs"],"es":["2 latas habas o porotos blancos","2 dientes de ajo picados","1 cdita comino","1 limón","3 cdas aceite de oliva","2 tomates en cubos","4 panes pita","4 huevos"]},"steps":{"en":["Warm the beans with garlic and cumin; mash roughly.","Finish with lemon, olive oil and tomato.","Serve with pita and boiled eggs."],"es":["Calentá las habas con el ajo y el comino; pisá un poco.","Terminá con limón, aceite de oliva y tomate.","Serví con pita y huevos duros."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"lablabi","type":"lunch","country":"TN","protein":"plant","base":"bread","tags":["soup"],"name":{"en":"Lablabi (Chickpea Soup with Bread & Egg)","es":"Lablabi: sopa de garbanzos con pan y huevo"},"ing":{"en":["2 cans chickpeas","3 garlic cloves, minced","1 tsp ground cumin","1 tsp harissa (optional)","5 cups vegetable broth","4 slices day-old bread","4 eggs","1 lemon"],"es":["2 latas garbanzos","3 dientes de ajo picados","1 cdita comino","1 cdita harissa (opcional)","5 tazas caldo de verduras","4 rebanadas de pan del día anterior","4 huevos","1 limón"]},"steps":{"en":["Simmer chickpeas, garlic and cumin in the broth for 15 min.","Poach the eggs in the soup for 4 min.","Ladle over torn bread with an egg each; add lemon and harissa for grown-ups."],"es":["Cociná los garbanzos, el ajo y el comino en el caldo 15 min.","Cociná los huevos en la sopa 4 min.","Serví sobre pan en trozos con un huevo cada uno; limón y harissa para los grandes."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"doro-wat","type":"dinner","country":"ET","protein":"poultry","base":"bread","tags":["stew"],"name":{"en":"Doro Wat (Spiced Chicken Stew) with Flatbread","es":"Doro wat: guiso especiado de pollo con pan plano"},"ing":{"en":["1 kg chicken thighs","3 onions, finely chopped","2 tbsp berbere spice (or paprika + chili)","2 garlic cloves, minced","1 tbsp fresh ginger, grated","2 tbsp butter","4 eggs, boiled","4 flatbreads (injera or pita)"],"es":["1 kg muslos de pollo","3 cebollas picadas finas","2 cdas especia berbere (o pimentón + ají)","2 dientes de ajo picados","1 cda jengibre fresco rallado","2 cdas manteca","4 huevos duros","4 panes planos (injera o pita)"]},"steps":{"en":["Cook the onions slowly in butter for 20 min until jammy; add berbere, garlic and ginger.","Add chicken and 1 cup water; simmer 40 min.","Add the peeled eggs for 5 min; serve with flatbread."],"es":["Cociná las cebollas despacio en manteca 20 min, hasta que se deshagan; sumá el berbere, el ajo y el jengibre.","Agregá el pollo y 1 taza de agua; cociná 40 min.","Sumá los huevos pelados 5 min; serví con pan plano."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"misir-wot","type":"lunch","country":"ET","protein":"plant","base":"bread","tags":["lentil"],"name":{"en":"Misir Wot (Red Lentil Stew) with Flatbread","es":"Misir wot: guiso de lentejas rojas con pan plano"},"ing":{"en":["1½ cups red lentils","2 onions, finely chopped","2 tbsp berbere spice (or paprika)","2 tbsp tomato paste","2 garlic cloves, minced","3 tbsp olive oil","4 flatbreads (injera or pita)"],"es":["1½ tazas lentejas rojas","2 cebollas picadas finas","2 cdas especia berbere (o pimentón)","2 cdas extracto de tomate","2 dientes de ajo picados","3 cdas aceite de oliva","4 panes planos (injera o pita)"]},"steps":{"en":["Soften the onions in oil for 10 min; add garlic, berbere and tomato paste.","Add lentils and 4 cups water; simmer 25 min, stirring, until thick.","Serve with flatbread to scoop."],"es":["Rehogá las cebollas en aceite 10 min; sumá el ajo, el berbere y el extracto.","Agregá las lentejas y 4 tazas de agua; cociná 25 min revolviendo, hasta que espese.","Serví con pan plano para comer con la mano."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"jollof-rice-with-chicken","type":"dinner","country":"NG","protein":"poultry","base":"rice","name":{"en":"Jollof Rice with Roast Chicken","es":"Arroz jollof con pollo al horno"},"ing":{"en":["1 kg chicken drumsticks or thighs","2 cups rice","1 can crushed tomatoes","2 red bell peppers","1 onion","2 tbsp tomato paste","1 tsp dried thyme","2 bay leaves","3 cups chicken broth"],"es":["1 kg patas o muslos de pollo","2 tazas arroz","1 lata tomate triturado","2 morrones rojos","1 cebolla","2 cdas extracto de tomate","1 cdita tomillo seco","2 hojas de laurel","3 tazas caldo de pollo"]},"steps":{"en":["Season the chicken with thyme and salt and roast at 200°C for 35 min.","Blend tomatoes, peppers and onion; fry with tomato paste for 15 min until reduced.","Stir in rice, broth and bay leaves; cover tightly and cook 25 min on low."],"es":["Condimentá el pollo con tomillo y sal y horneá a 200°C 35 min.","Licuá el tomate, los morrones y la cebolla; freí con el extracto 15 min hasta reducir.","Sumá el arroz, el caldo y el laurel; tapá bien y cociná 25 min a fuego bajo."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"moi-moi","type":"lunch","country":"NG","protein":"plant","base":"none","name":{"en":"Moi Moi (Steamed Bean Pudding) with Salad","es":"Moi moi: budín de porotos al vapor con ensalada"},"ing":{"en":["2 cans black-eyed or white beans, drained","1 red bell pepper","1 onion","2 eggs","3 tbsp sunflower oil","1 cup vegetable broth","1 head lettuce","2 tomatoes"],"es":["2 latas porotos tape o blancos escurridos","1 morrón rojo","1 cebolla","2 huevos","3 cdas aceite de girasol","1 taza caldo de verduras","1 planta de lechuga","2 tomates"]},"steps":{"en":["Blend beans, pepper, onion, oil and broth until smooth; season.","Pour into oiled cups with a slice of boiled egg in each.","Steam or bake in a water bath at 180°C for 40 min; serve with salad."],"es":["Licuá los porotos, el morrón, la cebolla, el aceite y el caldo; condimentá.","Volcá en moldecitos aceitados con una rodaja de huevo duro en cada uno.","Cociná al vapor o a baño María a 180°C 40 min; serví con ensalada."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"puff-puff","type":"snack","country":"NG","group":"grain","name":{"en":"Puff-Puff (Soft Dough Balls)","es":"Puff-puff: bolitas de masa esponjosa"},"ing":{"en":["2 cups flour","7 g dry yeast","3 tbsp sugar","1 cup warm water","¼ tsp nutmeg","Sunflower oil for frying"],"es":["2 tazas harina","7 g levadura seca","3 cdas azúcar","1 taza agua tibia","¼ cdita nuez moscada","Aceite de girasol para freír"]},"steps":{"en":["Mix everything into a thick, sticky batter; rise 1 hour.","Drop spoonfuls into hot oil and fry 3 min, turning, until golden.","Drain on paper."],"es":["Mezclá todo hasta tener una masa espesa y pegajosa; dejá levar 1 hora.","Echá cucharadas en aceite caliente y freí 3 min, dando vuelta, hasta dorar.","Escurrí sobre papel."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"akara-with-pap","type":"breakfast","country":"NG","group":"grain","name":{"en":"Akara (Bean Fritters) with Creamy Porridge","es":"Akara: buñuelos de porotos con papilla cremosa"},"ing":{"en":["1 can black-eyed or white beans, drained","1 onion","1 egg","3 tbsp sunflower oil","½ cup cornmeal","3 cups milk","2 bananas"],"es":["1 lata porotos tape o blancos escurridos","1 cebolla","1 huevo","3 cdas aceite de girasol","½ taza harina de maíz","3 tazas leche","2 bananas"]},"steps":{"en":["Blend beans, onion and egg into a thick paste; fry spoonfuls in oil until golden.","Whisk the cornmeal into hot milk and cook 8 min into a smooth porridge.","Serve together with banana."],"es":["Licuá los porotos con la cebolla y el huevo; freí cucharadas en aceite hasta dorar.","Batí la harina de maíz en la leche caliente y cociná 8 min hasta tener una papilla.","Serví todo junto con banana."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"nyama-stew-with-ugali","type":"dinner","country":"KE","protein":"beef","base":"grain","tags":["stew"],"name":{"en":"Kenyan Beef Stew with Ugali & Greens","es":"Guiso keniata de carne con ugali y verdes"},"ing":{"en":["600 g beef chuck, diced","1 onion, chopped","3 tomatoes, chopped","2 carrots, diced","1 tsp curry powder","2 cups fine cornmeal","1 bunch kale, shredded"],"es":["600 g carne para guiso en cubos","1 cebolla picada","3 tomates picados","2 zanahorias en cubos","1 cdita curry en polvo","2 tazas harina de maíz fina","1 atado de kale o col en tiras"]},"steps":{"en":["Brown the beef with onion; add tomato, carrot, curry and 2 cups water and simmer 1 hour.","Stir the cornmeal into 4 cups boiling water and cook 10 min, stirring hard, into a firm ugali.","Sauté the greens; serve together."],"es":["Dorá la carne con la cebolla; sumá el tomate, la zanahoria, el curry y 2 tazas de agua y cociná 1 hora.","Volcá la harina en 4 tazas de agua hirviendo y cociná 10 min revolviendo fuerte, hasta tener un ugali firme.","Salteá los verdes; serví todo junto."]},"tip":{"en":"","es":""},"prep":["cook-ahead"]},
{"id":"githeri","type":"lunch","country":"KE","protein":"plant","base":"none","tags":["stew"],"name":{"en":"Githeri (Corn & Bean Stew)","es":"Githeri: guiso de choclo y porotos"},"ing":{"en":["2 cups corn","2 cans kidney beans, drained","1 onion, chopped","2 tomatoes, chopped","2 potatoes, diced","1 carrot, diced","1 tsp curry powder","2 tbsp fresh cilantro, chopped"],"es":["2 tazas choclo","2 latas porotos colorados escurridos","1 cebolla picada","2 tomates picados","2 papas en cubos","1 zanahoria en cubos","1 cdita curry en polvo","2 cdas cilantro fresco picado"]},"steps":{"en":["Soften the onion with the curry; add tomatoes.","Add potatoes, carrot and 2 cups water; simmer 15 min.","Add corn and beans for 10 min; finish with cilantro."],"es":["Rehogá la cebolla con el curry; sumá el tomate.","Agregá las papas, la zanahoria y 2 tazas de agua; cociná 15 min.","Sumá el choclo y los porotos 10 min; terminá con cilantro."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"mandazi","type":"snack","country":"KE","group":"grain","name":{"en":"Mandazi (Coconut Doughnuts)","es":"Mandazi: buñuelos de coco"},"ing":{"en":["2 cups flour","2 tsp baking powder","¼ cup sugar","½ cup coconut milk","1 egg","½ tsp ground cardamom or cinnamon","Sunflower oil for frying"],"es":["2 tazas harina","2 cditas polvo para hornear","¼ taza azúcar","½ taza leche de coco","1 huevo","½ cdita cardamomo o canela","Aceite de girasol para freír"]},"steps":{"en":["Mix everything into a soft dough; rest 20 min.","Roll out 1 cm thick and cut triangles.","Fry until puffed and golden, 2 min a side."],"es":["Mezclá todo hasta tener una masa blanda; dejá reposar 20 min.","Estirá de 1 cm y cortá triángulos.","Freí hasta que se inflen y doren, 2 min por lado."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"bobotie","type":"dinner","country":"ZA","protein":"beef","base":"rice","name":{"en":"Bobotie with Yellow Rice","es":"Bobotie con arroz amarillo"},"ing":{"en":["600 g ground beef","1 onion, chopped","1 tbsp curry powder","1 slice bread, soaked in milk","2 tbsp apricot jam","2 tbsp raisins","2 eggs","1 cup milk","1½ cups rice","1 tsp turmeric"],"es":["600 g carne picada","1 cebolla picada","1 cda curry en polvo","1 rebanada de pan remojada en leche","2 cdas mermelada de damasco","2 cdas pasas de uva","2 huevos","1 taza leche","1½ tazas arroz","1 cdita cúrcuma"]},"steps":{"en":["Brown beef with onion and curry; stir in the soaked bread, jam and raisins.","Spread in a dish, pour over eggs whisked with milk and bake at 180°C for 30 min.","Cook the rice with turmeric and serve alongside."],"es":["Dorá la carne con la cebolla y el curry; sumá el pan remojado, la mermelada y las pasas.","Poné en una fuente, cubrí con los huevos batidos con la leche y horneá a 180°C 30 min.","Cociná el arroz con cúrcuma y serví al lado."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"bean-bunny-chow","type":"lunch","country":"ZA","protein":"plant","base":"bread","tags":["curry"],"name":{"en":"Bean Bunny Chow (Curry in a Bread Bowl)","es":"Bunny chow de porotos: curry en pan"},"ing":{"en":["2 cans kidney beans, drained","2 potatoes, diced","1 onion, chopped","1 can crushed tomatoes","1 tbsp curry powder","1 tbsp fresh ginger, grated","4 crusty rolls","1 cup grated carrot salad"],"es":["2 latas porotos colorados escurridos","2 papas en cubos","1 cebolla picada","1 lata tomate triturado","1 cda curry en polvo","1 cda jengibre fresco rallado","4 panes redondos","1 taza ensalada de zanahoria rallada"]},"steps":{"en":["Soften the onion with ginger and curry; add tomatoes, potatoes and 1 cup water and simmer 20 min.","Add beans and cook 10 min.","Hollow out the rolls, fill with curry and serve with carrot salad."],"es":["Rehogá la cebolla con el jengibre y el curry; sumá el tomate, las papas y 1 taza de agua y cociná 20 min.","Agregá los porotos y cociná 10 min.","Ahuecá los panes, rellenalos con el curry y serví con ensalada de zanahoria."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"malva-pudding","type":"snack","country":"ZA","group":"grain","tags":["cake"],"name":{"en":"Malva Pudding with Custard","es":"Malva pudding con crema"},"ing":{"en":["1 cup flour","1 tsp baking soda","1 egg","½ cup sugar","1 tbsp apricot jam","1 cup milk","1 tbsp butter","½ cup cream"],"es":["1 taza harina","1 cdita bicarbonato de sodio","1 huevo","½ taza azúcar","1 cda mermelada de damasco","1 taza leche","1 cda manteca","½ taza crema de leche"]},"steps":{"en":["Beat egg and sugar, add jam, butter, milk, flour and soda.","Bake in a buttered dish at 180°C for 35 min.","Pour warm cream over while hot; serve in small squares."],"es":["Batí el huevo con el azúcar, sumá la mermelada, la manteca, la leche, la harina y el bicarbonato.","Horneá en fuente enmantecada a 180°C 35 min.","Bañá con la crema tibia apenas sale; serví en cuadraditos."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"dal-tadka","type":"lunch","country":"IN","protein":"plant","base":"rice","tags":["lentil"],"name":{"en":"Dal Tadka with Rice","es":"Dal tadka con arroz"},"ing":{"en":["1½ cups red lentils","1 tsp turmeric","1 onion, chopped","2 tomatoes, chopped","2 garlic cloves, minced","1 tbsp fresh ginger, grated","1 tsp cumin seeds","2 tbsp butter","1½ cups rice"],"es":["1½ tazas lentejas rojas","1 cdita cúrcuma","1 cebolla picada","2 tomates picados","2 dientes de ajo picados","1 cda jengibre fresco rallado","1 cdita comino en grano","2 cdas manteca","1½ tazas arroz"]},"steps":{"en":["Simmer lentils with turmeric in 4 cups water for 20 min until soft.","Fry cumin in butter, then onion, garlic, ginger and tomato for 8 min; stir into the dal.","Serve with rice."],"es":["Cociná las lentejas con cúrcuma en 4 tazas de agua 20 min, hasta que se deshagan.","Freí el comino en manteca y después la cebolla, el ajo, el jengibre y el tomate 8 min; sumá al dal.","Serví con arroz."]},"tip":{"en":"","es":""},"prep":["rice"]},
{"id":"chana-masala","type":"dinner","country":"IN","protein":"plant","base":"rice","tags":["curry"],"name":{"en":"Chana Masala (Chickpea Curry) with Rice","es":"Chana masala: curry de garbanzos con arroz"},"ing":{"en":["2 cans chickpeas, drained","1 onion, chopped","2 garlic cloves, minced","1 tbsp fresh ginger, grated","1 can crushed tomatoes","2 tsp garam masala","1 tsp turmeric","1½ cups rice","2 tbsp fresh cilantro, chopped"],"es":["2 latas garbanzos escurridos","1 cebolla picada","2 dientes de ajo picados","1 cda jengibre fresco rallado","1 lata tomate triturado","2 cditas garam masala","1 cdita cúrcuma","1½ tazas arroz","2 cdas cilantro fresco picado"]},"steps":{"en":["Soften onion, garlic and ginger; add spices for 1 min.","Add tomatoes and chickpeas and simmer 20 min, mashing a few.","Serve with rice and cilantro."],"es":["Rehogá la cebolla, el ajo y el jengibre; sumá las especias 1 min.","Agregá el tomate y los garbanzos y cociná 20 min, pisando algunos.","Serví con arroz y cilantro."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"butter-chicken","type":"dinner","country":"IN","protein":"poultry","base":"rice","tags":["curry"],"name":{"en":"Butter Chicken with Rice","es":"Pollo a la manteca (butter chicken) con arroz"},"ing":{"en":["800 g chicken thighs, in pieces","½ cup plain yogurt","2 tsp garam masala","2 tbsp butter","1 onion, chopped","1 tbsp fresh ginger, grated","1 can crushed tomatoes","½ cup cream","1½ cups rice"],"es":["800 g muslos de pollo en trozos","½ taza yogur natural","2 cditas garam masala","2 cdas manteca","1 cebolla picada","1 cda jengibre fresco rallado","1 lata tomate triturado","½ taza crema de leche","1½ tazas arroz"]},"steps":{"en":["Marinate the chicken in yogurt and half the garam masala for 30 min.","Brown the chicken in butter; add onion, ginger and the rest of the spice, then tomatoes; simmer 20 min.","Stir in the cream; serve with rice."],"es":["Mariná el pollo con el yogur y la mitad del garam masala 30 min.","Dorá el pollo en manteca; sumá la cebolla, el jengibre y el resto de la especia y después el tomate; cociná 20 min.","Incorporá la crema; serví con arroz."]},"tip":{"en":"","es":""},"prep":["marinate"]},
{"id":"palak-paneer","type":"dinner","country":"IN","protein":"plant","base":"bread","tags":["curry"],"name":{"en":"Palak Paneer (Spinach & Cheese Curry) with Flatbread","es":"Palak paneer: curry de espinaca y queso con pan plano"},"ing":{"en":["3 bunches spinach","250 g paneer or halloumi, cubed","1 onion, chopped","2 garlic cloves, minced","1 tbsp fresh ginger, grated","1 tsp garam masala","¼ cup cream","4 naan or flatbreads"],"es":["3 atados de espinaca","250 g paneer o queso halloumi en cubos","1 cebolla picada","2 dientes de ajo picados","1 cda jengibre fresco rallado","1 cdita garam masala","¼ taza crema de leche","4 panes naan o planos"]},"steps":{"en":["Blanch the spinach 1 min and blend smooth.","Soften onion, garlic and ginger with garam masala; add spinach and simmer 5 min.","Add the cheese and cream and warm through; serve with flatbread."],"es":["Blanqueá la espinaca 1 min y licuala.","Rehogá la cebolla, el ajo y el jengibre con el garam masala; sumá la espinaca y cociná 5 min.","Agregá el queso y la crema y calentá; serví con pan plano."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"aloo-paratha","type":"breakfast","country":"IN","group":"grain","name":{"en":"Aloo Paratha (Potato-Stuffed Flatbread) with Yogurt","es":"Aloo paratha: pan relleno de papa con yogur"},"ing":{"en":["2 cups wholemeal flour","¾ cup water","3 potatoes, boiled and mashed","1 tsp ground cumin","2 tbsp fresh cilantro, chopped","2 tbsp butter","1 cup plain yogurt"],"es":["2 tazas harina integral","¾ taza agua","3 papas hervidas y pisadas","1 cdita comino","2 cdas cilantro fresco picado","2 cdas manteca","1 taza yogur natural"]},"steps":{"en":["Knead flour and water into a soft dough; rest 15 min.","Season the potato with cumin and cilantro; wrap a ball in each piece of dough and roll flat.","Cook in a dry pan, brushing with butter, 2 min a side; serve with yogurt."],"es":["Amasá la harina con el agua hasta tener una masa blanda; dejá reposar 15 min.","Condimentá la papa con comino y cilantro; envolvé una bola en cada bollo de masa y estirá.","Cociná en sartén seca pincelando con manteca, 2 min por lado; serví con yogur."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"poha","type":"breakfast","country":"IN","group":"grain","name":{"en":"Poha (Flattened Rice with Peas & Peanuts)","es":"Poha: arroz aplastado con arvejas y maní"},"ing":{"en":["2 cups flattened rice (poha) or leftover rice","1 onion, chopped","1 potato, finely diced","½ cup frozen peas","1 tsp turmeric","1 tsp mustard seeds","¼ cup peanuts (optional)","1 lemon","2 tbsp sunflower oil"],"es":["2 tazas arroz aplastado (poha) o arroz cocido","1 cebolla picada","1 papa en cubitos","½ taza arvejas congeladas","1 cdita cúrcuma","1 cdita semillas de mostaza","¼ taza maní (opcional)","1 limón","2 cdas aceite de girasol"]},"steps":{"en":["Rinse the poha and drain.","Fry mustard seeds, onion and potato in the oil for 8 min; add turmeric and peas.","Fold in the poha for 3 min; finish with lemon and peanuts."],"es":["Enjuagá el poha y escurrilo.","Freí las semillas de mostaza, la cebolla y la papa en el aceite 8 min; sumá la cúrcuma y las arvejas.","Incorporá el poha 3 min; terminá con limón y maní."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"masala-omelette","type":"breakfast","country":"IN","group":"egg","name":{"en":"Masala Omelette with Toast","es":"Omelette masala con tostadas"},"ing":{"en":["8 eggs","1 onion, finely chopped","1 tomato, finely chopped","2 tbsp fresh cilantro, chopped","½ tsp turmeric","1 tbsp butter","8 slices bread"],"es":["8 huevos","1 cebolla picada fina","1 tomate picado fino","2 cdas cilantro fresco picado","½ cdita cúrcuma","1 cda manteca","8 rebanadas de pan"]},"steps":{"en":["Beat eggs with onion, tomato, cilantro, turmeric and salt.","Cook thin omelettes in butter, folding them over.","Serve with toast."],"es":["Batí los huevos con la cebolla, el tomate, el cilantro, la cúrcuma y sal.","Cociná omelettes finas en manteca y doblalas.","Serví con tostadas."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"fruit-chaat","type":"snack","country":"IN","group":"fruit","name":{"en":"Fruit Chaat","es":"Fruit chaat: ensalada de frutas especiada"},"ing":{"en":["2 apples","2 bananas","1 cup grapes, halved","1 orange","1 lemon","½ tsp ground cumin"],"es":["2 manzanas","2 bananas","1 taza uvas en mitades","1 naranja","1 limón","½ cdita comino"]},"steps":{"en":["Dice the fruit.","Squeeze lemon over and toss.","Dust with a pinch of cumin and salt."],"es":["Cortá la fruta en cubos.","Exprimí limón por encima y mezclá.","Espolvoreá con una pizca de comino y sal."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"vegetable-pulao","type":"lunch","country":"IN","protein":"plant","base":"rice","name":{"en":"Vegetable Pulao with Raita","es":"Pulao de verduras con raita"},"ing":{"en":["1½ cups basmati rice","1 onion, sliced","1 carrot, diced","1 cup frozen peas","1 cup green beans, chopped","1 tsp cumin seeds","1 cinnamon stick","1 cup plain yogurt","1 cucumber, grated"],"es":["1½ tazas arroz basmati","1 cebolla en pluma","1 zanahoria en cubos","1 taza arvejas congeladas","1 taza chauchas picadas","1 cdita comino en grano","1 rama de canela","1 taza yogur natural","1 pepino rallado"]},"steps":{"en":["Fry cumin, cinnamon and onion; add vegetables and rice and stir 2 min.","Add 3 cups water, cover and cook 15 min; rest 5 min.","Mix yogurt and cucumber into a raita to serve alongside."],"es":["Freí el comino, la canela y la cebolla; sumá las verduras y el arroz y revolvé 2 min.","Agregá 3 tazas de agua, tapá y cociná 15 min; dejá reposar 5 min.","Mezclá el yogur con el pepino para la raita y serví al lado."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"sri-lankan-fish-curry","type":"dinner","country":"LK","protein":"fish","base":"rice","tags":["curry"],"name":{"en":"Sri Lankan Coconut Fish Curry","es":"Curry de pescado con coco de Sri Lanka"},"ing":{"en":["700 g firm white fish, in chunks","1 can coconut milk","1 onion, sliced","2 garlic cloves, minced","1 tbsp curry powder","1 tsp turmeric","2 tomatoes, chopped","1 lime","1½ cups rice"],"es":["700 g pescado blanco firme en trozos","1 lata leche de coco","1 cebolla en pluma","2 dientes de ajo picados","1 cda curry en polvo","1 cdita cúrcuma","2 tomates picados","1 lima","1½ tazas arroz"]},"steps":{"en":["Soften onion and garlic with the spices.","Add tomatoes and coconut milk and simmer 10 min.","Add the fish and cook 8 min; finish with lime; serve with rice."],"es":["Rehogá la cebolla y el ajo con las especias.","Sumá el tomate y la leche de coco y cociná 10 min.","Agregá el pescado y cociná 8 min; terminá con lima; serví con arroz."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"kiribath","type":"breakfast","country":"LK","group":"grain","name":{"en":"Kiribath (Coconut Milk Rice) with Banana","es":"Kiribath: arroz con leche de coco y banana"},"ing":{"en":["1½ cups short-grain rice","1 can coconut milk","3 cups water","4 bananas"],"es":["1½ tazas arroz de grano corto","1 lata leche de coco","3 tazas agua","4 bananas"]},"steps":{"en":["Cook the rice in the water for 15 min.","Stir in the coconut milk and a pinch of salt and cook 10 min until thick.","Press into a dish, cut into diamonds and serve with banana."],"es":["Cociná el arroz en el agua 15 min.","Sumá la leche de coco y una pizca de sal y cociná 10 min, hasta que espese.","Aplastá en una fuente, cortá en rombos y serví con banana."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"pad-thai","type":"lunch","country":"TH","protein":"fish","base":"pasta","tags":["stir-fry-noodles"],"name":{"en":"Shrimp Pad Thai","es":"Pad thai de langostinos"},"ing":{"en":["300 g rice noodles","300 g shrimp, peeled","2 eggs","2 cups bean sprouts","3 spring onions, sliced","2 tbsp fish sauce","1 tbsp brown sugar","2 limes","¼ cup peanuts, chopped (optional)"],"es":["300 g fideos de arroz","300 g langostinos pelados","2 huevos","2 tazas brotes de soja","3 cebollas de verdeo en rodajas","2 cdas salsa de pescado","1 cda azúcar mascabo","2 limas","¼ taza maní picado (opcional)"]},"steps":{"en":["Soak the noodles in hot water for 8 min; drain.","Stir-fry the shrimp 2 min, push aside and scramble the eggs.","Add noodles, fish sauce, sugar and lime juice; toss with sprouts and spring onion; top with peanuts."],"es":["Remojá los fideos en agua caliente 8 min; escurrí.","Saltá los langostinos 2 min, correlos y revolvé los huevos.","Sumá los fideos, la salsa de pescado, el azúcar y el jugo de lima; mezclá con los brotes y el verdeo; terminá con maní."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"thai-green-curry","type":"dinner","country":"TH","protein":"poultry","base":"rice","tags":["curry"],"name":{"en":"Thai Green Chicken Curry","es":"Curry verde tailandés de pollo"},"ing":{"en":["600 g chicken breast, sliced","2 tbsp green curry paste","1 can coconut milk","1 zucchini, sliced","1 cup green beans","1 tbsp fish sauce","1 handful fresh basil","1½ cups jasmine rice"],"es":["600 g pechuga de pollo en tiras","2 cdas pasta de curry verde","1 lata leche de coco","1 zapallito en rodajas","1 taza chauchas","1 cda salsa de pescado","1 puñado de albahaca fresca","1½ tazas arroz jazmín"]},"steps":{"en":["Fry the curry paste in a little coconut milk for 2 min.","Add chicken, the rest of the coconut milk and the vegetables; simmer 12 min.","Season with fish sauce and basil; serve with rice."],"es":["Freí la pasta de curry en un poco de leche de coco 2 min.","Sumá el pollo, el resto de la leche de coco y las verduras; cociná 12 min.","Condimentá con salsa de pescado y albahaca; serví con arroz."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"tom-kha-gai","type":"lunch","country":"TH","protein":"poultry","base":"rice","tags":["soup"],"name":{"en":"Tom Kha Gai (Coconut Chicken Soup)","es":"Tom kha gai: sopa de pollo y coco"},"ing":{"en":["500 g chicken breast, sliced","1 can coconut milk","3 cups chicken broth","1 stalk lemongrass, bruised","1 tbsp fresh ginger, sliced","200 g mushrooms, sliced","2 limes","1 tbsp fish sauce","1 cup rice"],"es":["500 g pechuga de pollo en tiras","1 lata leche de coco","3 tazas caldo de pollo","1 tallo de lemongrass machacado","1 cda jengibre fresco en láminas","200 g champiñones en láminas","2 limas","1 cda salsa de pescado","1 taza arroz"]},"steps":{"en":["Simmer broth, coconut milk, lemongrass and ginger for 10 min.","Add chicken and mushrooms and cook 8 min.","Season with lime and fish sauce; serve with a little rice."],"es":["Cociná el caldo, la leche de coco, el lemongrass y el jengibre 10 min.","Sumá el pollo y los champiñones y cociná 8 min.","Condimentá con lima y salsa de pescado; serví con un poco de arroz."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"pad-kra-pao","type":"dinner","country":"TH","protein":"poultry","base":"rice","name":{"en":"Thai Basil Chicken with Fried Egg","es":"Pollo salteado con albahaca y huevo frito"},"ing":{"en":["600 g ground chicken or chicken thighs, chopped","3 garlic cloves, minced","1 red bell pepper, sliced","2 tbsp soy sauce","1 tbsp oyster sauce","1 handful fresh basil","4 eggs","1½ cups jasmine rice"],"es":["600 g pollo picado o muslos picados","3 dientes de ajo picados","1 morrón rojo en tiras","2 cdas salsa de soja","1 cda salsa de ostras","1 puñado de albahaca fresca","4 huevos","1½ tazas arroz jazmín"]},"steps":{"en":["Stir-fry garlic and chicken over high heat for 5 min.","Add pepper, soy and oyster sauce for 2 min; toss in the basil.","Serve over rice with a fried egg on top."],"es":["Saltá el ajo y el pollo a fuego fuerte 5 min.","Sumá el morrón, la soja y la salsa de ostras 2 min; agregá la albahaca.","Serví sobre arroz con un huevo frito arriba."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"mango-sticky-rice","type":"snack","country":"TH","group":"fruit","name":{"en":"Mango with Coconut Sticky Rice","es":"Mango con arroz glutinoso de coco"},"ing":{"en":["1 cup glutinous or short-grain rice","1 can coconut milk","2 tbsp sugar","2 ripe mangoes","1 tbsp sesame seeds (optional)"],"es":["1 taza arroz glutinoso o de grano corto","1 lata leche de coco","2 cdas azúcar","2 mangos maduros","1 cda semillas de sésamo (opcional)"]},"steps":{"en":["Soak the rice 1 hour; steam or simmer until tender.","Warm half the coconut milk with the sugar and a pinch of salt and stir into the rice.","Serve with sliced mango and the rest of the coconut milk."],"es":["Remojá el arroz 1 hora; cocinalo al vapor o hervido hasta que esté tierno.","Calentá la mitad de la leche de coco con el azúcar y una pizca de sal y mezclá con el arroz.","Serví con mango en láminas y el resto de la leche de coco."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"pho-ga","type":"lunch","country":"VN","protein":"poultry","base":"pasta","tags":["soup"],"name":{"en":"Phở Gà (Chicken Noodle Soup)","es":"Phở gà: sopa de pollo con fideos de arroz"},"ing":{"en":["600 g chicken breast","8 cups chicken broth","1 onion, halved","1 tbsp fresh ginger, sliced","1 cinnamon stick","2 star anise (optional)","300 g rice noodles","2 cups bean sprouts","1 handful fresh herbs (basil, cilantro, mint)","2 limes"],"es":["600 g pechuga de pollo","8 tazas caldo de pollo","1 cebolla en mitades","1 cda jengibre fresco en láminas","1 rama de canela","2 anís estrellado (opcional)","300 g fideos de arroz","2 tazas brotes de soja","1 puñado de hierbas frescas (albahaca, cilantro, menta)","2 limas"]},"steps":{"en":["Char the onion and ginger in a dry pan; simmer in the broth with the spices and chicken for 20 min.","Shred the chicken; soak the noodles in hot water.","Put noodles and chicken in bowls, pour the strained broth over and add sprouts, herbs and lime."],"es":["Tostá la cebolla y el jengibre en sartén seca; cociná en el caldo con las especias y el pollo 20 min.","Desmenuzá el pollo; remojá los fideos en agua caliente.","Poné fideos y pollo en los bowls, volcá el caldo colado y sumá brotes, hierbas y lima."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"bun-cha","type":"dinner","country":"VN","protein":"pork","base":"pasta","name":{"en":"Bún Chả (Pork Patties with Rice Noodles & Herbs)","es":"Bún chả: hamburguesitas de cerdo con fideos de arroz"},"ing":{"en":["500 g ground pork","2 garlic cloves, minced","2 tbsp fish sauce","1 tbsp brown sugar","300 g rice noodles","1 head lettuce","1 cucumber, sliced","1 handful fresh herbs (mint, cilantro)","2 limes"],"es":["500 g carne picada de cerdo","2 dientes de ajo picados","2 cdas salsa de pescado","1 cda azúcar mascabo","300 g fideos de arroz","1 planta de lechuga","1 pepino en rodajas","1 puñado de hierbas frescas (menta, cilantro)","2 limas"]},"steps":{"en":["Mix pork, garlic, half the fish sauce and sugar; shape small patties and grill 8 min.","Soak the noodles; mix the rest of the fish sauce with lime juice and water for dipping.","Serve patties, noodles, lettuce, cucumber and herbs to build bowls."],"es":["Mezclá el cerdo, el ajo, la mitad de la salsa de pescado y el azúcar; formá hamburguesitas y cocinalas a la plancha 8 min.","Remojá los fideos; mezclá el resto de la salsa de pescado con jugo de lima y agua para mojar.","Serví las hamburguesitas, los fideos, la lechuga, el pepino y las hierbas para armar bowls."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"banh-mi","type":"lunch","country":"VN","protein":"pork","base":"bread","name":{"en":"Bánh Mì with Pork & Pickled Vegetables","es":"Bánh mì de cerdo con verduras encurtidas"},"ing":{"en":["500 g pork tenderloin","2 tbsp soy sauce","1 tbsp honey","2 carrots, in thin sticks","1 cucumber, in thin sticks","3 tbsp vinegar","4 crusty rolls","2 tbsp mayonnaise","1 handful fresh cilantro"],"es":["500 g lomo de cerdo","2 cdas salsa de soja","1 cda miel","2 zanahorias en bastones finos","1 pepino en bastones finos","3 cdas vinagre","4 panes franceses","2 cdas mayonesa","1 puñado de cilantro fresco"]},"steps":{"en":["Marinate the pork in soy and honey; roast at 200°C for 20 min and slice thin.","Quick-pickle carrot and cucumber in vinegar with a pinch of sugar for 15 min.","Fill mayonnaise-spread rolls with pork, pickles and cilantro."],"es":["Mariná el cerdo con soja y miel; horneá a 200°C 20 min y cortá fino.","Encurtí la zanahoria y el pepino en vinagre con una pizca de azúcar 15 min.","Rellená los panes con mayonesa, el cerdo, las verduras y el cilantro."]},"tip":{"en":"","es":""},"prep":["marinate"]},
{"id":"ca-kho","type":"dinner","country":"VN","protein":"fish","base":"rice","name":{"en":"Cá Kho (Caramel-Braised Fish) with Rice","es":"Cá kho: pescado braseado en caramelo con arroz"},"ing":{"en":["700 g firm white fish, in chunks","2 tbsp brown sugar","2 tbsp fish sauce","2 garlic cloves, minced","3 spring onions, sliced","½ cup water","1½ cups rice","1 cucumber"],"es":["700 g pescado blanco firme en trozos","2 cdas azúcar mascabo","2 cdas salsa de pescado","2 dientes de ajo picados","3 cebollas de verdeo en rodajas","½ taza agua","1½ tazas arroz","1 pepino"]},"steps":{"en":["Melt the sugar in a pan until amber; add garlic, fish sauce and water.","Add the fish, cover and simmer 15 min, turning once, until glazed.","Top with spring onion; serve with rice and cucumber."],"es":["Derretí el azúcar hasta que esté dorado; sumá el ajo, la salsa de pescado y el agua.","Agregá el pescado, tapá y cociná 15 min, dando vuelta una vez, hasta que se glasee.","Terminá con verdeo; serví con arroz y pepino."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"mapo-tofu","type":"dinner","country":"CN","protein":"plant","base":"rice","name":{"en":"Mild Mapo Tofu with Rice","es":"Mapo tofu suave con arroz"},"ing":{"en":["500 g firm tofu, cubed","200 g mushrooms, finely chopped","2 garlic cloves, minced","1 tbsp fresh ginger, grated","2 tbsp soy sauce","1 tbsp chili bean paste (optional)","1 tbsp cornstarch","3 spring onions, sliced","1½ cups rice"],"es":["500 g tofu firme en cubos","200 g champiñones picados finos","2 dientes de ajo picados","1 cda jengibre fresco rallado","2 cdas salsa de soja","1 cda pasta de porotos picante (opcional)","1 cda maicena","3 cebollas de verdeo en rodajas","1½ tazas arroz"]},"steps":{"en":["Fry garlic, ginger and mushrooms for 5 min.","Add 1 cup water, soy and chili paste, then the tofu; simmer 5 min.","Thicken with cornstarch mixed in water; top with spring onion and serve with rice."],"es":["Saltá el ajo, el jengibre y los champiñones 5 min.","Sumá 1 taza de agua, la soja y la pasta picante y después el tofu; cociná 5 min.","Espesá con la maicena disuelta en agua; terminá con verdeo y serví con arroz."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"kung-pao-chicken","type":"dinner","country":"CN","protein":"poultry","base":"rice","tags":["stir-fry"],"name":{"en":"Kung Pao Chicken with Rice","es":"Pollo kung pao con arroz"},"ing":{"en":["600 g chicken breast, diced","2 tbsp soy sauce","1 tbsp vinegar","1 tbsp honey","1 tsp cornstarch","1 red bell pepper, diced","1 zucchini, diced","¼ cup peanuts","1½ cups rice"],"es":["600 g pechuga de pollo en cubos","2 cdas salsa de soja","1 cda vinagre","1 cda miel","1 cdita maicena","1 morrón rojo en cubos","1 zapallito en cubos","¼ taza maní","1½ tazas arroz"]},"steps":{"en":["Toss the chicken with half the soy and the cornstarch.","Stir-fry the chicken 5 min, add pepper and zucchini for 3 min.","Add the rest of the soy, vinegar and honey and the peanuts; serve with rice."],"es":["Mezclá el pollo con la mitad de la soja y la maicena.","Saltá el pollo 5 min y sumá el morrón y el zapallito 3 min.","Agregá el resto de la soja, el vinagre, la miel y el maní; serví con arroz."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"congee-with-egg","type":"breakfast","country":"CN","group":"grain","name":{"en":"Congee (Rice Porridge) with Egg & Spring Onion","es":"Congee: sopa de arroz con huevo y verdeo"},"ing":{"en":["1 cup rice","8 cups chicken broth","1 tbsp fresh ginger, sliced","4 eggs","3 spring onions, sliced","1 tbsp soy sauce"],"es":["1 taza arroz","8 tazas caldo de pollo","1 cda jengibre fresco en láminas","4 huevos","3 cebollas de verdeo en rodajas","1 cda salsa de soja"]},"steps":{"en":["Simmer rice, broth and ginger for 1 hour, stirring now and then, until creamy.","Soft-boil the eggs for 7 min and halve.","Serve with egg, spring onion and a few drops of soy."],"es":["Cociná el arroz, el caldo y el jengibre 1 hora, revolviendo de vez en cuando, hasta que esté cremoso.","Herví los huevos 7 min y cortalos al medio.","Serví con huevo, verdeo y unas gotas de soja."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"jiaozi","type":"lunch","country":"CN","protein":"pork","base":"pasta","tags":["ravioli"],"name":{"en":"Pork & Cabbage Dumplings (Jiaozi)","es":"Jiaozi: empanaditas de cerdo y repollo"},"ing":{"en":["30 dumpling wrappers","400 g ground pork","2 cups Chinese cabbage, finely chopped","2 spring onions, finely chopped","1 tbsp fresh ginger, grated","2 tbsp soy sauce","1 tsp sesame oil","2 tbsp vinegar"],"es":["30 tapitas para dumplings","400 g carne picada de cerdo","2 tazas repollo chino picado fino","2 cebollas de verdeo picadas finas","1 cda jengibre fresco rallado","2 cdas salsa de soja","1 cdita aceite de sésamo","2 cdas vinagre"]},"steps":{"en":["Salt the cabbage 10 min and squeeze dry; mix with pork, spring onion, ginger, soy and sesame oil.","Fill and pleat the wrappers.","Boil 6 min after they float; serve with vinegar for dipping."],"es":["Salá el repollo 10 min y escurrilo; mezclá con el cerdo, el verdeo, el jengibre, la soja y el aceite de sésamo.","Rellená y cerrá las tapitas haciendo pliegues.","Herví 6 min desde que flotan; serví con vinagre para mojar."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"tomato-and-egg-stir-fry","type":"lunch","country":"CN","protein":"egg","base":"rice","name":{"en":"Tomato & Egg Stir-Fry with Rice","es":"Huevos salteados con tomate y arroz"},"ing":{"en":["6 eggs","5 tomatoes, in wedges","2 spring onions, sliced","1 tbsp sugar","1 tbsp soy sauce","2 tbsp sunflower oil","1½ cups rice"],"es":["6 huevos","5 tomates en gajos","2 cebollas de verdeo en rodajas","1 cda azúcar","1 cda salsa de soja","2 cdas aceite de girasol","1½ tazas arroz"]},"steps":{"en":["Scramble the eggs in half the oil until just set; remove.","Fry the tomatoes 4 min until juicy; add sugar and soy.","Return the eggs, add spring onion and serve over rice."],"es":["Revolvé los huevos en la mitad del aceite hasta que apenas cuajen; sacalos.","Saltá los tomates 4 min hasta que larguen jugo; sumá el azúcar y la soja.","Volvé a poner los huevos, sumá el verdeo y serví sobre arroz."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"steamed-fish-with-ginger","type":"dinner","country":"CN","protein":"fish","base":"rice","name":{"en":"Steamed Fish with Ginger & Spring Onion","es":"Pescado al vapor con jengibre y verdeo"},"ing":{"en":["4 white fish fillets","2 tbsp fresh ginger, in thin strips","4 spring onions, in thin strips","2 tbsp soy sauce","2 tbsp sunflower oil","1½ cups rice","1 head broccoli"],"es":["4 filetes de pescado blanco","2 cdas jengibre fresco en tiritas","4 cebollas de verdeo en tiritas","2 cdas salsa de soja","2 cdas aceite de girasol","1½ tazas arroz","1 brócoli"]},"steps":{"en":["Steam the fish with half the ginger for 8 min.","Top with the rest of the ginger and spring onion; pour hot oil and soy over.","Serve with rice and steamed broccoli."],"es":["Cociná el pescado al vapor con la mitad del jengibre 8 min.","Cubrí con el resto del jengibre y el verdeo; volcá aceite caliente y soja por encima.","Serví con arroz y brócoli al vapor."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"scallion-pancakes","type":"snack","country":"CN","group":"grain","name":{"en":"Scallion Pancakes","es":"Panqueques de cebolla de verdeo"},"ing":{"en":["2 cups flour","¾ cup hot water","4 spring onions, finely sliced","1 tbsp sesame oil","2 tbsp sunflower oil","2 tbsp soy sauce"],"es":["2 tazas harina","¾ taza agua caliente","4 cebollas de verdeo en rodajas finas","1 cda aceite de sésamo","2 cdas aceite de girasol","2 cdas salsa de soja"]},"steps":{"en":["Mix flour and hot water into a dough; rest 20 min.","Roll out, brush with sesame oil, scatter spring onion, roll up, coil and flatten again.","Fry 3 min a side until crisp; cut into wedges with soy for dipping."],"es":["Uní la harina con el agua caliente; dejá reposar 20 min.","Estirá, pincelá con aceite de sésamo, esparcí el verdeo, enrollá, hacé un caracol y aplaná de nuevo.","Freí 3 min por lado hasta que estén crocantes; cortá en porciones y serví con soja."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"japanese-breakfast","type":"breakfast","country":"JP","group":"grain","name":{"en":"Japanese Breakfast: Rice, Miso Soup & Salmon","es":"Desayuno japonés: arroz, sopa miso y salmón"},"ing":{"en":["1½ cups short-grain rice","3 tbsp miso paste","200 g silken tofu, cubed","2 spring onions, sliced","2 salmon fillets","1 cucumber"],"es":["1½ tazas arroz de grano corto","3 cdas pasta de miso","200 g tofu sedoso en cubos","2 cebollas de verdeo en rodajas","2 filetes de salmón","1 pepino"]},"steps":{"en":["Cook the rice.","Heat 4 cups water, dissolve the miso off the boil and add tofu and spring onion.","Grill the salmon 8 min and flake; serve with rice, soup and cucumber."],"es":["Cociná el arroz.","Calentá 4 tazas de agua, disolvé el miso sin que hierva y sumá el tofu y el verdeo.","Cociná el salmón a la plancha 8 min y desmenuzalo; serví con arroz, la sopa y pepino."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"tamagoyaki","type":"breakfast","country":"JP","group":"egg","name":{"en":"Tamagoyaki (Rolled Omelette) with Rice","es":"Tamagoyaki: omelette enrollada con arroz"},"ing":{"en":["8 eggs","1 tbsp sugar","1 tbsp soy sauce","1 tbsp sunflower oil","1 cup short-grain rice","1 cucumber"],"es":["8 huevos","1 cda azúcar","1 cda salsa de soja","1 cda aceite de girasol","1 taza arroz de grano corto","1 pepino"]},"steps":{"en":["Beat eggs with sugar, soy and 3 tbsp water.","Pour a thin layer into an oiled pan, roll it up, add another layer and roll again until used up.","Slice and serve with rice and cucumber."],"es":["Batí los huevos con el azúcar, la soja y 3 cdas de agua.","Volcá una capa fina en sartén aceitada, enrollala, sumá otra capa y volvé a enrollar hasta terminar.","Cortá en rodajas y serví con arroz y pepino."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"oyakodon","type":"lunch","country":"JP","protein":"poultry","base":"rice","name":{"en":"Oyakodon (Chicken & Egg Rice Bowl)","es":"Oyakodon: bowl de arroz con pollo y huevo"},"ing":{"en":["500 g chicken thighs, sliced","1 onion, sliced","1 cup chicken broth","2 tbsp soy sauce","1 tbsp sugar","6 eggs","1½ cups short-grain rice","2 spring onions, sliced"],"es":["500 g muslos de pollo en tiras","1 cebolla en pluma","1 taza caldo de pollo","2 cdas salsa de soja","1 cda azúcar","6 huevos","1½ tazas arroz de grano corto","2 cebollas de verdeo en rodajas"]},"steps":{"en":["Simmer onion in broth, soy and sugar for 5 min; add chicken and cook 6 min.","Pour in the lightly beaten eggs, cover and cook 2 min until just set.","Slide over bowls of rice and top with spring onion."],"es":["Cociná la cebolla en el caldo con la soja y el azúcar 5 min; sumá el pollo y cociná 6 min.","Volcá los huevos apenas batidos, tapá y cociná 2 min hasta que cuajen.","Serví sobre bowls de arroz con verdeo."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"chicken-katsu-curry","type":"dinner","country":"JP","protein":"poultry","base":"rice","tags":["curry"],"name":{"en":"Chicken Katsu Curry","es":"Curry japonés con pollo katsu"},"ing":{"en":["4 chicken breasts, butterflied","1 egg","1½ cups panko or breadcrumbs","1 onion, chopped","2 carrots, diced","2 potatoes, diced","2 tbsp curry powder","2 tbsp flour","2 cups chicken broth","1½ cups short-grain rice"],"es":["4 pechugas de pollo abiertas","1 huevo","1½ tazas panko o pan rallado","1 cebolla picada","2 zanahorias en cubos","2 papas en cubos","2 cdas curry en polvo","2 cdas harina","2 tazas caldo de pollo","1½ tazas arroz de grano corto"]},"steps":{"en":["Bread the chicken in egg and panko; bake at 210°C for 20 min and slice.","Soften onion, carrot and potato; stir in flour and curry, then broth; simmer 20 min until thick.","Serve rice, curry sauce and the crisp chicken."],"es":["Empaná el pollo con huevo y panko; horneá a 210°C 20 min y cortá en tiras.","Rehogá la cebolla, la zanahoria y la papa; sumá la harina y el curry y después el caldo; cociná 20 min hasta que espese.","Serví arroz, la salsa de curry y el pollo crocante."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"yaki-udon","type":"dinner","country":"JP","protein":"pork","base":"pasta","tags":["stir-fry-noodles"],"name":{"en":"Yaki Udon with Pork & Vegetables","es":"Yaki udon con cerdo y verduras"},"ing":{"en":["600 g udon noodles","300 g pork tenderloin, thinly sliced","¼ cabbage, shredded","1 carrot, in thin sticks","200 g mushrooms, sliced","3 tbsp soy sauce","1 tbsp Worcestershire sauce","2 spring onions, sliced"],"es":["600 g fideos udon","300 g lomo de cerdo en tiras finas","¼ repollo en juliana","1 zanahoria en bastones finos","200 g champiñones en láminas","3 cdas salsa de soja","1 cda salsa inglesa","2 cebollas de verdeo en rodajas"]},"steps":{"en":["Stir-fry the pork 3 min; add cabbage, carrot and mushrooms for 4 min.","Add the loosened noodles, soy and Worcestershire; toss 3 min.","Top with spring onion."],"es":["Saltá el cerdo 3 min; sumá el repollo, la zanahoria y los champiñones 4 min.","Agregá los fideos sueltos, la soja y la salsa inglesa; saltá 3 min.","Terminá con verdeo."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"salmon-onigiri","type":"snack","country":"JP","group":"grain","name":{"en":"Salmon Rice Balls (Onigiri)","es":"Onigiri: bolitas de arroz con salmón"},"ing":{"en":["1½ cups short-grain rice","1 salmon fillet, cooked and flaked","2 sheets nori seaweed","1 tbsp sesame seeds"],"es":["1½ tazas arroz de grano corto","1 filete de salmón cocido y desmenuzado","2 hojas de alga nori","1 cda semillas de sésamo"]},"steps":{"en":["Cook the rice and let it cool until warm.","With wet, salted hands shape triangles with a little salmon inside.","Wrap with a strip of nori and sprinkle with sesame."],"es":["Cociná el arroz y dejalo entibiar.","Con las manos mojadas y saladas formá triángulos con un poco de salmón adentro.","Envolvé con una tira de nori y espolvoreá con sésamo."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"okonomiyaki","type":"lunch","country":"JP","protein":"egg","base":"none","name":{"en":"Okonomiyaki (Cabbage Pancakes)","es":"Okonomiyaki: tortitas de repollo"},"ing":{"en":["½ cabbage, finely shredded","1 cup flour","4 eggs","¾ cup vegetable broth","3 spring onions, sliced","2 tbsp sunflower oil","2 tbsp mayonnaise","2 tbsp Worcestershire sauce"],"es":["½ repollo en juliana fina","1 taza harina","4 huevos","¾ taza caldo de verduras","3 cebollas de verdeo en rodajas","2 cdas aceite de girasol","2 cdas mayonesa","2 cdas salsa inglesa"]},"steps":{"en":["Whisk flour, eggs and broth; fold in cabbage and spring onion.","Cook thick pancakes in oil, 5 min a side, covered.","Drizzle with Worcestershire and mayonnaise."],"es":["Batí la harina, los huevos y el caldo; incorporá el repollo y el verdeo.","Cociná tortitas gruesas en aceite, 5 min por lado, tapadas.","Rociá con salsa inglesa y mayonesa."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"bibimbap","type":"lunch","country":"KR","protein":"beef","base":"rice","name":{"en":"Bibimbap","es":"Bibimbap"},"ing":{"en":["1½ cups short-grain rice","300 g ground beef","2 tbsp soy sauce","2 carrots, in thin sticks","1 zucchini, in thin sticks","2 cups spinach","2 cups bean sprouts","4 eggs","1 tbsp sesame oil","1 tbsp gochujang (optional)"],"es":["1½ tazas arroz de grano corto","300 g carne picada","2 cdas salsa de soja","2 zanahorias en bastones finos","1 zapallito en bastones finos","2 tazas espinaca","2 tazas brotes de soja","4 huevos","1 cda aceite de sésamo","1 cda gochujang (opcional)"]},"steps":{"en":["Cook the rice; brown the beef with the soy.","Quickly sauté each vegetable separately with a drop of sesame oil; fry the eggs.","Arrange everything over the rice with an egg on top; gochujang for grown-ups."],"es":["Cociná el arroz; dorá la carne con la soja.","Salteá rápido cada verdura por separado con unas gotas de aceite de sésamo; freí los huevos.","Acomodá todo sobre el arroz con un huevo arriba; gochujang para los grandes."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"japchae","type":"dinner","country":"KR","protein":"beef","base":"pasta","tags":["stir-fry-noodles"],"name":{"en":"Japchae (Glass Noodles with Beef & Vegetables)","es":"Japchae: fideos de batata con carne y verduras"},"ing":{"en":["300 g sweet potato glass noodles","300 g beef sirloin, in thin strips","1 onion, sliced","1 carrot, in thin sticks","1 red bell pepper, sliced","2 cups spinach","200 g mushrooms, sliced","4 tbsp soy sauce","1 tbsp sesame oil","1 tbsp sugar"],"es":["300 g fideos de almidón de batata","300 g lomo en tiras finas","1 cebolla en pluma","1 zanahoria en bastones finos","1 morrón rojo en tiras","2 tazas espinaca","200 g champiñones en láminas","4 cdas salsa de soja","1 cda aceite de sésamo","1 cda azúcar"]},"steps":{"en":["Cook the noodles 6 min; drain and toss with half the soy, sugar and sesame oil.","Stir-fry the beef, then the vegetables.","Toss everything with the noodles and the rest of the soy."],"es":["Cociná los fideos 6 min; escurrí y mezclá con la mitad de la soja, el azúcar y el aceite de sésamo.","Saltá la carne y después las verduras.","Mezclá todo con los fideos y el resto de la soja."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"kimchi-fried-rice","type":"lunch","country":"KR","protein":"plant","base":"rice","tags":["fried-rice"],"name":{"en":"Kimchi Fried Rice with Egg","es":"Arroz frito con kimchi y huevo"},"ing":{"en":["4 cups cooked rice","1½ cups kimchi, chopped","1 onion, chopped","1 cup frozen peas","4 eggs","1 tbsp soy sauce","1 tbsp sesame oil","2 spring onions, sliced"],"es":["4 tazas arroz cocido","1½ tazas kimchi picado","1 cebolla picada","1 taza arvejas congeladas","4 huevos","1 cda salsa de soja","1 cda aceite de sésamo","2 cebollas de verdeo en rodajas"]},"steps":{"en":["Fry onion and kimchi in sesame oil for 4 min.","Add rice, peas and soy and stir-fry 5 min until hot.","Serve with a fried egg and spring onion."],"es":["Saltá la cebolla y el kimchi en el aceite de sésamo 4 min.","Sumá el arroz, las arvejas y la soja y saltá 5 min, hasta que esté caliente.","Serví con un huevo frito y verdeo."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"pajeon","type":"snack","country":"KR","group":"veg","name":{"en":"Pajeon (Spring Onion & Vegetable Pancakes)","es":"Pajeon: tortitas de verdeo y verduras"},"ing":{"en":["1 cup flour","1 egg","¾ cup water","6 spring onions, in 6 cm lengths","1 zucchini, in thin sticks","2 tbsp sunflower oil","2 tbsp soy sauce"],"es":["1 taza harina","1 huevo","¾ taza agua","6 cebollas de verdeo en trozos de 6 cm","1 zapallito en bastones finos","2 cdas aceite de girasol","2 cdas salsa de soja"]},"steps":{"en":["Whisk flour, egg and water.","Lay spring onion and zucchini in an oiled pan and pour the batter over.","Cook 4 min a side until crisp; cut and serve with soy."],"es":["Batí la harina, el huevo y el agua.","Acomodá el verdeo y el zapallito en una sartén aceitada y volcá la mezcla encima.","Cociná 4 min por lado hasta que esté crocante; cortá y serví con soja."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"chicken-adobo","type":"dinner","country":"PH","protein":"poultry","base":"rice","name":{"en":"Chicken Adobo with Rice","es":"Pollo adobo con arroz"},"ing":{"en":["1 kg chicken thighs","½ cup soy sauce","⅓ cup vinegar","6 garlic cloves, crushed","2 bay leaves","1 tsp black peppercorns","1½ cups rice","300 g green beans"],"es":["1 kg muslos de pollo","½ taza salsa de soja","⅓ taza vinagre","6 dientes de ajo machacados","2 hojas de laurel","1 cdita pimienta en grano","1½ tazas arroz","300 g chauchas"]},"steps":{"en":["Marinate the chicken in soy, vinegar, garlic, bay and pepper for 30 min.","Simmer covered for 30 min, then uncover and cook until the sauce reduces.","Serve with rice and green beans."],"es":["Mariná el pollo con la soja, el vinagre, el ajo, el laurel y la pimienta 30 min.","Cociná tapado 30 min y después destapado hasta que la salsa se reduzca.","Serví con arroz y chauchas."]},"tip":{"en":"","es":""},"prep":["marinate"]},
{"id":"pancit-canton","type":"lunch","country":"PH","protein":"pork","base":"pasta","tags":["stir-fry-noodles"],"name":{"en":"Pancit Canton (Stir-Fried Noodles)","es":"Pancit canton: fideos salteados filipinos"},"ing":{"en":["400 g egg noodles","300 g pork tenderloin, sliced","¼ cabbage, shredded","1 carrot, in thin sticks","1 cup green beans, sliced","3 tbsp soy sauce","1 tbsp oyster sauce","1 cup chicken broth","1 lime"],"es":["400 g fideos de huevo","300 g lomo de cerdo en tiras","¼ repollo en juliana","1 zanahoria en bastones finos","1 taza chauchas en tiras","3 cdas salsa de soja","1 cda salsa de ostras","1 taza caldo de pollo","1 lima"]},"steps":{"en":["Stir-fry the pork 4 min; add the vegetables for 3 min.","Add broth, soy and oyster sauce and the noodles; toss until the liquid is absorbed.","Serve with lime."],"es":["Saltá el cerdo 4 min; sumá las verduras 3 min.","Agregá el caldo, la soja, la salsa de ostras y los fideos; mezclá hasta que se absorba el líquido.","Serví con lima."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"turon","type":"snack","country":"PH","group":"fruit","name":{"en":"Turon (Crisp Banana Rolls)","es":"Turon: rollitos crocantes de banana"},"ing":{"en":["4 bananas, halved lengthwise","8 spring roll wrappers","2 tbsp brown sugar","2 tbsp sunflower oil"],"es":["4 bananas cortadas a lo largo","8 masas para arrolladitos primavera","2 cdas azúcar mascabo","2 cdas aceite de girasol"]},"steps":{"en":["Roll each banana half in sugar, then wrap tightly in a wrapper.","Brush with oil.","Bake at 210°C for 15 min until crisp."],"es":["Pasá cada mitad de banana por azúcar y envolvela bien en una masa.","Pincelá con aceite.","Horneá a 210°C 15 min, hasta que estén crocantes."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"nasi-goreng","type":"lunch","country":"ID","protein":"poultry","base":"rice","tags":["fried-rice"],"name":{"en":"Nasi Goreng with Chicken & Egg","es":"Nasi goreng con pollo y huevo"},"ing":{"en":["4 cups cooked rice","300 g chicken breast, diced","1 onion, chopped","2 garlic cloves, minced","3 tbsp sweet soy sauce (or soy + honey)","4 eggs","1 cucumber","2 tomatoes"],"es":["4 tazas arroz cocido","300 g pechuga de pollo en cubos","1 cebolla picada","2 dientes de ajo picados","3 cdas salsa de soja dulce (o soja + miel)","4 huevos","1 pepino","2 tomates"]},"steps":{"en":["Stir-fry onion, garlic and chicken for 6 min.","Add rice and sweet soy and fry 5 min until coated.","Serve with a fried egg, cucumber and tomato."],"es":["Saltá la cebolla, el ajo y el pollo 6 min.","Sumá el arroz y la soja dulce y saltá 5 min, hasta que se impregne.","Serví con un huevo frito, pepino y tomate."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"gado-gado","type":"lunch","country":"ID","protein":"plant","base":"potato","name":{"en":"Gado-Gado (Vegetables & Egg with Peanut Sauce)","es":"Gado-gado: verduras y huevo con salsa de maní"},"ing":{"en":["4 potatoes, boiled and sliced","300 g green beans","¼ cabbage, shredded","2 cups bean sprouts","4 eggs","200 g firm tofu, cubed","4 tbsp peanut butter","1 tbsp soy sauce","1 lime"],"es":["4 papas hervidas en rodajas","300 g chauchas","¼ repollo en juliana","2 tazas brotes de soja","4 huevos","200 g tofu firme en cubos","4 cdas mantequilla de maní","1 cda salsa de soja","1 lima"]},"steps":{"en":["Boil the eggs 9 min; blanch beans, cabbage and sprouts 2 min; brown the tofu.","Whisk peanut butter, soy, lime and hot water into a pourable sauce.","Arrange everything and pour the sauce over."],"es":["Herví los huevos 9 min; blanqueá las chauchas, el repollo y los brotes 2 min; dorá el tofu.","Batí la mantequilla de maní con la soja, la lima y agua caliente hasta tener una salsa.","Acomodá todo y bañá con la salsa."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"sate-ayam","type":"dinner","country":"ID","protein":"poultry","base":"rice","tags":["skewers"],"name":{"en":"Satay Chicken Skewers with Rice & Cucumber","es":"Brochetas de pollo satay con arroz y pepino"},"ing":{"en":["700 g chicken thighs, in strips","2 tbsp soy sauce","1 tsp turmeric","1 tsp ground cumin","4 tbsp peanut butter","½ cup coconut milk","1 lime","1½ cups rice","1 cucumber"],"es":["700 g muslos de pollo en tiras","2 cdas salsa de soja","1 cdita cúrcuma","1 cdita comino","4 cdas mantequilla de maní","½ taza leche de coco","1 lima","1½ tazas arroz","1 pepino"]},"steps":{"en":["Marinate the chicken in soy, turmeric and cumin; thread on skewers.","Grill 10 min, turning.","Warm peanut butter with coconut milk and lime for the sauce; serve with rice and cucumber."],"es":["Mariná el pollo con la soja, la cúrcuma y el comino; ensartá en brochetas.","Cociná a la parrilla 10 min, dando vuelta.","Calentá la mantequilla de maní con la leche de coco y la lima para la salsa; serví con arroz y pepino."]},"tip":{"en":"","es":""},"prep":["marinate"]},
{"id":"nasi-lemak","type":"breakfast","country":"MY","group":"egg","name":{"en":"Nasi Lemak (Coconut Rice with Egg & Cucumber)","es":"Nasi lemak: arroz de coco con huevo y pepino"},"ing":{"en":["1½ cups rice","1 can coconut milk","4 eggs","1 cucumber, sliced","¼ cup peanuts (optional)","2 tbsp mild chili sauce (sambal, optional)"],"es":["1½ tazas arroz","1 lata leche de coco","4 huevos","1 pepino en rodajas","¼ taza maní (opcional)","2 cdas salsa de ají suave (sambal, opcional)"]},"steps":{"en":["Cook the rice in the coconut milk plus 1 cup water.","Boil the eggs 8 min and halve.","Serve rice with egg, cucumber, peanuts and a little sambal for grown-ups."],"es":["Cociná el arroz en la leche de coco más 1 taza de agua.","Herví los huevos 8 min y cortalos al medio.","Serví el arroz con huevo, pepino, maní y un poco de sambal para los grandes."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"chicken-laksa","type":"dinner","country":"MY","protein":"poultry","base":"pasta","tags":["soup"],"name":{"en":"Chicken Laksa (Coconut Curry Noodle Soup)","es":"Laksa de pollo: sopa de fideos con curry y coco"},"ing":{"en":["500 g chicken breast, sliced","2 tbsp laksa or red curry paste","1 can coconut milk","4 cups chicken broth","300 g rice noodles","2 cups bean sprouts","2 eggs, boiled","2 limes","1 handful fresh cilantro"],"es":["500 g pechuga de pollo en tiras","2 cdas pasta de laksa o curry rojo","1 lata leche de coco","4 tazas caldo de pollo","300 g fideos de arroz","2 tazas brotes de soja","2 huevos duros","2 limas","1 puñado de cilantro fresco"]},"steps":{"en":["Fry the paste 2 min, add broth and coconut milk and simmer 10 min.","Add chicken and cook 8 min; soak the noodles.","Serve noodles in bowls with the soup, sprouts, egg, lime and cilantro."],"es":["Freí la pasta 2 min, sumá el caldo y la leche de coco y cociná 10 min.","Agregá el pollo y cociná 8 min; remojá los fideos.","Serví los fideos en bowls con la sopa, los brotes, el huevo, la lima y el cilantro."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"fish-with-mango-salsa","type":"dinner","country":"AU","protein":"fish","base":"rice","name":{"en":"Grilled Fish with Mango Salsa & Rice","es":"Pescado grillado con salsa de mango y arroz"},"ing":{"en":["4 white fish fillets","1 mango, diced","1 red bell pepper, diced","1 red onion, finely chopped","2 limes","2 tbsp fresh cilantro, chopped","1½ cups rice","1 tbsp olive oil"],"es":["4 filetes de pescado blanco","1 mango en cubitos","1 morrón rojo en cubitos","1 cebolla morada picada fina","2 limas","2 cdas cilantro fresco picado","1½ tazas arroz","1 cda aceite de oliva"]},"steps":{"en":["Mix mango, pepper, onion, cilantro and lime for the salsa.","Brush the fish with oil and grill 3–4 min a side.","Serve with rice and the salsa."],"es":["Mezclá el mango, el morrón, la cebolla, el cilantro y la lima para la salsa.","Pincelá el pescado con aceite y cocinalo a la plancha 3–4 min por lado.","Serví con arroz y la salsa."]},"tip":{"en":"","es":""},"prep":["rice"]},
{"id":"anzac-biscuits","type":"snack","country":"AU","group":"grain","tags":["cookies"],"name":{"en":"Anzac Biscuits","es":"Galletas Anzac"},"ing":{"en":["1 cup rolled oats","1 cup flour","¾ cup desiccated coconut","⅓ cup brown sugar","100 g butter","2 tbsp honey or golden syrup","½ tsp baking soda"],"es":["1 taza avena arrollada","1 taza harina","¾ taza coco rallado","⅓ taza azúcar mascabo","100 g manteca","2 cdas miel o jarabe de caña","½ cdita bicarbonato de sodio"]},"steps":{"en":["Mix oats, flour, coconut and sugar.","Melt butter with honey, stir in soda dissolved in 2 tbsp boiling water; combine.","Roll small balls, flatten and bake at 170°C for 12 min."],"es":["Mezclá la avena, la harina, el coco y el azúcar.","Derretí la manteca con la miel, sumá el bicarbonato disuelto en 2 cdas de agua hirviendo; uní todo.","Formá bolitas, aplanalas y horneá a 170°C 12 min."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"pavlova","type":"snack","country":"AU","group":"fruit","name":{"en":"Mini Pavlovas with Fruit","es":"Mini pavlovas con fruta"},"ing":{"en":["3 egg whites","¾ cup sugar","1 tsp cornstarch","1 tsp vinegar","1 cup cream","2 kiwis","1 cup strawberries","1 mango"],"es":["3 claras","¾ taza azúcar","1 cdita maicena","1 cdita vinagre","1 taza crema de leche","2 kiwis","1 taza frutillas","1 mango"]},"steps":{"en":["Whisk whites stiff, add sugar gradually, then cornstarch and vinegar.","Spoon 8 nests on a tray and bake at 120°C for 1 hour; cool in the oven.","Top with whipped cream and lots of fruit."],"es":["Batí las claras a punto nieve, sumá el azúcar de a poco y después la maicena y el vinagre.","Formá 8 nidos sobre una placa y horneá a 120°C 1 hora; dejá enfriar en el horno.","Cubrí con crema batida y mucha fruta."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"pepian-de-pollo","type":"dinner","country":"GT","protein":"poultry","base":"rice","tags":["stew"],"name":{"en":"Pepián de Pollo (Roasted Pepper & Seed Stew)","es":"Pepián de pollo"},"ing":{"en":["1 kg chicken thighs","4 tomatoes","2 red bell peppers","1 onion","2 tbsp sesame seeds","2 tbsp pumpkin seeds","1 cinnamon stick","2 potatoes, diced","1½ cups rice"],"es":["1 kg muslos de pollo","4 tomates","2 morrones rojos","1 cebolla","2 cdas semillas de sésamo","2 cdas semillas de zapallo","1 rama de canela","2 papas en cubos","1½ tazas arroz"]},"steps":{"en":["Char the tomatoes, peppers and onion in a dry pan; toast the seeds and cinnamon.","Blend everything with 2 cups water into a thick sauce.","Simmer the chicken and potatoes in the sauce for 35 min; serve with rice."],"es":["Tostá los tomates, los morrones y la cebolla en una sartén seca; tostá las semillas y la canela.","Licuá todo con 2 tazas de agua hasta tener una salsa espesa.","Cociná el pollo y las papas en la salsa 35 min; serví con arroz."]},"tip":{"en":"","es":""},"prep":["rice"]},
{"id":"hilachas","type":"dinner","country":"GT","protein":"beef","base":"rice","tags":["stew"],"name":{"en":"Hilachas (Shredded Beef in Tomato Sauce)","es":"Hilachas: carne deshilachada en salsa de tomate"},"ing":{"en":["700 g beef flank or chuck","4 tomatoes","1 red bell pepper","2 potatoes, diced","2 carrots, diced","1 onion","1½ cups rice"],"es":["700 g falda o carne para guiso","4 tomates","1 morrón rojo","2 papas en cubos","2 zanahorias en cubos","1 cebolla","1½ tazas arroz"]},"steps":{"en":["Simmer the beef with half the onion for 1½ hours; shred it.","Blend the tomatoes, pepper and the rest of the onion; simmer 10 min.","Add the beef, potatoes and carrots and cook 20 min; serve with rice."],"es":["Herví la carne con media cebolla 1½ horas; deshilachala.","Licuá los tomates, el morrón y el resto de la cebolla; cociná 10 min.","Sumá la carne, las papas y las zanahorias y cociná 20 min; serví con arroz."]},"tip":{"en":"","es":""},"prep":["cook-ahead"]},
{"id":"desayuno-chapin","type":"breakfast","country":"GT","group":"egg","name":{"en":"Desayuno Chapín (Eggs, Beans, Plantain & Cheese)","es":"Desayuno chapín"},"ing":{"en":["4 eggs","1 can black beans","2 ripe plantains","100 g fresh cheese","8 corn tortillas","2 tomatoes, chopped"],"es":["4 huevos","1 lata porotos negros","2 plátanos maduros","100 g queso fresco","8 tortillas de maíz","2 tomates picados"]},"steps":{"en":["Fry slices of ripe plantain until golden.","Warm and mash the beans; scramble or fry the eggs with the tomato.","Serve everything with cheese and warm tortillas."],"es":["Freí rodajas de plátano maduro hasta dorar.","Calentá y pisá los porotos; revolvé o freí los huevos con el tomate.","Serví todo con queso y tortillas calientes."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"rellenitos-de-platano","type":"snack","country":"GT","group":"fruit","name":{"en":"Rellenitos (Plantain Balls Filled with Sweet Beans)","es":"Rellenitos de plátano"},"ing":{"en":["3 ripe plantains","1 can black beans, drained","1 tbsp cocoa powder","1 tsp cinnamon","2 tbsp sugar","2 tbsp sunflower oil"],"es":["3 plátanos maduros","1 lata porotos negros escurridos","1 cda cacao en polvo","1 cdita canela","2 cdas azúcar","2 cdas aceite de girasol"]},"steps":{"en":["Boil the plantains 15 min and mash.","Blend the beans with cocoa, cinnamon and sugar and cook until thick.","Wrap a spoon of beans in plantain, shape balls and pan-fry until golden."],"es":["Herví los plátanos 15 min y pisalos.","Licuá los porotos con el cacao, la canela y el azúcar y cociná hasta que espese.","Envolvé una cucharada de porotos con plátano, formá bolitas y doralas en sartén."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"baleadas","type":"breakfast","country":"HN","group":"grain","tags":["tortilla"],"name":{"en":"Baleadas (Flour Tortillas with Beans, Cheese & Cream)","es":"Baleadas"},"ing":{"en":["8 flour tortillas","1 can black beans","100 g fresh cheese, crumbled","½ cup sour cream","4 eggs","1 avocado"],"es":["8 tortillas de harina","1 lata porotos negros","100 g queso fresco desmenuzado","½ taza crema agria","4 huevos","1 palta"]},"steps":{"en":["Warm and mash the beans.","Scramble the eggs.","Spread warm tortillas with beans, add egg, cheese, cream and avocado and fold."],"es":["Calentá y pisá los porotos.","Revolvé los huevos.","Untá las tortillas calientes con porotos, sumá huevo, queso, crema y palta y doblalas."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"pollo-con-tajadas","type":"lunch","country":"HN","protein":"poultry","base":"none","name":{"en":"Pollo con Tajadas (Chicken with Green Plantain Chips & Slaw)","es":"Pollo con tajadas"},"ing":{"en":["800 g chicken thighs","1 tsp ground cumin","2 limes","3 green plantains","¼ cabbage, shredded","1 tomato, diced","3 tbsp sunflower oil","2 tbsp mayonnaise"],"es":["800 g muslos de pollo","1 cdita comino","2 limas","3 plátanos verdes","¼ repollo en juliana","1 tomate en cubitos","3 cdas aceite de girasol","2 cdas mayonesa"]},"steps":{"en":["Season the chicken with cumin, lime and salt and bake at 200°C for 35 min.","Slice the plantains thin lengthwise and bake with the oil until crisp.","Toss cabbage and tomato with mayonnaise and lime; serve together."],"es":["Condimentá el pollo con comino, lima y sal y horneá a 200°C 35 min.","Cortá los plátanos en láminas finas a lo largo y horneá con el aceite hasta que estén crocantes.","Mezclá el repollo y el tomate con mayonesa y lima; serví todo junto."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"tapado-hondureno","type":"dinner","country":"HN","protein":"fish","base":"none","tags":["soup"],"name":{"en":"Tapado (Coconut Seafood & Plantain Soup)","es":"Tapado hondureño"},"ing":{"en":["500 g white fish fillets, in chunks","300 g shrimp","2 cans coconut milk","2 green plantains, sliced","300 g cassava (yuca), diced","1 onion, chopped","2 garlic cloves, minced","2 tbsp fresh cilantro, chopped"],"es":["500 g filet de pescado blanco en trozos","300 g langostinos","2 latas leche de coco","2 plátanos verdes en rodajas","300 g mandioca en cubos","1 cebolla picada","2 dientes de ajo picados","2 cdas cilantro fresco picado"]},"steps":{"en":["Simmer the onion, garlic, cassava and plantain in the coconut milk plus 2 cups water for 20 min.","Add the fish and shrimp and cook 6 min.","Finish with cilantro."],"es":["Cociná la cebolla, el ajo, la mandioca y el plátano en la leche de coco más 2 tazas de agua 20 min.","Sumá el pescado y los langostinos y cociná 6 min.","Terminá con cilantro."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"pupusas-de-queso-y-frijol","type":"lunch","country":"SV","protein":"plant","base":"bread","name":{"en":"Pupusas with Cheese & Beans and Curtido","es":"Pupusas de queso y frijol con curtido"},"ing":{"en":["2 cups masa harina (corn flour)","1½ cups warm water","200 g mozzarella, grated","1 can black beans, drained and mashed","¼ cabbage, shredded","1 carrot, grated","3 tbsp vinegar","1 tsp dried oregano"],"es":["2 tazas harina de maíz para tortillas","1½ tazas agua tibia","200 g mozzarella rallada","1 lata porotos negros escurridos y pisados","¼ repollo en juliana","1 zanahoria rallada","3 cdas vinagre","1 cdita orégano"]},"steps":{"en":["Mix cabbage, carrot, vinegar and oregano for the curtido; rest 1 hour.","Knead the masa with water; fill balls with cheese and beans and pat into thick discs.","Cook on a dry griddle 4 min a side; serve with curtido."],"es":["Mezclá el repollo, la zanahoria, el vinagre y el orégano para el curtido; dejá reposar 1 hora.","Amasá la harina con el agua; rellená bolitas con queso y porotos y aplanalas en discos gruesos.","Cociná en plancha seca 4 min por lado; serví con curtido."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"quesadilla-salvadorena","type":"snack","country":"SV","group":"grain","tags":["cake"],"name":{"en":"Salvadoran Cheese Cake (Quesadilla)","es":"Quesadilla salvadoreña"},"ing":{"en":["1 cup flour","150 g fresh cheese, grated","½ cup sour cream","3 eggs","½ cup sugar","50 g butter, melted","1 tsp baking powder","1 tbsp sesame seeds"],"es":["1 taza harina","150 g queso fresco rallado","½ taza crema agria","3 huevos","½ taza azúcar","50 g manteca derretida","1 cdita polvo para hornear","1 cda semillas de sésamo"]},"steps":{"en":["Beat butter, sugar and eggs; add cheese and cream.","Fold in flour and baking powder; pour into a tin and sprinkle with sesame.","Bake at 180°C for 35 min."],"es":["Batí la manteca, el azúcar y los huevos; sumá el queso y la crema.","Incorporá la harina y el polvo de hornear; volcá en un molde y espolvoreá con sésamo.","Horneá a 180°C 35 min."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"panes-con-pollo","type":"dinner","country":"SV","protein":"poultry","base":"bread","name":{"en":"Panes con Pollo (Saucy Chicken Sandwiches)","es":"Panes con pollo"},"ing":{"en":["800 g chicken thighs","4 tomatoes","1 onion","1 red bell pepper","2 tbsp pumpkin seeds","4 crusty rolls","1 cucumber, sliced","1 head lettuce"],"es":["800 g muslos de pollo","4 tomates","1 cebolla","1 morrón rojo","2 cdas semillas de zapallo","4 panes franceses","1 pepino en rodajas","1 planta de lechuga"]},"steps":{"en":["Toast the seeds; blend with the tomatoes, onion and pepper into a sauce.","Simmer the chicken in the sauce for 35 min; shred.","Fill the rolls with chicken, sauce, lettuce and cucumber."],"es":["Tostá las semillas; licualas con los tomates, la cebolla y el morrón.","Cociná el pollo en la salsa 35 min; desmenuzalo.","Rellená los panes con pollo, salsa, lechuga y pepino."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"gallo-pinto-con-huevo","type":"breakfast","country":"NI","group":"egg","name":{"en":"Gallo Pinto with Fried Egg","es":"Gallo pinto con huevo frito"},"ing":{"en":["3 cups cooked rice","1 can kidney beans, drained","1 onion, chopped","1 red bell pepper, chopped","4 eggs","2 tbsp fresh cilantro, chopped","2 tbsp sunflower oil"],"es":["3 tazas arroz cocido","1 lata porotos colorados escurridos","1 cebolla picada","1 morrón rojo picado","4 huevos","2 cdas cilantro fresco picado","2 cdas aceite de girasol"]},"steps":{"en":["Soften the onion and pepper in the oil.","Add the beans and rice and fry 5 min until mixed and lightly crisp.","Serve with a fried egg and cilantro."],"es":["Rehogá la cebolla y el morrón en el aceite.","Sumá los porotos y el arroz y saltá 5 min, hasta que se mezclen y se doren apenas.","Serví con un huevo frito y cilantro."]},"tip":{"en":"","es":""},"prep":["rice"]},
{"id":"indio-viejo","type":"dinner","country":"NI","protein":"beef","base":"none","tags":["stew"],"name":{"en":"Indio Viejo (Beef & Corn Masa Stew)","es":"Indio viejo"},"ing":{"en":["600 g beef chuck","1 cup masa harina (corn flour)","2 tomatoes, chopped","1 onion, chopped","1 red bell pepper, chopped","2 oranges (juice)","1 handful fresh mint","4 corn tortillas"],"es":["600 g carne para guiso","1 taza harina de maíz para tortillas","2 tomates picados","1 cebolla picada","1 morrón rojo picado","2 naranjas (jugo)","1 puñado de menta fresca","4 tortillas de maíz"]},"steps":{"en":["Simmer the beef for 1½ hours; shred, keeping 4 cups of broth.","Soften the vegetables, add the beef, broth and orange juice.","Whisk in the masa and cook 10 min until thick; finish with mint and serve with tortillas."],"es":["Herví la carne 1½ horas; desmechala y guardá 4 tazas del caldo.","Rehogá las verduras, sumá la carne, el caldo y el jugo de naranja.","Incorporá la harina de maíz batiendo y cociná 10 min hasta que espese; terminá con menta y serví con tortillas."]},"tip":{"en":"","es":""},"prep":["cook-ahead"]},
{"id":"casado","type":"lunch","country":"CR","protein":"beef","base":"rice","name":{"en":"Casado (Rice, Beans, Plantain, Salad & Steak)","es":"Casado costarricense"},"ing":{"en":["1½ cups rice","1 can black beans","4 thin beef steaks","2 ripe plantains","1 head lettuce","2 tomatoes","1 lime"],"es":["1½ tazas arroz","1 lata porotos negros","4 bifes finos","2 plátanos maduros","1 planta de lechuga","2 tomates","1 lima"]},"steps":{"en":["Cook the rice; warm the beans.","Fry the plantain slices; sear the steaks 2 min a side.","Serve everything on one plate with a lime-dressed salad."],"es":["Cociná el arroz; calentá los porotos.","Freí las rodajas de plátano; cociná los bifes 2 min por lado.","Serví todo en un plato con ensalada aliñada con lima."]},"tip":{"en":"","es":""},"prep":["rice"]},
{"id":"olla-de-carne","type":"dinner","country":"CR","protein":"beef","base":"potato","tags":["soup"],"name":{"en":"Olla de Carne (Beef & Root Vegetable Soup)","es":"Olla de carne"},"ing":{"en":["700 g beef shin (osobuco)","3 potatoes, in chunks","300 g cassava (yuca), in chunks","2 corn cobs, in rounds","2 carrots, in chunks","2 cups pumpkin, in chunks","1 green plantain, in chunks","2 tbsp fresh cilantro, chopped"],"es":["700 g osobuco","3 papas en trozos","300 g mandioca en trozos","2 choclos en rodajas","2 zanahorias en trozos","2 tazas zapallo en trozos","1 plátano verde en trozos","2 cdas cilantro fresco picado"]},"steps":{"en":["Cover the beef with water and simmer 1½ hours.","Add cassava, plantain, corn and potatoes and cook 20 min.","Add carrots and pumpkin for 15 min more; serve with cilantro."],"es":["Cubrí la carne con agua y cociná 1½ horas.","Sumá la mandioca, el plátano, el choclo y las papas y cociná 20 min.","Agregá las zanahorias y el zapallo 15 min más; serví con cilantro."]},"tip":{"en":"","es":""},"prep":["cook-ahead"]},
{"id":"sancocho-panameno","type":"dinner","country":"PA","protein":"poultry","base":"none","tags":["soup"],"name":{"en":"Sancocho Panameño (Chicken & Cassava Soup)","es":"Sancocho panameño"},"ing":{"en":["1 kg chicken thighs","600 g cassava (yuca), in chunks","1 onion, chopped","2 garlic cloves, minced","1 tsp dried oregano","4 tbsp fresh cilantro, chopped","1 cup rice"],"es":["1 kg muslos de pollo","600 g mandioca en trozos","1 cebolla picada","2 dientes de ajo picados","1 cdita orégano","4 cdas cilantro fresco picado","1 taza arroz"]},"steps":{"en":["Brown the chicken with onion, garlic and oregano.","Cover with 8 cups water and simmer 30 min.","Add the cassava and cook 20 min until soft; finish with plenty of cilantro and serve with rice."],"es":["Dorá el pollo con la cebolla, el ajo y el orégano.","Cubrí con 8 tazas de agua y cociná 30 min.","Sumá la mandioca y cociná 20 min, hasta que esté tierna; terminá con mucho cilantro y serví con arroz."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"hojaldras","type":"breakfast","country":"PA","group":"grain","name":{"en":"Hojaldras (Fried Bread) with Eggs & Cheese","es":"Hojaldras con huevo y queso"},"ing":{"en":["2 cups flour","1 tsp baking powder","¾ cup warm water","Sunflower oil for frying","4 eggs","100 g fresh cheese"],"es":["2 tazas harina","1 cdita polvo para hornear","¾ taza agua tibia","Aceite de girasol para freír","4 huevos","100 g queso fresco"]},"steps":{"en":["Knead flour, baking powder, water and salt; rest 20 min.","Stretch into thin discs and fry until puffed and golden.","Serve with fried eggs and fresh cheese."],"es":["Amasá la harina, el polvo de hornear, el agua y sal; dejá reposar 20 min.","Estirá discos finos y freí hasta que se inflen y doren.","Serví con huevos fritos y queso fresco."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"mangu-tres-golpes","type":"breakfast","country":"DO","group":"egg","name":{"en":"Mangú with Eggs, Cheese & Pickled Onions","es":"Mangú con huevo, queso y cebolla encurtida"},"ing":{"en":["4 green plantains","2 tbsp butter","1 red onion, sliced","2 tbsp vinegar","4 eggs","150 g fresh cheese, sliced"],"es":["4 plátanos verdes","2 cdas manteca","1 cebolla morada en pluma","2 cdas vinagre","4 huevos","150 g queso fresco en fetas"]},"steps":{"en":["Boil the plantains 20 min and mash with butter and some of the cooking water until smooth.","Soften the onion in a little oil and splash with vinegar.","Serve the mangú topped with onions, with fried eggs and pan-fried cheese."],"es":["Herví los plátanos 20 min y pisalos con la manteca y un poco del agua hasta que queden lisos.","Rehogá la cebolla en un poco de aceite y rociá con vinagre.","Serví el mangú con la cebolla arriba, huevos fritos y queso a la plancha."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"la-bandera-dominicana","type":"lunch","country":"DO","protein":"beef","base":"rice","tags":["stew"],"name":{"en":"La Bandera (Rice, Beans & Stewed Beef)","es":"La bandera dominicana"},"ing":{"en":["600 g beef chuck, diced","1 onion, chopped","1 green bell pepper, chopped","2 tbsp tomato paste","1 tsp dried oregano","1½ cups rice","1 can kidney beans","1 head lettuce"],"es":["600 g carne para guiso en cubos","1 cebolla picada","1 morrón verde picado","2 cdas extracto de tomate","1 cdita orégano","1½ tazas arroz","1 lata porotos colorados","1 planta de lechuga"]},"steps":{"en":["Brown the beef, add onion, pepper, tomato paste, oregano and 1 cup water; simmer 1 hour.","Simmer the beans with a little of the stew sauce.","Serve with rice and a green salad."],"es":["Dorá la carne, sumá la cebolla, el morrón, el extracto, el orégano y 1 taza de agua; cociná 1 hora.","Cociná los porotos con un poco de la salsa del guiso.","Serví con arroz y ensalada verde."]},"tip":{"en":"","es":""},"prep":["cook-ahead","rice"]},
{"id":"pescado-con-coco","type":"dinner","country":"DO","protein":"fish","base":"rice","tags":["stew"],"name":{"en":"Fish in Coconut Sauce","es":"Pescado con coco"},"ing":{"en":["4 white fish fillets","1 can coconut milk","1 onion, sliced","1 red bell pepper, sliced","2 tomatoes, chopped","2 garlic cloves, minced","2 limes","1½ cups rice"],"es":["4 filetes de pescado blanco","1 lata leche de coco","1 cebolla en pluma","1 morrón rojo en tiras","2 tomates picados","2 dientes de ajo picados","2 limas","1½ tazas arroz"]},"steps":{"en":["Marinate the fish in lime juice and garlic for 15 min.","Soften onion, pepper and tomato; add the coconut milk and simmer 5 min.","Add the fish and cook 8 min; serve with rice."],"es":["Mariná el pescado con jugo de lima y ajo 15 min.","Rehogá la cebolla, el morrón y el tomate; sumá la leche de coco y cociná 5 min.","Agregá el pescado y cociná 8 min; serví con arroz."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"habichuelas-con-dulce","type":"snack","country":"DO","group":"dairy","name":{"en":"Habichuelas con Dulce (Sweet Cream of Beans)","es":"Habichuelas con dulce"},"ing":{"en":["1 can kidney beans, drained","1 can coconut milk","1 cup milk","1 sweet potato, diced small","⅓ cup brown sugar","1 cinnamon stick","2 tbsp raisins"],"es":["1 lata porotos colorados escurridos","1 lata leche de coco","1 taza leche","1 batata en cubitos","⅓ taza azúcar mascabo","1 rama de canela","2 cdas pasas de uva"]},"steps":{"en":["Blend the beans with the coconut milk until smooth.","Simmer with milk, sweet potato, sugar and cinnamon for 20 min, stirring.","Add the raisins; serve warm or cold in small cups."],"es":["Licuá los porotos con la leche de coco.","Cociná con la leche, la batata, el azúcar y la canela 20 min, revolviendo.","Sumá las pasas; serví tibio o frío en vasitos."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"mofongo-con-camarones","type":"dinner","country":"PR","protein":"fish","base":"none","name":{"en":"Mofongo with Garlic Shrimp","es":"Mofongo con langostinos al ajillo"},"ing":{"en":["4 green plantains","4 garlic cloves, minced","3 tbsp olive oil","500 g shrimp, peeled","1 can crushed tomatoes","2 tbsp fresh cilantro, chopped","1 head lettuce"],"es":["4 plátanos verdes","4 dientes de ajo picados","3 cdas aceite de oliva","500 g langostinos pelados","1 lata tomate triturado","2 cdas cilantro fresco picado","1 planta de lechuga"]},"steps":{"en":["Fry or boil thick plantain chunks until tender; mash with half the garlic and oil.","Cook the rest of the garlic in oil, add tomatoes and shrimp and cook 4 min.","Press the mofongo into bowls, unmould and spoon the shrimp over; serve with salad."],"es":["Freí o herví trozos gruesos de plátano hasta que estén tiernos; pisalos con la mitad del ajo y el aceite.","Cociná el resto del ajo en aceite, sumá el tomate y los langostinos y cociná 4 min.","Apretá el mofongo en bowls, desmoldá y cubrí con los langostinos; serví con ensalada."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"arroz-con-gandules","type":"lunch","country":"PR","protein":"pork","base":"rice","name":{"en":"Arroz con Gandules (Rice with Pigeon Peas)","es":"Arroz con gandules"},"ing":{"en":["2 cups rice","1 can pigeon peas, drained","150 g cooked ham, diced","1 onion, chopped","1 green bell pepper, chopped","3 tbsp fresh cilantro, chopped","2 tbsp tomato paste","¼ cup green olives"],"es":["2 tazas arroz","1 lata gandules escurridos","150 g jamón cocido en cubos","1 cebolla picada","1 morrón verde picado","3 cdas cilantro fresco picado","2 cdas extracto de tomate","¼ taza aceitunas verdes"]},"steps":{"en":["Soften onion, pepper and cilantro (sofrito) with the ham.","Add tomato paste, olives, pigeon peas and rice; stir.","Add 3 cups water, cover and cook 25 min on low."],"es":["Rehogá la cebolla, el morrón y el cilantro (sofrito) con el jamón.","Sumá el extracto, las aceitunas, los gandules y el arroz; revolvé.","Agregá 3 tazas de agua, tapá y cociná 25 min a fuego bajo."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"pastelon","type":"dinner","country":"PR","protein":"beef","base":"none","tags":["lasagna"],"name":{"en":"Pastelón (Sweet Plantain Lasagna)","es":"Pastelón boricua"},"ing":{"en":["4 ripe plantains, sliced lengthwise","500 g ground beef","1 onion, chopped","1 green bell pepper, chopped","1 can crushed tomatoes","200 g mozzarella, grated","2 eggs"],"es":["4 plátanos maduros en láminas a lo largo","500 g carne picada","1 cebolla picada","1 morrón verde picado","1 lata tomate triturado","200 g mozzarella rallada","2 huevos"]},"steps":{"en":["Fry or bake the plantain slices until golden.","Brown the beef with onion and pepper, add tomatoes and simmer 15 min.","Layer plantain, beef and cheese, pour beaten eggs over and bake at 180°C for 30 min."],"es":["Freí u horneá las láminas de plátano hasta dorar.","Dorá la carne con la cebolla y el morrón, sumá el tomate y cociná 15 min.","Armá capas de plátano, carne y queso, volcá los huevos batidos y horneá a 180°C 30 min."]},"tip":{"en":"","es":""},"prep":["brown-beef"]},
{"id":"tembleque","type":"snack","country":"PR","group":"dairy","name":{"en":"Tembleque (Coconut Pudding)","es":"Tembleque de coco"},"ing":{"en":["2 cans coconut milk","½ cup cornstarch","⅓ cup sugar","1 tsp cinnamon","2 cups mixed berries"],"es":["2 latas leche de coco","½ taza maicena","⅓ taza azúcar","1 cdita canela","2 tazas frutos rojos"]},"steps":{"en":["Whisk the coconut milk, cornstarch and sugar in a pan.","Cook, stirring, until very thick; pour into cups and chill 3 hours.","Dust with cinnamon and serve with berries."],"es":["Batí la leche de coco con la maicena y el azúcar en una olla.","Cociná revolviendo hasta que esté bien espeso; volcá en vasitos y enfriá 3 horas.","Espolvoreá con canela y serví con frutos rojos."]},"tip":{"en":"","es":""},"prep":["chill-ahead"]},
{"id":"griot-with-pikliz","type":"dinner","country":"HT","protein":"pork","base":"rice","name":{"en":"Griot (Citrus-Braised Pork) with Pikliz & Rice","es":"Griot: cerdo braseado con cítricos, pikliz y arroz"},"ing":{"en":["800 g pork shoulder, in cubes","2 oranges (juice)","2 limes","1 onion, chopped","3 garlic cloves, minced","1 tsp dried thyme","¼ cabbage, shredded","1 carrot, grated","½ cup vinegar","1½ cups rice"],"es":["800 g bondiola en cubos","2 naranjas (jugo)","2 limas","1 cebolla picada","3 dientes de ajo picados","1 cdita tomillo seco","¼ repollo en juliana","1 zanahoria rallada","½ taza vinagre","1½ tazas arroz"]},"steps":{"en":["Marinate the pork in citrus juice, onion, garlic and thyme for 2 hours.","Simmer in the marinade with 1 cup water for 1 hour, then roast at 220°C for 15 min until crisp.","Toss cabbage and carrot with vinegar for the pikliz; serve with rice."],"es":["Mariná el cerdo con los jugos, la cebolla, el ajo y el tomillo 2 horas.","Cociná en la marinada con 1 taza de agua 1 hora y después asá a 220°C 15 min hasta que se dore.","Mezclá el repollo y la zanahoria con el vinagre para el pikliz; serví con arroz."]},"tip":{"en":"","es":""},"prep":["marinate"]},
{"id":"soup-joumou","type":"lunch","country":"HT","protein":"beef","base":"pasta","tags":["soup"],"name":{"en":"Soup Joumou (Pumpkin & Beef Soup)","es":"Soup joumou: sopa de zapallo y carne"},"ing":{"en":["400 g beef chuck, diced","4 cups pumpkin, diced","2 potatoes, diced","2 carrots, sliced","¼ cabbage, shredded","1 cup pasta (small shapes)","1 lime","1 tsp dried thyme"],"es":["400 g carne para guiso en cubos","4 tazas zapallo en cubos","2 papas en cubos","2 zanahorias en rodajas","¼ repollo en juliana","1 taza fideos chicos","1 lima","1 cdita tomillo seco"]},"steps":{"en":["Simmer the beef with thyme in 6 cups water for 1 hour.","Boil the pumpkin separately until soft, blend and add to the pot.","Add potatoes, carrots, cabbage and pasta and cook 15 min; finish with lime."],"es":["Cociná la carne con tomillo en 6 tazas de agua 1 hora.","Herví el zapallo aparte hasta que esté tierno, licualo y sumalo a la olla.","Sumá las papas, las zanahorias, el repollo y los fideos y cociná 15 min; terminá con lima."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"doubles","type":"breakfast","country":"TT","group":"grain","name":{"en":"Doubles (Curried Chickpeas in Soft Fried Bread)","es":"Doubles: garbanzos al curry en pan frito"},"ing":{"en":["2 cups flour","1 tsp dry yeast","1 tsp turmeric","¾ cup warm water","2 cans chickpeas, drained","1 tbsp curry powder","1 onion, chopped","1 cucumber, grated"],"es":["2 tazas harina","1 cdita levadura seca","1 cdita cúrcuma","¾ taza agua tibia","2 latas garbanzos escurridos","1 cda curry en polvo","1 cebolla picada","1 pepino rallado"]},"steps":{"en":["Knead flour, yeast, turmeric and water; rise 1 hour.","Cook the chickpeas with onion, curry and 1 cup water for 15 min until saucy.","Stretch small rounds of dough, fry 30 s a side, and fill pairs with chickpeas and cucumber."],"es":["Amasá la harina, la levadura, la cúrcuma y el agua; dejá levar 1 hora.","Cociná los garbanzos con la cebolla, el curry y 1 taza de agua 15 min hasta que queden con salsa.","Estirá círculos chicos de masa, freí 30 s por lado y rellená de a dos con garbanzos y pepino."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"pelau","type":"dinner","country":"TT","protein":"poultry","base":"rice","name":{"en":"Pelau (Caramelised Chicken, Rice & Pigeon Peas)","es":"Pelau trinitense"},"ing":{"en":["1 kg chicken thighs, in pieces","2 tbsp brown sugar","2 cups rice","1 can pigeon peas, drained","1 can coconut milk","1 onion, chopped","2 carrots, diced","1 tsp dried thyme"],"es":["1 kg muslos de pollo en trozos","2 cdas azúcar mascabo","2 tazas arroz","1 lata gandules escurridos","1 lata leche de coco","1 cebolla picada","2 zanahorias en cubos","1 cdita tomillo seco"]},"steps":{"en":["Melt the sugar in a pot until dark amber, add the chicken and brown well.","Add onion, carrots, thyme, pigeon peas and rice; stir.","Pour in coconut milk and 2 cups water, cover and cook 30 min on low."],"es":["Derretí el azúcar en una olla hasta que esté bien dorado, sumá el pollo y doralo bien.","Agregá la cebolla, las zanahorias, el tomillo, los gandules y el arroz; revolvé.","Volcá la leche de coco y 2 tazas de agua, tapá y cociná 30 min a fuego bajo."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"callaloo","type":"lunch","country":"TT","protein":"plant","base":"none","tags":["soup"],"name":{"en":"Callaloo (Greens, Okra & Coconut Soup)","es":"Callaloo: sopa de verdes, okra y coco"},"ing":{"en":["3 bunches spinach (or callaloo leaves)","200 g okra, sliced","1 can coconut milk","1 onion, chopped","2 garlic cloves, minced","1 tsp dried thyme","2 cups pumpkin, diced","4 slices bread"],"es":["3 atados de espinaca (u hojas de callaloo)","200 g okra en rodajas","1 lata leche de coco","1 cebolla picada","2 dientes de ajo picados","1 cdita tomillo seco","2 tazas zapallo en cubos","4 rebanadas de pan"]},"steps":{"en":["Soften onion and garlic; add pumpkin, okra, thyme, coconut milk and 2 cups water.","Simmer 20 min, add the greens and cook 5 min.","Blend until smooth; serve with bread."],"es":["Rehogá la cebolla y el ajo; sumá el zapallo, la okra, el tomillo, la leche de coco y 2 tazas de agua.","Cociná 20 min, sumá los verdes y cociná 5 min.","Licuá hasta que quede liso; serví con pan."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"enfrijoladas","type":"lunch","country":"MX","protein":"plant","base":"bread","tags":["tortilla"],"name":{"en":"Enfrijoladas (Tortillas in Black Bean Sauce)","es":"Enfrijoladas"},"ing":{"en":["2 cans black beans","1 cup vegetable broth","1 garlic clove","12 corn tortillas","100 g fresh cheese, crumbled","½ cup sour cream","1 red onion, thinly sliced","1 avocado"],"es":["2 latas porotos negros","1 taza caldo de verduras","1 diente de ajo","12 tortillas de maíz","100 g queso fresco desmenuzado","½ taza crema agria","1 cebolla morada en pluma fina","1 palta"]},"steps":{"en":["Blend the beans with broth and garlic and simmer into a pourable sauce.","Dip warm tortillas in the sauce, fold in quarters and lay on plates.","Top with cheese, cream, onion and avocado."],"es":["Licuá los porotos con el caldo y el ajo y cociná hasta tener una salsa fluida.","Pasá las tortillas calientes por la salsa, doblalas en cuatro y acomodalas en los platos.","Terminá con queso, crema, cebolla y palta."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"sopes","type":"lunch","country":"MX","protein":"beef","base":"bread","name":{"en":"Sopes with Beef, Beans & Salsa","es":"Sopes de carne con porotos y salsa"},"ing":{"en":["2 cups masa harina (corn flour)","1½ cups warm water","400 g ground beef","1 can black beans, drained","2 cups lettuce, shredded","1 cup green salsa (tomatillo)","100 g fresh cheese, crumbled"],"es":["2 tazas harina de maíz para tortillas","1½ tazas agua tibia","400 g carne picada","1 lata porotos negros escurridos","2 tazas lechuga en tiras","1 taza salsa verde","100 g queso fresco desmenuzado"]},"steps":{"en":["Knead the masa and water; shape 12 thick discs and cook on a griddle 2 min a side; pinch up a rim.","Brown the beef with salt; warm and mash the beans.","Spread beans on the sopes and top with beef, lettuce, salsa and cheese."],"es":["Amasá la harina con el agua; formá 12 discos gruesos, cocinalos en plancha 2 min por lado y levantá un borde.","Dorá la carne con sal; calentá y pisá los porotos.","Untá los sopes con porotos y cubrí con carne, lechuga, salsa y queso."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"caldo-de-pollo-mexicano","type":"dinner","country":"MX","protein":"poultry","base":"rice","tags":["soup"],"name":{"en":"Caldo de Pollo (Mexican Chicken Soup)","es":"Caldo de pollo mexicano"},"ing":{"en":["1 kg chicken thighs","2 carrots, in chunks","2 zucchini, in chunks","2 potatoes, in chunks","2 corn cobs, in rounds","1 onion, halved","½ cup rice","2 limes","2 tbsp fresh cilantro, chopped"],"es":["1 kg muslos de pollo","2 zanahorias en trozos","2 zapallitos en trozos","2 papas en trozos","2 choclos en rodajas","1 cebolla en mitades","½ taza arroz","2 limas","2 cdas cilantro fresco picado"]},"steps":{"en":["Simmer the chicken and onion in 8 cups water for 30 min.","Add carrots, potatoes, corn and rice and cook 15 min; add zucchini for 8 min.","Serve with lime and cilantro."],"es":["Cociná el pollo y la cebolla en 8 tazas de agua 30 min.","Sumá las zanahorias, las papas, el choclo y el arroz y cociná 15 min; agregá los zapallitos 8 min.","Serví con lima y cilantro."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"molletes","type":"breakfast","country":"MX","group":"grain","tags":["toast"],"name":{"en":"Molletes (Bean & Cheese Rolls with Pico de Gallo)","es":"Molletes con pico de gallo"},"ing":{"en":["4 crusty rolls","1 can black beans","150 g mozzarella, grated","2 tomatoes, finely diced","1 red onion, finely chopped","2 tbsp fresh cilantro, chopped","1 lime"],"es":["4 panes franceses","1 lata porotos negros","150 g mozzarella rallada","2 tomates en cubitos","1 cebolla morada picada fina","2 cdas cilantro fresco picado","1 lima"]},"steps":{"en":["Split the rolls, spread with mashed beans and top with cheese.","Bake at 200°C for 8 min until melted.","Mix tomato, onion, cilantro and lime for the pico de gallo and spoon over."],"es":["Abrí los panes, untalos con porotos pisados y poné queso arriba.","Horneá a 200°C 8 min, hasta que se derrita.","Mezclá el tomate, la cebolla, el cilantro y la lima para el pico de gallo y servilo encima."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"calabacitas-a-la-mexicana","type":"dinner","country":"MX","protein":"plant","base":"bread","name":{"en":"Calabacitas a la Mexicana with Corn & Cheese","es":"Calabacitas a la mexicana con choclo y queso"},"ing":{"en":["4 zucchini, diced","2 cups corn","3 tomatoes, chopped","1 onion, chopped","150 g fresh cheese, diced","1 can black beans","12 corn tortillas"],"es":["4 zapallitos en cubos","2 tazas choclo","3 tomates picados","1 cebolla picada","150 g queso fresco en cubos","1 lata porotos negros","12 tortillas de maíz"]},"steps":{"en":["Soften the onion, add tomatoes and cook 5 min.","Add zucchini and corn and cook 10 min.","Stir in the cheese; serve with warm beans and tortillas."],"es":["Rehogá la cebolla, sumá el tomate y cociná 5 min.","Agregá los zapallitos y el choclo y cociná 10 min.","Incorporá el queso; serví con porotos calientes y tortillas."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"atole-de-avena","type":"breakfast","country":"MX","group":"grain","tags":["oats"],"name":{"en":"Atole de Avena (Warm Oat Drink) with Fruit","es":"Atole de avena con fruta"},"ing":{"en":["1 cup rolled oats","4 cups milk","1 cinnamon stick","2 tbsp brown sugar","2 bananas","1 cup strawberries"],"es":["1 taza avena arrollada","4 tazas leche","1 rama de canela","2 cdas azúcar mascabo","2 bananas","1 taza frutillas"]},"steps":{"en":["Simmer the oats in the milk with cinnamon for 10 min.","Blend until smooth and sweeten lightly.","Serve warm in mugs with fruit on the side."],"es":["Cociná la avena en la leche con la canela 10 min.","Licuá hasta que quede liso y endulzá apenas.","Serví caliente en tazas con fruta al lado."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"paletas-de-fruta","type":"snack","country":"MX","group":"fruit","tags":["frozen"],"name":{"en":"Paletas (Fruit Ice Pops)","es":"Paletas de fruta"},"ing":{"en":["2 cups strawberries","1 mango","2 limes","1 cup water","2 tbsp honey"],"es":["2 tazas frutillas","1 mango","2 limas","1 taza agua","2 cdas miel"]},"steps":{"en":["Blend the fruit separately with a little lime, water and honey.","Pour into moulds in layers.","Freeze 5 hours."],"es":["Licuá cada fruta por separado con un poco de lima, agua y miel.","Volcá en moldes por capas.","Congelá 5 horas."]},"tip":{"en":"","es":""},"prep":["freeze-ahead"]},
{"id":"pescado-zarandeado","type":"dinner","country":"MX","protein":"fish","base":"rice","name":{"en":"Pescado Zarandeado (Adobo-Grilled Fish)","es":"Pescado zarandeado"},"ing":{"en":["4 white fish fillets","2 tbsp achiote paste","2 tbsp mayonnaise","1 tbsp soy sauce","2 garlic cloves","2 limes","1½ cups rice","1 cucumber"],"es":["4 filetes de pescado blanco","2 cdas pasta de achiote","2 cdas mayonesa","1 cda salsa de soja","2 dientes de ajo","2 limas","1½ tazas arroz","1 pepino"]},"steps":{"en":["Blend achiote, mayonnaise, soy, garlic and lime into a paste; spread over the fish.","Grill or roast at 220°C for 12 min.","Serve with rice and cucumber."],"es":["Licuá el achiote, la mayonesa, la soja, el ajo y la lima; untá el pescado.","Cociná a la parrilla o al horno a 220°C 12 min.","Serví con arroz y pepino."]},"tip":{"en":"","es":""},"prep":["rice"]},
{"id":"arroz-rojo-con-huevo","type":"lunch","country":"MX","protein":"egg","base":"rice","name":{"en":"Mexican Red Rice with Fried Eggs & Avocado","es":"Arroz rojo con huevo frito y palta"},"ing":{"en":["1½ cups rice","2 tomatoes","1 onion","1 garlic clove","1 cup frozen peas","1 carrot, diced","4 eggs","1 avocado"],"es":["1½ tazas arroz","2 tomates","1 cebolla","1 diente de ajo","1 taza arvejas congeladas","1 zanahoria en cubos","4 huevos","1 palta"]},"steps":{"en":["Fry the rice in a little oil until golden.","Blend tomato, onion and garlic, pour in with 2½ cups water, carrot and peas; cover 20 min.","Serve with fried eggs and avocado."],"es":["Dorá el arroz en un poco de aceite.","Licuá el tomate, la cebolla y el ajo, volcá con 2½ tazas de agua, la zanahoria y las arvejas; tapá 20 min.","Serví con huevos fritos y palta."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"picadillo-a-la-cubana","type":"dinner","country":"CU","protein":"beef","base":"rice","name":{"en":"Picadillo a la Cubana","es":"Picadillo a la cubana"},"ing":{"en":["500 g ground beef","1 onion, chopped","1 green bell pepper, chopped","1 can crushed tomatoes","¼ cup green olives","2 tbsp raisins","1 tsp ground cumin","1½ cups rice","2 ripe plantains"],"es":["500 g carne picada","1 cebolla picada","1 morrón verde picado","1 lata tomate triturado","¼ taza aceitunas verdes","2 cdas pasas de uva","1 cdita comino","1½ tazas arroz","2 plátanos maduros"]},"steps":{"en":["Brown the beef with onion, pepper and cumin.","Add tomatoes, olives and raisins and simmer 15 min.","Serve with rice and fried ripe plantain."],"es":["Dorá la carne con la cebolla, el morrón y el comino.","Sumá el tomate, las aceitunas y las pasas y cociná 15 min.","Serví con arroz y plátano maduro frito."]},"tip":{"en":"","es":""},"prep":["brown-beef"]},
{"id":"yuca-con-mojo","type":"lunch","country":"CU","protein":"plant","base":"potato","name":{"en":"Yuca con Mojo with Black Beans","es":"Yuca con mojo y porotos negros"},"ing":{"en":["800 g cassava (yuca), in chunks","4 garlic cloves, minced","2 oranges (juice)","1 lime","4 tbsp olive oil","1 red onion, thinly sliced","1 can black beans","1 tsp ground cumin"],"es":["800 g mandioca en trozos","4 dientes de ajo picados","2 naranjas (jugo)","1 lima","4 cdas aceite de oliva","1 cebolla morada en pluma fina","1 lata porotos negros","1 cdita comino"]},"steps":{"en":["Boil the cassava 25 min until tender; remove the woody core.","Warm the garlic and onion in the oil, add orange and lime juice; pour over the cassava.","Warm the beans with cumin and serve alongside."],"es":["Herví la mandioca 25 min hasta que esté tierna; sacale el centro fibroso.","Calentá el ajo y la cebolla en el aceite, sumá los jugos de naranja y lima; volcá sobre la mandioca.","Calentá los porotos con el comino y serví al lado."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"pan-con-lechon","type":"lunch","country":"CU","protein":"pork","base":"bread","name":{"en":"Pan con Lechón (Mojo Pork Sandwich)","es":"Pan con lechón"},"ing":{"en":["800 g pork shoulder","2 oranges (juice)","2 limes","4 garlic cloves, minced","1 tsp ground cumin","1 tsp dried oregano","4 crusty rolls","1 red onion, thinly sliced"],"es":["800 g bondiola","2 naranjas (jugo)","2 limas","4 dientes de ajo picados","1 cdita comino","1 cdita orégano","4 panes franceses","1 cebolla morada en pluma fina"]},"steps":{"en":["Marinate the pork in citrus, garlic, cumin and oregano overnight.","Roast covered at 160°C for 3 hours; shred.","Fill the rolls with pork, a spoon of the juices and onion."],"es":["Mariná el cerdo con los cítricos, el ajo, el comino y el orégano toda la noche.","Asá tapado a 160°C 3 horas; desmenuzalo.","Rellená los panes con el cerdo, una cucharada de los jugos y cebolla."]},"tip":{"en":"","es":""},"prep":["marinate","cook-ahead"]},
{"id":"batido-de-mango","type":"snack","country":"CU","group":"fruit","tags":["smoothie"],"name":{"en":"Batido de Mango","es":"Batido de mango"},"ing":{"en":["2 mangoes","2 cups milk","1 lime","4 ice cubes"],"es":["2 mangos","2 tazas leche","1 lima","4 cubitos de hielo"]},"steps":{"en":["Peel and chop the mangoes.","Blend with the milk, a squeeze of lime and the ice.","Serve straight away."],"es":["Pelá y cortá los mangos.","Licuá con la leche, un chorrito de lima y el hielo.","Serví enseguida."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"jamaican-beef-patties","type":"lunch","country":"JM","protein":"beef","base":"bread","tags":["empanadas"],"name":{"en":"Jamaican Beef Patties","es":"Empanadas jamaiquinas de carne"},"ing":{"en":["2 pie crusts","1 tsp turmeric","500 g ground beef","1 onion, chopped","2 tsp curry powder","1 tsp dried thyme","½ cup breadcrumbs","1 cup beef broth"],"es":["2 tapas de tarta","1 cdita cúrcuma","500 g carne picada","1 cebolla picada","2 cditas curry en polvo","1 cdita tomillo seco","½ taza pan rallado","1 taza caldo de carne"]},"steps":{"en":["Brown the beef with onion, curry and thyme; add broth and breadcrumbs and cook until thick; cool.","Rub the crusts with turmeric, cut rounds and fill half-moons.","Crimp and bake at 200°C for 25 min."],"es":["Dorá la carne con la cebolla, el curry y el tomillo; sumá el caldo y el pan rallado y cociná hasta que espese; enfriá.","Frotá las masas con la cúrcuma, cortá círculos y armá medialunas rellenas.","Cerrá con tenedor y horneá a 200°C 25 min."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"run-down","type":"dinner","country":"JM","protein":"fish","base":"none","tags":["stew"],"name":{"en":"Run Down (Fish Simmered in Coconut) with Boiled Plantain","es":"Run down: pescado en coco con plátano hervido"},"ing":{"en":["600 g white fish fillets","2 cans coconut milk","1 onion, sliced","2 tomatoes, chopped","2 garlic cloves, minced","1 tsp dried thyme","3 green plantains"],"es":["600 g filet de pescado blanco","2 latas leche de coco","1 cebolla en pluma","2 tomates picados","2 dientes de ajo picados","1 cdita tomillo seco","3 plátanos verdes"]},"steps":{"en":["Simmer the coconut milk until it reduces by half and turns custardy.","Add onion, garlic, tomato and thyme; cook 5 min, then add the fish for 8 min.","Boil the plantains in their skins 20 min; peel and serve alongside."],"es":["Cociná la leche de coco hasta que se reduzca a la mitad y espese.","Sumá la cebolla, el ajo, el tomate y el tomillo; cociná 5 min y agregá el pescado 8 min.","Herví los plátanos con cáscara 20 min; pelalos y serví al lado."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"jamaican-festival","type":"snack","country":"JM","group":"grain","name":{"en":"Festival (Sweet Cornmeal Dumplings)","es":"Festival: bollitos dulces de harina de maíz"},"ing":{"en":["1 cup flour","½ cup cornmeal","2 tbsp sugar","1 tsp baking powder","½ cup milk","½ tsp vanilla extract","Sunflower oil for frying"],"es":["1 taza harina","½ taza harina de maíz","2 cdas azúcar","1 cdita polvo para hornear","½ taza leche","½ cdita esencia de vainilla","Aceite de girasol para freír"]},"steps":{"en":["Mix the dry ingredients, then the milk and vanilla into a firm dough.","Roll into small fingers.","Fry 3 min, turning, until golden."],"es":["Mezclá los secos y después la leche y la vainilla hasta tener una masa firme.","Formá deditos.","Freí 3 min, dando vuelta, hasta dorar."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"carbonnade-flamande","type":"dinner","country":"BE","protein":"beef","base":"potato","tags":["stew"],"name":{"en":"Carbonnade (Flemish Beef Stew) with Oven Fries","es":"Carbonada flamenca con papas al horno"},"ing":{"en":["800 g beef chuck, diced","3 onions, sliced","2 cups beef broth","1 tbsp brown sugar","1 tbsp Dijon mustard","1 slice bread","2 bay leaves","1 kg potatoes, cut into fries"],"es":["800 g carne para guiso en cubos","3 cebollas en pluma","2 tazas caldo de carne","1 cda azúcar mascabo","1 cda mostaza Dijon","1 rebanada de pan","2 hojas de laurel","1 kg papas en bastones"]},"steps":{"en":["Brown the beef; add the onions and cook 10 min.","Add broth, sugar and bay; spread the bread with mustard and lay it on top; simmer 2 hours.","Bake the fries at 220°C for 35 min and serve with the stew."],"es":["Dorá la carne; sumá la cebolla y cociná 10 min.","Agregá el caldo, el azúcar y el laurel; untá el pan con mostaza y ponelo encima; cociná 2 horas.","Horneá las papas a 220°C 35 min y serví con el guiso."]},"tip":{"en":"","es":""},"prep":["cook-ahead"]},
{"id":"stoemp-met-worst","type":"lunch","country":"BE","protein":"pork","base":"potato","tags":["sausages"],"name":{"en":"Stoemp (Carrot & Potato Mash) with Sausages","es":"Stoemp: puré de papa y zanahoria con salchichas"},"ing":{"en":["1 kg potatoes","4 carrots","1 leek, sliced","½ cup milk","1 tbsp butter","8 pork sausages"],"es":["1 kg papas","4 zanahorias","1 puerro en rodajas","½ taza leche","1 cda manteca","8 salchichas de cerdo"]},"steps":{"en":["Boil the potatoes and carrots together until soft.","Soften the leek in butter and mash everything with the milk.","Serve with oven-baked sausages."],"es":["Herví las papas y las zanahorias juntas hasta que estén tiernas.","Rehogá el puerro en manteca y pisá todo con la leche.","Serví con salchichas al horno."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"belgian-waffles","type":"breakfast","country":"BE","group":"grain","tags":["pancakes"],"name":{"en":"Belgian Waffles with Strawberries & Yogurt","es":"Waffles belgas con frutillas y yogur"},"ing":{"en":["2 cups flour","2 tsp baking powder","2 eggs","1½ cups milk","50 g butter, melted","2 cups strawberries","1 cup plain yogurt"],"es":["2 tazas harina","2 cditas polvo para hornear","2 huevos","1½ tazas leche","50 g manteca derretida","2 tazas frutillas","1 taza yogur natural"]},"steps":{"en":["Whisk flour, baking powder, eggs, milk and butter into a batter.","Cook in a hot waffle iron 4 min (or as thick pancakes).","Serve with strawberries and yogurt."],"es":["Batí la harina, el polvo de hornear, los huevos, la leche y la manteca.","Cociná en waflera caliente 4 min (o como panqueques gruesos).","Serví con frutillas y yogur."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"kaiserschmarrn","type":"breakfast","country":"AT","group":"grain","tags":["pancakes"],"name":{"en":"Kaiserschmarrn (Torn Pancake) with Apple Sauce","es":"Kaiserschmarrn con puré de manzana"},"ing":{"en":["4 eggs, separated","1 cup flour","1 cup milk","2 tbsp raisins","1 tbsp butter","3 apples"],"es":["4 huevos, separadas claras y yemas","1 taza harina","1 taza leche","2 cdas pasas de uva","1 cda manteca","3 manzanas"]},"steps":{"en":["Whisk yolks, flour and milk; fold in the whites beaten stiff and the raisins.","Cook in buttered pan 4 min, flip and tear into pieces with two forks; cook 3 min more.","Simmer the apples into a sauce to serve alongside."],"es":["Batí las yemas con la harina y la leche; incorporá las claras a nieve y las pasas.","Cociná en sartén con manteca 4 min, da vuelta y rompé en trozos con dos tenedores; cociná 3 min más.","Cociná las manzanas hasta hacer un puré para acompañar."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"tafelspitz","type":"dinner","country":"AT","protein":"beef","base":"potato","name":{"en":"Tafelspitz (Boiled Beef) with Apple-Horseradish & Potatoes","es":"Tafelspitz: carne hervida con manzana y papas"},"ing":{"en":["1 kg beef shin or brisket","2 carrots","1 leek","2 celery stalks","1 onion, halved","800 g potatoes","2 apples, grated","1 tbsp Dijon mustard"],"es":["1 kg osobuco o pecho de carne","2 zanahorias","1 puerro","2 tallos de apio","1 cebolla en mitades","800 g papas","2 manzanas ralladas","1 cda mostaza Dijon"]},"steps":{"en":["Simmer the beef with the vegetables in water for 2½ hours; keep the broth.","Boil the potatoes.","Slice the beef and serve with broth, potatoes and grated apple mixed with a little mustard."],"es":["Cociná la carne con las verduras en agua 2½ horas; guardá el caldo.","Herví las papas.","Cortá la carne y serví con el caldo, las papas y la manzana rallada con un poco de mostaza."]},"tip":{"en":"","es":""},"prep":["cook-ahead"]},
{"id":"apfelstrudel","type":"snack","country":"AT","group":"fruit","name":{"en":"Apple Strudel","es":"Strudel de manzana"},"ing":{"en":["6 sheets filo pastry","4 apples, thinly sliced","2 tbsp raisins","2 tbsp breadcrumbs","1 tsp cinnamon","2 tbsp sugar","50 g butter, melted"],"es":["6 hojas de masa filo","4 manzanas en láminas finas","2 cdas pasas de uva","2 cdas pan rallado","1 cdita canela","2 cdas azúcar","50 g manteca derretida"]},"steps":{"en":["Mix apples, raisins, cinnamon and sugar.","Brush filo sheets with butter, stack, sprinkle with breadcrumbs, add the filling and roll up.","Bake at 190°C for 35 min."],"es":["Mezclá las manzanas, las pasas, la canela y el azúcar.","Pincelá las hojas de filo con manteca, apilalas, espolvoreá con pan rallado, sumá el relleno y enrollá.","Horneá a 190°C 35 min."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"smorrebrod","type":"lunch","country":"DK","protein":"fish","base":"bread","name":{"en":"Smørrebrød (Open Rye Sandwiches with Egg, Salmon & Shrimp)","es":"Smørrebrød: sándwiches abiertos de centeno"},"ing":{"en":["8 slices rye or whole-grain bread","4 eggs, boiled","200 g smoked or cooked salmon","200 g shrimp, cooked","1 cucumber, sliced","3 tbsp mayonnaise","2 tbsp fresh dill, chopped","1 lemon"],"es":["8 rebanadas de pan de centeno o integral","4 huevos duros","200 g salmón ahumado o cocido","200 g langostinos cocidos","1 pepino en rodajas","3 cdas mayonesa","2 cdas eneldo fresco picado","1 limón"]},"steps":{"en":["Butter or spread the bread with a little mayonnaise.","Top some slices with egg and cucumber, others with salmon or shrimp.","Finish with dill and lemon."],"es":["Untá el pan con un poco de mayonesa.","Cubrí unas rebanadas con huevo y pepino y otras con salmón o langostinos.","Terminá con eneldo y limón."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"frikadeller","type":"dinner","country":"DK","protein":"pork","base":"potato","tags":["meatballs"],"name":{"en":"Frikadeller (Danish Meatballs) with Potatoes & Red Cabbage","es":"Frikadeller con papas y repollo colorado"},"ing":{"en":["500 g ground pork","1 onion, grated","1 egg","½ cup milk","3 tbsp flour","1 kg baby potatoes","½ red cabbage, shredded","2 tbsp vinegar"],"es":["500 g carne picada de cerdo","1 cebolla rallada","1 huevo","½ taza leche","3 cdas harina","1 kg papines","½ repollo colorado en juliana","2 cdas vinagre"]},"steps":{"en":["Mix pork, onion, egg, milk and flour; shape flat ovals and fry 5 min a side.","Boil the potatoes.","Braise the cabbage with vinegar and a splash of water for 20 min."],"es":["Mezclá el cerdo, la cebolla, el huevo, la leche y la harina; formá óvalos planos y freí 5 min por lado.","Herví los papines.","Braseá el repollo con el vinagre y un chorrito de agua 20 min."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"fiskesuppe","type":"lunch","country":"NO","protein":"fish","base":"potato","tags":["soup"],"name":{"en":"Norwegian Creamy Fish Soup","es":"Sopa cremosa noruega de pescado"},"ing":{"en":["500 g white fish fillets, in chunks","200 g salmon, in chunks","2 potatoes, diced","2 carrots, sliced","1 leek, sliced","4 cups fish or vegetable broth","1 cup milk","2 tbsp fresh dill, chopped"],"es":["500 g filet de pescado blanco en trozos","200 g salmón en trozos","2 papas en cubos","2 zanahorias en rodajas","1 puerro en rodajas","4 tazas caldo de pescado o de verduras","1 taza leche","2 cdas eneldo fresco picado"]},"steps":{"en":["Simmer potatoes, carrots and leek in the broth for 15 min.","Add milk and fish and poach 6 min.","Finish with dill."],"es":["Cociná las papas, las zanahorias y el puerro en el caldo 15 min.","Sumá la leche y el pescado y cociná 6 min.","Terminá con eneldo."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"farikal","type":"dinner","country":"NO","protein":"beef","base":"potato","tags":["stew"],"name":{"en":"Fårikål (Lamb & Cabbage Stew)","es":"Fårikål: guiso de cordero y repollo"},"ing":{"en":["800 g lamb or beef stewing meat","1 cabbage, in wedges","1 tsp black peppercorns","2 tbsp flour","1 kg potatoes"],"es":["800 g cordero o carne para guiso","1 repollo en gajos","1 cdita pimienta en grano","2 cdas harina","1 kg papas"]},"steps":{"en":["Layer the meat and cabbage in a pot, sprinkling flour, peppercorns and salt between layers.","Add 2 cups water, cover and simmer 2 hours.","Serve with boiled potatoes."],"es":["Armá capas de carne y repollo en una olla, espolvoreando harina, pimienta y sal entre capas.","Sumá 2 tazas de agua, tapá y cociná 2 horas.","Serví con papas hervidas."]},"tip":{"en":"","es":""},"prep":["cook-ahead"]},
{"id":"lohikeitto","type":"dinner","country":"FI","protein":"fish","base":"potato","tags":["soup"],"name":{"en":"Lohikeitto (Finnish Salmon Soup)","es":"Lohikeitto: sopa finlandesa de salmón"},"ing":{"en":["500 g salmon, in chunks","4 potatoes, diced","1 leek, sliced","1 carrot, diced","1 cup cream","4 cups vegetable broth","3 tbsp fresh dill, chopped","4 slices rye or whole-grain bread"],"es":["500 g salmón en trozos","4 papas en cubos","1 puerro en rodajas","1 zanahoria en cubos","1 taza crema de leche","4 tazas caldo de verduras","3 cdas eneldo fresco picado","4 rebanadas de pan de centeno o integral"]},"steps":{"en":["Simmer potatoes, carrot and leek in the broth for 15 min.","Add cream and salmon and poach 6 min.","Finish with dill; serve with rye bread."],"es":["Cociná las papas, la zanahoria y el puerro en el caldo 15 min.","Sumá la crema y el salmón y cociná 6 min.","Terminá con eneldo; serví con pan de centeno."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"mustikkapiirakka","type":"snack","country":"FI","group":"fruit","tags":["tart"],"name":{"en":"Finnish Blueberry Pie","es":"Tarta finlandesa de arándanos"},"ing":{"en":["1 cup flour","50 g butter","2 tbsp sugar","1 egg","2 cups blueberries","1 cup sour cream","1 tsp vanilla extract"],"es":["1 taza harina","50 g manteca","2 cdas azúcar","1 huevo","2 tazas arándanos","1 taza crema agria","1 cdita esencia de vainilla"]},"steps":{"en":["Rub butter, flour, sugar and half the egg into a dough; press into a tin.","Scatter the blueberries; whisk sour cream, the rest of the egg and vanilla and pour over.","Bake at 200°C for 25 min."],"es":["Uní la manteca, la harina, el azúcar y medio huevo; extendé en un molde.","Repartí los arándanos; batí la crema agria con el resto del huevo y la vainilla y volcá encima.","Horneá a 200°C 25 min."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"cesnecka","type":"lunch","country":"CZ","protein":"plant","base":"bread","tags":["soup"],"name":{"en":"Česnečka (Garlic & Potato Soup with Cheese Croutons)","es":"Česnečka: sopa de ajo y papa con crutones de queso"},"ing":{"en":["6 garlic cloves, minced","3 potatoes, diced","1 tsp dried marjoram or oregano","6 cups vegetable broth","4 slices bread, in cubes","100 g mild cheese, grated","1 tbsp butter"],"es":["6 dientes de ajo picados","3 papas en cubos","1 cdita mejorana u orégano","6 tazas caldo de verduras","4 rebanadas de pan en cubos","100 g queso de máquina rallado","1 cda manteca"]},"steps":{"en":["Simmer potatoes and marjoram in the broth for 15 min.","Add the garlic for the last 3 min.","Fry the bread cubes in butter; serve the soup with croutons and cheese."],"es":["Cociná las papas y la mejorana en el caldo 15 min.","Sumá el ajo los últimos 3 min.","Dorá el pan en manteca; serví la sopa con los crutones y el queso."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"ovocne-knedliky","type":"snack","country":"CZ","group":"fruit","name":{"en":"Ovocné Knedlíky (Fruit Dumplings) with Quark","es":"Knedlíky de fruta con queso blanco"},"ing":{"en":["250 g ricotta or quark","1 egg","1 cup flour","2 cups strawberries or plums","2 tbsp butter, melted","2 tbsp sugar"],"es":["250 g ricota o queso blanco","1 huevo","1 taza harina","2 tazas frutillas o ciruelas","2 cdas manteca derretida","2 cdas azúcar"]},"steps":{"en":["Knead ricotta, egg and flour into a soft dough.","Wrap each piece of fruit in dough and seal into balls.","Boil 8 min; serve with melted butter and a little sugar."],"es":["Amasá la ricota, el huevo y la harina hasta tener una masa blanda.","Envolvé cada fruta con masa y cerrá formando bolitas.","Herví 8 min; serví con manteca derretida y un poco de azúcar."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"mamaliga-cu-branza","type":"breakfast","country":"RO","group":"grain","name":{"en":"Mămăligă (Polenta) with Cheese, Sour Cream & Egg","es":"Mămăligă: polenta con queso, crema agria y huevo"},"ing":{"en":["1½ cups polenta","150 g feta cheese, crumbled","½ cup sour cream","4 eggs","1 tbsp butter"],"es":["1½ tazas polenta","150 g queso feta desmenuzado","½ taza crema agria","4 huevos","1 cda manteca"]},"steps":{"en":["Whisk the polenta into 5 cups boiling water and stir 8 min.","Fry the eggs in the butter.","Serve the polenta topped with cheese, sour cream and a fried egg."],"es":["Volcá la polenta en 5 tazas de agua hirviendo y revolvé 8 min.","Freí los huevos en la manteca.","Serví la polenta con queso, crema agria y un huevo frito."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"ciorba-de-perisoare","type":"dinner","country":"RO","protein":"beef","base":"rice","tags":["soup"],"name":{"en":"Ciorbă de Perișoare (Sour Meatball Soup)","es":"Ciorbă de perișoare: sopa ácida de albondiguitas"},"ing":{"en":["400 g ground beef","⅓ cup rice","1 egg","1 onion, chopped","2 carrots, diced","1 red bell pepper, diced","2 tbsp tomato paste","2 lemons","3 tbsp fresh dill, chopped"],"es":["400 g carne picada","⅓ taza arroz","1 huevo","1 cebolla picada","2 zanahorias en cubos","1 morrón rojo en cubos","2 cdas extracto de tomate","2 limones","3 cdas eneldo fresco picado"]},"steps":{"en":["Mix beef, rice and egg; roll small balls.","Simmer the vegetables and tomato paste in 8 cups water for 15 min; add the meatballs and cook 25 min.","Sour with lemon juice and finish with dill."],"es":["Mezclá la carne, el arroz y el huevo; formá bolitas chicas.","Cociná las verduras y el extracto en 8 tazas de agua 15 min; sumá las albondiguitas y cociná 25 min.","Acidificá con jugo de limón y terminá con eneldo."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"brudet","type":"dinner","country":"HR","protein":"fish","base":"grain","tags":["stew"],"name":{"en":"Brudet (Dalmatian Fish Stew) with Polenta","es":"Brudet: guiso dálmata de pescado con polenta"},"ing":{"en":["700 g white fish fillets, in chunks","2 onions, sliced","2 garlic cloves, minced","1 can crushed tomatoes","1 tbsp vinegar","3 tbsp olive oil","3 tbsp fresh parsley, chopped","1½ cups polenta"],"es":["700 g filet de pescado blanco en trozos","2 cebollas en pluma","2 dientes de ajo picados","1 lata tomate triturado","1 cda vinagre","3 cdas aceite de oliva","3 cdas perejil fresco picado","1½ tazas polenta"]},"steps":{"en":["Soften onions and garlic in the oil; add tomatoes, vinegar and 1 cup water and simmer 15 min.","Add the fish without stirring (shake the pot) and cook 10 min.","Serve over soft polenta with parsley."],"es":["Rehogá la cebolla y el ajo en el aceite; sumá el tomate, el vinagre y 1 taza de agua y cociná 15 min.","Agregá el pescado sin revolver (mové la olla) y cociná 10 min.","Serví sobre polenta blanda con perejil."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"zagorski-strukli","type":"lunch","country":"HR","protein":"plant","base":"bread","name":{"en":"Štrukli (Baked Cheese Pastry) with Salad","es":"Štrukli: pastel de queso al horno con ensalada"},"ing":{"en":["6 sheets filo pastry","400 g ricotta or cottage cheese","2 eggs","½ cup sour cream","2 tbsp butter, melted","1 head lettuce"],"es":["6 hojas de masa filo","400 g ricota o queso blanco","2 huevos","½ taza crema agria","2 cdas manteca derretida","1 planta de lechuga"]},"steps":{"en":["Mix cheese, eggs and half the sour cream.","Layer buttered filo with the filling, roll up and cut into pieces in a dish.","Top with the rest of the cream and bake at 190°C for 30 min; serve with salad."],"es":["Mezclá el queso, los huevos y la mitad de la crema agria.","Armá capas de filo con manteca y el relleno, enrollá y cortá en trozos en una fuente.","Cubrí con el resto de la crema y horneá a 190°C 30 min; serví con ensalada."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"cevapi","type":"dinner","country":"RS","protein":"beef","base":"bread","name":{"en":"Ćevapi with Flatbread, Ajvar & Onion","es":"Ćevapi con pan plano, ajvar y cebolla"},"ing":{"en":["600 g ground beef","2 garlic cloves, minced","1 tsp paprika","½ tsp baking soda","4 pita breads","2 red bell peppers, roasted","1 eggplant, roasted","1 red onion, chopped"],"es":["600 g carne picada","2 dientes de ajo picados","1 cdita pimentón","½ cdita bicarbonato de sodio","4 panes pita","2 morrones rojos asados","1 berenjena asada","1 cebolla morada picada"]},"steps":{"en":["Mix beef, garlic, paprika, soda and salt; shape small sausages and chill 1 hour.","Blend the roasted peppers and eggplant into ajvar.","Grill the ćevapi 8 min, turning; serve in warm pita with ajvar and onion."],"es":["Mezclá la carne, el ajo, el pimentón, el bicarbonato y sal; formá salchichitas y enfriá 1 hora.","Procesá los morrones y la berenjena asados para el ajvar.","Cociná los ćevapi a la parrilla 8 min, dando vuelta; serví en pita tibia con ajvar y cebolla."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"gibanica","type":"breakfast","country":"RS","group":"dairy","name":{"en":"Gibanica (Cheese & Egg Filo Pie)","es":"Gibanica: pastel de filo con queso y huevo"},"ing":{"en":["10 sheets filo pastry","300 g feta cheese, crumbled","200 g cottage cheese or ricotta","4 eggs","1 cup plain yogurt","3 tbsp sunflower oil"],"es":["10 hojas de masa filo","300 g queso feta desmenuzado","200 g queso blanco o ricota","4 huevos","1 taza yogur natural","3 cdas aceite de girasol"]},"steps":{"en":["Whisk eggs, yogurt and both cheeses.","Crumple oiled filo sheets into a dish, pouring filling between the layers.","Bake at 190°C for 35 min; serve warm."],"es":["Batí los huevos, el yogur y los dos quesos.","Arrugá las hojas de filo aceitadas en una fuente, volcando el relleno entre capas.","Horneá a 190°C 35 min; serví tibio."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"shopska-salad","type":"lunch","country":"BG","protein":"plant","base":"bread","name":{"en":"Shopska Salad with Feta & Bread","es":"Ensalada shopska con feta y pan"},"ing":{"en":["4 tomatoes, diced","2 cucumbers, diced","2 red bell peppers, roasted and sliced","1 red onion, chopped","200 g feta cheese, grated","3 tbsp sunflower oil","1 tbsp vinegar","1 baguette"],"es":["4 tomates en cubos","2 pepinos en cubos","2 morrones rojos asados en tiras","1 cebolla morada picada","200 g queso feta rallado","3 cdas aceite de girasol","1 cda vinagre","1 baguette"]},"steps":{"en":["Toss tomato, cucumber, pepper and onion with oil, vinegar and salt.","Grate the feta over in a snowy layer.","Serve with bread."],"es":["Mezclá el tomate, el pepino, el morrón y la cebolla con aceite, vinagre y sal.","Rallá el feta por encima como nieve.","Serví con pan."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"banitsa","type":"breakfast","country":"BG","group":"dairy","name":{"en":"Banitsa (Feta & Yogurt Filo Swirl)","es":"Banitsa: espiral de filo con feta y yogur"},"ing":{"en":["8 sheets filo pastry","250 g feta cheese, crumbled","3 eggs","1 cup plain yogurt","½ tsp baking soda","50 g butter, melted"],"es":["8 hojas de masa filo","250 g queso feta desmenuzado","3 huevos","1 taza yogur natural","½ cdita bicarbonato de sodio","50 g manteca derretida"]},"steps":{"en":["Mix feta, eggs, yogurt and soda.","Brush each filo sheet with butter, spread filling, roll into a log and coil in a round tin.","Bake at 190°C for 35 min until golden."],"es":["Mezclá el feta, los huevos, el yogur y el bicarbonato.","Pincelá cada hoja de filo con manteca, untá relleno, enrollá y armá un espiral en un molde redondo.","Horneá a 190°C 35 min, hasta dorar."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"tarator","type":"snack","country":"BG","group":"dairy","name":{"en":"Tarator (Cold Cucumber Yogurt Soup)","es":"Tarator: sopa fría de pepino y yogur"},"ing":{"en":["2 cups plain yogurt","1 cucumber, finely diced","1 garlic clove, minced","2 tbsp fresh dill, chopped","¼ cup walnuts, ground (optional)","1 tbsp olive oil"],"es":["2 tazas yogur natural","1 pepino en cubitos","1 diente de ajo picado","2 cdas eneldo fresco picado","¼ taza nueces molidas (opcional)","1 cda aceite de oliva"]},"steps":{"en":["Whisk the yogurt with 1 cup cold water.","Stir in cucumber, garlic, dill and oil.","Chill and serve in cups with ground walnuts on top."],"es":["Batí el yogur con 1 taza de agua fría.","Sumá el pepino, el ajo, el eneldo y el aceite.","Enfriá y serví en vasitos con nueces molidas arriba."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"khachapuri-adjaruli","type":"lunch","country":"GE","protein":"egg","base":"bread","name":{"en":"Khachapuri Adjaruli (Cheese & Egg Bread Boats)","es":"Khachapuri adjaruli: barquitos de pan con queso y huevo"},"ing":{"en":["500 g pizza dough","200 g mozzarella, grated","150 g feta cheese, crumbled","4 eggs","2 tbsp butter","1 head lettuce"],"es":["500 g masa de pizza","200 g mozzarella rallada","150 g queso feta desmenuzado","4 huevos","2 cdas manteca","1 planta de lechuga"]},"steps":{"en":["Shape the dough into 4 boats with rolled edges; fill with the mixed cheeses.","Bake at 230°C for 12 min.","Crack an egg into each, bake 4 min more and add a knob of butter; stir at the table. Serve with salad."],"es":["Formá 4 barquitos de masa con bordes enrollados; rellenalos con los quesos mezclados.","Horneá a 230°C 12 min.","Rompé un huevo en cada uno, horneá 4 min más y sumá un trocito de manteca; mezclá en la mesa. Serví con ensalada."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"lobio","type":"dinner","country":"GE","protein":"plant","base":"bread","tags":["stew"],"name":{"en":"Lobio (Georgian Bean Stew with Walnuts & Herbs)","es":"Lobio: guiso georgiano de porotos con nueces y hierbas"},"ing":{"en":["2 cans kidney beans","1 onion, chopped","2 garlic cloves, minced","¼ cup walnuts, ground","1 tsp ground coriander or cumin","4 tbsp fresh cilantro, chopped","1 tbsp vinegar","1 baguette"],"es":["2 latas porotos colorados","1 cebolla picada","2 dientes de ajo picados","¼ taza nueces molidas","1 cdita coriandro o comino molido","4 cdas cilantro fresco picado","1 cda vinagre","1 baguette"]},"steps":{"en":["Soften the onion and garlic with the spice.","Add the beans with their liquid and simmer 15 min, mashing some.","Stir in walnuts, cilantro and vinegar; serve with bread."],"es":["Rehogá la cebolla y el ajo con la especia.","Sumá los porotos con su líquido y cociná 15 min, pisando algunos.","Incorporá las nueces, el cilantro y el vinagre; serví con pan."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"chkmeruli","type":"dinner","country":"GE","protein":"poultry","base":"potato","name":{"en":"Chkmeruli (Chicken in Garlic Milk Sauce)","es":"Chkmeruli: pollo en salsa de leche y ajo"},"ing":{"en":["1 kg chicken thighs","6 garlic cloves, minced","1 cup milk","½ cup cream","2 tbsp fresh cilantro, chopped","800 g potatoes, in wedges"],"es":["1 kg muslos de pollo","6 dientes de ajo picados","1 taza leche","½ taza crema de leche","2 cdas cilantro fresco picado","800 g papas en gajos"]},"steps":{"en":["Roast the chicken and potatoes at 200°C for 35 min.","Warm the garlic in a little butter, add milk and cream and simmer 5 min.","Pour over the chicken and bake 10 min more; finish with cilantro."],"es":["Asá el pollo y las papas a 200°C 35 min.","Calentá el ajo en un poco de manteca, sumá la leche y la crema y cociná 5 min.","Bañá el pollo y horneá 10 min más; terminá con cilantro."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"lahmajun","type":"lunch","country":"AM","protein":"beef","base":"bread","name":{"en":"Lahmajun (Thin Flatbreads with Spiced Beef)","es":"Lahmajun: panes finos con carne especiada"},"ing":{"en":["500 g pizza dough","300 g ground beef","1 onion, grated","1 red bell pepper, finely chopped","2 tbsp tomato paste","1 tsp paprika","3 tbsp fresh parsley, chopped","1 lemon","1 head lettuce"],"es":["500 g masa de pizza","300 g carne picada","1 cebolla rallada","1 morrón rojo picado fino","2 cdas extracto de tomate","1 cdita pimentón","3 cdas perejil fresco picado","1 limón","1 planta de lechuga"]},"steps":{"en":["Mix beef, onion, pepper, tomato paste, paprika and parsley.","Roll the dough very thin into 8 rounds and spread the mixture thinly over.","Bake at 240°C for 8 min; serve with lemon and lettuce to roll up."],"es":["Mezclá la carne, la cebolla, el morrón, el extracto, el pimentón y el perejil.","Estirá la masa muy fina en 8 círculos y untá la mezcla en capa fina.","Horneá a 240°C 8 min; serví con limón y lechuga para enrollar."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"armenian-harissa","type":"dinner","country":"AM","protein":"poultry","base":"grain","name":{"en":"Harissa (Armenian Chicken & Wheat Porridge)","es":"Harissa armenia: guiso de pollo y trigo"},"ing":{"en":["1 kg chicken thighs","1½ cups bulgur or pearl barley","2 tbsp butter","1 tsp paprika","1 onion","1 cucumber"],"es":["1 kg muslos de pollo","1½ tazas trigo burgol o cebada perlada","2 cdas manteca","1 cdita pimentón","1 cebolla","1 pepino"]},"steps":{"en":["Simmer the chicken and onion in 8 cups water for 40 min; shred the meat.","Add the grain to the broth and cook 30 min, stirring, until creamy; beat in the chicken.","Serve with butter melted with paprika and cucumber."],"es":["Cociná el pollo y la cebolla en 8 tazas de agua 40 min; desmenuzá la carne.","Sumá el cereal al caldo y cociná 30 min, revolviendo, hasta que quede cremoso; incorporá el pollo batiendo.","Serví con manteca derretida con pimentón y pepino."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"risotto-alla-zucca","type":"dinner","country":"IT","protein":"plant","base":"rice","tags":["risotto"],"name":{"en":"Pumpkin Risotto","es":"Risotto de calabaza"},"ing":{"en":["1½ cups arborio rice","3 cups pumpkin, diced","1 onion, chopped","6 cups vegetable broth","2 tbsp butter","½ cup grated parmesan","6 sage leaves"],"es":["1½ tazas arroz arborio","3 tazas zapallo en cubos","1 cebolla picada","6 tazas caldo de verduras","2 cdas manteca","½ taza queso parmesano rallado","6 hojas de salvia"]},"steps":{"en":["Soften onion and pumpkin in half the butter for 8 min; stir in the rice.","Add hot broth a ladle at a time, stirring, for 18 min.","Beat in the rest of the butter, parmesan and sage."],"es":["Rehogá la cebolla y el zapallo en la mitad de la manteca 8 min; sumá el arroz.","Agregá el caldo caliente de a un cucharón, revolviendo, durante 18 min.","Incorporá el resto de la manteca, el parmesano y la salvia."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"polpette-al-sugo","type":"dinner","country":"IT","protein":"beef","base":"bread","tags":["meatballs"],"name":{"en":"Polpette al Sugo (Meatballs in Tomato Sauce) with Bread","es":"Polpette al sugo con pan"},"ing":{"en":["500 g ground beef","1 egg","½ cup breadcrumbs","4 tbsp grated parmesan","2 cans crushed tomatoes","2 garlic cloves","1 handful fresh basil","1 baguette"],"es":["500 g carne picada","1 huevo","½ taza pan rallado","4 cdas queso parmesano rallado","2 latas tomate triturado","2 dientes de ajo","1 puñado de albahaca fresca","1 baguette"]},"steps":{"en":["Mix beef, egg, breadcrumbs and parmesan; roll walnut-size balls.","Simmer the tomatoes with garlic 10 min; add the meatballs and cook 25 min.","Finish with basil; serve with bread for the sauce."],"es":["Mezclá la carne, el huevo, el pan rallado y el parmesano; formá bolitas del tamaño de una nuez.","Cociná el tomate con el ajo 10 min; sumá las albóndigas y cociná 25 min.","Terminá con albahaca; serví con pan para la salsa."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"frittata-di-patate","type":"lunch","country":"IT","protein":"egg","base":"potato","name":{"en":"Potato & Onion Frittata with Rocket Salad","es":"Frittata de papa y cebolla con ensalada de rúcula"},"ing":{"en":["6 eggs","500 g potatoes, thinly sliced","1 onion, sliced","4 tbsp grated parmesan","3 tbsp olive oil","2 cups mixed greens","1 lemon"],"es":["6 huevos","500 g papas en láminas finas","1 cebolla en pluma","4 cdas queso parmesano rallado","3 cdas aceite de oliva","2 tazas hojas verdes variadas","1 limón"]},"steps":{"en":["Cook potatoes and onion in the oil for 15 min until tender.","Pour over eggs beaten with parmesan; cook on low 8 min.","Finish under the grill 3 min; serve with greens dressed with lemon."],"es":["Cociná las papas y la cebolla en el aceite 15 min, hasta que estén tiernas.","Volcá los huevos batidos con el parmesano; cociná a fuego bajo 8 min.","Terminá en el grill 3 min; serví con hojas verdes con limón."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"cacio-e-pepe","type":"lunch","country":"IT","protein":"plant","base":"pasta","name":{"en":"Cacio e Pepe with Peas","es":"Cacio e pepe con arvejas"},"ing":{"en":["400 g spaghetti","1 cup grated parmesan","1 tsp black peppercorns, crushed","1 tbsp butter","2 cups frozen peas"],"es":["400 g spaghetti","1 taza queso parmesano rallado","1 cdita pimienta en grano machacada","1 cda manteca","2 tazas arvejas congeladas"]},"steps":{"en":["Cook the spaghetti, adding the peas for the last 3 min; keep 1 cup of water.","Toast the pepper in the butter.","Toss pasta with pepper, cheese and splashes of pasta water until creamy."],"es":["Cociná los spaghetti y sumá las arvejas los últimos 3 min; guardá 1 taza del agua.","Tostá la pimienta en la manteca.","Mezclá la pasta con la pimienta, el queso y chorritos del agua de cocción hasta que quede cremosa."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"pasta-alla-norma","type":"dinner","country":"IT","protein":"plant","base":"pasta","name":{"en":"Pasta alla Norma (Eggplant & Tomato)","es":"Pasta a la Norma: berenjena y tomate"},"ing":{"en":["400 g short pasta","2 eggplants, diced","2 cans crushed tomatoes","2 garlic cloves, sliced","4 tbsp olive oil","1 handful fresh basil","100 g ricotta"],"es":["400 g pasta corta","2 berenjenas en cubos","2 latas tomate triturado","2 dientes de ajo en láminas","4 cdas aceite de oliva","1 puñado de albahaca fresca","100 g ricota"]},"steps":{"en":["Roast the eggplant with half the oil at 220°C for 25 min.","Warm the garlic in the rest of the oil, add tomatoes and simmer 15 min; add the eggplant.","Toss with the pasta and basil; top with spoonfuls of ricotta."],"es":["Asá la berenjena con la mitad del aceite a 220°C 25 min.","Calentá el ajo en el resto del aceite, sumá el tomate y cociná 15 min; agregá la berenjena.","Mezclá con la pasta y la albahaca; terminá con cucharadas de ricota."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"fette-biscottate","type":"breakfast","country":"IT","group":"grain","tags":["toast"],"name":{"en":"Italian Breakfast: Rusks, Jam & Caffè Latte","es":"Desayuno italiano: tostadas secas, mermelada y café con leche"},"ing":{"en":["12 crackers or rusks","4 tbsp apricot jam","2 tbsp butter","3 cups milk","2 tsp instant coffee (grown-ups)","2 oranges"],"es":["12 galletas o tostadas secas","4 cdas mermelada de damasco","2 cdas manteca","3 tazas leche","2 cditas café instantáneo (adultos)","2 naranjas"]},"steps":{"en":["Spread the rusks with butter and a little jam.","Warm the milk; add coffee to the grown-ups' cups.","Serve with orange segments."],"es":["Untá las tostadas con manteca y un poco de mermelada.","Calentá la leche; sumá café a las tazas de los grandes.","Serví con gajos de naranja."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"macedonia-di-frutta","type":"snack","country":"IT","group":"fruit","name":{"en":"Macedonia (Italian Fruit Salad with Lemon)","es":"Macedonia de frutas al limón"},"ing":{"en":["2 apples","2 pears","2 peaches","1 cup grapes, halved","2 oranges (juice)","1 lemon"],"es":["2 manzanas","2 peras","2 duraznos","1 taza uvas en mitades","2 naranjas (jugo)","1 limón"]},"steps":{"en":["Dice all the fruit.","Pour over orange and lemon juice and toss.","Chill 30 min before serving."],"es":["Cortá toda la fruta en cubos.","Bañá con el jugo de naranja y limón y mezclá.","Enfriá 30 min antes de servir."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"croque-madame","type":"breakfast","country":"FR","group":"egg","tags":["toast"],"name":{"en":"Croque-Madame","es":"Croque-madame"},"ing":{"en":["8 slices sandwich bread","150 g cooked ham","150 g gruyère or mild cheese, grated","1 tbsp butter","1 tbsp flour","1 cup milk","4 eggs"],"es":["8 rebanadas de pan de molde","150 g jamón cocido","150 g queso gruyère o de máquina rallado","1 cda manteca","1 cda harina","1 taza leche","4 huevos"]},"steps":{"en":["Make a quick white sauce with butter, flour and milk.","Fill the bread with ham and half the cheese, spread the top with sauce and the rest of the cheese.","Bake at 220°C for 10 min and top each with a fried egg."],"es":["Hacé una salsa blanca rápida con manteca, harina y leche.","Rellená el pan con jamón y la mitad del queso; cubrí con salsa y el resto del queso.","Horneá a 220°C 10 min y poné un huevo frito encima de cada uno."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"blanquette-de-poulet","type":"dinner","country":"FR","protein":"poultry","base":"rice","tags":["stew"],"name":{"en":"Chicken Blanquette with Rice","es":"Blanquette de pollo con arroz"},"ing":{"en":["800 g chicken thighs, in pieces","2 carrots, in chunks","200 g mushrooms","1 onion","2 tbsp butter","2 tbsp flour","½ cup cream","1 lemon","1½ cups rice"],"es":["800 g muslos de pollo en trozos","2 zanahorias en trozos","200 g champiñones","1 cebolla","2 cdas manteca","2 cdas harina","½ taza crema de leche","1 limón","1½ tazas arroz"]},"steps":{"en":["Simmer chicken, carrots and onion in water to cover for 30 min; keep 2 cups broth.","Make a sauce with butter, flour and the broth; add mushrooms and cream and simmer 10 min.","Return the chicken and carrots, add lemon juice; serve with rice."],"es":["Cociná el pollo, las zanahorias y la cebolla cubiertos de agua 30 min; guardá 2 tazas del caldo.","Hacé una salsa con manteca, harina y el caldo; sumá los champiñones y la crema y cociná 10 min.","Volvé a poner el pollo y las zanahorias, sumá jugo de limón; serví con arroz."]},"tip":{"en":"","es":""},"prep":["rice"]},
{"id":"gratin-dauphinois","type":"lunch","country":"FR","protein":"pork","base":"potato","name":{"en":"Gratin Dauphinois with Ham & Green Salad","es":"Gratín delfinés con jamón y ensalada verde"},"ing":{"en":["1 kg potatoes, thinly sliced","1½ cups milk","½ cup cream","2 garlic cloves","¼ tsp nutmeg","150 g cooked ham","1 head lettuce"],"es":["1 kg papas en láminas finas","1½ tazas leche","½ taza crema de leche","2 dientes de ajo","¼ cdita nuez moscada","150 g jamón cocido","1 planta de lechuga"]},"steps":{"en":["Simmer the potatoes in milk, cream, garlic and nutmeg for 10 min.","Pour into a dish and bake at 180°C for 40 min until golden.","Serve with ham and a green salad."],"es":["Cociná las papas en la leche, la crema, el ajo y la nuez moscada 10 min.","Volcá en una fuente y horneá a 180°C 40 min, hasta dorar.","Serví con jamón y ensalada verde."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"salade-lyonnaise","type":"lunch","country":"FR","protein":"egg","base":"bread","name":{"en":"Salade Lyonnaise (Frisée, Bacon, Croutons & Egg)","es":"Ensalada lionesa: verdes, panceta, crutones y huevo"},"ing":{"en":["2 heads lettuce or frisée","150 g bacon, diced","4 eggs","2 cups bread cubes","1 tbsp Dijon mustard","2 tbsp vinegar","3 tbsp olive oil"],"es":["2 plantas de lechuga o escarola","150 g panceta en cubos","4 huevos","2 tazas pan en cubos","1 cda mostaza Dijon","2 cdas vinagre","3 cdas aceite de oliva"]},"steps":{"en":["Fry the bacon, then the bread cubes in its fat until crisp.","Poach or soft-boil the eggs for 6 min.","Toss the leaves with mustard, vinegar and oil; top with bacon, croutons and eggs."],"es":["Dorá la panceta y después el pan en su grasa hasta que esté crocante.","Cociná los huevos poché o pasados por agua 6 min.","Mezclá las hojas con mostaza, vinagre y aceite; cubrí con panceta, crutones y huevos."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"madeleines","type":"snack","country":"FR","group":"grain","tags":["cake"],"name":{"en":"Lemon Madeleines","es":"Magdalenas de limón"},"ing":{"en":["2 eggs","⅓ cup sugar","¾ cup flour","1 tsp baking powder","80 g butter, melted","1 lemon (zest)"],"es":["2 huevos","⅓ taza azúcar","¾ taza harina","1 cdita polvo para hornear","80 g manteca derretida","1 limón (ralladura)"]},"steps":{"en":["Whisk eggs and sugar until pale and thick.","Fold in flour, baking powder, butter and zest; chill 30 min.","Spoon into a buttered tray and bake at 200°C for 9 min."],"es":["Batí los huevos con el azúcar hasta que estén claros y espesos.","Incorporá la harina, el polvo de hornear, la manteca y la ralladura; enfriá 30 min.","Repartí en una placa enmantecada y horneá a 200°C 9 min."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"pisto-con-huevo","type":"dinner","country":"ES","protein":"egg","base":"bread","name":{"en":"Pisto Manchego with Fried Eggs","es":"Pisto manchego con huevo frito"},"ing":{"en":["2 zucchini, diced","1 eggplant, diced","2 bell peppers, diced","1 onion, chopped","1 can crushed tomatoes","4 tbsp olive oil","4 eggs","1 baguette"],"es":["2 zapallitos en cubos","1 berenjena en cubos","2 morrones en cubos","1 cebolla picada","1 lata tomate triturado","4 cdas aceite de oliva","4 huevos","1 baguette"]},"steps":{"en":["Soften onion and peppers in the oil 10 min; add eggplant and zucchini for 10 min.","Add tomatoes and simmer 20 min until jammy.","Serve with fried eggs and bread."],"es":["Rehogá la cebolla y los morrones en el aceite 10 min; sumá la berenjena y los zapallitos 10 min.","Agregá el tomate y cociná 20 min, hasta que espese.","Serví con huevos fritos y pan."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"lentejas-a-la-riojana","type":"lunch","country":"ES","protein":"pork","base":"bread","tags":["stew"],"name":{"en":"Lentejas a la Riojana (Lentils with Chorizo)","es":"Lentejas a la riojana"},"ing":{"en":["1½ cups lentils (dry)","1 chorizo sausage, sliced","1 onion, chopped","1 red bell pepper, chopped","2 carrots, diced","2 potatoes, diced","1 tsp paprika","1 bay leaf","4 slices bread"],"es":["1½ tazas lentejas secas","1 chorizo en rodajas","1 cebolla picada","1 morrón rojo picado","2 zanahorias en cubos","2 papas en cubos","1 cdita pimentón","1 hoja de laurel","4 rebanadas de pan"]},"steps":{"en":["Soften the onion and pepper with the chorizo; add paprika.","Add lentils, carrots, potatoes, bay and 6 cups water; simmer 35 min.","Serve with bread."],"es":["Rehogá la cebolla y el morrón con el chorizo; sumá el pimentón.","Agregá las lentejas, las zanahorias, las papas, el laurel y 6 tazas de agua; cociná 35 min.","Serví con pan."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"fabada-asturiana","type":"dinner","country":"ES","protein":"pork","base":"bread","tags":["stew"],"name":{"en":"Fabada (Asturian White Bean & Chorizo Stew)","es":"Fabada asturiana"},"ing":{"en":["3 cans white beans","1 chorizo sausage, sliced","150 g bacon, diced","1 onion, chopped","1 tsp smoked paprika","1 pinch saffron or turmeric","1 baguette"],"es":["3 latas porotos blancos","1 chorizo en rodajas","150 g panceta en cubos","1 cebolla picada","1 cdita pimentón ahumado","1 pizca de azafrán o cúrcuma","1 baguette"]},"steps":{"en":["Brown the bacon and chorizo with the onion.","Add beans with their liquid, paprika, saffron and 2 cups water; simmer 30 min gently.","Serve with bread."],"es":["Dorá la panceta y el chorizo con la cebolla.","Sumá los porotos con su líquido, el pimentón, el azafrán y 2 tazas de agua; cociná 30 min a fuego suave.","Serví con pan."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"gemista","type":"dinner","country":"GR","protein":"plant","base":"rice","name":{"en":"Gemista (Rice-Stuffed Tomatoes & Peppers)","es":"Gemista: tomates y morrones rellenos de arroz"},"ing":{"en":["4 large tomatoes","4 bell peppers","1 cup rice","1 onion, chopped","2 zucchini, grated","3 tbsp fresh parsley, chopped","2 tbsp fresh mint, chopped","4 tbsp olive oil","2 potatoes, in wedges"],"es":["4 tomates grandes","4 morrones","1 taza arroz","1 cebolla picada","2 zapallitos rallados","3 cdas perejil fresco picado","2 cdas menta fresca picada","4 cdas aceite de oliva","2 papas en gajos"]},"steps":{"en":["Hollow out tomatoes and peppers; chop the tomato pulp.","Mix rice, onion, zucchini, herbs, pulp and half the oil; fill the vegetables.","Bake with the potatoes and the rest of the oil at 190°C for 1 hour."],"es":["Ahuecá los tomates y los morrones; picá la pulpa del tomate.","Mezclá el arroz, la cebolla, el zapallito, las hierbas, la pulpa y la mitad del aceite; rellená las verduras.","Horneá con las papas y el resto del aceite a 190°C 1 hora."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"avgolemono","type":"lunch","country":"GR","protein":"poultry","base":"rice","tags":["soup"],"name":{"en":"Avgolemono (Chicken, Egg & Lemon Soup)","es":"Avgolemono: sopa de pollo, huevo y limón"},"ing":{"en":["500 g chicken breast","8 cups chicken broth","½ cup rice","3 eggs","2 lemons","2 tbsp fresh dill, chopped","4 slices bread"],"es":["500 g pechuga de pollo","8 tazas caldo de pollo","½ taza arroz","3 huevos","2 limones","2 cdas eneldo fresco picado","4 rebanadas de pan"]},"steps":{"en":["Poach the chicken in the broth 15 min; shred. Cook the rice in the broth 15 min.","Whisk eggs with lemon juice; slowly whisk in 2 ladles of hot broth.","Stir back into the pot off the boil with the chicken; finish with dill."],"es":["Cociná el pollo en el caldo 15 min y desmenuzalo. Cociná el arroz en el caldo 15 min.","Batí los huevos con el jugo de limón; sumá despacio 2 cucharones de caldo caliente batiendo.","Volcá a la olla sin que hierva, con el pollo; terminá con eneldo."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"bratkartoffeln-mit-spiegelei","type":"lunch","country":"DE","protein":"egg","base":"potato","name":{"en":"Bratkartoffeln (Pan-Fried Potatoes) with Fried Eggs & Gherkin Salad","es":"Bratkartoffeln: papas salteadas con huevo frito y ensalada de pepino"},"ing":{"en":["1 kg potatoes, boiled and sliced","1 onion, sliced","2 tbsp butter","4 eggs","2 cucumbers, thinly sliced","2 tbsp vinegar","2 tbsp fresh dill, chopped"],"es":["1 kg papas hervidas en rodajas","1 cebolla en pluma","2 cdas manteca","4 huevos","2 pepinos en rodajas finas","2 cdas vinagre","2 cdas eneldo fresco picado"]},"steps":{"en":["Fry the potatoes in butter until golden; add the onion for the last 5 min.","Fry the eggs.","Toss cucumber with vinegar, dill and salt; serve together."],"es":["Dorá las papas en manteca; sumá la cebolla los últimos 5 min.","Freí los huevos.","Mezclá el pepino con vinagre, eneldo y sal; serví todo junto."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"linseneintopf","type":"dinner","country":"DE","protein":"pork","base":"potato","tags":["stew"],"name":{"en":"Linseneintopf (Lentil Stew with Sausage)","es":"Linseneintopf: guiso de lentejas con salchicha"},"ing":{"en":["1½ cups lentils (dry)","2 potatoes, diced","2 carrots, diced","1 leek, sliced","1 onion, chopped","4 frankfurters, sliced","1 tbsp vinegar","6 cups vegetable broth"],"es":["1½ tazas lentejas secas","2 papas en cubos","2 zanahorias en cubos","1 puerro en rodajas","1 cebolla picada","4 salchichas tipo viena en rodajas","1 cda vinagre","6 tazas caldo de verduras"]},"steps":{"en":["Soften onion and leek; add lentils, potatoes, carrots and broth; simmer 30 min.","Add the sausages for 5 min.","Season with a splash of vinegar."],"es":["Rehogá la cebolla y el puerro; sumá las lentejas, las papas, las zanahorias y el caldo; cociná 30 min.","Agregá las salchichas 5 min.","Condimentá con un chorrito de vinagre."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"quark-mit-fruchten","type":"snack","country":"DE","group":"dairy","name":{"en":"Quark with Berries & Oats","es":"Queso blanco con frutos rojos y avena"},"ing":{"en":["2 cups cottage cheese or quark","2 tbsp honey","1½ cups mixed berries","3 tbsp oats"],"es":["2 tazas queso blanco","2 cdas miel","1½ tazas frutos rojos","3 cdas avena"]},"steps":{"en":["Whip the quark with the honey until smooth.","Spoon into cups.","Top with berries and toasted oats."],"es":["Batí el queso blanco con la miel hasta que quede liso.","Serví en vasitos.","Terminá con frutos rojos y avena tostada."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"twarozek-z-rzodkiewka","type":"breakfast","country":"PL","group":"dairy","tags":["toast"],"name":{"en":"Twarożek (Herbed Cottage Cheese with Radish) on Rye","es":"Twarożek: queso blanco con rabanitos sobre pan de centeno"},"ing":{"en":["2 cups cottage cheese","6 radishes, finely chopped","3 spring onions, sliced","2 tbsp fresh dill, chopped","½ cup plain yogurt","8 slices rye or whole-grain bread"],"es":["2 tazas queso blanco","6 rabanitos picados finos","3 cebollas de verdeo en rodajas","2 cdas eneldo fresco picado","½ taza yogur natural","8 rebanadas de pan de centeno o integral"]},"steps":{"en":["Mix the cheese with yogurt, radish, spring onion and dill.","Season with salt.","Spread thickly on the bread."],"es":["Mezclá el queso con el yogur, el rabanito, el verdeo y el eneldo.","Salá.","Untá bien sobre el pan."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"bifana","type":"lunch","country":"PT","protein":"pork","base":"bread","name":{"en":"Bifana (Garlic-Wine Pork Sandwich) with Salad","es":"Bifana: sándwich de cerdo al ajo con ensalada"},"ing":{"en":["600 g pork tenderloin, thinly sliced","4 garlic cloves, minced","1 tsp paprika","1 lemon","1 bay leaf","4 crusty rolls","1 tbsp Dijon mustard","1 head lettuce"],"es":["600 g lomo de cerdo en láminas finas","4 dientes de ajo picados","1 cdita pimentón","1 limón","1 hoja de laurel","4 panes franceses","1 cda mostaza Dijon","1 planta de lechuga"]},"steps":{"en":["Marinate the pork with garlic, paprika, lemon and bay for 1 hour.","Cook in a hot pan 2 min a side with a splash of water to make a little sauce.","Pile into rolls with mustard; serve with salad."],"es":["Mariná el cerdo con el ajo, el pimentón, el limón y el laurel 1 hora.","Cociná en sartén caliente 2 min por lado con un chorrito de agua para hacer un poco de salsa.","Rellená los panes con mostaza; serví con ensalada."]},"tip":{"en":"","es":""},"prep":["marinate"]},
{"id":"caldeirada","type":"dinner","country":"PT","protein":"fish","base":"potato","tags":["stew"],"name":{"en":"Caldeirada (Portuguese Fish & Potato Stew)","es":"Caldeirada: guiso portugués de pescado y papa"},"ing":{"en":["700 g white fish fillets, in chunks","800 g potatoes, sliced","2 onions, sliced","2 bell peppers, sliced","3 tomatoes, sliced","2 garlic cloves, sliced","3 tbsp olive oil","3 tbsp fresh parsley, chopped"],"es":["700 g filet de pescado blanco en trozos","800 g papas en rodajas","2 cebollas en pluma","2 morrones en tiras","3 tomates en rodajas","2 dientes de ajo en láminas","3 cdas aceite de oliva","3 cdas perejil fresco picado"]},"steps":{"en":["Layer potatoes, onions, peppers, tomatoes and garlic in a pot with oil and 1 cup water.","Cover and cook 25 min.","Lay the fish on top and cook 10 min more; finish with parsley."],"es":["Armá capas de papa, cebolla, morrón, tomate y ajo en una olla con aceite y 1 taza de agua.","Tapá y cociná 25 min.","Acomodá el pescado arriba y cociná 10 min más; terminá con perejil."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"welsh-rarebit","type":"breakfast","country":"GB","group":"dairy","tags":["toast"],"name":{"en":"Welsh Rarebit with Tomatoes","es":"Welsh rarebit con tomates"},"ing":{"en":["200 g cheddar cheese, grated","1 tbsp Dijon mustard","1 tbsp Worcestershire sauce","3 tbsp milk","1 egg yolk","8 slices whole-grain bread","4 tomatoes, halved"],"es":["200 g queso cheddar rallado","1 cda mostaza Dijon","1 cda salsa inglesa","3 cdas leche","1 yema","8 rebanadas de pan integral","4 tomates en mitades"]},"steps":{"en":["Mix cheese, mustard, Worcestershire, milk and yolk into a paste.","Toast the bread, spread with the cheese and grill until bubbling.","Serve with grilled tomatoes."],"es":["Mezclá el queso, la mostaza, la salsa inglesa, la leche y la yema.","Tostá el pan, untá con el queso y gratiná hasta que burbujee.","Serví con tomates grillados."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"cornish-pasties","type":"lunch","country":"GB","protein":"beef","base":"bread","tags":["empanadas"],"name":{"en":"Cornish Pasties","es":"Pasties de Cornualles"},"ing":{"en":["2 pie crusts","400 g beef sirloin, finely diced","2 potatoes, finely diced","1 onion, chopped","1 cup pumpkin or swede, diced","1 egg"],"es":["2 tapas de tarta","400 g carne en cubitos","2 papas en cubitos","1 cebolla picada","1 taza zapallo en cubitos","1 huevo"]},"steps":{"en":["Mix beef, potato, onion and pumpkin with salt and pepper.","Cut 4 rounds of pastry, fill, fold and crimp the edge.","Brush with egg and bake at 190°C for 45 min."],"es":["Mezclá la carne, la papa, la cebolla y el zapallo con sal y pimienta.","Cortá 4 círculos de masa, rellená, doblá y repulgá.","Pincelá con huevo y horneá a 190°C 45 min."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"toad-in-the-hole","type":"dinner","country":"GB","protein":"pork","base":"bread","tags":["sausages"],"name":{"en":"Toad in the Hole with Onion Gravy & Peas","es":"Salchichas en masa con salsa de cebolla y arvejas"},"ing":{"en":["8 pork sausages","1 cup flour","3 eggs","1 cup milk","2 onions, sliced","1 cup beef broth","2 cups frozen peas"],"es":["8 salchichas de cerdo","1 taza harina","3 huevos","1 taza leche","2 cebollas en pluma","1 taza caldo de carne","2 tazas arvejas congeladas"]},"steps":{"en":["Brown the sausages in an oiled tin at 220°C for 10 min.","Pour in the batter of flour, eggs and milk and bake 25 min until puffed.","Cook the onions slowly, add broth and simmer into gravy; serve with peas."],"es":["Dorá las salchichas en una fuente aceitada a 220°C 10 min.","Volcá la mezcla de harina, huevos y leche y horneá 25 min, hasta que se infle.","Cociná las cebollas despacio, sumá el caldo y cociná hasta tener una salsa; serví con arvejas."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"boxty-with-egg","type":"breakfast","country":"IE","group":"egg","name":{"en":"Boxty (Irish Potato Pancakes) with Eggs","es":"Boxty: panqueques irlandeses de papa con huevo"},"ing":{"en":["2 potatoes, grated","1 cup mashed potato","1 cup flour","1 tsp baking powder","¾ cup milk","4 eggs","1 tbsp butter"],"es":["2 papas ralladas","1 taza puré de papas","1 taza harina","1 cdita polvo para hornear","¾ taza leche","4 huevos","1 cda manteca"]},"steps":{"en":["Squeeze the grated potato dry and mix with mash, flour, baking powder and milk.","Cook spoonfuls in butter 4 min a side.","Serve with fried or poached eggs."],"es":["Escurrí bien la papa rallada y mezclala con el puré, la harina, el polvo de hornear y la leche.","Cociná cucharadas en manteca 4 min por lado.","Serví con huevos fritos o poché."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"fatteh-hummus","type":"lunch","country":"SY","protein":"plant","base":"bread","name":{"en":"Fatteh (Chickpeas, Toasted Pita & Garlic Yogurt)","es":"Fatteh: garbanzos, pita tostada y yogur al ajo"},"ing":{"en":["2 cans chickpeas","3 pita breads","2 cups plain yogurt","2 tbsp tahini","1 garlic clove, minced","1 tsp ground cumin","2 tbsp fresh parsley, chopped","2 tbsp pine nuts (optional)"],"es":["2 latas garbanzos","3 panes pita","2 tazas yogur natural","2 cdas tahini","1 diente de ajo picado","1 cdita comino","2 cdas perejil fresco picado","2 cdas piñones (opcional)"]},"steps":{"en":["Tear the pitas and bake at 200°C for 8 min until crisp.","Warm the chickpeas in their liquid with the cumin.","Layer pita, chickpeas and the yogurt whisked with tahini and garlic; top with parsley and pine nuts."],"es":["Cortá las pitas en trozos y horneá a 200°C 8 min, hasta que estén crocantes.","Calentá los garbanzos en su líquido con el comino.","Armá capas de pita, garbanzos y el yogur batido con tahini y ajo; terminá con perejil y piñones."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"kibbeh-bil-sanieh","type":"dinner","country":"SY","protein":"beef","base":"grain","name":{"en":"Baked Kibbeh (Bulgur & Beef Pie) with Yogurt","es":"Kibbeh al horno con yogur"},"ing":{"en":["1½ cups fine bulgur","700 g ground beef","2 onions, grated","1 tsp cinnamon","1 tsp allspice or cumin","¼ cup pine nuts (optional)","3 tbsp olive oil","1 cup plain yogurt","1 cucumber"],"es":["1½ tazas trigo burgol fino","700 g carne picada","2 cebollas ralladas","1 cdita canela","1 cdita pimienta de Jamaica o comino","¼ taza piñones (opcional)","3 cdas aceite de oliva","1 taza yogur natural","1 pepino"]},"steps":{"en":["Soak the bulgur 15 min, squeeze dry and knead with 500 g beef, 1 onion and spices.","Brown the rest of the beef with the other onion and pine nuts for the filling.","Layer half the kibbeh, the filling and the rest; score, drizzle with oil and bake at 190°C for 35 min. Serve with yogurt and cucumber."],"es":["Remojá el burgol 15 min, escurrilo y amasalo con 500 g de carne, 1 cebolla y las especias.","Dorá el resto de la carne con la otra cebolla y los piñones para el relleno.","Armá capas: mitad del kibbeh, el relleno y el resto; marcá, rociá con aceite y horneá a 190°C 35 min. Serví con yogur y pepino."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"muhammara","type":"snack","country":"SY","group":"veg","name":{"en":"Muhammara (Red Pepper & Walnut Dip) with Veg & Pita","es":"Muhammara: dip de morrón y nueces con verduras y pita"},"ing":{"en":["3 red bell peppers, roasted","½ cup walnuts","2 tbsp breadcrumbs","1 tsp ground cumin","1 lemon","2 tbsp olive oil","2 carrots, in sticks","2 pita breads"],"es":["3 morrones rojos asados","½ taza nueces","2 cdas pan rallado","1 cdita comino","1 limón","2 cdas aceite de oliva","2 zanahorias en bastones","2 panes pita"]},"steps":{"en":["Blend peppers, walnuts, breadcrumbs, cumin, lemon and oil until thick.","Spread in a bowl with a drizzle of oil.","Serve with carrot sticks and warm pita."],"es":["Procesá los morrones, las nueces, el pan rallado, el comino, el limón y el aceite hasta que espese.","Serví en un bol con un hilo de aceite.","Acompañá con bastones de zanahoria y pita tibia."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"mansaf","type":"dinner","country":"JO","protein":"beef","base":"rice","name":{"en":"Mansaf (Lamb in Yogurt Sauce with Rice)","es":"Mansaf: cordero en salsa de yogur con arroz"},"ing":{"en":["800 g lamb or beef stewing meat","3 cups plain yogurt","1 tbsp cornstarch","1 onion","1 pinch saffron or turmeric","2 cups rice","2 tbsp almonds or pine nuts (optional)","2 tbsp fresh parsley, chopped"],"es":["800 g cordero o carne para guiso","3 tazas yogur natural","1 cda maicena","1 cebolla","1 pizca de azafrán o cúrcuma","2 tazas arroz","2 cdas almendras o piñones (opcional)","2 cdas perejil fresco picado"]},"steps":{"en":["Simmer the meat with the onion in water for 1½ hours.","Whisk yogurt with cornstarch, add 1 cup of the broth and the meat and simmer gently 15 min, stirring.","Cook the rice with saffron; serve the meat on the rice with the sauce, nuts and parsley."],"es":["Cociná la carne con la cebolla en agua 1½ horas.","Batí el yogur con la maicena, sumá 1 taza del caldo y la carne y cociná suave 15 min, revolviendo.","Cociná el arroz con azafrán; serví la carne sobre el arroz con la salsa, los frutos secos y el perejil."]},"tip":{"en":"","es":""},"prep":["cook-ahead"]},
{"id":"maqluba","type":"dinner","country":"JO","protein":"poultry","base":"rice","name":{"en":"Maqluba (Upside-Down Chicken, Eggplant & Rice)","es":"Maqluba: arroz invertido con pollo y berenjena"},"ing":{"en":["800 g chicken thighs","2 eggplants, sliced","1 cauliflower, in florets","2 cups rice","2 tomatoes, sliced","1 tsp ground cinnamon","1 tsp allspice or cumin","4 cups chicken broth","1 cup plain yogurt"],"es":["800 g muslos de pollo","2 berenjenas en rodajas","1 coliflor en ramitos","2 tazas arroz","2 tomates en rodajas","1 cdita canela","1 cdita pimienta de Jamaica o comino","4 tazas caldo de pollo","1 taza yogur natural"]},"steps":{"en":["Brown the chicken; roast the eggplant and cauliflower with oil at 220°C for 20 min.","Layer tomato, chicken, vegetables and the spiced rice in a pot; pour in the broth, cover and cook 30 min on low.","Rest 10 min, turn out upside down and serve with yogurt."],"es":["Dorá el pollo; asá la berenjena y la coliflor con aceite a 220°C 20 min.","Armá capas de tomate, pollo, verduras y el arroz con especias en una olla; volcá el caldo, tapá y cociná 30 min a fuego bajo.","Dejá reposar 10 min, desmoldá dando vuelta y serví con yogur."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"tepsi-baytinijan","type":"dinner","country":"IQ","protein":"beef","base":"potato","tags":["meatballs"],"name":{"en":"Tepsi Baytinijan (Eggplant, Meatball & Potato Bake)","es":"Tepsi baytinijan: horno de berenjena, albóndigas y papa"},"ing":{"en":["2 eggplants, sliced","3 potatoes, sliced","500 g ground beef","1 onion, grated","2 tomatoes, sliced","1 green bell pepper, sliced","2 tbsp tomato paste","1 cup rice"],"es":["2 berenjenas en rodajas","3 papas en rodajas","500 g carne picada","1 cebolla rallada","2 tomates en rodajas","1 morrón verde en tiras","2 cdas extracto de tomate","1 taza arroz"]},"steps":{"en":["Roast the eggplant and potato slices with oil at 220°C for 20 min.","Mix beef and onion, shape small meatballs and brown.","Layer everything with tomato and pepper, pour tomato paste mixed with 1 cup water over and bake at 190°C for 35 min; serve with rice."],"es":["Asá las rodajas de berenjena y papa con aceite a 220°C 20 min.","Mezclá la carne con la cebolla, formá albondiguitas y doralas.","Armá capas con el tomate y el morrón, volcá el extracto disuelto en 1 taza de agua y horneá a 190°C 35 min; serví con arroz."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"iraqi-grilled-fish","type":"dinner","country":"IQ","protein":"fish","base":"rice","name":{"en":"Iraqi-Style Grilled Fish with Tomato, Onion & Rice","es":"Pescado grillado al estilo iraquí con tomate, cebolla y arroz"},"ing":{"en":["4 white fish fillets","1 tsp turmeric","2 lemons","2 tomatoes, sliced","1 onion, sliced","1 tsp curry powder","1½ cups rice"],"es":["4 filetes de pescado blanco","1 cdita cúrcuma","2 limones","2 tomates en rodajas","1 cebolla en pluma","1 cdita curry en polvo","1½ tazas arroz"]},"steps":{"en":["Rub the fish with turmeric, curry, lemon and salt.","Grill or roast at 220°C for 10 min; top with tomato and onion and cook 5 min more.","Serve with rice and lemon."],"es":["Frotá el pescado con cúrcuma, curry, limón y sal.","Cociná a la parrilla o al horno a 220°C 10 min; cubrí con tomate y cebolla y cociná 5 min más.","Serví con arroz y limón."]},"tip":{"en":"","es":""},"prep":["rice"]},
{"id":"chicken-kabsa","type":"dinner","country":"SA","protein":"poultry","base":"rice","name":{"en":"Chicken Kabsa (Spiced Rice with Chicken)","es":"Kabsa de pollo"},"ing":{"en":["1 kg chicken thighs","2 cups basmati rice","1 onion, chopped","2 tomatoes, chopped","2 carrots, grated","1 tsp cinnamon","½ tsp ground cardamom","2 tbsp raisins","3 cups chicken broth"],"es":["1 kg muslos de pollo","2 tazas arroz basmati","1 cebolla picada","2 tomates picados","2 zanahorias ralladas","1 cdita canela","½ cdita cardamomo molido","2 cdas pasas de uva","3 tazas caldo de pollo"]},"steps":{"en":["Brown the chicken with the onion; add tomatoes, carrots and spices.","Add the broth and simmer 20 min; lift out the chicken and roast at 220°C for 10 min.","Cook the rice in the broth for 18 min; serve the chicken on top with raisins."],"es":["Dorá el pollo con la cebolla; sumá el tomate, la zanahoria y las especias.","Agregá el caldo y cociná 20 min; sacá el pollo y doralo en el horno a 220°C 10 min.","Cociná el arroz en el caldo 18 min; serví el pollo encima con las pasas."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"saleeg","type":"lunch","country":"SA","protein":"poultry","base":"rice","name":{"en":"Saleeg (Creamy Chicken Rice)","es":"Saleeg: arroz cremoso con pollo"},"ing":{"en":["600 g chicken breast","1½ cups short-grain rice","2 cups milk","4 cups chicken broth","2 tbsp butter","½ tsp ground cardamom","1 cucumber"],"es":["600 g pechuga de pollo","1½ tazas arroz de grano corto","2 tazas leche","4 tazas caldo de pollo","2 cdas manteca","½ cdita cardamomo molido","1 pepino"]},"steps":{"en":["Poach the chicken in the broth 15 min; shred.","Cook the rice in the broth, then add the milk and cardamom and stir until creamy, 15 min.","Serve topped with the chicken and butter, with cucumber."],"es":["Cociná el pollo en el caldo 15 min y desmenuzalo.","Cociná el arroz en el caldo y después sumá la leche y el cardamomo, revolviendo hasta que quede cremoso, 15 min.","Serví con el pollo y la manteca encima, con pepino."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"malawah","type":"breakfast","country":"YE","group":"grain","name":{"en":"Malawah (Flaky Flatbread) with Grated Tomato & Honey","es":"Malawah: pan hojaldrado con tomate rallado y miel"},"ing":{"en":["2 cups flour","¾ cup warm water","50 g butter, melted","3 ripe tomatoes, grated","2 tbsp honey","4 eggs, boiled"],"es":["2 tazas harina","¾ taza agua tibia","50 g manteca derretida","3 tomates maduros rallados","2 cdas miel","4 huevos duros"]},"steps":{"en":["Knead flour, water and salt; rest 30 min.","Stretch thin, brush with butter, fold and coil; flatten and cook in a pan 3 min a side.","Serve with grated tomato, a little honey and boiled eggs."],"es":["Amasá la harina con el agua y sal; dejá reposar 30 min.","Estirá fino, pincelá con manteca, doblá y enrollá en espiral; aplaná y cociná en sartén 3 min por lado.","Serví con tomate rallado, un poco de miel y huevos duros."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"fasolia-yemeni","type":"lunch","country":"YE","protein":"plant","base":"bread","tags":["stew"],"name":{"en":"Fasolia (Spiced Bean Stew) with Eggs & Flatbread","es":"Fasolia: guiso especiado de porotos con huevo y pan"},"ing":{"en":["2 cans white beans","1 onion, chopped","2 tomatoes, chopped","1 tsp ground cumin","1 tsp turmeric","4 eggs","4 pita breads"],"es":["2 latas porotos blancos","1 cebolla picada","2 tomates picados","1 cdita comino","1 cdita cúrcuma","4 huevos","4 panes pita"]},"steps":{"en":["Soften the onion with the spices; add tomatoes and cook 5 min.","Add the beans with some liquid and simmer 10 min.","Crack in the eggs, cover until set; serve with flatbread."],"es":["Rehogá la cebolla con las especias; sumá el tomate y cociná 5 min.","Agregá los porotos con un poco de líquido y cociná 10 min.","Rompé los huevos encima, tapá hasta que cuajen; serví con pan."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"chorba-frik","type":"lunch","country":"DZ","protein":"beef","base":"grain","tags":["soup"],"name":{"en":"Chorba Frik (Lamb, Tomato & Cracked Wheat Soup)","es":"Chorba frik: sopa de cordero, tomate y trigo partido"},"ing":{"en":["400 g lamb or beef stewing meat, diced","¾ cup freekeh or bulgur","1 onion, chopped","2 tbsp tomato paste","1 can chickpeas, drained","1 tsp paprika","4 tbsp fresh cilantro, chopped","1 lemon"],"es":["400 g cordero o carne para guiso en cubos","¾ taza freekeh o trigo burgol","1 cebolla picada","2 cdas extracto de tomate","1 lata garbanzos escurridos","1 cdita pimentón","4 cdas cilantro fresco picado","1 limón"]},"steps":{"en":["Brown the meat with onion, paprika and tomato paste.","Add 8 cups water and simmer 45 min.","Add the grain and chickpeas and cook 20 min; finish with cilantro and lemon."],"es":["Dorá la carne con la cebolla, el pimentón y el extracto.","Sumá 8 tazas de agua y cociná 45 min.","Agregá el cereal y los garbanzos y cociná 20 min; terminá con cilantro y limón."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"garantita","type":"snack","country":"DZ","group":"grain","name":{"en":"Garantita (Chickpea Flour Bake) with Cumin","es":"Garantita: horneado de harina de garbanzo con comino"},"ing":{"en":["1½ cups chickpea flour","3 cups water","3 tbsp olive oil","1 egg","1 tsp ground cumin","2 crusty rolls"],"es":["1½ tazas harina de garbanzo","3 tazas agua","3 cdas aceite de oliva","1 huevo","1 cdita comino","2 panes franceses"]},"steps":{"en":["Whisk chickpea flour, water, oil and salt; rest 30 min.","Pour into an oiled tin, brush with beaten egg and bake at 220°C for 30 min until set and golden.","Cut into squares, dust with cumin; serve warm, alone or in bread."],"es":["Batí la harina de garbanzo con el agua, el aceite y sal; dejá reposar 30 min.","Volcá en una fuente aceitada, pincelá con huevo batido y horneá a 220°C 30 min, hasta que cuaje y dore.","Cortá en cuadrados y espolvoreá con comino; serví tibio, solo o en pan."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"mhadjeb","type":"breakfast","country":"DZ","group":"grain","name":{"en":"Mhadjeb (Semolina Flatbreads Filled with Tomato & Pepper)","es":"Mhadjeb: panes de sémola rellenos de tomate y morrón"},"ing":{"en":["2 cups flour","¾ cup warm water","2 tomatoes, chopped","1 red bell pepper, chopped","1 onion, chopped","3 tbsp olive oil","2 cups milk"],"es":["2 tazas harina","¾ taza agua tibia","2 tomates picados","1 morrón rojo picado","1 cebolla picada","3 cdas aceite de oliva","2 tazas leche"]},"steps":{"en":["Knead flour, water and salt; rest 20 min. Cook onion, pepper and tomato in oil until jammy.","Stretch thin squares, spoon filling in the middle and fold into parcels.","Cook on a dry pan 3 min a side; serve with warm milk."],"es":["Amasá la harina con el agua y sal; dejá reposar 20 min. Cociná la cebolla, el morrón y el tomate en aceite hasta que espese.","Estirá cuadrados finos, poné relleno en el centro y doblá en paquetitos.","Cociná en sartén seca 3 min por lado; serví con leche tibia."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"thieboudienne","type":"dinner","country":"SN","protein":"fish","base":"rice","name":{"en":"Thieboudienne (Fish, Vegetables & Tomato Rice)","es":"Thieboudienne: pescado, verduras y arroz con tomate"},"ing":{"en":["700 g firm white fish fillets","2 cups rice","3 tbsp tomato paste","1 onion, chopped","2 carrots, in chunks","1 eggplant, in chunks","¼ cabbage, in wedges","3 tbsp fresh parsley, chopped","2 garlic cloves"],"es":["700 g filet de pescado blanco firme","2 tazas arroz","3 cdas extracto de tomate","1 cebolla picada","2 zanahorias en trozos","1 berenjena en trozos","¼ repollo en gajos","3 cdas perejil fresco picado","2 dientes de ajo"]},"steps":{"en":["Soften the onion, add tomato paste and 6 cups water; simmer the vegetables 20 min and lift out.","Stuff slits in the fish with parsley and garlic; poach in the broth 10 min and lift out.","Cook the rice in 4 cups of the broth for 20 min; serve with fish and vegetables on top."],"es":["Rehogá la cebolla, sumá el extracto y 6 tazas de agua; cociná las verduras 20 min y sacalas.","Rellená cortes en el pescado con perejil y ajo; cocinalo en el caldo 10 min y sacalo.","Cociná el arroz en 4 tazas del caldo 20 min; serví con el pescado y las verduras encima."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"yassa-poulet","type":"dinner","country":"SN","protein":"poultry","base":"rice","name":{"en":"Yassa Poulet (Lemon-Onion Chicken)","es":"Yassa de pollo: pollo al limón con cebolla"},"ing":{"en":["1 kg chicken thighs","4 onions, sliced","3 lemons","2 tbsp Dijon mustard","2 garlic cloves, minced","¼ cup green olives","1½ cups rice"],"es":["1 kg muslos de pollo","4 cebollas en pluma","3 limones","2 cdas mostaza Dijon","2 dientes de ajo picados","¼ taza aceitunas verdes","1½ tazas arroz"]},"steps":{"en":["Marinate the chicken and onions in lemon juice, mustard and garlic for 2 hours.","Grill or roast the chicken at 220°C for 25 min; cook the onions slowly in the marinade for 20 min.","Add chicken and olives to the onions for 10 min; serve with rice."],"es":["Mariná el pollo y la cebolla con jugo de limón, mostaza y ajo 2 horas.","Asá el pollo a 220°C 25 min; cociná la cebolla despacio en la marinada 20 min.","Sumá el pollo y las aceitunas a la cebolla 10 min; serví con arroz."]},"tip":{"en":"","es":""},"prep":["marinate"]},
{"id":"mafe","type":"lunch","country":"SN","protein":"beef","base":"rice","tags":["stew"],"name":{"en":"Mafé (Peanut Stew) with Rice","es":"Mafé: guiso de maní con arroz"},"ing":{"en":["500 g beef chuck, diced","½ cup peanut butter","1 can crushed tomatoes","1 onion, chopped","2 sweet potatoes, diced","2 carrots, diced","1 cup beef broth","1½ cups rice"],"es":["500 g carne para guiso en cubos","½ taza mantequilla de maní","1 lata tomate triturado","1 cebolla picada","2 batatas en cubos","2 zanahorias en cubos","1 taza caldo de carne","1½ tazas arroz"]},"steps":{"en":["Brown the beef with the onion.","Add tomatoes, broth and peanut butter whisked in; simmer 1 hour.","Add sweet potato and carrots for 25 min; serve with rice."],"es":["Dorá la carne con la cebolla.","Sumá el tomate, el caldo y la mantequilla de maní batida; cociná 1 hora.","Agregá la batata y la zanahoria 25 min; serví con arroz."]},"tip":{"en":"","es":""},"prep":["cook-ahead"]},
{"id":"red-red","type":"lunch","country":"GH","protein":"plant","base":"none","tags":["stew"],"name":{"en":"Red Red (Black-Eyed Bean Stew) with Fried Plantain","es":"Red red: guiso de porotos tape con plátano frito"},"ing":{"en":["2 cans black-eyed or white beans, drained","1 onion, chopped","1 can crushed tomatoes","1 tbsp fresh ginger, grated","1 tsp paprika","3 tbsp sunflower oil","3 ripe plantains"],"es":["2 latas porotos tape o blancos escurridos","1 cebolla picada","1 lata tomate triturado","1 cda jengibre fresco rallado","1 cdita pimentón","3 cdas aceite de girasol","3 plátanos maduros"]},"steps":{"en":["Soften onion and ginger in the oil with paprika; add tomatoes and simmer 10 min.","Add the beans and cook 10 min.","Fry plantain slices until caramelised and serve alongside."],"es":["Rehogá la cebolla y el jengibre en el aceite con el pimentón; sumá el tomate y cociná 10 min.","Agregá los porotos y cociná 10 min.","Freí rodajas de plátano hasta caramelizar y serví al lado."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"kelewele","type":"snack","country":"GH","group":"fruit","name":{"en":"Kelewele (Spiced Plantain Bites)","es":"Kelewele: bocaditos de plátano especiados"},"ing":{"en":["3 ripe plantains, diced","1 tbsp fresh ginger, grated","¼ tsp nutmeg","2 tbsp sunflower oil","2 tbsp peanuts, chopped (optional)"],"es":["3 plátanos maduros en cubos","1 cda jengibre fresco rallado","¼ cdita nuez moscada","2 cdas aceite de girasol","2 cdas maní picado (opcional)"]},"steps":{"en":["Toss plantain with ginger, nutmeg and a pinch of salt.","Pan-fry in the oil until golden on all sides.","Serve warm with peanuts for older kids."],"es":["Mezclá el plátano con el jengibre, la nuez moscada y una pizca de sal.","Dorá en el aceite por todos lados.","Serví tibio con maní para los más grandes."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"ghana-light-soup","type":"dinner","country":"GH","protein":"poultry","base":"none","tags":["soup"],"name":{"en":"Light Soup with Chicken","es":"Light soup: sopa liviana de pollo"},"ing":{"en":["1 kg chicken thighs","4 tomatoes","1 onion","1 tbsp fresh ginger, grated","2 garlic cloves","1 eggplant, in chunks","600 g cassava (yuca), in chunks"],"es":["1 kg muslos de pollo","4 tomates","1 cebolla","1 cda jengibre fresco rallado","2 dientes de ajo","1 berenjena en trozos","600 g mandioca en trozos"]},"steps":{"en":["Simmer the chicken with ginger and garlic in 6 cups water for 15 min.","Boil the tomatoes, onion and eggplant in the pot 10 min, lift out, blend and return.","Simmer 20 min more; serve with boiled cassava."],"es":["Cociná el pollo con el jengibre y el ajo en 6 tazas de agua 15 min.","Herví los tomates, la cebolla y la berenjena en la olla 10 min, sacalos, licualos y volvelos a poner.","Cociná 20 min más; serví con mandioca hervida."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"waakye","type":"lunch","country":"GH","protein":"plant","base":"rice","name":{"en":"Waakye (Rice & Beans) with Egg, Salad & Shito-Style Pepper Sauce","es":"Waakye: arroz con porotos, huevo y ensalada"},"ing":{"en":["1½ cups rice","1 can kidney beans, with liquid","4 eggs","1 head lettuce","2 tomatoes","2 tbsp tomato paste","1 onion, chopped","1 tsp paprika"],"es":["1½ tazas arroz","1 lata porotos colorados con su líquido","4 huevos","1 planta de lechuga","2 tomates","2 cdas extracto de tomate","1 cebolla picada","1 cdita pimentón"]},"steps":{"en":["Cook the rice with the beans and their liquid plus 2 cups water for 20 min.","Fry the onion with tomato paste and paprika into a thick sauce.","Serve with boiled eggs, salad and the sauce."],"es":["Cociná el arroz con los porotos y su líquido más 2 tazas de agua 20 min.","Freí la cebolla con el extracto y el pimentón hasta tener una salsa espesa.","Serví con huevos duros, ensalada y la salsa."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"pilau-ya-nyama","type":"dinner","country":"TZ","protein":"beef","base":"rice","name":{"en":"Pilau ya Nyama (Spiced Beef Pilau) with Kachumbari","es":"Pilau de carne con kachumbari"},"ing":{"en":["500 g beef chuck, diced","2 cups basmati rice","2 onions, sliced","1 tsp ground cumin","1 cinnamon stick","½ tsp ground cardamom","3 garlic cloves, minced","2 tomatoes, diced","1 red onion, finely chopped"],"es":["500 g carne para guiso en cubos","2 tazas arroz basmati","2 cebollas en pluma","1 cdita comino","1 rama de canela","½ cdita cardamomo molido","3 dientes de ajo picados","2 tomates en cubitos","1 cebolla morada picada fina"]},"steps":{"en":["Simmer the beef in 4 cups water for 1 hour; keep the broth.","Brown the onions deeply, add garlic, spices, beef and rice; pour in 3 cups broth, cover and cook 20 min.","Mix tomato and red onion with lime or lemon for kachumbari."],"es":["Cociná la carne en 4 tazas de agua 1 hora; guardá el caldo.","Dorá bien la cebolla, sumá el ajo, las especias, la carne y el arroz; volcá 3 tazas de caldo, tapá y cociná 20 min.","Mezclá el tomate y la cebolla morada con lima o limón para el kachumbari."]},"tip":{"en":"","es":""},"prep":["cook-ahead"]},
{"id":"mchuzi-wa-samaki","type":"dinner","country":"TZ","protein":"fish","base":"rice","tags":["curry"],"name":{"en":"Mchuzi wa Samaki (Coconut Fish Curry)","es":"Mchuzi wa samaki: curry de pescado con coco"},"ing":{"en":["700 g white fish fillets, in chunks","1 can coconut milk","1 onion, chopped","2 tomatoes, chopped","1 tbsp curry powder","1 tsp turmeric","1 lime","1½ cups rice"],"es":["700 g filet de pescado blanco en trozos","1 lata leche de coco","1 cebolla picada","2 tomates picados","1 cda curry en polvo","1 cdita cúrcuma","1 lima","1½ tazas arroz"]},"steps":{"en":["Soften onion with curry and turmeric; add tomatoes and cook 5 min.","Pour in coconut milk and simmer 5 min; add the fish and cook 8 min.","Finish with lime; serve with rice."],"es":["Rehogá la cebolla con el curry y la cúrcuma; sumá el tomate y cociná 5 min.","Volcá la leche de coco y cociná 5 min; agregá el pescado y cociná 8 min.","Terminá con lima; serví con arroz."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"rolex-chapati","type":"breakfast","country":"UG","group":"egg","tags":["tortilla"],"name":{"en":"Rolex (Chapati Rolled with Vegetable Omelette)","es":"Rolex: chapati enrollado con omelette de verduras"},"ing":{"en":["2 cups flour","¾ cup warm water","2 tbsp sunflower oil","6 eggs","1 tomato, diced","¼ cabbage, finely shredded","1 onion, finely chopped"],"es":["2 tazas harina","¾ taza agua tibia","2 cdas aceite de girasol","6 huevos","1 tomate en cubitos","¼ repollo en juliana fina","1 cebolla picada fina"]},"steps":{"en":["Knead flour, water, oil and salt; rest 20 min, then roll thin rounds and cook 1 min a side.","Beat eggs with tomato, cabbage and onion; cook thin omelettes.","Lay each omelette on a chapati and roll up."],"es":["Amasá la harina, el agua, el aceite y sal; dejá reposar 20 min, estirá círculos finos y cociná 1 min por lado.","Batí los huevos con el tomate, el repollo y la cebolla; cociná omelettes finas.","Poné cada omelette sobre un chapati y enrollá."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"groundnut-chicken-stew","type":"dinner","country":"UG","protein":"poultry","base":"rice","tags":["stew"],"name":{"en":"Groundnut (Peanut) Chicken Stew with Rice","es":"Guiso de pollo con maní y arroz"},"ing":{"en":["1 kg chicken thighs","½ cup peanut butter","1 onion, chopped","3 tomatoes, chopped","2 cups spinach","2 cups chicken broth","1½ cups rice"],"es":["1 kg muslos de pollo","½ taza mantequilla de maní","1 cebolla picada","3 tomates picados","2 tazas espinaca","2 tazas caldo de pollo","1½ tazas arroz"]},"steps":{"en":["Brown the chicken with the onion; add tomatoes and broth and simmer 20 min.","Whisk in the peanut butter and simmer 15 min, stirring.","Stir in spinach; serve with rice."],"es":["Dorá el pollo con la cebolla; sumá el tomate y el caldo y cociná 20 min.","Incorporá la mantequilla de maní batiendo y cociná 15 min, revolviendo.","Sumá la espinaca; serví con arroz."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"poulet-dg","type":"dinner","country":"CM","protein":"poultry","base":"none","name":{"en":"Poulet DG (Chicken with Plantains & Vegetables)","es":"Poulet DG: pollo con plátanos y verduras"},"ing":{"en":["1 kg chicken thighs","3 ripe plantains, in chunks","2 carrots, sliced","2 bell peppers, sliced","300 g green beans","2 tomatoes, chopped","1 onion, sliced","1 tbsp fresh ginger, grated"],"es":["1 kg muslos de pollo","3 plátanos maduros en trozos","2 zanahorias en rodajas","2 morrones en tiras","300 g chauchas","2 tomates picados","1 cebolla en pluma","1 cda jengibre fresco rallado"]},"steps":{"en":["Brown the chicken with ginger; fry the plantain chunks until golden.","Cook onion, tomato, carrots, beans and peppers 10 min; add chicken and ½ cup water and simmer 20 min.","Fold in the plantains and serve."],"es":["Dorá el pollo con el jengibre; freí los trozos de plátano hasta dorar.","Cociná la cebolla, el tomate, las zanahorias, las chauchas y los morrones 10 min; sumá el pollo y ½ taza de agua y cociná 20 min.","Incorporá los plátanos y serví."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"kefta-tagine","type":"dinner","country":"MA","protein":"beef","base":"bread","tags":["meatballs"],"name":{"en":"Kefta Tagine (Meatballs & Eggs in Tomato) with Bread","es":"Tajín de kefta: albóndigas y huevos en tomate con pan"},"ing":{"en":["500 g ground beef","1 onion, grated","1 tsp ground cumin","1 tsp paprika","2 cans crushed tomatoes","4 eggs","3 tbsp fresh cilantro, chopped","1 baguette"],"es":["500 g carne picada","1 cebolla rallada","1 cdita comino","1 cdita pimentón","2 latas tomate triturado","4 huevos","3 cdas cilantro fresco picado","1 baguette"]},"steps":{"en":["Mix beef, onion and half the spices; roll small balls.","Simmer the tomatoes with the rest of the spices 10 min; add the meatballs and cook 15 min.","Crack in the eggs, cover until set; finish with cilantro and serve with bread."],"es":["Mezclá la carne, la cebolla y la mitad de las especias; formá bolitas.","Cociná el tomate con el resto de las especias 10 min; sumá las albóndigas y cociná 15 min.","Rompé los huevos encima, tapá hasta que cuajen; terminá con cilantro y serví con pan."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"msemen","type":"breakfast","country":"MA","group":"grain","name":{"en":"Msemen (Square Pancakes) with Honey & Mint Tea for Grown-Ups","es":"Msemen con miel (y té de menta para los grandes)"},"ing":{"en":["2 cups flour","½ cup fine semolina or flour","¾ cup warm water","50 g butter, melted","2 tbsp honey","1 handful fresh mint","2 cups milk"],"es":["2 tazas harina","½ taza sémola fina o harina","¾ taza agua tibia","50 g manteca derretida","2 cdas miel","1 puñado de menta fresca","2 tazas leche"]},"steps":{"en":["Knead flour, semolina, water and salt; rest 20 min.","Stretch thin, brush with butter, fold into squares and cook in a pan 3 min a side.","Serve with honey and warm milk; steep mint for the grown-ups' tea."],"es":["Amasá la harina, la sémola, el agua y sal; dejá reposar 20 min.","Estirá fino, pincelá con manteca, doblá en cuadrados y cociná en sartén 3 min por lado.","Serví con miel y leche tibia; prepará té de menta para los grandes."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"zaalouk","type":"snack","country":"MA","group":"veg","name":{"en":"Zaalouk (Smoky Eggplant & Tomato Dip) with Bread","es":"Zaalouk: dip de berenjena y tomate con pan"},"ing":{"en":["2 eggplants","3 tomatoes, chopped","2 garlic cloves, minced","1 tsp ground cumin","1 tsp paprika","3 tbsp olive oil","2 pita breads"],"es":["2 berenjenas","3 tomates picados","2 dientes de ajo picados","1 cdita comino","1 cdita pimentón","3 cdas aceite de oliva","2 panes pita"]},"steps":{"en":["Roast the eggplants whole at 220°C for 35 min; scoop out the flesh.","Cook tomato, garlic and spices in the oil 10 min, add the eggplant and mash 5 min more.","Serve warm or cold with pita."],"es":["Asá las berenjenas enteras a 220°C 35 min; sacá la pulpa.","Cociná el tomate, el ajo y las especias en el aceite 10 min, sumá la berenjena y pisá 5 min más.","Serví tibio o frío con pita."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"hawawshi","type":"lunch","country":"EG","protein":"beef","base":"bread","name":{"en":"Hawawshi (Spiced Beef Baked in Pita) with Salad","es":"Hawawshi: pita rellena de carne especiada con ensalada"},"ing":{"en":["500 g ground beef","1 onion, grated","1 green bell pepper, finely chopped","1 tsp ground cumin","1 tsp paprika","4 pita breads","2 tomatoes","1 cucumber"],"es":["500 g carne picada","1 cebolla rallada","1 morrón verde picado fino","1 cdita comino","1 cdita pimentón","4 panes pita","2 tomates","1 pepino"]},"steps":{"en":["Mix beef, onion, pepper and spices.","Open the pitas, spread the filling thinly inside and press closed; brush with oil.","Bake at 220°C for 15 min; serve with tomato and cucumber salad."],"es":["Mezclá la carne, la cebolla, el morrón y las especias.","Abrí las pitas, untá el relleno en capa fina adentro y cerrá apretando; pincelá con aceite.","Horneá a 220°C 15 min; serví con ensalada de tomate y pepino."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"eggah","type":"breakfast","country":"EG","group":"egg","name":{"en":"Eggah (Herb & Leek Omelette Cake) with Bread","es":"Eggah: tortilla gruesa de hierbas y puerro con pan"},"ing":{"en":["8 eggs","1 leek, finely sliced","4 tbsp fresh parsley, chopped","2 tbsp fresh dill, chopped","1 tsp ground cumin","2 tbsp butter","4 pita breads"],"es":["8 huevos","1 puerro en rodajas finas","4 cdas perejil fresco picado","2 cdas eneldo fresco picado","1 cdita comino","2 cdas manteca","4 panes pita"]},"steps":{"en":["Soften the leek in the butter.","Beat the eggs with herbs, cumin and salt; pour over and cook covered on low 12 min.","Cut in wedges; serve with pita."],"es":["Rehogá el puerro en la manteca.","Batí los huevos con las hierbas, el comino y sal; volcá encima y cociná tapado a fuego bajo 12 min.","Cortá en porciones; serví con pita."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"beef-tibs","type":"dinner","country":"ET","protein":"beef","base":"bread","name":{"en":"Tibs (Sautéed Beef with Peppers & Rosemary)","es":"Tibs: carne salteada con morrones y romero"},"ing":{"en":["600 g beef sirloin, in cubes","1 onion, sliced","2 green bell peppers, sliced","1 sprig fresh rosemary","2 garlic cloves, minced","1 tbsp berbere spice (or paprika)","2 tbsp butter","4 flatbreads (injera or pita)"],"es":["600 g lomo en cubos","1 cebolla en pluma","2 morrones verdes en tiras","1 rama de romero fresco","2 dientes de ajo picados","1 cda especia berbere (o pimentón)","2 cdas manteca","4 panes planos (injera o pita)"]},"steps":{"en":["Sear the beef in butter over high heat for 3 min.","Add onion, peppers, garlic, rosemary and berbere and stir-fry 5 min.","Serve with flatbread."],"es":["Saltá la carne en manteca a fuego fuerte 3 min.","Sumá la cebolla, los morrones, el ajo, el romero y el berbere y saltá 5 min.","Serví con pan plano."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"shiro","type":"lunch","country":"ET","protein":"plant","base":"bread","tags":["stew"],"name":{"en":"Shiro (Spiced Chickpea Flour Stew) with Flatbread","es":"Shiro: guiso de harina de garbanzo con pan plano"},"ing":{"en":["1 cup chickpea flour","1 onion, finely chopped","2 garlic cloves, minced","1 tbsp berbere spice (or paprika)","2 tomatoes, chopped","3 tbsp olive oil","4 flatbreads (injera or pita)"],"es":["1 taza harina de garbanzo","1 cebolla picada fina","2 dientes de ajo picados","1 cda especia berbere (o pimentón)","2 tomates picados","3 cdas aceite de oliva","4 panes planos (injera o pita)"]},"steps":{"en":["Soften onion and garlic in the oil; add tomato and berbere.","Whisk in the chickpea flour with 3 cups water and simmer 15 min, stirring, until smooth and thick.","Serve with flatbread."],"es":["Rehogá la cebolla y el ajo en el aceite; sumá el tomate y el berbere.","Incorporá la harina de garbanzo con 3 tazas de agua batiendo y cociná 15 min, revolviendo, hasta que quede liso y espeso.","Serví con pan plano."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"nigerian-fish-pepper-soup","type":"dinner","country":"NG","protein":"fish","base":"none","tags":["soup"],"name":{"en":"Fish Pepper Soup with Boiled Sweet Potato","es":"Sopa picante de pescado con batata hervida"},"ing":{"en":["700 g firm white fish fillets","1 onion, chopped","2 tomatoes, chopped","1 tbsp fresh ginger, grated","1 tsp curry powder","½ tsp chili flakes (optional)","2 tbsp fresh basil or mint","4 sweet potatoes"],"es":["700 g filet de pescado blanco firme","1 cebolla picada","2 tomates picados","1 cda jengibre fresco rallado","1 cdita curry en polvo","½ cdita ají en hojuelas (opcional)","2 cdas albahaca o menta fresca","4 batatas"]},"steps":{"en":["Simmer onion, tomato, ginger and spices in 6 cups water for 15 min.","Add the fish and poach 10 min; finish with the herbs.","Serve with boiled sweet potatoes."],"es":["Cociná la cebolla, el tomate, el jengibre y las especias en 6 tazas de agua 15 min.","Sumá el pescado y cociná 10 min; terminá con las hierbas.","Serví con batatas hervidas."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"chin-chin","type":"snack","country":"NG","group":"grain","tags":["cookies"],"name":{"en":"Chin Chin (Crunchy Nutmeg Dough Bites)","es":"Chin chin: bocaditos crocantes de masa con nuez moscada"},"ing":{"en":["2 cups flour","¼ cup sugar","50 g butter","1 egg","¼ cup milk","¼ tsp nutmeg"],"es":["2 tazas harina","¼ taza azúcar","50 g manteca","1 huevo","¼ taza leche","¼ cdita nuez moscada"]},"steps":{"en":["Rub butter into flour, sugar and nutmeg; add egg and milk to a firm dough.","Roll 5 mm thick and cut small cubes.","Bake at 180°C for 18 min, shaking once, until golden and crunchy."],"es":["Desmenuzá la manteca con la harina, el azúcar y la nuez moscada; sumá el huevo y la leche hasta tener una masa firme.","Estirá de 5 mm y cortá cubitos.","Horneá a 180°C 18 min, moviendo una vez, hasta que estén dorados y crocantes."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"sweet-potato-pottage","type":"lunch","country":"NG","protein":"plant","base":"potato","tags":["stew"],"name":{"en":"Sweet Potato Pottage (Asaro-Style) with Spinach","es":"Guiso de batata al estilo asaro con espinaca"},"ing":{"en":["1 kg sweet potatoes, diced","1 onion, chopped","2 tomatoes, chopped","1 red bell pepper, chopped","2 tbsp sunflower oil","3 cups spinach","1 can white beans, drained"],"es":["1 kg batatas en cubos","1 cebolla picada","2 tomates picados","1 morrón rojo picado","2 cdas aceite de girasol","3 tazas espinaca","1 lata porotos blancos escurridos"]},"steps":{"en":["Blend tomato, pepper and onion; fry in the oil 10 min.","Add sweet potato and 2 cups water and simmer 20 min until some breaks down.","Stir in beans and spinach for 5 min."],"es":["Licuá el tomate, el morrón y la cebolla; freí en el aceite 10 min.","Sumá la batata y 2 tazas de agua y cociná 20 min, hasta que parte se deshaga.","Incorporá los porotos y la espinaca 5 min."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"boerewors-chakalaka-pap","type":"dinner","country":"ZA","protein":"beef","base":"grain","tags":["sausages"],"name":{"en":"Beef Sausage with Chakalaka & Pap","es":"Salchicha de carne con chakalaka y pap"},"ing":{"en":["600 g beef sausages","1 onion, chopped","2 carrots, grated","1 red bell pepper, diced","1 can baked beans","1 tsp curry powder","2 cups fine cornmeal"],"es":["600 g salchichas de carne","1 cebolla picada","2 zanahorias ralladas","1 morrón rojo en cubitos","1 lata porotos en salsa de tomate","1 cdita curry en polvo","2 tazas harina de maíz fina"]},"steps":{"en":["Grill or bake the sausages at 200°C for 25 min.","Fry onion, carrot, pepper and curry 8 min; add baked beans and simmer 5 min (chakalaka).","Stir the cornmeal into 5 cups boiling water and cook 15 min into a soft pap."],"es":["Cociná las salchichas a la parrilla o al horno a 200°C 25 min.","Saltá la cebolla, la zanahoria, el morrón y el curry 8 min; sumá los porotos y cociná 5 min (chakalaka).","Volcá la harina de maíz en 5 tazas de agua hirviendo y cociná 15 min hasta tener un pap blando."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"melktert","type":"snack","country":"ZA","group":"dairy","tags":["tart"],"name":{"en":"Melktert (Cinnamon Milk Tart)","es":"Melktert: tarta de leche con canela"},"ing":{"en":["1 pie crust","3 cups milk","3 tbsp cornstarch","2 tbsp flour","⅓ cup sugar","2 eggs","1 tsp vanilla extract","1 tsp cinnamon"],"es":["1 tapa de tarta","3 tazas leche","3 cdas maicena","2 cdas harina","⅓ taza azúcar","2 huevos","1 cdita esencia de vainilla","1 cdita canela"]},"steps":{"en":["Bake the crust blind at 200°C for 15 min.","Cook milk, cornstarch, flour, sugar and eggs, stirring, until thick; add vanilla.","Pour into the crust, dust with cinnamon and chill 2 hours."],"es":["Precociná la masa a 200°C 15 min.","Cociná la leche con la maicena, la harina, el azúcar y los huevos, revolviendo, hasta que espese; sumá la vainilla.","Volcá en la masa, espolvoreá con canela y enfriá 2 horas."]},"tip":{"en":"","es":""},"prep":["chill-ahead"]},
{"id":"sukuma-wiki-eggs","type":"breakfast","country":"KE","group":"egg","name":{"en":"Sukuma Wiki (Greens) with Eggs & Chapati","es":"Sukuma wiki: verdes salteados con huevo y chapati"},"ing":{"en":["1 bunch kale, shredded","1 onion, chopped","2 tomatoes, chopped","4 eggs","4 flour tortillas","1 tbsp sunflower oil"],"es":["1 atado de kale en tiras","1 cebolla picada","2 tomates picados","4 huevos","4 tortillas de harina","1 cda aceite de girasol"]},"steps":{"en":["Soften the onion in oil, add tomatoes and cook 5 min.","Add the greens and cook 5 min until tender.","Serve with fried eggs and warm chapati (or tortillas)."],"es":["Rehogá la cebolla en aceite, sumá el tomate y cociná 5 min.","Agregá los verdes y cociná 5 min, hasta que estén tiernos.","Serví con huevos fritos y chapati tibio (o tortillas)."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"chapati-na-maharagwe","type":"lunch","country":"KE","protein":"plant","base":"bread","tags":["stew"],"name":{"en":"Chapati na Maharagwe (Coconut Bean Stew with Chapati)","es":"Chapati con guiso de porotos y coco"},"ing":{"en":["2 cans kidney beans, drained","1 can coconut milk","1 onion, chopped","2 tomatoes, chopped","1 tsp curry powder","8 flour tortillas","2 tbsp fresh cilantro, chopped"],"es":["2 latas porotos colorados escurridos","1 lata leche de coco","1 cebolla picada","2 tomates picados","1 cdita curry en polvo","8 tortillas de harina","2 cdas cilantro fresco picado"]},"steps":{"en":["Soften the onion with the curry; add tomatoes.","Add beans and coconut milk and simmer 15 min.","Finish with cilantro; serve with warm chapati (or tortillas)."],"es":["Rehogá la cebolla con el curry; sumá el tomate.","Agregá los porotos y la leche de coco y cociná 15 min.","Terminá con cilantro; serví con chapati tibio (o tortillas)."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"karniyarik","type":"dinner","country":"TR","protein":"beef","base":"rice","name":{"en":"Karnıyarık (Beef-Stuffed Eggplant) with Rice","es":"Karnıyarık: berenjenas rellenas de carne con arroz"},"ing":{"en":["4 eggplants","400 g ground beef","1 onion, chopped","2 tomatoes, chopped","1 green bell pepper, chopped","2 tbsp tomato paste","3 tbsp fresh parsley, chopped","1½ cups rice"],"es":["4 berenjenas","400 g carne picada","1 cebolla picada","2 tomates picados","1 morrón verde picado","2 cdas extracto de tomate","3 cdas perejil fresco picado","1½ tazas arroz"]},"steps":{"en":["Peel the eggplants in stripes, slit lengthwise and roast at 220°C for 20 min.","Brown the beef with onion, pepper and tomato; add parsley.","Fill the eggplants, pour tomato paste mixed with 1 cup water around and bake 20 min; serve with rice."],"es":["Pelá las berenjenas a rayas, abrilas a lo largo y asalas a 220°C 20 min.","Dorá la carne con la cebolla, el morrón y el tomate; sumá el perejil.","Rellená las berenjenas, volcá alrededor el extracto con 1 taza de agua y horneá 20 min; serví con arroz."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"manti","type":"dinner","country":"TR","protein":"beef","base":"pasta","tags":["ravioli"],"name":{"en":"Mantı (Tiny Beef Dumplings with Garlic Yogurt)","es":"Mantı: mini empanaditas de carne con yogur al ajo"},"ing":{"en":["30 dumpling wrappers","300 g ground beef","1 onion, grated","2 cups plain yogurt","1 garlic clove, minced","2 tbsp butter","1 tsp paprika","1 tsp dried mint"],"es":["30 tapitas para dumplings","300 g carne picada","1 cebolla rallada","2 tazas yogur natural","1 diente de ajo picado","2 cdas manteca","1 cdita pimentón","1 cdita menta seca"]},"steps":{"en":["Mix beef and onion; fill the wrappers and pinch closed.","Boil 6 min after they float.","Serve with garlic yogurt and butter melted with paprika and mint."],"es":["Mezclá la carne con la cebolla; rellená las tapitas y cerralas.","Herví 6 min desde que flotan.","Serví con yogur al ajo y manteca derretida con pimentón y menta."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"gozleme","type":"lunch","country":"TR","protein":"plant","base":"bread","name":{"en":"Gözleme (Spinach & Feta Flatbreads)","es":"Gözleme: panes rellenos de espinaca y feta"},"ing":{"en":["2 cups flour","¾ cup warm water","3 cups spinach, chopped","200 g feta cheese, crumbled","1 onion, finely chopped","2 tbsp butter, melted","1 lemon"],"es":["2 tazas harina","¾ taza agua tibia","3 tazas espinaca picada","200 g queso feta desmenuzado","1 cebolla picada fina","2 cdas manteca derretida","1 limón"]},"steps":{"en":["Knead flour, water and salt; rest 20 min.","Roll thin rounds, fill half with spinach, feta and onion and fold.","Cook on a dry pan 3 min a side, brushing with butter; serve with lemon."],"es":["Amasá la harina con el agua y sal; dejá reposar 20 min.","Estirá círculos finos, rellená la mitad con espinaca, feta y cebolla y doblá.","Cociná en sartén seca 3 min por lado pincelando con manteca; serví con limón."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"kafta-bil-sayniyeh","type":"dinner","country":"LB","protein":"beef","base":"potato","name":{"en":"Kafta bil Sayniyeh (Kafta, Potato & Tomato Bake)","es":"Kafta al horno con papas y tomate"},"ing":{"en":["600 g ground beef","1 onion, grated","4 tbsp fresh parsley, chopped","1 tsp allspice or cumin","3 potatoes, sliced","3 tomatoes, sliced","2 tbsp tomato paste","1 cup plain yogurt"],"es":["600 g carne picada","1 cebolla rallada","4 cdas perejil fresco picado","1 cdita pimienta de Jamaica o comino","3 papas en rodajas","3 tomates en rodajas","2 cdas extracto de tomate","1 taza yogur natural"]},"steps":{"en":["Mix beef, onion, parsley and spice; press into a dish.","Bake at 200°C for 15 min; cover with fried or roasted potato and tomato slices.","Pour over tomato paste mixed with 1 cup water and bake 25 min; serve with yogurt."],"es":["Mezclá la carne, la cebolla, el perejil y la especia; aplastala en una fuente.","Horneá a 200°C 15 min; cubrí con rodajas de papa frita o asada y tomate.","Bañá con el extracto disuelto en 1 taza de agua y horneá 25 min; serví con yogur."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"fatayer-sabanekh","type":"snack","country":"LB","group":"veg","name":{"en":"Fatayer (Spinach Triangles)","es":"Fatayer: triangulitos de espinaca"},"ing":{"en":["300 g pizza dough","3 cups spinach, chopped","1 onion, finely chopped","1 lemon","1 tsp sumac (optional)","2 tbsp olive oil"],"es":["300 g masa de pizza","3 tazas espinaca picada","1 cebolla picada fina","1 limón","1 cdita zumaque (opcional)","2 cdas aceite de oliva"]},"steps":{"en":["Salt the spinach 10 min, squeeze dry and mix with onion, lemon, sumac and oil.","Cut small rounds of dough, fill and pinch into triangles.","Bake at 220°C for 15 min."],"es":["Salá la espinaca 10 min, escurrila y mezclala con la cebolla, el limón, el zumaque y el aceite.","Cortá círculos chicos de masa, rellená y cerrá formando triángulos.","Horneá a 220°C 15 min."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"ptitim-salad","type":"lunch","country":"IL","protein":"plant","base":"grain","name":{"en":"Pearl Couscous Salad with Chickpeas, Cucumber & Herbs","es":"Ensalada de cuscús perlado con garbanzos, pepino y hierbas"},"ing":{"en":["1½ cups pearl couscous or orzo","1 can chickpeas, drained","1 cucumber, diced","1 cup cherry tomatoes, halved","4 tbsp fresh parsley, chopped","2 tbsp fresh mint, chopped","1 lemon","3 tbsp olive oil","100 g feta cheese"],"es":["1½ tazas cuscús perlado o risoni","1 lata garbanzos escurridos","1 pepino en cubos","1 taza tomates cherry en mitades","4 cdas perejil fresco picado","2 cdas menta fresca picada","1 limón","3 cdas aceite de oliva","100 g queso feta"]},"steps":{"en":["Cook the couscous 8 min; drain and cool.","Toss with chickpeas, cucumber, tomatoes and herbs.","Dress with lemon and oil; crumble feta over."],"es":["Cociná el cuscús 8 min; escurrí y enfriá.","Mezclá con los garbanzos, el pepino, los tomates y las hierbas.","Condimentá con limón y aceite; desmenuzá el feta por encima."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"fesenjan","type":"dinner","country":"IR","protein":"poultry","base":"rice","tags":["stew"],"name":{"en":"Fesenjan (Walnut & Pomegranate Chicken)","es":"Fesenjan: pollo con nueces y granada"},"ing":{"en":["1 kg chicken thighs","1½ cups walnuts, ground","1 cup pomegranate juice","1 onion, chopped","1 tsp cinnamon","1 tbsp honey","1½ cups basmati rice"],"es":["1 kg muslos de pollo","1½ tazas nueces molidas","1 taza jugo de granada","1 cebolla picada","1 cdita canela","1 cda miel","1½ tazas arroz basmati"]},"steps":{"en":["Toast the ground walnuts in a dry pan 5 min.","Brown the chicken with the onion; add walnuts, pomegranate juice, cinnamon and 1 cup water and simmer 45 min.","Balance with honey; serve with rice."],"es":["Tostá las nueces molidas en una sartén seca 5 min.","Dorá el pollo con la cebolla; sumá las nueces, el jugo de granada, la canela y 1 taza de agua y cociná 45 min.","Equilibrá con miel; serví con arroz."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"adasi","type":"breakfast","country":"IR","group":"grain","name":{"en":"Adasi (Lentil Breakfast Stew) with Bread & Yogurt","es":"Adasi: guiso de lentejas para el desayuno con pan y yogur"},"ing":{"en":["1 cup lentils (dry)","1 onion, chopped","1 tsp turmeric","1 tsp ground cumin","1 tbsp butter","4 pita breads","1 cup plain yogurt"],"es":["1 taza lentejas secas","1 cebolla picada","1 cdita cúrcuma","1 cdita comino","1 cda manteca","4 panes pita","1 taza yogur natural"]},"steps":{"en":["Soften the onion in the butter with the spices.","Add lentils and 4 cups water and simmer 30 min until thick.","Serve with warm bread and yogurt."],"es":["Rehogá la cebolla en la manteca con las especias.","Sumá las lentejas y 4 tazas de agua y cociná 30 min, hasta que espese.","Serví con pan tibio y yogur."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"kashk-e-bademjan","type":"snack","country":"IR","group":"veg","name":{"en":"Kashk-e Bademjan (Eggplant & Yogurt Dip) with Pita","es":"Kashk-e bademjan: dip de berenjena y yogur con pita"},"ing":{"en":["2 eggplants, diced","1 onion, sliced","2 garlic cloves, minced","½ cup plain yogurt","1 tsp dried mint","3 tbsp olive oil","2 pita breads"],"es":["2 berenjenas en cubos","1 cebolla en pluma","2 dientes de ajo picados","½ taza yogur natural","1 cdita menta seca","3 cdas aceite de oliva","2 panes pita"]},"steps":{"en":["Fry the eggplant in the oil 15 min until soft; mash.","Fry the onion until golden and the garlic with mint for 1 min.","Mix the eggplant with yogurt, top with the onion and serve with pita."],"es":["Freí la berenjena en el aceite 15 min, hasta que esté tierna; pisala.","Dorá la cebolla y el ajo con la menta 1 min.","Mezclá la berenjena con el yogur, poné la cebolla arriba y serví con pita."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"kabuli-pulao","type":"dinner","country":"AF","protein":"beef","base":"rice","name":{"en":"Kabuli Pulao (Rice with Lamb, Carrots & Raisins)","es":"Kabuli pulao: arroz con cordero, zanahoria y pasas"},"ing":{"en":["700 g lamb or beef stewing meat","2 cups basmati rice","2 onions, sliced","3 carrots, in thin sticks","½ cup raisins","1 tsp ground cumin","½ tsp ground cardamom","2 tbsp sunflower oil"],"es":["700 g cordero o carne para guiso","2 tazas arroz basmati","2 cebollas en pluma","3 zanahorias en bastones finos","½ taza pasas de uva","1 cdita comino","½ cdita cardamomo molido","2 cdas aceite de girasol"]},"steps":{"en":["Brown the onions and meat, add cumin and 4 cups water and simmer 1 hour.","Add the rice, cardamom and 2½ cups of the broth; cover and cook 20 min.","Fry the carrots in the oil until soft, add raisins for 1 min and pile over the rice."],"es":["Dorá la cebolla y la carne, sumá el comino y 4 tazas de agua y cociná 1 hora.","Agregá el arroz, el cardamomo y 2½ tazas del caldo; tapá y cociná 20 min.","Saltá las zanahorias en el aceite hasta que se ablanden, sumá las pasas 1 min y poné todo sobre el arroz."]},"tip":{"en":"","es":""},"prep":["cook-ahead"]},
{"id":"bolani","type":"lunch","country":"AF","protein":"plant","base":"bread","name":{"en":"Bolani (Potato & Spring Onion Stuffed Flatbreads) with Yogurt","es":"Bolani: panes rellenos de papa y verdeo con yogur"},"ing":{"en":["2 cups flour","¾ cup warm water","3 potatoes, boiled and mashed","4 spring onions, sliced","2 tbsp fresh cilantro, chopped","2 tbsp sunflower oil","1 cup plain yogurt","1 tbsp fresh mint, chopped"],"es":["2 tazas harina","¾ taza agua tibia","3 papas hervidas y pisadas","4 cebollas de verdeo en rodajas","2 cdas cilantro fresco picado","2 cdas aceite de girasol","1 taza yogur natural","1 cda menta fresca picada"]},"steps":{"en":["Knead flour, water and salt; rest 30 min.","Mix potato, spring onion and cilantro; fill thin rounds of dough and fold into half-moons.","Cook in a lightly oiled pan 3 min a side; serve with yogurt mixed with mint."],"es":["Amasá la harina con el agua y sal; dejá reposar 30 min.","Mezclá la papa, el verdeo y el cilantro; rellená círculos finos de masa y doblá en medialunas.","Cociná en sartén apenas aceitada 3 min por lado; serví con yogur con menta."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"chicken-karahi","type":"dinner","country":"PK","protein":"poultry","base":"bread","tags":["curry"],"name":{"en":"Chicken Karahi with Naan","es":"Karahi de pollo con naan"},"ing":{"en":["1 kg chicken thighs, in pieces","5 tomatoes, chopped","1 tbsp fresh ginger, grated","4 garlic cloves, minced","1 tsp ground cumin","1 tsp garam masala","½ cup plain yogurt","3 tbsp fresh cilantro, chopped","4 naan breads"],"es":["1 kg muslos de pollo en trozos","5 tomates picados","1 cda jengibre fresco rallado","4 dientes de ajo picados","1 cdita comino","1 cdita garam masala","½ taza yogur natural","3 cdas cilantro fresco picado","4 panes naan"]},"steps":{"en":["Brown the chicken over high heat with ginger and garlic.","Add tomatoes and spices and cook 20 min, stirring, until the tomatoes melt into a thick sauce.","Stir in yogurt and cilantro; serve with naan."],"es":["Dorá el pollo a fuego fuerte con el jengibre y el ajo.","Sumá el tomate y las especias y cociná 20 min, revolviendo, hasta tener una salsa espesa.","Incorporá el yogur y el cilantro; serví con naan."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"aloo-keema","type":"lunch","country":"PK","protein":"beef","base":"bread","name":{"en":"Aloo Keema (Spiced Beef & Potato) with Flatbread","es":"Aloo keema: carne picada especiada con papa y pan plano"},"ing":{"en":["500 g ground beef","2 potatoes, diced","1 onion, chopped","2 tomatoes, chopped","1 tbsp fresh ginger, grated","1 tsp garam masala","1 cup frozen peas","4 flour tortillas or chapati"],"es":["500 g carne picada","2 papas en cubos","1 cebolla picada","2 tomates picados","1 cda jengibre fresco rallado","1 cdita garam masala","1 taza arvejas congeladas","4 tortillas de harina o chapati"]},"steps":{"en":["Brown the onion and beef with ginger and garam masala.","Add tomatoes, potatoes and ½ cup water; cover and cook 20 min.","Add peas for 5 min; serve with warm flatbread."],"es":["Dorá la cebolla y la carne con el jengibre y el garam masala.","Sumá el tomate, las papas y ½ taza de agua; tapá y cociná 20 min.","Agregá las arvejas 5 min; serví con pan plano tibio."]},"tip":{"en":"","es":""},"prep":["brown-beef"]},
{"id":"anda-paratha","type":"breakfast","country":"PK","group":"egg","name":{"en":"Anda Paratha (Egg-Stuffed Flatbread)","es":"Anda paratha: pan plano relleno de huevo"},"ing":{"en":["2 cups wholemeal flour","¾ cup water","4 eggs","1 onion, finely chopped","2 tbsp fresh cilantro, chopped","2 tbsp butter"],"es":["2 tazas harina integral","¾ taza agua","4 huevos","1 cebolla picada fina","2 cdas cilantro fresco picado","2 cdas manteca"]},"steps":{"en":["Knead flour, water and salt; rest 15 min and roll 4 rounds.","Cook a paratha in butter 1 min, pour a beaten egg with onion and cilantro on top and fold over.","Cook 2 min a side until the egg sets."],"es":["Amasá la harina con el agua y sal; dejá reposar 15 min y estirá 4 círculos.","Cociná un paratha en manteca 1 min, volcá encima un huevo batido con cebolla y cilantro y doblalo.","Cociná 2 min por lado hasta que el huevo cuaje."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"khichuri","type":"lunch","country":"BD","protein":"plant","base":"rice","tags":["lentil"],"name":{"en":"Khichuri (Rice & Lentil Porridge) with Fried Egg","es":"Khichuri: arroz con lentejas y huevo frito"},"ing":{"en":["1 cup rice","1 cup red lentils","1 onion, chopped","1 tsp turmeric","1 tbsp fresh ginger, grated","2 cups cauliflower, in small florets","1 cup frozen peas","4 eggs"],"es":["1 taza arroz","1 taza lentejas rojas","1 cebolla picada","1 cdita cúrcuma","1 cda jengibre fresco rallado","2 tazas coliflor en ramitos chicos","1 taza arvejas congeladas","4 huevos"]},"steps":{"en":["Soften onion and ginger with turmeric; add rice, lentils and 6 cups water.","Simmer 25 min, adding cauliflower and peas for the last 10 min, until soft and porridgy.","Serve with fried eggs."],"es":["Rehogá la cebolla y el jengibre con la cúrcuma; sumá el arroz, las lentejas y 6 tazas de agua.","Cociná 25 min, sumando la coliflor y las arvejas los últimos 10 min, hasta que quede cremoso.","Serví con huevos fritos."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"machher-jhol","type":"dinner","country":"BD","protein":"fish","base":"rice","tags":["curry"],"name":{"en":"Machher Jhol (Light Fish & Potato Curry) with Rice","es":"Machher jhol: curry liviano de pescado y papa con arroz"},"ing":{"en":["600 g white fish fillets, in chunks","2 potatoes, in wedges","1 tsp turmeric","1 tsp ground cumin","2 tomatoes, chopped","1 tbsp fresh ginger, grated","2 tbsp fresh cilantro, chopped","1½ cups rice"],"es":["600 g filet de pescado blanco en trozos","2 papas en gajos","1 cdita cúrcuma","1 cdita comino","2 tomates picados","1 cda jengibre fresco rallado","2 cdas cilantro fresco picado","1½ tazas arroz"]},"steps":{"en":["Rub the fish with turmeric and salt and sear 2 min a side.","Fry potatoes with ginger and cumin, add tomatoes and 2 cups water and simmer 15 min.","Add the fish for 5 min; finish with cilantro and serve with rice."],"es":["Frotá el pescado con cúrcuma y sal y doralo 2 min por lado.","Saltá las papas con el jengibre y el comino, sumá el tomate y 2 tazas de agua y cociná 15 min.","Agregá el pescado 5 min; terminá con cilantro y serví con arroz."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"chicken-momo","type":"dinner","country":"NP","protein":"poultry","base":"pasta","tags":["ravioli"],"name":{"en":"Chicken Momo with Tomato Achar","es":"Momos de pollo con achar de tomate"},"ing":{"en":["30 dumpling wrappers","400 g ground chicken or turkey","1 onion, finely chopped","1 tbsp fresh ginger, grated","2 tbsp fresh cilantro, chopped","4 tomatoes","2 tbsp sesame seeds","1 lime"],"es":["30 tapitas para dumplings","400 g pollo o pavo picado","1 cebolla picada fina","1 cda jengibre fresco rallado","2 cdas cilantro fresco picado","4 tomates","2 cdas semillas de sésamo","1 lima"]},"steps":{"en":["Mix chicken, onion, ginger and cilantro; fill and pleat the wrappers.","Steam 12 min.","Char the tomatoes, blend with toasted sesame, lime and salt for the achar."],"es":["Mezclá el pollo, la cebolla, el jengibre y el cilantro; rellená las tapitas y cerralas con pliegues.","Cociná al vapor 12 min.","Tostá los tomates y licualos con el sésamo tostado, la lima y sal para el achar."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"dal-bhat-tarkari","type":"lunch","country":"NP","protein":"plant","base":"rice","tags":["lentil"],"name":{"en":"Dal Bhat Tarkari (Lentils, Rice & Vegetable Curry)","es":"Dal bhat tarkari: lentejas, arroz y curry de verduras"},"ing":{"en":["1 cup red lentils","1½ cups rice","2 potatoes, diced","1 cauliflower, in florets","1 onion, chopped","1 tsp turmeric","1 tsp ground cumin","1 tbsp fresh ginger, grated","1 cucumber"],"es":["1 taza lentejas rojas","1½ tazas arroz","2 papas en cubos","1 coliflor en ramitos","1 cebolla picada","1 cdita cúrcuma","1 cdita comino","1 cda jengibre fresco rallado","1 pepino"]},"steps":{"en":["Simmer the lentils with turmeric in 4 cups water for 20 min.","Fry onion, ginger and cumin, add potatoes, cauliflower and ½ cup water and cook 15 min covered.","Serve with rice and cucumber."],"es":["Cociná las lentejas con cúrcuma en 4 tazas de agua 20 min.","Saltá la cebolla, el jengibre y el comino, sumá las papas, la coliflor y ½ taza de agua y cociná 15 min tapado.","Serví con arroz y pepino."]},"tip":{"en":"","es":""},"prep":["rice"]},
{"id":"mohinga","type":"lunch","country":"MM","protein":"fish","base":"pasta","tags":["soup"],"name":{"en":"Mohinga (Fish & Rice Noodle Soup)","es":"Mohinga: sopa de pescado con fideos de arroz"},"ing":{"en":["500 g white fish fillets","1 stalk lemongrass, bruised","1 onion, chopped","1 tbsp fresh ginger, grated","1 tsp turmeric","3 tbsp rice flour or chickpea flour","300 g rice noodles","4 eggs, boiled","2 limes"],"es":["500 g filet de pescado blanco","1 tallo de lemongrass machacado","1 cebolla picada","1 cda jengibre fresco rallado","1 cdita cúrcuma","3 cdas harina de arroz o de garbanzo","300 g fideos de arroz","4 huevos duros","2 limas"]},"steps":{"en":["Poach the fish with lemongrass in 6 cups water 8 min; flake and keep the broth.","Fry onion, ginger and turmeric; add the broth, fish and the flour mixed in water; simmer 15 min.","Serve over soaked noodles with boiled egg and lime."],"es":["Cociná el pescado con el lemongrass en 6 tazas de agua 8 min; desmenuzalo y guardá el caldo.","Saltá la cebolla, el jengibre y la cúrcuma; sumá el caldo, el pescado y la harina disuelta en agua; cociná 15 min.","Serví sobre los fideos remojados con huevo duro y lima."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"burmese-chicken-curry","type":"dinner","country":"MM","protein":"poultry","base":"rice","tags":["curry"],"name":{"en":"Burmese Chicken & Potato Curry","es":"Curry birmano de pollo y papa"},"ing":{"en":["1 kg chicken thighs","2 potatoes, in chunks","2 onions, blended","4 garlic cloves","1 tbsp fresh ginger, grated","1 tsp turmeric","1 tsp paprika","1½ cups rice"],"es":["1 kg muslos de pollo","2 papas en trozos","2 cebollas licuadas","4 dientes de ajo","1 cda jengibre fresco rallado","1 cdita cúrcuma","1 cdita pimentón","1½ tazas arroz"]},"steps":{"en":["Fry the blended onion, garlic and ginger slowly for 15 min until sweet.","Add chicken, turmeric and paprika, then potatoes and 1 cup water; simmer 35 min.","Serve with rice."],"es":["Freí despacio la cebolla licuada, el ajo y el jengibre 15 min, hasta que se dulcifique.","Sumá el pollo, la cúrcuma y el pimentón y después las papas y 1 taza de agua; cociná 35 min.","Serví con arroz."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"fish-amok","type":"dinner","country":"KH","protein":"fish","base":"rice","tags":["curry"],"name":{"en":"Fish Amok (Steamed Coconut Curry Fish)","es":"Amok de pescado: curry de coco al vapor"},"ing":{"en":["600 g white fish fillets, in chunks","1 can coconut milk","1 stalk lemongrass, finely chopped","1 tbsp fresh ginger, grated","1 tsp turmeric","1 egg","1 tbsp fish sauce","2 cups spinach","1½ cups jasmine rice"],"es":["600 g filet de pescado blanco en trozos","1 lata leche de coco","1 tallo de lemongrass picado fino","1 cda jengibre fresco rallado","1 cdita cúrcuma","1 huevo","1 cda salsa de pescado","2 tazas espinaca","1½ tazas arroz jazmín"]},"steps":{"en":["Blend lemongrass, ginger and turmeric with half the coconut milk; whisk in the egg and fish sauce.","Line bowls with spinach, add fish and pour the mixture over; steam 20 min until set.","Top with the rest of the coconut milk; serve with rice."],"es":["Procesá el lemongrass, el jengibre y la cúrcuma con la mitad de la leche de coco; sumá el huevo y la salsa de pescado.","Forrá bowls con espinaca, sumá el pescado y volcá la mezcla; cociná al vapor 20 min hasta que cuaje.","Cubrí con el resto de la leche de coco; serví con arroz."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"lok-lak","type":"dinner","country":"KH","protein":"beef","base":"rice","name":{"en":"Lok Lak (Peppered Beef with Lime Dip & Fried Egg)","es":"Lok lak: carne a la pimienta con salsa de lima y huevo"},"ing":{"en":["600 g beef sirloin, in cubes","2 tbsp soy sauce","1 tbsp oyster sauce","2 limes","1 tsp black peppercorns, crushed","1 head lettuce","2 tomatoes, sliced","4 eggs","1½ cups rice"],"es":["600 g lomo en cubos","2 cdas salsa de soja","1 cda salsa de ostras","2 limas","1 cdita pimienta en grano machacada","1 planta de lechuga","2 tomates en rodajas","4 huevos","1½ tazas arroz"]},"steps":{"en":["Marinate the beef in soy and oyster sauce 20 min; sear over high heat 3 min.","Mix lime juice with crushed pepper and salt for the dip.","Serve the beef on lettuce and tomato with rice, fried eggs and the dip."],"es":["Mariná la carne con la soja y la salsa de ostras 20 min; saltala a fuego fuerte 3 min.","Mezclá el jugo de lima con la pimienta y sal para la salsa.","Serví la carne sobre lechuga y tomate con arroz, huevos fritos y la salsa."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"larb-gai","type":"lunch","country":"LA","protein":"poultry","base":"rice","name":{"en":"Larb Gai (Minced Chicken & Herb Salad) with Sticky Rice","es":"Larb gai: ensalada de pollo picado y hierbas con arroz"},"ing":{"en":["500 g ground chicken or turkey","2 limes","1 tbsp fish sauce","1 red onion, thinly sliced","1 handful fresh herbs (mint, cilantro)","2 tbsp rice, toasted and ground","1 head lettuce","1½ cups short-grain rice"],"es":["500 g pollo o pavo picado","2 limas","1 cda salsa de pescado","1 cebolla morada en pluma fina","1 puñado de hierbas frescas (menta, cilantro)","2 cdas arroz tostado y molido","1 planta de lechuga","1½ tazas arroz de grano corto"]},"steps":{"en":["Cook the chicken in a dry pan with a splash of water for 6 min.","Toss with lime, fish sauce, onion, herbs and toasted rice powder.","Serve in lettuce cups with steamed rice."],"es":["Cociná el pollo en sartén seca con un chorrito de agua 6 min.","Mezclalo con la lima, la salsa de pescado, la cebolla, las hierbas y el arroz tostado molido.","Serví en hojas de lechuga con arroz."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"khao-piak-sen","type":"dinner","country":"LA","protein":"poultry","base":"pasta","tags":["soup"],"name":{"en":"Khao Piak Sen (Chicken Noodle Soup with Garlic & Ginger)","es":"Khao piak sen: sopa de pollo y fideos con ajo y jengibre"},"ing":{"en":["600 g chicken breast","8 cups chicken broth","1 tbsp fresh ginger, sliced","4 garlic cloves, sliced","400 g udon noodles","3 spring onions, sliced","1 handful fresh cilantro","2 limes"],"es":["600 g pechuga de pollo","8 tazas caldo de pollo","1 cda jengibre fresco en láminas","4 dientes de ajo en láminas","400 g fideos udon","3 cebollas de verdeo en rodajas","1 puñado de cilantro fresco","2 limas"]},"steps":{"en":["Simmer the chicken with ginger in the broth 15 min; shred.","Fry the garlic in a little oil until golden.","Cook the noodles in the broth 5 min; serve with chicken, crispy garlic, herbs and lime."],"es":["Cociná el pollo con el jengibre en el caldo 15 min; desmenuzalo.","Dorá el ajo en un poco de aceite.","Cociná los fideos en el caldo 5 min; serví con el pollo, el ajo crocante, las hierbas y lima."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"hainanese-chicken-rice","type":"lunch","country":"SG","protein":"poultry","base":"rice","name":{"en":"Hainanese Chicken Rice with Ginger Sauce","es":"Arroz con pollo hainanés con salsa de jengibre"},"ing":{"en":["1 kg chicken thighs","2 cups jasmine rice","4 garlic cloves, minced","2 tbsp fresh ginger, grated","3 spring onions, sliced","2 tbsp soy sauce","1 cucumber, sliced"],"es":["1 kg muslos de pollo","2 tazas arroz jazmín","4 dientes de ajo picados","2 cdas jengibre fresco rallado","3 cebollas de verdeo en rodajas","2 cdas salsa de soja","1 pepino en rodajas"]},"steps":{"en":["Poach the chicken with half the ginger in water for 25 min; keep the broth.","Fry the rice with garlic, then cook in 3 cups of the broth for 18 min.","Mix the rest of the ginger with spring onion and a little hot oil; serve with chicken, rice, cucumber and soy."],"es":["Cociná el pollo con la mitad del jengibre en agua 25 min; guardá el caldo.","Saltá el arroz con el ajo y cocinalo en 3 tazas del caldo 18 min.","Mezclá el resto del jengibre con el verdeo y un poco de aceite caliente; serví con el pollo, el arroz, el pepino y la soja."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"kaya-toast","type":"breakfast","country":"SG","group":"egg","tags":["toast"],"name":{"en":"Kaya Toast with Soft-Boiled Eggs","es":"Tostadas con kaya y huevos pasados por agua"},"ing":{"en":["8 slices white bread","4 tbsp coconut jam or apricot jam","2 tbsp butter","4 eggs","1 tbsp soy sauce","2 cups milk"],"es":["8 rebanadas de pan blanco","4 cdas mermelada de coco o de damasco","2 cdas manteca","4 huevos","1 cda salsa de soja","2 tazas leche"]},"steps":{"en":["Toast the bread and spread with butter and a little jam.","Boil the eggs for 6 min for runny yolks.","Crack the eggs into cups with a drop of soy for dipping; serve with warm milk."],"es":["Tostá el pan y untá con manteca y un poco de mermelada.","Herví los huevos 6 min para que la yema quede líquida.","Abrí los huevos en tazas con unas gotas de soja para mojar; serví con leche tibia."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"singapore-noodles","type":"dinner","country":"SG","protein":"pork","base":"pasta","tags":["stir-fry-noodles"],"name":{"en":"Singapore Noodles (Curry Rice Noodles with Pork & Shrimp)","es":"Fideos Singapur: fideos de arroz al curry con cerdo y langostinos"},"ing":{"en":["300 g rice noodles","300 g pork tenderloin, thinly sliced","200 g shrimp","2 eggs","1 red bell pepper, sliced","2 cups bean sprouts","2 tsp curry powder","2 tbsp soy sauce"],"es":["300 g fideos de arroz","300 g lomo de cerdo en tiras finas","200 g langostinos","2 huevos","1 morrón rojo en tiras","2 tazas brotes de soja","2 cditas curry en polvo","2 cdas salsa de soja"]},"steps":{"en":["Soak the noodles 8 min; scramble the eggs and set aside.","Stir-fry pork and shrimp 3 min, add pepper and sprouts for 2 min.","Add noodles, curry, soy and egg and toss 2 min."],"es":["Remojá los fideos 8 min; revolvé los huevos y reservá.","Saltá el cerdo y los langostinos 3 min, sumá el morrón y los brotes 2 min.","Agregá los fideos, el curry, la soja y el huevo y saltá 2 min."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"taiwanese-beef-noodle-soup","type":"dinner","country":"TW","protein":"beef","base":"pasta","tags":["soup"],"name":{"en":"Taiwanese Beef Noodle Soup","es":"Sopa taiwanesa de fideos con carne"},"ing":{"en":["700 g beef shin or chuck","2 tbsp soy sauce","2 tomatoes, quartered","1 tbsp fresh ginger, sliced","2 star anise (optional)","400 g udon or egg noodles","1 bunch Swiss chard or bok choy","3 spring onions, sliced"],"es":["700 g osobuco o carne para guiso","2 cdas salsa de soja","2 tomates en cuartos","1 cda jengibre fresco en láminas","2 anís estrellado (opcional)","400 g fideos udon o de huevo","1 atado de acelga o bok choy","3 cebollas de verdeo en rodajas"]},"steps":{"en":["Brown the beef with ginger; add soy, tomato, star anise and 8 cups water; simmer 2 hours.","Cook the noodles and blanch the greens.","Serve noodles, greens and beef in the broth with spring onion."],"es":["Dorá la carne con el jengibre; sumá la soja, el tomate, el anís y 8 tazas de agua; cociná 2 horas.","Cociná los fideos y blanqueá los verdes.","Serví los fideos, los verdes y la carne en el caldo con verdeo."]},"tip":{"en":"","es":""},"prep":["cook-ahead"]},
{"id":"gua-bao","type":"lunch","country":"TW","protein":"pork","base":"bread","name":{"en":"Gua Bao (Pork Belly Buns) with Pickled Cucumber","es":"Gua bao: pancitos de cerdo con pepino encurtido"},"ing":{"en":["600 g pork shoulder, sliced","3 tbsp soy sauce","1 tbsp brown sugar","8 soft burger buns or bao","1 cucumber, thinly sliced","2 tbsp vinegar","3 tbsp peanuts, chopped (optional)","1 handful fresh cilantro"],"es":["600 g bondiola en láminas","3 cdas salsa de soja","1 cda azúcar mascabo","8 pancitos blandos o bao","1 pepino en rodajas finas","2 cdas vinagre","3 cdas maní picado (opcional)","1 puñado de cilantro fresco"]},"steps":{"en":["Simmer the pork in soy, sugar and 1 cup water for 1 hour until tender and glazed.","Quick-pickle cucumber in vinegar with a pinch of salt.","Steam or warm the buns and fill with pork, cucumber, peanuts and cilantro."],"es":["Cociná el cerdo en la soja, el azúcar y 1 taza de agua 1 hora, hasta que esté tierno y glaseado.","Encurtí el pepino en vinagre con una pizca de sal.","Calentá los pancitos al vapor y rellená con el cerdo, el pepino, el maní y el cilantro."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"dan-bing","type":"breakfast","country":"TW","group":"egg","name":{"en":"Dan Bing (Spring Onion Egg Crêpes)","es":"Dan bing: crepes de huevo y verdeo"},"ing":{"en":["1 cup flour","1 cup water","4 eggs","4 spring onions, sliced","1 tbsp soy sauce","1 tbsp sunflower oil"],"es":["1 taza harina","1 taza agua","4 huevos","4 cebollas de verdeo en rodajas","1 cda salsa de soja","1 cda aceite de girasol"]},"steps":{"en":["Whisk flour, water and salt into a thin batter; cook 4 thin crêpes.","Pour a beaten egg with spring onion into the pan, lay a crêpe on top and cook 1 min.","Flip, roll up and slice; serve with soy."],"es":["Batí la harina con el agua y sal; cociná 4 crepes finas.","Volcá un huevo batido con verdeo en la sartén, apoyá una crepe encima y cociná 1 min.","Da vuelta, enrollá y cortá; serví con soja."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"three-cup-chicken","type":"dinner","country":"TW","protein":"poultry","base":"rice","name":{"en":"Three-Cup Chicken with Basil","es":"Pollo tres tazas con albahaca"},"ing":{"en":["1 kg chicken thighs, in pieces","3 tbsp sesame oil","3 tbsp soy sauce","1 tbsp brown sugar","8 garlic cloves","1 tbsp fresh ginger, sliced","1 handful fresh basil","1½ cups rice"],"es":["1 kg muslos de pollo en trozos","3 cdas aceite de sésamo","3 cdas salsa de soja","1 cda azúcar mascabo","8 dientes de ajo","1 cda jengibre fresco en láminas","1 puñado de albahaca fresca","1½ tazas arroz"]},"steps":{"en":["Fry garlic and ginger in the sesame oil; add chicken and brown.","Add soy, sugar and ½ cup water; cover and simmer 20 min, then reduce until sticky.","Toss in the basil; serve with rice."],"es":["Freí el ajo y el jengibre en el aceite de sésamo; sumá el pollo y doralo.","Agregá la soja, el azúcar y ½ taza de agua; tapá y cociná 20 min y después reducí hasta que quede pegajoso.","Sumá la albahaca; serví con arroz."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"buuz","type":"dinner","country":"MN","protein":"beef","base":"pasta","tags":["ravioli"],"name":{"en":"Buuz (Steamed Beef Dumplings) with Salad","es":"Buuz: empanaditas de carne al vapor con ensalada"},"ing":{"en":["30 dumpling wrappers","500 g ground beef","1 onion, grated","2 garlic cloves, minced","1 tsp ground cumin","¼ cabbage, shredded","1 carrot, grated","1 tbsp vinegar"],"es":["30 tapitas para dumplings","500 g carne picada","1 cebolla rallada","2 dientes de ajo picados","1 cdita comino","¼ repollo en juliana","1 zanahoria rallada","1 cda vinagre"]},"steps":{"en":["Mix beef, onion, garlic, cumin and 3 tbsp water; fill the wrappers leaving a small opening on top.","Steam 15 min.","Serve with cabbage and carrot dressed with vinegar."],"es":["Mezclá la carne, la cebolla, el ajo, el comino y 3 cdas de agua; rellená las tapitas dejando una abertura arriba.","Cociná al vapor 15 min.","Serví con repollo y zanahoria condimentados con vinagre."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"tsuivan","type":"lunch","country":"MN","protein":"beef","base":"pasta","tags":["stir-fry-noodles"],"name":{"en":"Tsuivan (Stir-Fried Noodles with Beef & Vegetables)","es":"Tsuivan: fideos salteados con carne y verduras"},"ing":{"en":["400 g egg noodles","400 g beef sirloin, in thin strips","2 carrots, in thin sticks","¼ cabbage, shredded","1 onion, sliced","2 tbsp soy sauce","1 cup beef broth"],"es":["400 g fideos de huevo","400 g lomo en tiras finas","2 zanahorias en bastones finos","¼ repollo en juliana","1 cebolla en pluma","2 cdas salsa de soja","1 taza caldo de carne"]},"steps":{"en":["Sear the beef in batches.","Fry onion, carrot and cabbage 5 min; add the beef and broth.","Lay the cooked noodles on top, cover 5 min to steam, then toss with soy."],"es":["Saltá la carne de a poco.","Saltá la cebolla, la zanahoria y el repollo 5 min; sumá la carne y el caldo.","Poné los fideos cocidos encima, tapá 5 min y después mezclá con la soja."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"uzbek-plov","type":"dinner","country":"UZ","protein":"beef","base":"rice","name":{"en":"Uzbek Plov (Rice with Beef, Carrots & Chickpeas)","es":"Plov uzbeko: arroz con carne, zanahoria y garbanzos"},"ing":{"en":["700 g beef chuck, diced","2 cups rice","4 carrots, in thin sticks","2 onions, sliced","1 can chickpeas, drained","1 head garlic","1 tsp ground cumin","3 tbsp sunflower oil"],"es":["700 g carne para guiso en cubos","2 tazas arroz","4 zanahorias en bastones finos","2 cebollas en pluma","1 lata garbanzos escurridos","1 cabeza de ajo","1 cdita comino","3 cdas aceite de girasol"]},"steps":{"en":["Brown the beef and onions in the oil; add carrots and cumin and cook 10 min.","Add chickpeas and 3 cups water and simmer 40 min.","Spread the rice on top, push in the whole garlic head, add water to cover by 1 cm, cover and cook 25 min on low."],"es":["Dorá la carne y la cebolla en el aceite; sumá las zanahorias y el comino y cociná 10 min.","Agregá los garbanzos y 3 tazas de agua y cociná 40 min.","Esparcí el arroz encima, hundí la cabeza de ajo entera, cubrí con agua 1 cm por encima, tapá y cociná 25 min a fuego bajo."]},"tip":{"en":"","es":""},"prep":["cook-ahead"]},
{"id":"lagman","type":"lunch","country":"UZ","protein":"beef","base":"pasta","tags":["soup"],"name":{"en":"Lagman (Beef & Vegetable Noodle Soup)","es":"Lagman: sopa de fideos con carne y verduras"},"ing":{"en":["400 g beef sirloin, diced","400 g spaghetti or udon","1 red bell pepper, diced","2 potatoes, diced","1 carrot, diced","2 tomatoes, chopped","2 garlic cloves, minced","1 tsp ground cumin","6 cups beef broth"],"es":["400 g carne en cubos","400 g spaghetti o udon","1 morrón rojo en cubos","2 papas en cubos","1 zanahoria en cubos","2 tomates picados","2 dientes de ajo picados","1 cdita comino","6 tazas caldo de carne"]},"steps":{"en":["Brown the beef with garlic and cumin; add vegetables and fry 5 min.","Add the broth and simmer 25 min.","Serve over cooked noodles."],"es":["Dorá la carne con el ajo y el comino; sumá las verduras y saltá 5 min.","Agregá el caldo y cociná 25 min.","Serví sobre los fideos cocidos."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"beshbarmak","type":"dinner","country":"KZ","protein":"beef","base":"pasta","name":{"en":"Beshbarmak (Beef with Wide Noodles & Onion Broth)","es":"Beshbarmak: carne con fideos anchos y caldo de cebolla"},"ing":{"en":["800 g beef shin or chuck","400 g lasagna sheets, cut into squares","2 onions, sliced","1 bay leaf","3 tbsp fresh dill, chopped"],"es":["800 g osobuco o carne para guiso","400 g láminas de lasaña cortadas en cuadrados","2 cebollas en pluma","1 hoja de laurel","3 cdas eneldo fresco picado"]},"steps":{"en":["Simmer the beef with the bay leaf in 8 cups water for 2 hours; slice the meat.","Cook the pasta squares in some of the broth; poach the onions in a ladle of broth 5 min.","Layer pasta, beef and onion; serve with cups of broth and dill."],"es":["Cociná la carne con el laurel en 8 tazas de agua 2 horas; cortala en láminas.","Cociná los cuadrados de pasta en parte del caldo; cociná la cebolla en un cucharón de caldo 5 min.","Armá capas de pasta, carne y cebolla; serví con tazas de caldo y eneldo."]},"tip":{"en":"","es":""},"prep":["cook-ahead"]},
{"id":"baursak","type":"snack","country":"KZ","group":"grain","name":{"en":"Baursak (Puffy Fried Dough) with Honey","es":"Baursak: bollitos fritos con miel"},"ing":{"en":["2 cups flour","7 g dry yeast","¾ cup warm milk","1 egg","1 tbsp sugar","Sunflower oil for frying","2 tbsp honey"],"es":["2 tazas harina","7 g levadura seca","¾ taza leche tibia","1 huevo","1 cda azúcar","Aceite de girasol para freír","2 cdas miel"]},"steps":{"en":["Mix flour, yeast, milk, egg and sugar into a soft dough; rise 1 hour.","Roll 1 cm thick and cut small squares.","Fry until puffed and golden; serve with a little honey."],"es":["Mezclá la harina, la levadura, la leche, el huevo y el azúcar; dejá levar 1 hora.","Estirá de 1 cm y cortá cuadraditos.","Freí hasta que se inflen y doren; serví con un poco de miel."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"rajma-chawal","type":"lunch","country":"IN","protein":"plant","base":"rice","tags":["curry"],"name":{"en":"Rajma Chawal (Kidney Bean Curry with Rice)","es":"Rajma chawal: curry de porotos colorados con arroz"},"ing":{"en":["2 cans kidney beans","1 onion, chopped","2 tomatoes, chopped","1 tbsp fresh ginger, grated","2 garlic cloves, minced","1 tsp garam masala","1 tsp ground cumin","1½ cups basmati rice"],"es":["2 latas porotos colorados","1 cebolla picada","2 tomates picados","1 cda jengibre fresco rallado","2 dientes de ajo picados","1 cdita garam masala","1 cdita comino","1½ tazas arroz basmati"]},"steps":{"en":["Soften onion, ginger and garlic; add tomatoes and spices and cook 10 min.","Add beans with their liquid and simmer 20 min, mashing a few.","Serve with rice."],"es":["Rehogá la cebolla, el jengibre y el ajo; sumá el tomate y las especias y cociná 10 min.","Agregá los porotos con su líquido y cociná 20 min, pisando algunos.","Serví con arroz."]},"tip":{"en":"","es":""},"prep":["rice"]},
{"id":"masala-dosa","type":"breakfast","country":"IN","group":"grain","tags":["pancakes"],"name":{"en":"Masala Dosa-Style Crêpes with Spiced Potato","es":"Crepes estilo masala dosa con papa especiada"},"ing":{"en":["1 cup rice flour or flour","½ cup chickpea flour","1 cup plain yogurt","4 potatoes, boiled and diced","1 onion, sliced","1 tsp mustard seeds","1 tsp turmeric","2 tbsp sunflower oil"],"es":["1 taza harina de arroz o común","½ taza harina de garbanzo","1 taza yogur natural","4 papas hervidas en cubos","1 cebolla en pluma","1 cdita semillas de mostaza","1 cdita cúrcuma","2 cdas aceite de girasol"]},"steps":{"en":["Whisk the flours, yogurt and water into a thin batter; rest 30 min.","Fry mustard seeds, onion and turmeric; add potatoes and mash lightly.","Cook thin crêpes, fill with the potato and fold."],"es":["Batí las harinas con el yogur y agua hasta tener una mezcla fina; dejá reposar 30 min.","Freí las semillas de mostaza, la cebolla y la cúrcuma; sumá las papas y pisá un poco.","Cociná crepes finas, rellenalas con la papa y doblalas."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"chicken-biryani","type":"dinner","country":"IN","protein":"poultry","base":"rice","name":{"en":"Chicken Biryani","es":"Biryani de pollo"},"ing":{"en":["800 g chicken thighs, in pieces","1 cup plain yogurt","2 tsp garam masala","1 tbsp fresh ginger, grated","2 onions, thinly sliced","2 cups basmati rice","1 pinch saffron or turmeric","2 tbsp fresh mint, chopped","1 cucumber"],"es":["800 g muslos de pollo en trozos","1 taza yogur natural","2 cditas garam masala","1 cda jengibre fresco rallado","2 cebollas en pluma fina","2 tazas arroz basmati","1 pizca de azafrán o cúrcuma","2 cdas menta fresca picada","1 pepino"]},"steps":{"en":["Marinate the chicken in yogurt, garam masala and ginger 1 hour; fry the onions until deep golden.","Par-boil the rice 6 min. Layer chicken, half the onions, rice, saffron in a splash of milk, mint and the rest of the onions.","Cover tightly and cook on low 35 min; serve with cucumber."],"es":["Mariná el pollo con el yogur, el garam masala y el jengibre 1 hora; dorá bien la cebolla.","Herví el arroz 6 min. Armá capas de pollo, mitad de la cebolla, arroz, azafrán en un chorrito de leche, menta y el resto de la cebolla.","Tapá bien y cociná a fuego bajo 35 min; serví con pepino."]},"tip":{"en":"","es":""},"prep":["marinate"]},
{"id":"fish-moilee","type":"dinner","country":"IN","protein":"fish","base":"rice","tags":["curry"],"name":{"en":"Fish Moilee (Kerala Coconut Fish Curry)","es":"Fish moilee: curry de pescado con coco de Kerala"},"ing":{"en":["600 g white fish fillets","1 can coconut milk","1 onion, sliced","1 tbsp fresh ginger, in strips","1 tsp turmeric","1 tsp mustard seeds","2 tomatoes, sliced","1½ cups rice"],"es":["600 g filet de pescado blanco","1 lata leche de coco","1 cebolla en pluma","1 cda jengibre fresco en tiritas","1 cdita cúrcuma","1 cdita semillas de mostaza","2 tomates en rodajas","1½ tazas arroz"]},"steps":{"en":["Fry the mustard seeds, then onion and ginger until soft; add turmeric.","Pour in the coconut milk, add the fish and tomato and simmer gently 8 min.","Serve with rice."],"es":["Freí las semillas de mostaza y después la cebolla y el jengibre hasta que se ablanden; sumá la cúrcuma.","Volcá la leche de coco, sumá el pescado y el tomate y cociná suave 8 min.","Serví con arroz."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"paneer-tikka-wraps","type":"lunch","country":"IN","protein":"plant","base":"bread","name":{"en":"Paneer Tikka Wraps with Mint Yogurt","es":"Wraps de paneer tikka con yogur de menta"},"ing":{"en":["250 g paneer or halloumi, cubed","1 cup plain yogurt","1 tsp garam masala","1 tsp turmeric","2 bell peppers, in chunks","1 red onion, in wedges","4 naan breads","2 tbsp fresh mint, chopped"],"es":["250 g paneer o queso halloumi en cubos","1 taza yogur natural","1 cdita garam masala","1 cdita cúrcuma","2 morrones en trozos","1 cebolla morada en gajos","4 panes naan","2 cdas menta fresca picada"]},"steps":{"en":["Toss the cheese, peppers and onion with half the yogurt and the spices.","Roast at 220°C for 15 min until charred at the edges.","Wrap in warm naan with the rest of the yogurt mixed with mint."],"es":["Mezclá el queso, los morrones y la cebolla con la mitad del yogur y las especias.","Asá a 220°C 15 min, hasta que se doren los bordes.","Envolvé en naan tibio con el resto del yogur mezclado con menta."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"upma","type":"breakfast","country":"IN","group":"grain","name":{"en":"Upma (Savoury Semolina with Vegetables)","es":"Upma: sémola salada con verduras"},"ing":{"en":["1 cup semolina","1 onion, chopped","1 carrot, diced","½ cup frozen peas","1 tsp mustard seeds","1 tbsp butter","1 lemon"],"es":["1 taza sémola","1 cebolla picada","1 zanahoria en cubitos","½ taza arvejas congeladas","1 cdita semillas de mostaza","1 cda manteca","1 limón"]},"steps":{"en":["Toast the semolina in a dry pan 4 min.","Fry mustard seeds, onion and vegetables in butter 5 min; add 2½ cups water and bring to a boil.","Stir in the semolina until thick and fluffy, 3 min; finish with lemon."],"es":["Tostá la sémola en sartén seca 4 min.","Freí las semillas de mostaza, la cebolla y las verduras en manteca 5 min; sumá 2½ tazas de agua y llevá a hervor.","Incorporá la sémola revolviendo hasta que espese, 3 min; terminá con limón."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"vegetable-korma","type":"dinner","country":"IN","protein":"plant","base":"rice","tags":["curry"],"name":{"en":"Mild Vegetable Korma with Rice","es":"Korma suave de verduras con arroz"},"ing":{"en":["1 cauliflower, in florets","2 carrots, diced","2 potatoes, diced","1 cup frozen peas","1 onion, chopped","1 tbsp fresh ginger, grated","1 tsp garam masala","½ cup cream","1½ cups basmati rice"],"es":["1 coliflor en ramitos","2 zanahorias en cubos","2 papas en cubos","1 taza arvejas congeladas","1 cebolla picada","1 cda jengibre fresco rallado","1 cdita garam masala","½ taza crema de leche","1½ tazas arroz basmati"]},"steps":{"en":["Soften onion and ginger with garam masala.","Add potatoes, carrots and cauliflower with 1 cup water; cover and cook 15 min.","Stir in peas and cream for 5 min; serve with rice."],"es":["Rehogá la cebolla y el jengibre con el garam masala.","Sumá las papas, las zanahorias y la coliflor con 1 taza de agua; tapá y cociná 15 min.","Agregá las arvejas y la crema 5 min; serví con arroz."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"besan-chilla","type":"breakfast","country":"IN","group":"grain","tags":["pancakes"],"name":{"en":"Besan Chilla (Chickpea Flour Pancakes) with Yogurt","es":"Besan chilla: panqueques de harina de garbanzo con yogur"},"ing":{"en":["1½ cups chickpea flour","1 tomato, finely diced","1 onion, finely chopped","2 tbsp fresh cilantro, chopped","½ tsp turmeric","1 tbsp sunflower oil","1 cup plain yogurt"],"es":["1½ tazas harina de garbanzo","1 tomate en cubitos","1 cebolla picada fina","2 cdas cilantro fresco picado","½ cdita cúrcuma","1 cda aceite de girasol","1 taza yogur natural"]},"steps":{"en":["Whisk chickpea flour with 1 cup water, turmeric and salt.","Stir in tomato, onion and cilantro.","Cook thin pancakes in a lightly oiled pan 2 min a side; serve with yogurt."],"es":["Batí la harina de garbanzo con 1 taza de agua, la cúrcuma y sal.","Sumá el tomate, la cebolla y el cilantro.","Cociná panqueques finos en sartén apenas aceitada 2 min por lado; serví con yogur."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"masala-chaas","type":"snack","country":"IN","group":"dairy","name":{"en":"Masala Chaas (Spiced Yogurt Drink) with Crackers","es":"Masala chaas: bebida de yogur especiada con galletitas"},"ing":{"en":["2 cups plain yogurt","2 cups cold water","½ tsp ground cumin, toasted","1 tbsp fresh mint, chopped","12 crackers"],"es":["2 tazas yogur natural","2 tazas agua fría","½ cdita comino tostado","1 cda menta fresca picada","12 galletitas"]},"steps":{"en":["Whisk yogurt and water until frothy.","Stir in toasted cumin, mint and a pinch of salt.","Serve cold with crackers."],"es":["Batí el yogur con el agua hasta que haga espuma.","Sumá el comino tostado, la menta y una pizca de sal.","Serví frío con galletitas."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"corn-chaat","type":"snack","country":"IN","group":"veg","name":{"en":"Corn Chaat (Spiced Corn Cups)","es":"Corn chaat: vasitos de choclo especiado"},"ing":{"en":["3 cups corn","1 tomato, finely diced","½ red onion, finely chopped","1 lime","½ tsp ground cumin","2 tbsp fresh cilantro, chopped","1 tbsp butter"],"es":["3 tazas choclo","1 tomate en cubitos","½ cebolla morada picada fina","1 lima","½ cdita comino","2 cdas cilantro fresco picado","1 cda manteca"]},"steps":{"en":["Sauté the corn in butter 4 min.","Toss with tomato, onion, lime, cumin and cilantro.","Serve warm in cups."],"es":["Salteá el choclo en manteca 4 min.","Mezclá con el tomate, la cebolla, la lima, el comino y el cilantro.","Serví tibio en vasitos."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"hot-and-sour-soup","type":"lunch","country":"CN","protein":"pork","base":"none","tags":["soup"],"name":{"en":"Hot & Sour Soup with Tofu & Pork","es":"Sopa agripicante con tofu y cerdo"},"ing":{"en":["200 g pork tenderloin, in thin strips","200 g firm tofu, in strips","200 g mushrooms, sliced","6 cups chicken broth","3 tbsp vinegar","2 tbsp soy sauce","2 tbsp cornstarch","2 eggs","½ tsp black peppercorns, crushed"],"es":["200 g lomo de cerdo en tiras finas","200 g tofu firme en tiras","200 g champiñones en láminas","6 tazas caldo de pollo","3 cdas vinagre","2 cdas salsa de soja","2 cdas maicena","2 huevos","½ cdita pimienta en grano machacada"]},"steps":{"en":["Simmer pork, tofu and mushrooms in the broth 8 min.","Season with vinegar, soy and pepper; thicken with cornstarch in water.","Drizzle in the beaten eggs while stirring gently."],"es":["Cociná el cerdo, el tofu y los champiñones en el caldo 8 min.","Condimentá con vinagre, soja y pimienta; espesá con la maicena disuelta en agua.","Volcá los huevos batidos en hilo mientras revolvés suave."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"char-siu-pork","type":"dinner","country":"CN","protein":"pork","base":"rice","name":{"en":"Char Siu (Honey-Glazed Roast Pork) with Rice & Greens","es":"Char siu: cerdo glaseado con miel, arroz y verdes"},"ing":{"en":["800 g pork tenderloin","3 tbsp honey","3 tbsp soy sauce","1 tbsp oyster sauce","2 garlic cloves, minced","1½ cups rice","1 head broccoli"],"es":["800 g lomo de cerdo","3 cdas miel","3 cdas salsa de soja","1 cda salsa de ostras","2 dientes de ajo picados","1½ tazas arroz","1 brócoli"]},"steps":{"en":["Marinate the pork in honey, soy, oyster sauce and garlic for 2 hours.","Roast at 200°C for 25 min, brushing with marinade; rest and slice.","Serve with rice and steamed broccoli."],"es":["Mariná el cerdo con la miel, la soja, la salsa de ostras y el ajo 2 horas.","Asá a 200°C 25 min, pincelando con la marinada; dejá reposar y cortá.","Serví con arroz y brócoli al vapor."]},"tip":{"en":"","es":""},"prep":["marinate"]},
{"id":"dan-dan-noodles","type":"lunch","country":"CN","protein":"pork","base":"pasta","tags":["stir-fry-noodles"],"name":{"en":"Mild Dan Dan Noodles with Pork & Greens","es":"Fideos dan dan suaves con cerdo y verdes"},"ing":{"en":["400 g egg noodles","300 g ground pork","3 tbsp tahini or peanut butter","3 tbsp soy sauce","1 tbsp vinegar","1 tsp sesame oil","2 cups spinach","2 spring onions, sliced"],"es":["400 g fideos de huevo","300 g carne picada de cerdo","3 cdas tahini o mantequilla de maní","3 cdas salsa de soja","1 cda vinagre","1 cdita aceite de sésamo","2 tazas espinaca","2 cebollas de verdeo en rodajas"]},"steps":{"en":["Brown the pork with 1 tbsp soy until crisp.","Whisk tahini, the rest of the soy, vinegar, sesame oil and warm water into a sauce.","Cook the noodles with the spinach for the last 30 s; toss with sauce, pork and spring onion."],"es":["Dorá el cerdo con 1 cda de soja hasta que esté crocante.","Batí el tahini con el resto de la soja, el vinagre, el aceite de sésamo y agua tibia.","Cociná los fideos y sumá la espinaca los últimos 30 s; mezclá con la salsa, el cerdo y el verdeo."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"steamed-egg-custard","type":"breakfast","country":"CN","group":"egg","name":{"en":"Silky Steamed Eggs with Soy & Rice","es":"Huevos al vapor sedosos con soja y arroz"},"ing":{"en":["6 eggs","1½ cups chicken broth","1 tbsp soy sauce","2 spring onions, sliced","1 tsp sesame oil","1 cup rice"],"es":["6 huevos","1½ tazas caldo de pollo","1 cda salsa de soja","2 cebollas de verdeo en rodajas","1 cdita aceite de sésamo","1 taza arroz"]},"steps":{"en":["Whisk eggs with warm broth and strain into bowls.","Cover and steam on low 12 min until just set.","Drizzle with soy and sesame oil, add spring onion; serve with rice."],"es":["Batí los huevos con el caldo tibio y colá en bowls.","Tapá y cociná al vapor a fuego bajo 12 min, hasta que apenas cuaje.","Rociá con soja y aceite de sésamo y sumá verdeo; serví con arroz."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"mantou","type":"snack","country":"CN","group":"grain","name":{"en":"Mantou (Steamed Milk Buns)","es":"Mantou: pancitos al vapor con leche"},"ing":{"en":["2½ cups flour","7 g dry yeast","1 cup warm milk","1 tbsp sugar","1 tbsp sunflower oil"],"es":["2½ tazas harina","7 g levadura seca","1 taza leche tibia","1 cda azúcar","1 cda aceite de girasol"]},"steps":{"en":["Knead flour, yeast, milk, sugar and oil until smooth; rise 1 hour.","Roll into a log, cut 12 pieces and rest 20 min on paper squares.","Steam 12 min."],"es":["Amasá la harina, la levadura, la leche, el azúcar y el aceite hasta que quede lisa; dejá levar 1 hora.","Formá un cilindro, cortá 12 trozos y dejá reposar 20 min sobre cuadraditos de papel.","Cociná al vapor 12 min."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"gyudon","type":"dinner","country":"JP","protein":"beef","base":"rice","name":{"en":"Gyudon (Beef & Onion Rice Bowl)","es":"Gyudon: bowl de arroz con carne y cebolla"},"ing":{"en":["500 g beef sirloin, very thinly sliced","2 onions, sliced","1 cup beef broth","3 tbsp soy sauce","1 tbsp sugar","1½ cups short-grain rice","2 spring onions, sliced","4 eggs (optional)"],"es":["500 g lomo en láminas muy finas","2 cebollas en pluma","1 taza caldo de carne","3 cdas salsa de soja","1 cda azúcar","1½ tazas arroz de grano corto","2 cebollas de verdeo en rodajas","4 huevos (opcional)"]},"steps":{"en":["Simmer the onions in broth, soy and sugar for 8 min.","Add the beef and cook 2 min, just until done.","Spoon over bowls of rice with spring onion (and an egg if you like)."],"es":["Cociná la cebolla en el caldo con la soja y el azúcar 8 min.","Sumá la carne y cociná 2 min, apenas hasta que esté.","Serví sobre bowls de arroz con verdeo (y un huevo si querés)."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"nikujaga","type":"dinner","country":"JP","protein":"beef","base":"potato","tags":["stew"],"name":{"en":"Nikujaga (Beef & Potato Stew)","es":"Nikujaga: guiso japonés de carne y papa"},"ing":{"en":["400 g beef sirloin, thinly sliced","4 potatoes, in chunks","2 carrots, in chunks","1 onion, in wedges","3 tbsp soy sauce","1 tbsp sugar","2 cups beef broth","1 cup frozen peas"],"es":["400 g lomo en láminas finas","4 papas en trozos","2 zanahorias en trozos","1 cebolla en gajos","3 cdas salsa de soja","1 cda azúcar","2 tazas caldo de carne","1 taza arvejas congeladas"]},"steps":{"en":["Brown the beef with the onion.","Add potatoes, carrots, broth, soy and sugar; cover and simmer 20 min.","Add peas for 3 min."],"es":["Dorá la carne con la cebolla.","Sumá las papas, las zanahorias, el caldo, la soja y el azúcar; tapá y cociná 20 min.","Agregá las arvejas 3 min."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"zaru-soba","type":"lunch","country":"JP","protein":"plant","base":"pasta","name":{"en":"Cold Soba Noodles with Dipping Sauce & Tofu","es":"Fideos soba fríos con salsa y tofu"},"ing":{"en":["400 g soba or thin spaghetti","4 tbsp soy sauce","1 tbsp honey","1 cup water","200 g firm tofu, cubed","1 cucumber, in thin sticks","3 spring onions, sliced","1 sheet nori seaweed"],"es":["400 g fideos soba o spaghetti finos","4 cdas salsa de soja","1 cda miel","1 taza agua","200 g tofu firme en cubos","1 pepino en bastones finos","3 cebollas de verdeo en rodajas","1 hoja de alga nori"]},"steps":{"en":["Cook the noodles, rinse under cold water and drain.","Mix soy, honey and water for the dipping sauce.","Serve noodles with tofu, cucumber, spring onion, nori strips and the sauce for dipping."],"es":["Cociná los fideos, enjuagalos con agua fría y escurrí.","Mezclá la soja, la miel y el agua para la salsa.","Serví los fideos con el tofu, el pepino, el verdeo, tiras de nori y la salsa para mojar."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"tamago-sando","type":"breakfast","country":"JP","group":"egg","name":{"en":"Tamago Sando (Japanese Egg Sandwiches)","es":"Tamago sando: sándwiches japoneses de huevo"},"ing":{"en":["6 eggs","3 tbsp mayonnaise","8 slices crustless sandwich bread","1 tbsp milk","2 cups strawberries"],"es":["6 huevos","3 cdas mayonesa","8 rebanadas de pan de miga","1 cda leche","2 tazas frutillas"]},"steps":{"en":["Boil the eggs 10 min, cool and chop.","Mix with mayonnaise, milk and a pinch of salt.","Fill the bread thickly, cut in half and serve with strawberries."],"es":["Herví los huevos 10 min, enfrialos y picalos.","Mezclalos con la mayonesa, la leche y una pizca de sal.","Rellená el pan con abundante relleno, cortá al medio y serví con frutillas."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"fruit-sando","type":"snack","country":"JP","group":"dairy","name":{"en":"Fruit Sando (Cream & Fruit Sandwiches)","es":"Fruit sando: sándwiches de crema y fruta"},"ing":{"en":["8 slices crustless sandwich bread","½ cup cream","½ cup plain yogurt","1 cup strawberries","2 kiwis","1 mango"],"es":["8 rebanadas de pan de miga","½ taza crema de leche","½ taza yogur natural","1 taza frutillas","2 kiwis","1 mango"]},"steps":{"en":["Whip the cream and fold in the yogurt.","Spread on the bread and line up whole strawberries and fruit slices; close.","Chill 30 min wrapped, then cut through the fruit."],"es":["Batí la crema e incorporá el yogur.","Untá el pan y acomodá frutillas enteras y fruta en láminas; cerrá.","Enfriá 30 min envueltos y cortá atravesando la fruta."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"kimchi-jjigae","type":"dinner","country":"KR","protein":"pork","base":"rice","tags":["stew"],"name":{"en":"Kimchi Jjigae (Kimchi, Pork & Tofu Stew)","es":"Kimchi jjigae: guiso de kimchi, cerdo y tofu"},"ing":{"en":["300 g pork shoulder, thinly sliced","2 cups kimchi, chopped","300 g firm tofu, cubed","1 onion, sliced","3 spring onions, sliced","1 tsp sesame oil","1½ cups short-grain rice"],"es":["300 g bondiola en láminas finas","2 tazas kimchi picado","300 g tofu firme en cubos","1 cebolla en pluma","3 cebollas de verdeo en rodajas","1 cdita aceite de sésamo","1½ tazas arroz de grano corto"]},"steps":{"en":["Fry the pork in sesame oil until browned; add kimchi and onion and cook 5 min.","Add 3 cups water and simmer 15 min.","Add tofu and spring onion for 5 min; serve with rice."],"es":["Dorá el cerdo en el aceite de sésamo; sumá el kimchi y la cebolla y cociná 5 min.","Agregá 3 tazas de agua y cociná 15 min.","Sumá el tofu y el verdeo 5 min; serví con arroz."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"bulgogi","type":"dinner","country":"KR","protein":"beef","base":"rice","name":{"en":"Bulgogi (Sweet Soy Beef) with Rice & Cucumber Salad","es":"Bulgogi: carne a la soja dulce con arroz y ensalada de pepino"},"ing":{"en":["600 g beef sirloin, very thinly sliced","4 tbsp soy sauce","1 pear, grated","3 garlic cloves, minced","1 tbsp sesame oil","1 onion, sliced","1½ cups short-grain rice","1 cucumber, sliced","1 tbsp vinegar"],"es":["600 g lomo en láminas muy finas","4 cdas salsa de soja","1 pera rallada","3 dientes de ajo picados","1 cda aceite de sésamo","1 cebolla en pluma","1½ tazas arroz de grano corto","1 pepino en rodajas","1 cda vinagre"]},"steps":{"en":["Marinate the beef in soy, pear, garlic and sesame oil for 1 hour.","Stir-fry with the onion over high heat 4 min.","Serve with rice and cucumber dressed with vinegar."],"es":["Mariná la carne con la soja, la pera, el ajo y el aceite de sésamo 1 hora.","Saltá con la cebolla a fuego fuerte 4 min.","Serví con arroz y pepino con vinagre."]},"tip":{"en":"","es":""},"prep":["marinate"]},
{"id":"gimbap","type":"lunch","country":"KR","protein":"egg","base":"rice","name":{"en":"Gimbap (Seaweed Rice Rolls with Egg & Vegetables)","es":"Gimbap: rollos de arroz y alga con huevo y verduras"},"ing":{"en":["2 cups short-grain rice","5 sheets nori seaweed","4 eggs","2 carrots, in thin sticks","2 cups spinach","1 cucumber, in sticks","1 tbsp sesame oil","1 tbsp sesame seeds"],"es":["2 tazas arroz de grano corto","5 hojas de alga nori","4 huevos","2 zanahorias en bastones finos","2 tazas espinaca","1 pepino en bastones","1 cda aceite de sésamo","1 cda semillas de sésamo"]},"steps":{"en":["Cook the rice and season with sesame oil and salt.","Make a thin omelette and cut into strips; sauté the carrot and wilt the spinach.","Spread rice on nori, line up the fillings, roll tightly and slice; sprinkle with sesame."],"es":["Cociná el arroz y condimentalo con aceite de sésamo y sal.","Hacé una omelette fina y cortala en tiras; salteá la zanahoria y rehogá la espinaca.","Esparcí arroz sobre el nori, acomodá los rellenos, enrollá bien y cortá; espolvoreá con sésamo."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"gyeran-jjim","type":"breakfast","country":"KR","group":"egg","name":{"en":"Gyeran Jjim (Fluffy Steamed Eggs) with Rice & Seaweed","es":"Gyeran jjim: huevos al vapor esponjosos con arroz y alga"},"ing":{"en":["6 eggs","1 cup chicken broth","2 spring onions, sliced","1 tsp sesame oil","1 cup short-grain rice","2 sheets nori seaweed"],"es":["6 huevos","1 taza caldo de pollo","2 cebollas de verdeo en rodajas","1 cdita aceite de sésamo","1 taza arroz de grano corto","2 hojas de alga nori"]},"steps":{"en":["Whisk eggs with broth and spring onion.","Cook in a small covered pot on low 10 min until puffed.","Drizzle with sesame oil; serve with rice and nori."],"es":["Batí los huevos con el caldo y el verdeo.","Cociná en una ollita tapada a fuego bajo 10 min, hasta que se infle.","Rociá con aceite de sésamo; serví con arroz y nori."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"goguma","type":"snack","country":"KR","group":"veg","name":{"en":"Roasted Sweet Potatoes (Goguma) with Milk","es":"Batatas asadas (goguma) con leche"},"ing":{"en":["4 small sweet potatoes","2 cups milk","1 tsp cinnamon (optional)"],"es":["4 batatas chicas","2 tazas leche","1 cdita canela (opcional)"]},"steps":{"en":["Wash the sweet potatoes and prick them.","Roast whole at 200°C for 45 min until caramelised.","Serve warm with cold milk."],"es":["Lavá las batatas y pinchalas.","Asalas enteras a 200°C 45 min, hasta que se caramelicen.","Serví tibias con leche fría."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"massaman-curry","type":"dinner","country":"TH","protein":"beef","base":"rice","tags":["curry"],"name":{"en":"Mild Massaman Beef Curry","es":"Curry massaman suave de carne"},"ing":{"en":["600 g beef chuck, diced","2 tbsp red curry paste","1 can coconut milk","3 potatoes, in chunks","1 onion, in wedges","1 cinnamon stick","2 tbsp peanuts, chopped (optional)","1 tbsp fish sauce","1½ cups jasmine rice"],"es":["600 g carne para guiso en cubos","2 cdas pasta de curry rojo","1 lata leche de coco","3 papas en trozos","1 cebolla en gajos","1 rama de canela","2 cdas maní picado (opcional)","1 cda salsa de pescado","1½ tazas arroz jazmín"]},"steps":{"en":["Fry the curry paste in a splash of coconut milk; add the beef and brown.","Add the rest of the coconut milk, cinnamon and 1 cup water and simmer 1 hour.","Add potatoes and onion for 25 min; season with fish sauce, top with peanuts and serve with rice."],"es":["Freí la pasta de curry en un chorrito de leche de coco; sumá la carne y dorala.","Agregá el resto de la leche de coco, la canela y 1 taza de agua y cociná 1 hora.","Sumá las papas y la cebolla 25 min; condimentá con salsa de pescado, sumá el maní y serví con arroz."]},"tip":{"en":"","es":""},"prep":["cook-ahead"]},
{"id":"tom-yum-goong","type":"lunch","country":"TH","protein":"fish","base":"rice","tags":["soup"],"name":{"en":"Tom Yum Goong (Hot & Sour Shrimp Soup)","es":"Tom yum goong: sopa agripicante de langostinos"},"ing":{"en":["400 g shrimp","1 stalk lemongrass, bruised","1 tbsp fresh ginger, sliced","200 g mushrooms, sliced","2 tomatoes, in wedges","3 limes","2 tbsp fish sauce","6 cups chicken broth","1 cup jasmine rice"],"es":["400 g langostinos","1 tallo de lemongrass machacado","1 cda jengibre fresco en láminas","200 g champiñones en láminas","2 tomates en gajos","3 limas","2 cdas salsa de pescado","6 tazas caldo de pollo","1 taza arroz jazmín"]},"steps":{"en":["Simmer lemongrass and ginger in the broth 10 min.","Add mushrooms and tomatoes for 5 min, then shrimp for 3 min.","Season with lime and fish sauce; serve with rice."],"es":["Cociná el lemongrass y el jengibre en el caldo 10 min.","Sumá los champiñones y el tomate 5 min y después los langostinos 3 min.","Condimentá con lima y salsa de pescado; serví con arroz."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"khai-jiao","type":"lunch","country":"TH","protein":"egg","base":"rice","name":{"en":"Khai Jiao (Crispy Thai Omelette) with Rice & Cucumber","es":"Khai jiao: omelette tailandesa crocante con arroz y pepino"},"ing":{"en":["8 eggs","1 tbsp fish sauce","1 tbsp lime juice","3 tbsp sunflower oil","1½ cups jasmine rice","1 cucumber, sliced","2 tbsp mild chili sauce (sambal, optional)"],"es":["8 huevos","1 cda salsa de pescado","1 cda jugo de lima","3 cdas aceite de girasol","1½ tazas arroz jazmín","1 pepino en rodajas","2 cdas salsa de ají suave (sambal, opcional)"]},"steps":{"en":["Beat the eggs hard with fish sauce and lime until frothy.","Pour into very hot oil; it puffs up — cook 1 min, flip and cook 1 min.","Serve over rice with cucumber and chili sauce for grown-ups."],"es":["Batí bien los huevos con la salsa de pescado y la lima hasta que hagan espuma.","Volcá en aceite bien caliente; se infla: cociná 1 min, da vuelta y cociná 1 min.","Serví sobre arroz con pepino y salsa de ají para los grandes."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"pisang-goreng","type":"snack","country":"ID","group":"fruit","name":{"en":"Pisang Goreng (Crispy Battered Bananas)","es":"Pisang goreng: bananas rebozadas crocantes"},"ing":{"en":["4 bananas, halved lengthwise","½ cup flour","2 tbsp cornstarch","½ cup water","3 tbsp sunflower oil"],"es":["4 bananas cortadas a lo largo","½ taza harina","2 cdas maicena","½ taza agua","3 cdas aceite de girasol"]},"steps":{"en":["Whisk flour, cornstarch, water and a pinch of salt into a batter.","Dip the bananas and pan-fry 2 min a side until golden.","Drain and serve warm."],"es":["Batí la harina, la maicena, el agua y una pizca de sal.","Pasá las bananas por la mezcla y doralas en sartén 2 min por lado.","Escurrí y serví tibias."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"bo-luc-lac","type":"dinner","country":"VN","protein":"beef","base":"rice","name":{"en":"Bò Lúc Lắc (Shaking Beef) with Rice & Watercress","es":"Bò lúc lắc: carne salteada con arroz y berro"},"ing":{"en":["600 g beef sirloin, in cubes","2 tbsp soy sauce","1 tbsp oyster sauce","3 garlic cloves, minced","1 red onion, in wedges","2 cups watercress or mixed greens","2 tomatoes, sliced","1 lime","1½ cups jasmine rice"],"es":["600 g lomo en cubos","2 cdas salsa de soja","1 cda salsa de ostras","3 dientes de ajo picados","1 cebolla morada en gajos","2 tazas berro u hojas verdes","2 tomates en rodajas","1 lima","1½ tazas arroz jazmín"]},"steps":{"en":["Marinate the beef in soy, oyster sauce and garlic 20 min.","Sear over very high heat 2 min, shaking the pan; add onion for 1 min.","Serve over greens and tomato with lime and rice."],"es":["Mariná la carne con la soja, la salsa de ostras y el ajo 20 min.","Saltá a fuego muy fuerte 2 min, sacudiendo la sartén; sumá la cebolla 1 min.","Serví sobre las hojas y el tomate con lima y arroz."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"goi-ga","type":"lunch","country":"VN","protein":"poultry","base":"none","name":{"en":"Gỏi Gà (Chicken & Cabbage Salad with Herbs)","es":"Gỏi gà: ensalada de pollo y repollo con hierbas"},"ing":{"en":["500 g chicken breast","¼ cabbage, finely shredded","1 carrot, in thin sticks","1 red onion, thinly sliced","1 handful fresh herbs (mint, cilantro)","2 limes","1 tbsp fish sauce","1 tbsp sugar","3 tbsp peanuts, chopped (optional)"],"es":["500 g pechuga de pollo","¼ repollo en juliana fina","1 zanahoria en bastones finos","1 cebolla morada en pluma fina","1 puñado de hierbas frescas (menta, cilantro)","2 limas","1 cda salsa de pescado","1 cda azúcar","3 cdas maní picado (opcional)"]},"steps":{"en":["Poach the chicken 15 min; shred.","Whisk lime juice, fish sauce, sugar and 2 tbsp water.","Toss chicken, cabbage, carrot, onion and herbs with the dressing; top with peanuts."],"es":["Herví la pechuga 15 min; desmenuzala.","Batí el jugo de lima, la salsa de pescado, el azúcar y 2 cdas de agua.","Mezclá el pollo, el repollo, la zanahoria, la cebolla y las hierbas con el aderezo; terminá con maní."]},"tip":{"en":"","es":""},"prep":["cook-chicken"]},
{"id":"banh-xeo","type":"lunch","country":"VN","protein":"fish","base":"none","name":{"en":"Bánh Xèo (Crispy Turmeric Crêpes with Shrimp & Sprouts)","es":"Bánh xèo: crepes crocantes de cúrcuma con langostinos y brotes"},"ing":{"en":["1 cup rice flour or flour","1 tsp turmeric","1 can coconut milk","300 g shrimp","2 cups bean sprouts","1 head lettuce","1 handful fresh herbs (mint, cilantro)","2 limes","1 tbsp fish sauce"],"es":["1 taza harina de arroz o común","1 cdita cúrcuma","1 lata leche de coco","300 g langostinos","2 tazas brotes de soja","1 planta de lechuga","1 puñado de hierbas frescas (menta, cilantro)","2 limas","1 cda salsa de pescado"]},"steps":{"en":["Whisk flour, turmeric, coconut milk and ½ cup water into a thin batter.","Fry a few shrimp in an oiled pan, pour a thin layer of batter, add sprouts, cover 2 min and fold.","Wrap pieces in lettuce with herbs; dip in lime and fish sauce."],"es":["Batí la harina, la cúrcuma, la leche de coco y ½ taza de agua.","Saltá unos langostinos en sartén aceitada, volcá una capa fina de mezcla, sumá brotes, tapá 2 min y doblá.","Envolvé trozos en lechuga con hierbas; mojá en lima con salsa de pescado."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"sinh-to-xoai","type":"snack","country":"VN","group":"fruit","tags":["smoothie"],"name":{"en":"Sinh Tố Xoài (Mango Shake)","es":"Sinh tố xoài: batido de mango"},"ing":{"en":["2 mangoes","1 cup milk","½ cup plain yogurt","4 ice cubes"],"es":["2 mangos","1 taza leche","½ taza yogur natural","4 cubitos de hielo"]},"steps":{"en":["Peel and chop the mangoes.","Blend with milk, yogurt and ice.","Serve straight away."],"es":["Pelá y cortá los mangos.","Licuá con la leche, el yogur y el hielo.","Serví enseguida."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"beef-rendang","type":"dinner","country":"ID","protein":"beef","base":"rice","tags":["curry"],"name":{"en":"Beef Rendang (Slow-Cooked Coconut Beef)","es":"Rendang de carne: carne en coco a fuego lento"},"ing":{"en":["800 g beef chuck, diced","1 can coconut milk","2 onions","4 garlic cloves","1 tbsp fresh ginger, grated","1 stalk lemongrass, bruised","1 tsp turmeric","1 cinnamon stick","1½ cups rice"],"es":["800 g carne para guiso en cubos","1 lata leche de coco","2 cebollas","4 dientes de ajo","1 cda jengibre fresco rallado","1 tallo de lemongrass machacado","1 cdita cúrcuma","1 rama de canela","1½ tazas arroz"]},"steps":{"en":["Blend onions, garlic, ginger and turmeric into a paste; fry 5 min.","Add beef, coconut milk, lemongrass and cinnamon and simmer uncovered 2 hours, stirring, until dry and dark.","Serve with rice."],"es":["Procesá la cebolla, el ajo, el jengibre y la cúrcuma; freí la pasta 5 min.","Sumá la carne, la leche de coco, el lemongrass y la canela y cociná destapado 2 horas, revolviendo, hasta que se seque y oscurezca.","Serví con arroz."]},"tip":{"en":"","es":""},"prep":["cook-ahead"]},
{"id":"soto-ayam","type":"lunch","country":"ID","protein":"poultry","base":"rice","tags":["soup"],"name":{"en":"Soto Ayam (Turmeric Chicken Soup)","es":"Soto ayam: sopa de pollo con cúrcuma"},"ing":{"en":["600 g chicken breast","8 cups chicken broth","1 tsp turmeric","1 stalk lemongrass, bruised","1 tbsp fresh ginger, sliced","2 cups bean sprouts","2 eggs, boiled","1 cup rice","2 limes"],"es":["600 g pechuga de pollo","8 tazas caldo de pollo","1 cdita cúrcuma","1 tallo de lemongrass machacado","1 cda jengibre fresco en láminas","2 tazas brotes de soja","2 huevos duros","1 taza arroz","2 limas"]},"steps":{"en":["Simmer the chicken with turmeric, lemongrass and ginger in the broth 20 min; shred.","Cook the rice.","Serve rice, chicken, sprouts and egg in bowls with the hot broth and lime."],"es":["Cociná el pollo con la cúrcuma, el lemongrass y el jengibre en el caldo 20 min; desmenuzalo.","Cociná el arroz.","Serví arroz, pollo, brotes y huevo en bowls con el caldo caliente y lima."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"pork-sinigang","type":"dinner","country":"PH","protein":"pork","base":"rice","tags":["soup"],"name":{"en":"Sinigang (Sour Pork & Vegetable Soup)","es":"Sinigang: sopa agria de cerdo y verduras"},"ing":{"en":["600 g pork shoulder, in chunks","3 tomatoes, quartered","1 onion, quartered","1 radish or 4 small radishes, sliced","300 g green beans","2 cups spinach","3 limes","1 tbsp fish sauce","1½ cups rice"],"es":["600 g bondiola en trozos","3 tomates en cuartos","1 cebolla en cuartos","1 nabo o 4 rabanitos en rodajas","300 g chauchas","2 tazas espinaca","3 limas","1 cda salsa de pescado","1½ tazas arroz"]},"steps":{"en":["Simmer the pork with tomato and onion in 8 cups water for 1 hour.","Add radish and beans for 8 min, then spinach for 1 min.","Sour with lime juice and season with fish sauce; serve with rice."],"es":["Cociná el cerdo con el tomate y la cebolla en 8 tazas de agua 1 hora.","Sumá el rabanito y las chauchas 8 min y después la espinaca 1 min.","Acidificá con jugo de lima y condimentá con salsa de pescado; serví con arroz."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"lumpia-shanghai","type":"lunch","country":"PH","protein":"pork","base":"rice","name":{"en":"Lumpia Shanghai (Baked Pork Spring Rolls) with Rice","es":"Lumpia shanghai: arrolladitos de cerdo al horno con arroz"},"ing":{"en":["400 g ground pork","1 carrot, grated","1 onion, finely chopped","2 garlic cloves, minced","1 egg","16 spring roll wrappers","1½ cups rice","3 tbsp sweet chili sauce or ketchup"],"es":["400 g carne picada de cerdo","1 zanahoria rallada","1 cebolla picada fina","2 dientes de ajo picados","1 huevo","16 masas para arrolladitos primavera","1½ tazas arroz","3 cdas salsa de ají dulce o ketchup"]},"steps":{"en":["Mix pork, carrot, onion, garlic and egg.","Roll thin logs in the wrappers, brush with oil and bake at 210°C for 20 min, turning once.","Serve with rice and the dipping sauce."],"es":["Mezclá el cerdo, la zanahoria, la cebolla, el ajo y el huevo.","Armá rollitos finos con las masas, pincelá con aceite y horneá a 210°C 20 min, dando vuelta una vez.","Serví con arroz y la salsa para mojar."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"tapsilog","type":"breakfast","country":"PH","group":"egg","name":{"en":"Tapsilog (Beef Tapa, Garlic Rice & Egg)","es":"Tapsilog: carne tapa, arroz al ajo y huevo"},"ing":{"en":["300 g beef sirloin, thinly sliced","2 tbsp soy sauce","1 tbsp vinegar","1 tbsp brown sugar","3 cups cooked rice","4 garlic cloves, minced","4 eggs","2 tomatoes, sliced"],"es":["300 g lomo en láminas finas","2 cdas salsa de soja","1 cda vinagre","1 cda azúcar mascabo","3 tazas arroz cocido","4 dientes de ajo picados","4 huevos","2 tomates en rodajas"]},"steps":{"en":["Marinate the beef in soy, vinegar and sugar overnight; fry 3 min.","Fry the garlic until golden and toss the rice in it.","Serve with fried eggs and tomato."],"es":["Mariná la carne con la soja, el vinagre y el azúcar toda la noche; freíla 3 min.","Dorá el ajo y saltá el arroz con él.","Serví con huevos fritos y tomate."]},"tip":{"en":"","es":""},"prep":["marinate"]},
{"id":"mee-goreng","type":"lunch","country":"MY","protein":"poultry","base":"pasta","tags":["stir-fry-noodles"],"name":{"en":"Mee Goreng (Fried Noodles with Chicken & Vegetables)","es":"Mee goreng: fideos fritos con pollo y verduras"},"ing":{"en":["400 g egg noodles","300 g chicken breast, sliced","2 eggs","¼ cabbage, shredded","2 tomatoes, in wedges","2 cups bean sprouts","3 tbsp sweet soy sauce (or soy + honey)","1 tbsp ketchup","1 lime"],"es":["400 g fideos de huevo","300 g pechuga de pollo en tiras","2 huevos","¼ repollo en juliana","2 tomates en gajos","2 tazas brotes de soja","3 cdas salsa de soja dulce (o soja + miel)","1 cda ketchup","1 lima"]},"steps":{"en":["Stir-fry the chicken 5 min; push aside and scramble the eggs.","Add cabbage and tomato for 2 min, then noodles, sauces and sprouts.","Toss 2 min; serve with lime."],"es":["Saltá el pollo 5 min; correlo y revolvé los huevos.","Sumá el repollo y el tomate 2 min y después los fideos, las salsas y los brotes.","Saltá 2 min; serví con lima."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"roti-canai-dal","type":"breakfast","country":"MY","group":"grain","name":{"en":"Roti Canai-Style Flatbread with Mild Dal","es":"Pan plano estilo roti canai con dal suave"},"ing":{"en":["2 cups flour","¾ cup warm water","3 tbsp butter, melted","1 cup red lentils","1 tsp turmeric","1 tsp ground cumin","1 tomato, chopped"],"es":["2 tazas harina","¾ taza agua tibia","3 cdas manteca derretida","1 taza lentejas rojas","1 cdita cúrcuma","1 cdita comino","1 tomate picado"]},"steps":{"en":["Knead flour, water and salt; rest 30 min. Simmer lentils with turmeric, cumin and tomato in 3 cups water 20 min.","Stretch dough thin, brush with butter, fold into squares.","Cook in a pan 3 min a side, scrunch to fluff, and serve with the dal."],"es":["Amasá la harina con el agua y sal; dejá reposar 30 min. Cociná las lentejas con la cúrcuma, el comino y el tomate en 3 tazas de agua 20 min.","Estirá la masa fina, pincelá con manteca y doblá en cuadrados.","Cociná en sartén 3 min por lado, apretá para que se esponje y serví con el dal."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"kottu-roti","type":"dinner","country":"LK","protein":"poultry","base":"bread","name":{"en":"Kottu Roti (Chopped Flatbread Stir-Fry with Chicken)","es":"Kottu roti: salteado de pan plano picado con pollo"},"ing":{"en":["6 flour tortillas or roti, cut into strips","400 g chicken breast, diced","2 eggs","1 onion, sliced","2 carrots, in thin sticks","¼ cabbage, shredded","1 tbsp curry powder","1 cup chicken broth"],"es":["6 tortillas de harina o roti en tiras","400 g pechuga de pollo en cubos","2 huevos","1 cebolla en pluma","2 zanahorias en bastones finos","¼ repollo en juliana","1 cda curry en polvo","1 taza caldo de pollo"]},"steps":{"en":["Stir-fry the chicken with curry powder 5 min.","Add onion, carrot and cabbage for 4 min; scramble the eggs into the pan.","Add the bread strips and broth and chop and toss together 3 min."],"es":["Saltá el pollo con el curry 5 min.","Sumá la cebolla, la zanahoria y el repollo 4 min; revolvé los huevos en la sartén.","Agregá las tiras de pan y el caldo y picá y mezclá todo 3 min."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"exprimido-con-tostadas","type":"breakfast","country":"AR","group":"fruit","tags":["toast"],"name":{"en":"Fresh Orange Juice with Toast & Fresh Cheese","es":"Exprimido de naranja con tostadas y queso blanco"},"ing":{"en":["8 oranges","8 slices bread","150 g cottage cheese or fresh cheese","2 tbsp honey (optional)"],"es":["8 naranjas","8 rebanadas de pan","150 g queso blanco o fresco","2 cdas miel (opcional)"]},"steps":{"en":["Squeeze the oranges.","Toast the bread and spread with fresh cheese.","Add a little honey if you like."],"es":["Exprimí las naranjas.","Tostá el pan y untalo con queso blanco.","Sumá un poco de miel si querés."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"huevos-al-plato-con-tomate","type":"breakfast","country":"AR","group":"egg","name":{"en":"Baked Eggs with Tomato & Cheese","es":"Huevos al plato con tomate y queso"},"ing":{"en":["8 eggs","1 can crushed tomatoes","80 g mozzarella, grated","1 tsp dried oregano","8 slices bread"],"es":["8 huevos","1 lata tomate triturado","80 g mozzarella rallada","1 cdita orégano","8 rebanadas de pan"]},"steps":{"en":["Spread the tomatoes in 4 small oven dishes with a pinch of oregano.","Crack in 2 eggs each and top with cheese.","Bake at 200°C for 12 min; serve with toast."],"es":["Repartí el tomate en 4 cazuelitas con una pizca de orégano.","Rompé 2 huevos en cada una y cubrí con queso.","Horneá a 200°C 12 min; serví con tostadas."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"revuelto-de-acelga","type":"breakfast","country":"AR","group":"egg","name":{"en":"Swiss Chard Scramble with Toast","es":"Revuelto de acelga con tostadas"},"ing":{"en":["1 bunch Swiss chard, shredded","6 eggs","1 onion, chopped","2 tbsp grated parmesan","1 tbsp olive oil","8 slices bread"],"es":["1 atado de acelga en tiras","6 huevos","1 cebolla picada","2 cdas queso parmesano rallado","1 cda aceite de oliva","8 rebanadas de pan"]},"steps":{"en":["Soften the onion in the oil; add the chard and cook 4 min.","Add the beaten eggs and parmesan and stir until just set.","Serve with toast."],"es":["Rehogá la cebolla en el aceite; sumá la acelga y cociná 4 min.","Agregá los huevos batidos y el parmesano y revolvé hasta que apenas cuajen.","Serví con tostadas."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"tostadas-de-campo-con-palta-y-tomate","type":"breakfast","country":"AR","group":"grain","tags":["toast"],"name":{"en":"Country Bread with Avocado, Tomato & Oregano","es":"Tostadas de pan de campo con palta, tomate y orégano"},"ing":{"en":["8 slices crusty bread","2 ripe avocados","2 tomatoes, sliced","1 tsp dried oregano","1 tbsp olive oil","2 cups milk"],"es":["8 rebanadas de pan de campo","2 paltas maduras","2 tomates en rodajas","1 cdita orégano","1 cda aceite de oliva","2 tazas leche"]},"steps":{"en":["Toast the bread.","Mash the avocado with salt and spread; top with tomato, oregano and oil.","Serve with warm milk."],"es":["Tostá el pan.","Pisá la palta con sal y untá; cubrí con tomate, orégano y aceite.","Serví con leche tibia."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"yogur-con-granola-casera","type":"breakfast","country":"AR","group":"dairy","tags":["yogurt"],"name":{"en":"Yogurt with Homemade Honey Granola","es":"Yogur con granola casera de miel"},"ing":{"en":["2 cups rolled oats","2 tbsp honey","2 tbsp sunflower oil","3 tbsp sunflower seeds","2 tbsp raisins","3 cups plain yogurt","2 bananas"],"es":["2 tazas avena arrollada","2 cdas miel","2 cdas aceite de girasol","3 cdas semillas de girasol","2 cdas pasas de uva","3 tazas yogur natural","2 bananas"]},"steps":{"en":["Mix oats, honey, oil and seeds; bake at 170°C for 20 min, stirring once; add the raisins.","Spoon the yogurt into bowls.","Top with banana and the granola (it keeps a week in a jar)."],"es":["Mezclá la avena, la miel, el aceite y las semillas; horneá a 170°C 20 min, revolviendo una vez; sumá las pasas.","Serví el yogur en compoteras.","Sumá banana y la granola (dura una semana en un frasco)."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"torrejas","type":"breakfast","country":"AR","group":"grain","tags":["pancakes"],"name":{"en":"Torrejas (Argentine French Toast) with Fruit","es":"Torrejas con fruta"},"ing":{"en":["8 slices day-old bread","2 eggs","1 cup milk","1 tsp cinnamon","1 tbsp butter","2 cups strawberries"],"es":["8 rebanadas de pan del día anterior","2 huevos","1 taza leche","1 cdita canela","1 cda manteca","2 tazas frutillas"]},"steps":{"en":["Whisk eggs, milk and cinnamon.","Soak the bread and cook in butter 2 min a side.","Serve with strawberries."],"es":["Batí los huevos, la leche y la canela.","Remojá el pan y cocinalo en manteca 2 min por lado.","Serví con frutillas."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"licuado-de-banana-y-frutilla","type":"breakfast","country":"AR","group":"fruit","tags":["smoothie"],"name":{"en":"Banana & Strawberry Licuado with Cheese Toast","es":"Licuado de banana y frutilla con tostado de queso"},"ing":{"en":["2 bananas","2 cups strawberries","3 cups milk","8 slices sandwich bread","100 g mild cheese, sliced"],"es":["2 bananas","2 tazas frutillas","3 tazas leche","8 rebanadas de pan de molde","100 g queso de máquina en fetas"]},"steps":{"en":["Blend the fruit with the milk.","Make cheese toasties in a pan.","Serve together."],"es":["Licuá la fruta con la leche.","Hacé tostados de queso en sartén.","Serví todo junto."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"chocotorta","type":"snack","country":"AR","group":"dairy","tags":["cake"],"name":{"en":"Chocotorta (No-Bake Chocolate Cookie Cake)","es":"Chocotorta"},"ing":{"en":["24 chocolate cookies","250 g cream cheese","½ cup dulce de leche","1 cup milk"],"es":["24 galletitas de chocolate","250 g queso crema","½ taza dulce de leche","1 taza leche"]},"steps":{"en":["Beat the cream cheese with the dulce de leche.","Dip the cookies quickly in milk and layer with the cream in a dish.","Chill 4 hours; serve small squares."],"es":["Batí el queso crema con el dulce de leche.","Pasá las galletitas rápido por leche y armá capas con la crema en una fuente.","Enfriá 4 horas; serví cuadraditos."]},"tip":{"en":"A party treat — small squares go a long way.","es":"Es un gusto de fiesta: con cuadraditos chicos alcanza."},"prep":["chill-ahead"]},
{"id":"budin-de-pan","type":"snack","country":"AR","group":"dairy","tags":["cake"],"name":{"en":"Budín de Pan (Bread Pudding)","es":"Budín de pan"},"ing":{"en":["6 slices day-old bread","3 cups milk","3 eggs","⅓ cup sugar","3 tbsp raisins","1 tsp vanilla extract","1 orange (zest)"],"es":["6 rebanadas de pan del día anterior","3 tazas leche","3 huevos","⅓ taza azúcar","3 cdas pasas de uva","1 cdita esencia de vainilla","1 naranja (ralladura)"]},"steps":{"en":["Soak the bread in the milk and mash.","Beat in eggs, sugar, vanilla, zest and raisins.","Bake in a buttered loaf tin in a water bath at 180°C for 50 min; chill."],"es":["Remojá el pan en la leche y pisalo.","Incorporá los huevos, el azúcar, la vainilla, la ralladura y las pasas.","Horneá en molde enmantecado a baño María a 180°C 50 min; enfriá."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"galletitas-de-limon","type":"snack","country":"AR","group":"grain","tags":["cookies"],"name":{"en":"Lemon Butter Cookies","es":"Galletitas de limón"},"ing":{"en":["2 cups flour","100 g butter, soft","⅓ cup sugar","1 egg","1 lemon (zest)","1 tsp baking powder"],"es":["2 tazas harina","100 g manteca blanda","⅓ taza azúcar","1 huevo","1 limón (ralladura)","1 cdita polvo para hornear"]},"steps":{"en":["Beat butter and sugar, add egg and zest, then flour and baking powder.","Roll out and cut shapes.","Bake at 180°C for 12 min."],"es":["Batí la manteca con el azúcar, sumá el huevo y la ralladura y después la harina y el polvo de hornear.","Estirá y cortá formas.","Horneá a 180°C 12 min."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"faina","type":"snack","country":"AR","group":"grain","name":{"en":"Fainá (Chickpea Flatbread)","es":"Fainá"},"ing":{"en":["1½ cups chickpea flour","3 cups water","4 tbsp olive oil","½ tsp black peppercorns, crushed"],"es":["1½ tazas harina de garbanzo","3 tazas agua","4 cdas aceite de oliva","½ cdita pimienta en grano machacada"]},"steps":{"en":["Whisk chickpea flour, water and salt; rest 1 hour.","Heat the oil in a pizza tin at 250°C, pour in the batter.","Bake 15 min until set and golden; sprinkle with pepper."],"es":["Batí la harina de garbanzo con el agua y sal; dejá reposar 1 hora.","Calentá el aceite en una pizzera a 250°C y volcá la mezcla.","Horneá 15 min, hasta que cuaje y se dore; espolvoreá con pimienta."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"ensalada-de-frutas-de-estacion","type":"snack","country":"AR","group":"fruit","name":{"en":"Seasonal Fruit Salad with Orange Juice","es":"Ensalada de frutas de estación con jugo de naranja"},"ing":{"en":["2 apples","2 bananas","2 peaches","1 cup strawberries","2 tangerines","2 oranges (juice)"],"es":["2 manzanas","2 bananas","2 duraznos","1 taza frutillas","2 mandarinas","2 naranjas (jugo)"]},"steps":{"en":["Dice the fruit.","Pour over the orange juice and stir.","Chill 20 min."],"es":["Cortá la fruta en cubos.","Bañá con el jugo de naranja y mezclá.","Enfriá 20 min."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"tostado-de-jamon-queso-y-tomate","type":"snack","country":"AR","group":"grain","tags":["toast"],"name":{"en":"Ham, Cheese & Tomato Toastie with Chocolate Milk","es":"Tostado de jamón, queso y tomate con chocolatada"},"ing":{"en":["8 slices sandwich bread","100 g cooked ham","100 g mild cheese, sliced","1 tomato, sliced","3 cups milk","2 tbsp cocoa powder"],"es":["8 rebanadas de pan de molde","100 g jamón cocido","100 g queso de máquina en fetas","1 tomate en rodajas","3 tazas leche","2 cdas cacao en polvo"]},"steps":{"en":["Fill the bread with ham, cheese and tomato.","Toast in a pan, pressing, 3 min a side.","Serve with warm chocolate milk."],"es":["Rellená el pan con jamón, queso y tomate.","Tostá en sartén, apretando, 3 min por lado.","Serví con chocolatada tibia."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"banana-con-dulce-de-leche-y-nueces","type":"snack","country":"AR","group":"fruit","name":{"en":"Banana with a Spoon of Dulce de Leche & Walnuts","es":"Banana con una cucharadita de dulce de leche y nueces"},"ing":{"en":["4 bananas","4 tsp dulce de leche","2 tbsp walnuts, chopped"],"es":["4 bananas","4 cditas dulce de leche","2 cdas nueces picadas"]},"steps":{"en":["Slice the bananas into rounds.","Add a teaspoon of dulce de leche to each plate.","Sprinkle walnuts over (ground for little ones)."],"es":["Cortá las bananas en rodajas.","Sumá una cucharadita de dulce de leche a cada plato.","Espolvoreá nueces (molidas para los más chicos)."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"zanahoria-y-pepino-con-limon","type":"snack","country":"AR","group":"veg","name":{"en":"Carrot & Cucumber Sticks with Lemon & Salt","es":"Bastones de zanahoria y pepino con limón y sal"},"ing":{"en":["3 carrots","2 cucumbers","1 lemon","4 slices cheese"],"es":["3 zanahorias","2 pepinos","1 limón","4 fetas de queso"]},"steps":{"en":["Cut the vegetables into sticks.","Squeeze lemon over with a pinch of salt.","Serve with cheese."],"es":["Cortá las verduras en bastones.","Exprimí limón por encima con una pizca de sal.","Serví con queso."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"yogur-con-frutillas-y-avena","type":"snack","country":"AR","group":"dairy","tags":["yogurt"],"name":{"en":"Strawberry Yogurt Pots with Toasted Oats","es":"Vasitos de yogur con frutilla y avena tostada"},"ing":{"en":["3 cups plain yogurt","2 cups strawberries","½ cup rolled oats","1 tbsp honey"],"es":["3 tazas yogur natural","2 tazas frutillas","½ taza avena arrollada","1 cda miel"]},"steps":{"en":["Toast the oats in a dry pan with the honey 4 min.","Mash half the strawberries into the yogurt.","Layer with the rest of the strawberries and the oats."],"es":["Tostá la avena en sartén seca con la miel 4 min.","Pisá la mitad de las frutillas con el yogur.","Armá capas con el resto de las frutillas y la avena."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"empanadas-tucumanas","type":"lunch","country":"AR","protein":"beef","base":"bread","tags":["empanadas"],"name":{"en":"Tucumán-Style Knife-Cut Beef Empanadas","es":"Empanadas tucumanas de carne cortada a cuchillo"},"ing":{"en":["12 empanada discs","500 g beef sirloin, finely diced","3 spring onions, sliced","1 onion, chopped","2 eggs, boiled and chopped","1 tsp ground cumin","1 tsp paprika","1 lemon"],"es":["12 tapas de empanadas","500 g carne cortada a cuchillo","3 cebollas de verdeo en rodajas","1 cebolla picada","2 huevos duros picados","1 cdita comino","1 cdita pimentón","1 limón"]},"steps":{"en":["Sear the beef quickly; soften the onions separately with the spices.","Mix with egg and a squeeze of lemon; cool.","Fill, seal and bake at 220°C for 15 min."],"es":["Sellá la carne rápido; rehogá las cebollas aparte con las especias.","Mezclá con el huevo y un chorrito de limón; enfriá.","Rellená, cerrá y horneá a 220°C 15 min."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"tarta-de-jamon-y-queso","type":"lunch","country":"AR","protein":"pork","base":"bread","tags":["tart"],"name":{"en":"Ham & Cheese Tart with Salad","es":"Tarta de jamón y queso con ensalada"},"ing":{"en":["2 pie crusts","200 g cooked ham, diced","200 g mozzarella, diced","3 eggs","½ cup milk","1 onion, chopped","1 head lettuce","2 tomatoes"],"es":["2 tapas de tarta","200 g jamón cocido en cubos","200 g mozzarella en cubos","3 huevos","½ taza leche","1 cebolla picada","1 planta de lechuga","2 tomates"]},"steps":{"en":["Soften the onion; mix with ham, cheese, eggs and milk.","Fill the lined tin and cover with the second crust.","Bake at 200°C for 35 min; serve with salad."],"es":["Rehogá la cebolla; mezclá con el jamón, el queso, los huevos y la leche.","Rellená la tartera forrada y tapá con la otra masa.","Horneá a 200°C 35 min; serví con ensalada."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"fideos-con-brocoli","type":"lunch","country":"AR","protein":"plant","base":"pasta","name":{"en":"Pasta with Broccoli, Garlic & Cheese","es":"Fideos con brócoli, ajo y queso"},"ing":{"en":["400 g short pasta","1 head broccoli, in florets","3 garlic cloves, sliced","3 tbsp olive oil","½ cup grated parmesan","1 lemon (zest)"],"es":["400 g pasta corta","1 brócoli en ramitos","3 dientes de ajo en láminas","3 cdas aceite de oliva","½ taza queso parmesano rallado","1 limón (ralladura)"]},"steps":{"en":["Cook the pasta, adding the broccoli for the last 4 min.","Warm the garlic in the oil.","Toss everything with parmesan, lemon zest and a splash of pasta water."],"es":["Cociná la pasta y sumá el brócoli los últimos 4 min.","Calentá el ajo en el aceite.","Mezclá todo con el parmesano, la ralladura y un chorrito del agua de cocción."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"croquetas-de-arroz","type":"lunch","country":"AR","protein":"plant","base":"rice","name":{"en":"Rice & Cheese Croquettes with Tomato Salad","es":"Croquetas de arroz y queso con ensalada de tomate"},"ing":{"en":["3 cups cooked rice","150 g mozzarella, diced","2 eggs","4 tbsp grated parmesan","1 cup breadcrumbs","3 tomatoes","1 red onion, thinly sliced"],"es":["3 tazas arroz cocido","150 g mozzarella en cubitos","2 huevos","4 cdas queso parmesano rallado","1 taza pan rallado","3 tomates","1 cebolla morada en pluma fina"]},"steps":{"en":["Mix rice, 1 egg and parmesan; shape croquettes around a cube of mozzarella.","Dip in the other egg and breadcrumbs; bake at 210°C for 20 min.","Serve with tomato and onion salad."],"es":["Mezclá el arroz, 1 huevo y el parmesano; formá croquetas con un cubito de mozzarella adentro.","Pasalas por el otro huevo y pan rallado; horneá a 210°C 20 min.","Serví con ensalada de tomate y cebolla."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"bunuelos-de-acelga","type":"lunch","country":"AR","protein":"plant","base":"potato","name":{"en":"Swiss Chard Fritters with Mashed Pumpkin","es":"Buñuelos de acelga con puré de calabaza"},"ing":{"en":["1 bunch Swiss chard","2 eggs","½ cup flour","1 tsp baking powder","3 tbsp grated parmesan","3 tbsp sunflower oil","800 g pumpkin"],"es":["1 atado de acelga","2 huevos","½ taza harina","1 cdita polvo para hornear","3 cdas queso parmesano rallado","3 cdas aceite de girasol","800 g calabaza"]},"steps":{"en":["Blanch and chop the chard; mix with eggs, flour, baking powder and cheese.","Fry spoonfuls in the oil 2 min a side.","Boil and mash the pumpkin to serve alongside."],"es":["Blanqueá y picá la acelga; mezclala con los huevos, la harina, el polvo de hornear y el queso.","Freí cucharadas en el aceite 2 min por lado.","Herví la calabaza y hacé puré para acompañar."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"salpicon-de-atun","type":"lunch","country":"AR","protein":"fish","base":"potato","tags":["tuna"],"name":{"en":"Tuna Salpicón with Potatoes & Egg","es":"Salpicón de atún con papas y huevo"},"ing":{"en":["2 cans tuna, drained","4 potatoes, boiled and diced","3 eggs, boiled","1 red bell pepper, diced","1 cup corn","2 tbsp mayonnaise","1 lemon"],"es":["2 latas atún escurrido","4 papas hervidas en cubos","3 huevos duros","1 morrón rojo en cubos","1 taza choclo","2 cdas mayonesa","1 limón"]},"steps":{"en":["Dice the vegetables and eggs.","Flake in the tuna.","Dress with mayonnaise and lemon."],"es":["Cortá las verduras y los huevos en cubos.","Sumá el atún desmenuzado.","Condimentá con mayonesa y limón."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"pan-de-carne","type":"lunch","country":"AR","protein":"beef","base":"potato","name":{"en":"Pan de Carne (Meatloaf with Egg) & Potato Salad","es":"Pan de carne con huevo y ensalada de papas"},"ing":{"en":["600 g ground beef","1 egg","½ cup breadcrumbs","1 onion, grated","3 eggs, boiled","800 g potatoes","2 tbsp mayonnaise","2 tbsp fresh parsley, chopped"],"es":["600 g carne picada","1 huevo","½ taza pan rallado","1 cebolla rallada","3 huevos duros","800 g papas","2 cdas mayonesa","2 cdas perejil fresco picado"]},"steps":{"en":["Mix beef, egg, breadcrumbs, onion and parsley; press half into a loaf tin, lay the boiled eggs in a row and cover with the rest.","Bake at 190°C for 45 min.","Serve sliced with potato salad."],"es":["Mezclá la carne, el huevo, el pan rallado, la cebolla y el perejil; poné la mitad en un molde, acomodá los huevos duros en fila y cubrí con el resto.","Horneá a 190°C 45 min.","Serví en rodajas con ensalada de papas."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"ensalada-rusa-con-huevo","type":"lunch","country":"AR","protein":"egg","base":"potato","name":{"en":"Russian Salad with Egg","es":"Ensalada rusa con huevo"},"ing":{"en":["4 potatoes, diced","2 carrots, diced","1½ cups frozen peas","4 eggs, boiled","3 tbsp mayonnaise","1 lemon","1 head lettuce"],"es":["4 papas en cubos","2 zanahorias en cubos","1½ tazas arvejas congeladas","4 huevos duros","3 cdas mayonesa","1 limón","1 planta de lechuga"]},"steps":{"en":["Boil the potatoes, carrots and peas until just tender; cool.","Mix with mayonnaise and lemon.","Serve on lettuce with quartered eggs."],"es":["Herví las papas, las zanahorias y las arvejas hasta que estén tiernas; enfriá.","Mezclá con mayonesa y limón.","Serví sobre lechuga con huevos en cuartos."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"pollo-a-la-mostaza","type":"dinner","country":"AR","protein":"poultry","base":"potato","name":{"en":"Mustard Chicken with Mashed Potatoes","es":"Pollo a la mostaza con puré"},"ing":{"en":["800 g chicken thighs","2 tbsp Dijon mustard","½ cup cream","1 onion, chopped","1 kg potatoes","½ cup milk","1 tbsp butter"],"es":["800 g muslos de pollo","2 cdas mostaza Dijon","½ taza crema de leche","1 cebolla picada","1 kg papas","½ taza leche","1 cda manteca"]},"steps":{"en":["Brown the chicken; add onion and cook 5 min.","Stir in mustard, cream and ½ cup water; cover and simmer 25 min.","Serve with mashed potatoes."],"es":["Dorá el pollo; sumá la cebolla y cociná 5 min.","Incorporá la mostaza, la crema y ½ taza de agua; tapá y cociná 25 min.","Serví con puré."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"canelones-de-carne","type":"dinner","country":"AR","protein":"beef","base":"pasta","tags":["lasagna"],"name":{"en":"Beef Cannelloni with Tomato & White Sauce","es":"Canelones de carne con salsa de tomate y blanca"},"ing":{"en":["12 crêpes or cannelloni tubes","500 g ground beef","1 onion, chopped","1 bunch Swiss chard, chopped","1 can crushed tomatoes","2 tbsp butter","2 tbsp flour","2 cups milk","4 tbsp grated parmesan"],"es":["12 panqueques o canelones","500 g carne picada","1 cebolla picada","1 atado de acelga picada","1 lata tomate triturado","2 cdas manteca","2 cdas harina","2 tazas leche","4 cdas queso parmesano rallado"]},"steps":{"en":["Brown the beef with the onion; add the chard and cook 5 min.","Make a white sauce with butter, flour and milk.","Fill and roll the crêpes, cover with tomato, white sauce and parmesan; bake at 200°C for 20 min."],"es":["Dorá la carne con la cebolla; sumá la acelga y cociná 5 min.","Hacé una salsa blanca con la manteca, la harina y la leche.","Rellená y enrollá, cubrí con tomate, salsa blanca y parmesano; horneá a 200°C 20 min."]},"tip":{"en":"","es":""},"prep":["brown-beef"]},
{"id":"pizza-de-molde","type":"dinner","country":"AR","protein":"plant","base":"bread","tags":["pizza"],"name":{"en":"Thick Pan Pizza with Mozzarella & Olives","es":"Pizza de molde con mozzarella y aceitunas"},"ing":{"en":["500 g pizza dough","1 cup tomato sauce","300 g mozzarella, sliced","¼ cup green olives","1 tsp dried oregano","1 head lettuce"],"es":["500 g masa de pizza","1 taza salsa de tomate","300 g mozzarella en fetas","¼ taza aceitunas verdes","1 cdita orégano","1 planta de lechuga"]},"steps":{"en":["Press the dough into an oiled pan and let it rise 30 min.","Spread with sauce and bake at 220°C for 12 min.","Add mozzarella, olives and oregano and bake 8 min more; serve with salad."],"es":["Estirá la masa en una pizzera aceitada y dejala levar 30 min.","Untá con la salsa y horneá a 220°C 12 min.","Sumá la mozzarella, las aceitunas y el orégano y horneá 8 min más; serví con ensalada."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"merluza-con-pure-de-calabaza","type":"dinner","country":"AR","protein":"fish","base":"potato","name":{"en":"Baked Hake with Pumpkin Mash","es":"Merluza al horno con puré de calabaza"},"ing":{"en":["4 hake fillets","2 tbsp olive oil","2 tbsp fresh parsley, chopped","1 lemon","800 g pumpkin","2 potatoes","1 tbsp butter"],"es":["4 filetes de merluza","2 cdas aceite de oliva","2 cdas perejil fresco picado","1 limón","800 g calabaza","2 papas","1 cda manteca"]},"steps":{"en":["Boil pumpkin and potatoes; mash with butter.","Season the hake with oil, lemon and parsley and bake at 200°C for 12 min.","Serve together."],"es":["Herví la calabaza y las papas; hacé puré con manteca.","Condimentá la merluza con aceite, limón y perejil y horneá a 200°C 12 min.","Serví todo junto."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"morrones-rellenos","type":"dinner","country":"AR","protein":"beef","base":"rice","name":{"en":"Peppers Stuffed with Beef & Rice","es":"Morrones rellenos de carne y arroz"},"ing":{"en":["4 bell peppers","400 g ground beef","1 cup cooked rice","1 onion, chopped","1 can crushed tomatoes","100 g mozzarella, grated"],"es":["4 morrones","400 g carne picada","1 taza arroz cocido","1 cebolla picada","1 lata tomate triturado","100 g mozzarella rallada"]},"steps":{"en":["Halve and seed the peppers.","Brown the beef with the onion, add rice and half the tomatoes.","Fill the peppers, pour the rest of the tomato around, top with cheese and bake at 190°C for 35 min."],"es":["Cortá los morrones al medio y sacales las semillas.","Dorá la carne con la cebolla, sumá el arroz y la mitad del tomate.","Rellená los morrones, volcá el resto del tomate alrededor, cubrí con queso y horneá a 190°C 35 min."]},"tip":{"en":"","es":""},"prep":["brown-beef"]},
{"id":"calabaza-rellena","type":"dinner","country":"AR","protein":"plant","base":"none","name":{"en":"Stuffed Butternut Squash with Corn & Cheese","es":"Calabaza rellena de choclo y queso"},"ing":{"en":["2 butternut squash, halved","2 cups corn","1 onion, chopped","1 red bell pepper, chopped","½ cup milk","150 g mozzarella, grated","2 cups mixed greens"],"es":["2 calabazas en mitades","2 tazas choclo","1 cebolla picada","1 morrón rojo picado","½ taza leche","150 g mozzarella rallada","2 tazas hojas verdes variadas"]},"steps":{"en":["Roast the squash halves at 200°C for 40 min; scoop some flesh out.","Soften onion and pepper, add corn, milk and the scooped flesh.","Fill the squash, top with cheese and bake 10 min; serve with greens."],"es":["Asá las mitades de calabaza a 200°C 40 min; sacá un poco de pulpa.","Rehogá la cebolla y el morrón, sumá el choclo, la leche y la pulpa.","Rellená la calabaza, cubrí con queso y horneá 10 min; serví con hojas verdes."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"arrollado-de-pollo","type":"dinner","country":"AR","protein":"poultry","base":"potato","name":{"en":"Rolled Chicken with Ham, Cheese & Vegetables","es":"Arrollado de pollo con jamón, queso y verduras"},"ing":{"en":["4 chicken breasts, butterflied","4 slices cooked ham","4 slices mozzarella","1 carrot, grated","1 cup spinach","800 g potatoes, in wedges","2 tbsp olive oil"],"es":["4 pechugas abiertas","4 fetas de jamón cocido","4 fetas de mozzarella","1 zanahoria rallada","1 taza espinaca","800 g papas en gajos","2 cdas aceite de oliva"]},"steps":{"en":["Flatten the chicken, layer ham, cheese, carrot and spinach and roll up; tie or use toothpicks.","Roast with the potato wedges and oil at 200°C for 35 min.","Slice into rounds to serve."],"es":["Aplaná las pechugas, poné jamón, queso, zanahoria y espinaca y enrollá; atá o usá palillos.","Asá con las papas en gajos y el aceite a 200°C 35 min.","Cortá en rodajas para servir."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"bife-con-ensalada-mixta","type":"dinner","country":"AR","protein":"beef","base":"potato","name":{"en":"Grilled Steak with Mixed Salad & Baked Potatoes","es":"Bife a la plancha con ensalada mixta y papas al horno"},"ing":{"en":["4 beef steaks","800 g potatoes, in wedges","1 head lettuce","2 tomatoes","1 onion","3 tbsp olive oil","1 tbsp vinegar"],"es":["4 bifes","800 g papas en gajos","1 planta de lechuga","2 tomates","1 cebolla","3 cdas aceite de oliva","1 cda vinagre"]},"steps":{"en":["Roast the potatoes with a little oil at 220°C for 35 min.","Sear the steaks to taste.","Dress lettuce, tomato and onion with oil, vinegar and salt."],"es":["Asá las papas con un poco de aceite a 220°C 35 min.","Cociná los bifes a gusto.","Condimentá la lechuga, el tomate y la cebolla con aceite, vinagre y sal."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"fideos-con-tuco-y-albondigas","type":"dinner","country":"AR","protein":"beef","base":"pasta","tags":["meatballs"],"name":{"en":"Pasta with Tuco & Meatballs","es":"Fideos con tuco y albóndigas"},"ing":{"en":["400 g spaghetti","400 g ground beef","1 egg","½ cup breadcrumbs","2 cans crushed tomatoes","1 onion, chopped","1 red bell pepper, chopped","4 tbsp grated parmesan"],"es":["400 g spaghetti","400 g carne picada","1 huevo","½ taza pan rallado","2 latas tomate triturado","1 cebolla picada","1 morrón rojo picado","4 cdas queso parmesano rallado"]},"steps":{"en":["Mix beef, egg and breadcrumbs; roll small meatballs and brown.","Soften onion and pepper, add tomatoes and simmer 15 min; add the meatballs for 20 min.","Serve over the pasta with parmesan."],"es":["Mezclá la carne, el huevo y el pan rallado; formá albondiguitas y doralas.","Rehogá la cebolla y el morrón, sumá el tomate y cociná 15 min; agregá las albóndigas 20 min.","Serví sobre la pasta con parmesano."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"pescado-con-salsa-criolla","type":"dinner","country":"AR","protein":"fish","base":"rice","name":{"en":"Grilled Fish with Salsa Criolla & Rice","es":"Pescado a la plancha con salsa criolla y arroz"},"ing":{"en":["4 white fish fillets","2 tomatoes, finely diced","1 red onion, finely chopped","1 red bell pepper, finely diced","2 tbsp vinegar","3 tbsp olive oil","1½ cups rice"],"es":["4 filetes de pescado blanco","2 tomates en cubitos","1 cebolla morada picada fina","1 morrón rojo en cubitos","2 cdas vinagre","3 cdas aceite de oliva","1½ tazas arroz"]},"steps":{"en":["Mix tomato, onion, pepper, vinegar and oil for the salsa criolla.","Cook the fish on a hot griddle 3 min a side.","Serve with rice and the salsa."],"es":["Mezclá el tomate, la cebolla, el morrón, el vinagre y el aceite para la salsa criolla.","Cociná el pescado en plancha caliente 3 min por lado.","Serví con arroz y la salsa."]},"tip":{"en":"","es":""},"prep":["rice"]},
{"id":"guiso-de-arroz","type":"dinner","country":"AR","protein":"poultry","base":"rice","tags":["stew"],"name":{"en":"Guiso de Arroz con Pollo y Verduras","es":"Guiso de arroz con pollo y verduras"},"ing":{"en":["600 g chicken thighs, in pieces","1½ cups rice","1 onion, chopped","1 red bell pepper, chopped","2 carrots, diced","1 cup frozen peas","1 tsp paprika","4 cups chicken broth"],"es":["600 g muslos de pollo en trozos","1½ tazas arroz","1 cebolla picada","1 morrón rojo picado","2 zanahorias en cubos","1 taza arvejas congeladas","1 cdita pimentón","4 tazas caldo de pollo"]},"steps":{"en":["Brown the chicken with onion, pepper and paprika.","Add carrots, rice and broth; simmer 20 min, stirring now and then.","Add the peas for the last 5 min; it should be soupy."],"es":["Dorá el pollo con la cebolla, el morrón y el pimentón.","Sumá las zanahorias, el arroz y el caldo; cociná 20 min, revolviendo de vez en cuando.","Agregá las arvejas los últimos 5 min; tiene que quedar caldoso."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"chicken-sausage-gumbo","type":"dinner","country":"US","protein":"poultry","base":"rice","tags":["stew"],"name":{"en":"Chicken & Sausage Gumbo with Rice","es":"Gumbo de pollo y salchicha con arroz"},"ing":{"en":["600 g chicken thighs, diced","1 smoked sausage, sliced","⅓ cup flour","⅓ cup sunflower oil","1 onion, chopped","1 green bell pepper, chopped","2 celery stalks, chopped","200 g okra, sliced","4 cups chicken broth","1½ cups rice"],"es":["600 g muslos de pollo en cubos","1 salchicha ahumada en rodajas","⅓ taza harina","⅓ taza aceite de girasol","1 cebolla picada","1 morrón verde picado","2 tallos de apio picados","200 g okra en rodajas","4 tazas caldo de pollo","1½ tazas arroz"]},"steps":{"en":["Cook the flour in the oil, stirring, for 15 min until peanut-brown (the roux).","Add onion, pepper and celery, then broth, chicken, sausage and okra; simmer 40 min.","Serve over rice."],"es":["Cociná la harina en el aceite, revolviendo, 15 min hasta que tome color maní (el roux).","Sumá la cebolla, el morrón y el apio y después el caldo, el pollo, la salchicha y la okra; cociná 40 min.","Serví sobre arroz."]},"tip":{"en":"","es":""},"prep":["rice"]},
{"id":"jambalaya","type":"dinner","country":"US","protein":"poultry","base":"rice","name":{"en":"Chicken & Shrimp Jambalaya","es":"Jambalaya de pollo y langostinos"},"ing":{"en":["500 g chicken thighs, diced","300 g shrimp","1 smoked sausage, sliced","1½ cups rice","1 onion, chopped","1 green bell pepper, chopped","2 celery stalks, chopped","1 can crushed tomatoes","1 tsp smoked paprika","3 cups chicken broth"],"es":["500 g muslos de pollo en cubos","300 g langostinos","1 salchicha ahumada en rodajas","1½ tazas arroz","1 cebolla picada","1 morrón verde picado","2 tallos de apio picados","1 lata tomate triturado","1 cdita pimentón ahumado","3 tazas caldo de pollo"]},"steps":{"en":["Brown chicken and sausage; add onion, pepper, celery and paprika.","Add rice, tomatoes and broth; cover and cook 20 min.","Stir in the shrimp, cover 5 min more."],"es":["Dorá el pollo y la salchicha; sumá la cebolla, el morrón, el apio y el pimentón.","Agregá el arroz, el tomate y el caldo; tapá y cociná 20 min.","Incorporá los langostinos y tapá 5 min más."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"mac-and-cheese-with-broccoli","type":"dinner","country":"US","protein":"plant","base":"pasta","tags":["mac-cheese"],"name":{"en":"Baked Mac & Cheese with Broccoli","es":"Macarrones con queso al horno con brócoli"},"ing":{"en":["400 g macaroni","2 tbsp butter","2 tbsp flour","2½ cups milk","200 g cheddar cheese, grated","1 head broccoli, in florets","½ cup breadcrumbs"],"es":["400 g macarrones","2 cdas manteca","2 cdas harina","2½ tazas leche","200 g queso cheddar rallado","1 brócoli en ramitos","½ taza pan rallado"]},"steps":{"en":["Cook the macaroni, adding the broccoli for the last 3 min.","Make a white sauce with butter, flour and milk; melt in most of the cheese.","Mix, top with the rest of the cheese and breadcrumbs and bake at 200°C for 15 min."],"es":["Cociná los macarrones y sumá el brócoli los últimos 3 min.","Hacé una salsa blanca con manteca, harina y leche; derretí casi todo el queso.","Mezclá, cubrí con el resto del queso y pan rallado y horneá a 200°C 15 min."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"pulled-chicken-sliders","type":"lunch","country":"US","protein":"poultry","base":"bread","name":{"en":"Pulled BBQ Chicken Sliders with Slaw","es":"Mini sándwiches de pollo desmechado a la barbacoa con ensalada de repollo"},"ing":{"en":["800 g chicken thighs","½ cup BBQ sauce","1 onion, sliced","8 small burger buns","2 cups coleslaw mix","2 tbsp mayonnaise","1 tbsp vinegar"],"es":["800 g muslos de pollo","½ taza salsa barbacoa","1 cebolla en pluma","8 panes de hamburguesa chicos","2 tazas repollo y zanahoria rallados","2 cdas mayonesa","1 cda vinagre"]},"steps":{"en":["Simmer the chicken and onion in the BBQ sauce with ½ cup water, covered, 30 min.","Shred the chicken in the sauce.","Fill the buns with chicken and slaw dressed with mayonnaise and vinegar."],"es":["Cociná el pollo y la cebolla en la salsa barbacoa con ½ taza de agua, tapado, 30 min.","Desmechá el pollo en la salsa.","Rellená los panes con el pollo y el repollo condimentado con mayonesa y vinagre."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"blueberry-pancakes","type":"breakfast","country":"US","group":"grain","tags":["pancakes"],"name":{"en":"Blueberry Pancakes with Yogurt","es":"Panqueques de arándanos con yogur"},"ing":{"en":["1½ cups flour","2 tsp baking powder","1 egg","1¼ cups milk","2 tbsp butter, melted","1 cup blueberries","1 cup plain yogurt"],"es":["1½ tazas harina","2 cditas polvo para hornear","1 huevo","1¼ tazas leche","2 cdas manteca derretida","1 taza arándanos","1 taza yogur natural"]},"steps":{"en":["Whisk flour, baking powder, egg, milk and butter.","Cook small pancakes, dotting each with blueberries, 2 min a side.","Serve with yogurt."],"es":["Batí la harina, el polvo de hornear, el huevo, la leche y la manteca.","Cociná panqueques chicos con arándanos encima, 2 min por lado.","Serví con yogur."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"sweet-potato-black-bean-tacos","type":"lunch","country":"US","protein":"plant","base":"bread","tags":["tacos"],"name":{"en":"Sweet Potato & Black Bean Tacos with Lime Crema","es":"Tacos de batata y porotos negros con crema de lima"},"ing":{"en":["2 sweet potatoes, diced","1 can black beans, drained","1 tsp ground cumin","1 tsp smoked paprika","8 corn tortillas","½ cup sour cream","1 lime","1 avocado"],"es":["2 batatas en cubos","1 lata porotos negros escurridos","1 cdita comino","1 cdita pimentón ahumado","8 tortillas de maíz","½ taza crema agria","1 lima","1 palta"]},"steps":{"en":["Roast the sweet potato with oil, cumin and paprika at 220°C for 25 min.","Warm the beans; mix sour cream with lime.","Fill the tortillas with sweet potato, beans and avocado; add the crema."],"es":["Asá la batata con aceite, comino y pimentón a 220°C 25 min.","Calentá los porotos; mezclá la crema agria con la lima.","Rellená las tortillas con batata, porotos y palta; sumá la crema."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"apple-crisp","type":"snack","country":"US","group":"fruit","name":{"en":"Apple Crisp with Yogurt","es":"Crumble de manzana con yogur"},"ing":{"en":["5 apples, sliced","1 tsp cinnamon","1 cup rolled oats","½ cup flour","50 g butter","3 tbsp brown sugar","1 cup plain yogurt"],"es":["5 manzanas en láminas","1 cdita canela","1 taza avena arrollada","½ taza harina","50 g manteca","3 cdas azúcar mascabo","1 taza yogur natural"]},"steps":{"en":["Toss the apples with cinnamon in a dish.","Rub oats, flour, butter and sugar into crumbs and scatter over.","Bake at 180°C for 35 min; serve with yogurt."],"es":["Mezclá las manzanas con la canela en una fuente.","Desmenuzá la avena, la harina, la manteca y el azúcar y repartí por encima.","Horneá a 180°C 35 min; serví con yogur."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"chicken-and-dumplings","type":"dinner","country":"US","protein":"poultry","base":"bread","tags":["soup"],"name":{"en":"Chicken & Dumplings","es":"Pollo con bollitos (chicken & dumplings)"},"ing":{"en":["800 g chicken thighs","2 carrots, sliced","2 celery stalks, sliced","1 onion, chopped","6 cups chicken broth","1½ cups flour","2 tsp baking powder","¾ cup milk","2 tbsp butter"],"es":["800 g muslos de pollo","2 zanahorias en rodajas","2 tallos de apio en rodajas","1 cebolla picada","6 tazas caldo de pollo","1½ tazas harina","2 cditas polvo para hornear","¾ taza leche","2 cdas manteca"]},"steps":{"en":["Simmer the chicken with the vegetables in the broth 25 min; shred the chicken back in.","Mix flour, baking powder, butter and milk into a soft dough.","Drop spoonfuls into the simmering soup, cover and cook 15 min."],"es":["Cociná el pollo con las verduras en el caldo 25 min; desmenuzalo y volvelo a la olla.","Mezclá la harina, el polvo de hornear, la manteca y la leche hasta tener una masa blanda.","Echá cucharadas en la sopa hirviendo, tapá y cociná 15 min."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"tourtiere","type":"dinner","country":"CA","protein":"pork","base":"bread","tags":["pie"],"name":{"en":"Tourtière (Spiced Meat Pie) with Salad","es":"Tourtière: pastel de carne especiada con ensalada"},"ing":{"en":["2 pie crusts","400 g ground pork","300 g ground beef","1 onion, chopped","1 potato, boiled and mashed","½ tsp cinnamon","¼ tsp nutmeg","1 cup beef broth","1 head lettuce"],"es":["2 tapas de tarta","400 g carne picada de cerdo","300 g carne picada","1 cebolla picada","1 papa hervida y pisada","½ cdita canela","¼ cdita nuez moscada","1 taza caldo de carne","1 planta de lechuga"]},"steps":{"en":["Brown the meats with onion and spices; add broth and simmer 15 min; stir in the potato.","Fill the lined dish, cover with the second crust and cut a vent.","Bake at 200°C for 35 min; serve with salad."],"es":["Dorá las carnes con la cebolla y las especias; sumá el caldo y cociná 15 min; incorporá la papa.","Rellená la tartera forrada, tapá con la otra masa y hacé un corte.","Horneá a 200°C 35 min; serví con ensalada."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"bagels-with-cream-cheese","type":"breakfast","country":"CA","group":"grain","name":{"en":"Bagels with Cream Cheese, Cucumber & Tomato","es":"Bagels con queso crema, pepino y tomate"},"ing":{"en":["4 sesame bagels or rolls","150 g cream cheese","1 cucumber, sliced","2 tomatoes, sliced","2 tbsp fresh dill, chopped","2 apples"],"es":["4 bagels o panes con sésamo","150 g queso crema","1 pepino en rodajas","2 tomates en rodajas","2 cdas eneldo fresco picado","2 manzanas"]},"steps":{"en":["Split and toast the bagels.","Spread with cream cheese and top with cucumber, tomato and dill.","Serve with apple slices."],"es":["Abrí y tostá los bagels.","Untá con queso crema y cubrí con pepino, tomate y eneldo.","Serví con manzana en gajos."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"galinhada","type":"dinner","country":"BR","protein":"poultry","base":"rice","name":{"en":"Galinhada (Turmeric Chicken Rice)","es":"Galinhada: arroz con pollo y cúrcuma"},"ing":{"en":["800 g chicken thighs, in pieces","2 cups rice","1 onion, chopped","1 red bell pepper, chopped","1 tsp turmeric","1 cup corn","3 tbsp fresh parsley, chopped","4 cups chicken broth"],"es":["800 g muslos de pollo en trozos","2 tazas arroz","1 cebolla picada","1 morrón rojo picado","1 cdita cúrcuma","1 taza choclo","3 cdas perejil fresco picado","4 tazas caldo de pollo"]},"steps":{"en":["Brown the chicken with onion and pepper.","Add rice and turmeric and stir; pour in the broth, cover and cook 20 min.","Stir in corn and parsley for the last 5 min."],"es":["Dorá el pollo con la cebolla y el morrón.","Sumá el arroz y la cúrcuma y revolvé; volcá el caldo, tapá y cociná 20 min.","Agregá el choclo y el perejil los últimos 5 min."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"baiao-de-dois","type":"lunch","country":"BR","protein":"plant","base":"rice","name":{"en":"Baião de Dois (Rice, Beans & Melted Cheese)","es":"Baião de dois: arroz con porotos y queso derretido"},"ing":{"en":["1½ cups rice","2 cans black-eyed or white beans, drained","1 onion, chopped","2 garlic cloves, minced","150 g fresh cheese, diced","3 tbsp fresh cilantro, chopped","2 tomatoes, diced"],"es":["1½ tazas arroz","2 latas porotos tape o blancos escurridos","1 cebolla picada","2 dientes de ajo picados","150 g queso fresco en cubos","3 cdas cilantro fresco picado","2 tomates en cubos"]},"steps":{"en":["Soften onion and garlic; add rice, beans and 3 cups water; cover and cook 18 min.","Fold in the cheese and let it melt 2 min.","Finish with cilantro and tomato."],"es":["Rehogá la cebolla y el ajo; sumá el arroz, los porotos y 3 tazas de agua; tapá y cociná 18 min.","Incorporá el queso y dejá que se derrita 2 min.","Terminá con cilantro y tomate."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"pao-na-chapa","type":"breakfast","country":"BR","group":"grain","tags":["toast"],"name":{"en":"Pão na Chapa (Buttered Griddled Rolls) with Café com Leite","es":"Pão na chapa con café con leche"},"ing":{"en":["4 crusty rolls","2 tbsp butter","3 cups milk","2 tsp instant coffee (grown-ups)","1 papaya or 2 mangoes"],"es":["4 panes franceses","2 cdas manteca","3 tazas leche","2 cditas café instantáneo (adultos)","1 papaya o 2 mangos"]},"steps":{"en":["Split the rolls, butter the cut sides and press on a hot griddle 3 min until golden.","Warm the milk; add coffee to the grown-ups' cups.","Serve with fruit."],"es":["Abrí los panes, untá el lado cortado con manteca y apretá en plancha caliente 3 min hasta dorar.","Calentá la leche; sumá café a las tazas de los grandes.","Serví con fruta."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"arroz-chaufa","type":"lunch","country":"PE","protein":"poultry","base":"rice","tags":["fried-rice"],"name":{"en":"Arroz Chaufa (Peruvian-Chinese Fried Rice)","es":"Arroz chaufa"},"ing":{"en":["4 cups cooked rice","400 g chicken breast, diced","3 eggs","4 spring onions, sliced","1 red bell pepper, diced","3 tbsp soy sauce","1 tbsp fresh ginger, grated","1 tsp sesame oil"],"es":["4 tazas arroz cocido","400 g pechuga de pollo en cubos","3 huevos","4 cebollas de verdeo en rodajas","1 morrón rojo en cubitos","3 cdas salsa de soja","1 cda jengibre fresco rallado","1 cdita aceite de sésamo"]},"steps":{"en":["Make a thin omelette, cut into strips.","Stir-fry chicken with ginger 5 min; add pepper and the white of the spring onions.","Add the rice, soy and sesame oil and fry 5 min; fold in egg and green onion."],"es":["Hacé una omelette fina y cortala en tiras.","Saltá el pollo con el jengibre 5 min; sumá el morrón y la parte blanca del verdeo.","Agregá el arroz, la soja y el aceite de sésamo y saltá 5 min; incorporá el huevo y el verdeo."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"pollo-a-la-brasa","type":"dinner","country":"PE","protein":"poultry","base":"potato","tags":["traybake"],"name":{"en":"Pollo a la Brasa with Fries & Salad","es":"Pollo a la brasa con papas y ensalada"},"ing":{"en":["1 kg chicken thighs","3 garlic cloves, minced","1 tsp ground cumin","1 tsp paprika","2 tbsp soy sauce","2 limes","1 kg potatoes, cut into fries","1 head lettuce","2 tomatoes"],"es":["1 kg muslos de pollo","3 dientes de ajo picados","1 cdita comino","1 cdita pimentón","2 cdas salsa de soja","2 limas","1 kg papas en bastones","1 planta de lechuga","2 tomates"]},"steps":{"en":["Marinate the chicken in garlic, spices, soy and lime for 2 hours.","Roast at 210°C for 40 min; bake the fries alongside with a little oil.","Serve with lettuce and tomato salad."],"es":["Mariná el pollo con el ajo, las especias, la soja y la lima 2 horas.","Asá a 210°C 40 min; horneá las papas al lado con un poco de aceite.","Serví con ensalada de lechuga y tomate."]},"tip":{"en":"","es":""},"prep":["marinate"]},
{"id":"tacu-tacu","type":"lunch","country":"PE","protein":"plant","base":"rice","name":{"en":"Tacu Tacu (Crispy Rice & Bean Cake) with Fried Egg & Salsa Criolla","es":"Tacu tacu con huevo frito y salsa criolla"},"ing":{"en":["3 cups cooked rice","1 can white beans, drained","1 onion, chopped","2 tbsp ají amarillo paste (or ½ yellow pepper)","4 eggs","1 red onion, thinly sliced","2 limes"],"es":["3 tazas arroz cocido","1 lata porotos blancos escurridos","1 cebolla picada","2 cdas pasta de ají amarillo (o ½ morrón amarillo)","4 huevos","1 cebolla morada en pluma fina","2 limas"]},"steps":{"en":["Soften the onion with the ají; mash with the beans and mix in the rice.","Fry as one large cake in a little oil, 5 min a side, until crisp.","Serve with fried eggs and red onion soaked in lime."],"es":["Rehogá la cebolla con el ají; pisá con los porotos y mezclá con el arroz.","Freí como una torta grande en poco aceite, 5 min por lado, hasta que esté crocante.","Serví con huevos fritos y cebolla morada en lima."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"huevos-pericos","type":"breakfast","country":"CO","group":"egg","name":{"en":"Huevos Pericos with Arepas","es":"Huevos pericos con arepas"},"ing":{"en":["6 eggs","2 tomatoes, chopped","3 spring onions, sliced","1 tbsp butter","2 cups precooked corn flour (arepa flour)","2½ cups warm water"],"es":["6 huevos","2 tomates picados","3 cebollas de verdeo en rodajas","1 cda manteca","2 tazas harina de maíz precocida","2½ tazas agua tibia"]},"steps":{"en":["Make 8 arepas: knead flour, water and salt, shape discs and cook 6 min a side.","Soften tomato and spring onion in butter 4 min.","Add beaten eggs and stir until softly set; serve with the arepas."],"es":["Hacé 8 arepas: amasá la harina con el agua y sal, formá discos y cociná 6 min por lado.","Rehogá el tomate y el verdeo en manteca 4 min.","Sumá los huevos batidos y revolvé hasta que cuajen suave; serví con las arepas."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"arroz-atollado","type":"dinner","country":"CO","protein":"pork","base":"rice","name":{"en":"Arroz Atollado (Soupy Rice with Pork & Chicken)","es":"Arroz atollado"},"ing":{"en":["400 g pork shoulder, diced","400 g chicken thighs, diced","1½ cups rice","2 potatoes, diced","1 onion, chopped","2 tomatoes, chopped","1 tsp ground cumin","6 cups chicken broth","1 avocado"],"es":["400 g bondiola en cubos","400 g muslos de pollo en cubos","1½ tazas arroz","2 papas en cubos","1 cebolla picada","2 tomates picados","1 cdita comino","6 tazas caldo de pollo","1 palta"]},"steps":{"en":["Brown pork and chicken with onion, tomato and cumin.","Add the broth and simmer 20 min.","Add rice and potatoes and cook 20 min more, stirring, until creamy and soupy; serve with avocado."],"es":["Dorá el cerdo y el pollo con la cebolla, el tomate y el comino.","Sumá el caldo y cociná 20 min.","Agregá el arroz y las papas y cociná 20 min más, revolviendo, hasta que quede cremoso y caldoso; serví con palta."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"empanadas-de-pino","type":"lunch","country":"CL","protein":"beef","base":"bread","tags":["empanadas"],"name":{"en":"Empanadas de Pino (Beef, Onion, Egg & Olive)","es":"Empanadas de pino"},"ing":{"en":["12 empanada discs","500 g ground beef","3 onions, chopped","1 tsp paprika","1 tsp ground cumin","2 eggs, boiled and sliced","12 black olives","2 tbsp raisins"],"es":["12 tapas de empanadas","500 g carne picada","3 cebollas picadas","1 cdita pimentón","1 cdita comino","2 huevos duros en rodajas","12 aceitunas negras","2 cdas pasas de uva"]},"steps":{"en":["Cook the onions slowly 15 min; add beef and spices and cook until done; cool.","Fill each disc with pino, a slice of egg, an olive and a few raisins.","Seal and bake at 210°C for 20 min."],"es":["Cociná la cebolla despacio 15 min; sumá la carne y las especias y cociná; enfriá.","Rellená cada tapa con pino, una rodaja de huevo, una aceituna y unas pasas.","Cerrá y horneá a 210°C 20 min."]},"tip":{"en":"","es":""},"prep":["brown-beef"]},
{"id":"porotos-con-riendas","type":"dinner","country":"CL","protein":"plant","base":"pasta","tags":["stew"],"name":{"en":"Porotos con Riendas (Beans with Noodles & Squash)","es":"Porotos con riendas"},"ing":{"en":["2 cans white beans","2 cups pumpkin, diced","1 onion, chopped","1 tsp paprika","150 g spaghetti, broken","4 cups vegetable broth","2 tbsp grated parmesan"],"es":["2 latas porotos blancos","2 tazas zapallo en cubos","1 cebolla picada","1 cdita pimentón","150 g spaghetti partidos","4 tazas caldo de verduras","2 cdas queso parmesano rallado"]},"steps":{"en":["Soften the onion with paprika; add pumpkin and broth and simmer 15 min.","Add the beans and broken spaghetti and cook 10 min.","Serve with parmesan."],"es":["Rehogá la cebolla con el pimentón; sumá el zapallo y el caldo y cociná 15 min.","Agregá los porotos y los spaghetti partidos y cociná 10 min.","Serví con parmesano."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"asado-negro","type":"dinner","country":"VE","protein":"beef","base":"rice","name":{"en":"Asado Negro (Caramelised Braised Beef) with Rice & Plantain","es":"Asado negro con arroz y plátano"},"ing":{"en":["1 kg beef brisket or chuck","3 tbsp brown sugar","2 onions, chopped","1 red bell pepper, chopped","3 garlic cloves","1 tbsp Worcestershire sauce","1½ cups rice","2 ripe plantains"],"es":["1 kg pecho o carne para guiso","3 cdas azúcar mascabo","2 cebollas picadas","1 morrón rojo picado","3 dientes de ajo","1 cda salsa inglesa","1½ tazas arroz","2 plátanos maduros"]},"steps":{"en":["Melt the sugar until dark; brown the beef in it on all sides.","Add onion, pepper, garlic, Worcestershire and 2 cups water; cover and simmer 2 hours.","Slice the beef, blend the sauce; serve with rice and fried plantain."],"es":["Derretí el azúcar hasta que esté bien oscuro; dorá la carne en él de todos lados.","Sumá la cebolla, el morrón, el ajo, la salsa inglesa y 2 tazas de agua; tapá y cociná 2 horas.","Cortá la carne y licuá la salsa; serví con arroz y plátano frito."]},"tip":{"en":"","es":""},"prep":["cook-ahead"]},
{"id":"llapingachos","type":"lunch","country":"EC","protein":"egg","base":"potato","name":{"en":"Llapingachos (Cheesy Potato Patties) with Egg & Avocado","es":"Llapingachos con huevo y palta"},"ing":{"en":["1 kg potatoes","150 g mozzarella, grated","1 onion, finely chopped","1 tsp paprika","4 eggs","1 avocado","1 head lettuce"],"es":["1 kg papas","150 g mozzarella rallada","1 cebolla picada fina","1 cdita pimentón","4 huevos","1 palta","1 planta de lechuga"]},"steps":{"en":["Boil and mash the potatoes; soften the onion with paprika and mix in.","Shape patties around a little cheese and brown in a pan 4 min a side.","Serve with fried eggs, avocado and lettuce."],"es":["Herví y pisá las papas; rehogá la cebolla con el pimentón y mezclá.","Formá medallones con un poco de queso adentro y doralos en sartén 4 min por lado.","Serví con huevos fritos, palta y lechuga."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"seco-de-pollo","type":"dinner","country":"EC","protein":"poultry","base":"rice","tags":["stew"],"name":{"en":"Seco de Pollo (Cilantro Chicken Stew) with Rice","es":"Seco de pollo con arroz"},"ing":{"en":["1 kg chicken thighs","1 onion, chopped","1 red bell pepper, chopped","3 tomatoes, chopped","1 bunch fresh cilantro, blended","1 orange (juice)","1 tsp ground cumin","1½ cups rice","2 ripe plantains"],"es":["1 kg muslos de pollo","1 cebolla picada","1 morrón rojo picado","3 tomates picados","1 atado de cilantro fresco licuado","1 naranja (jugo)","1 cdita comino","1½ tazas arroz","2 plátanos maduros"]},"steps":{"en":["Brown the chicken; add onion, pepper, tomato and cumin.","Add blended cilantro, orange juice and ½ cup water; simmer 35 min.","Serve with rice and fried plantain."],"es":["Dorá el pollo; sumá la cebolla, el morrón, el tomate y el comino.","Agregá el cilantro licuado, el jugo de naranja y ½ taza de agua; cociná 35 min.","Serví con arroz y plátano frito."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"sopa-de-quinoa","type":"lunch","country":"BO","protein":"plant","base":"grain","tags":["soup"],"name":{"en":"Sopa de Quinoa with Vegetables & Cheese","es":"Sopa de quinoa con verduras y queso"},"ing":{"en":["¾ cup quinoa, rinsed","2 potatoes, diced","1 carrot, diced","1 cup frozen peas","1 onion, chopped","6 cups vegetable broth","100 g fresh cheese, diced","2 tbsp fresh parsley, chopped"],"es":["¾ taza quinoa lavada","2 papas en cubos","1 zanahoria en cubos","1 taza arvejas congeladas","1 cebolla picada","6 tazas caldo de verduras","100 g queso fresco en cubos","2 cdas perejil fresco picado"]},"steps":{"en":["Soften the onion; add quinoa, potatoes, carrot and broth and simmer 20 min.","Add peas for 5 min.","Serve with cheese and parsley."],"es":["Rehogá la cebolla; sumá la quinoa, las papas, la zanahoria y el caldo y cociná 20 min.","Agregá las arvejas 5 min.","Serví con queso y perejil."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"silpancho","type":"dinner","country":"BO","protein":"beef","base":"rice","tags":["milanesa"],"name":{"en":"Silpancho (Thin Breaded Steak on Rice & Potatoes with Egg)","es":"Silpancho"},"ing":{"en":["600 g thin beef cutlets","1 cup breadcrumbs","1½ cups rice","4 potatoes, sliced","4 eggs","2 tomatoes, diced","1 onion, diced","2 tbsp fresh parsley, chopped"],"es":["600 g milanesas de nalga finas","1 taza pan rallado","1½ tazas arroz","4 papas en rodajas","4 huevos","2 tomates en cubitos","1 cebolla en cubitos","2 cdas perejil fresco picado"]},"steps":{"en":["Press breadcrumbs into the cutlets and pound very thin; pan-fry 2 min a side.","Cook the rice; fry or roast the potato slices.","Layer rice, potatoes and steak, top with a fried egg and tomato-onion salsa."],"es":["Apretá el pan rallado sobre la carne y aplaná bien fino; cociná en sartén 2 min por lado.","Cociná el arroz; freí u horneá las rodajas de papa.","Armá capas de arroz, papas y carne, y terminá con un huevo frito y salsa de tomate y cebolla."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"chipa-guasu","type":"lunch","country":"PY","protein":"plant","base":"none","name":{"en":"Chipa Guasu (Corn & Cheese Bake) with Salad","es":"Chipa guasu con ensalada"},"ing":{"en":["4 cups corn","1 onion, chopped","3 eggs","1 cup milk","200 g fresh cheese, crumbled","50 g butter","1 head lettuce","2 tomatoes"],"es":["4 tazas choclo","1 cebolla picada","3 huevos","1 taza leche","200 g queso fresco desmenuzado","50 g manteca","1 planta de lechuga","2 tomates"]},"steps":{"en":["Blend the corn with the milk until coarse.","Soften the onion in the butter; mix everything with eggs and cheese.","Bake at 190°C for 40 min; serve with salad."],"es":["Licuá el choclo con la leche, que quede grueso.","Rehogá la cebolla en la manteca; mezclá todo con los huevos y el queso.","Horneá a 190°C 40 min; serví con ensalada."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"mbeju","type":"breakfast","country":"PY","group":"grain","name":{"en":"Mbejú (Cassava Starch & Cheese Pancake) with Milk","es":"Mbejú con leche"},"ing":{"en":["2 cups tapioca starch","150 g fresh cheese, grated","50 g butter, soft","1 egg","3 cups milk"],"es":["2 tazas almidón de mandioca","150 g queso fresco rallado","50 g manteca blanda","1 huevo","3 tazas leche"]},"steps":{"en":["Rub starch, cheese, butter and egg with a splash of milk until it looks like damp crumbs.","Press into a hot dry pan and cook 4 min a side until it holds together.","Cut in wedges; serve with warm milk."],"es":["Frotá el almidón con el queso, la manteca, el huevo y un chorrito de leche hasta que parezca arena húmeda.","Aplastá en una sartén caliente seca y cociná 4 min por lado, hasta que se una.","Cortá en porciones; serví con leche tibia."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"pozole-rojo","type":"dinner","country":"MX","protein":"pork","base":"none","tags":["soup"],"name":{"en":"Pozole Rojo (Pork & Hominy Soup)","es":"Pozole rojo"},"ing":{"en":["700 g pork shoulder, in chunks","2 cans hominy, drained","2 tbsp paprika","1 tsp ground cumin","1 onion","3 garlic cloves","¼ cabbage, shredded","4 radishes, sliced","2 limes"],"es":["700 g bondiola en trozos","2 latas maíz pozolero escurrido","2 cdas pimentón","1 cdita comino","1 cebolla","3 dientes de ajo","¼ repollo en juliana","4 rabanitos en rodajas","2 limas"]},"steps":{"en":["Simmer the pork with onion and garlic in 8 cups water for 1½ hours.","Blend 1 cup of broth with paprika and cumin and stir in with the hominy; simmer 20 min.","Serve with cabbage, radish and lime on top."],"es":["Cociná el cerdo con la cebolla y el ajo en 8 tazas de agua 1½ horas.","Licuá 1 taza de caldo con el pimentón y el comino y sumalo con el maíz; cociná 20 min.","Serví con repollo, rabanito y lima arriba."]},"tip":{"en":"","es":""},"prep":["cook-ahead"]},
{"id":"chiles-rellenos","type":"dinner","country":"MX","protein":"plant","base":"rice","name":{"en":"Cheese-Stuffed Peppers in Tomato Broth","es":"Chiles rellenos de queso en caldillo de tomate"},"ing":{"en":["4 bell peppers or poblanos, roasted and peeled","250 g mozzarella, in sticks","2 eggs","3 tbsp flour","1 can crushed tomatoes","1 onion, chopped","1 cup vegetable broth","1½ cups rice"],"es":["4 morrones o chiles poblanos asados y pelados","250 g mozzarella en bastones","2 huevos","3 cdas harina","1 lata tomate triturado","1 cebolla picada","1 taza caldo de verduras","1½ tazas arroz"]},"steps":{"en":["Fill the peppers with cheese; dust with flour and dip in the eggs beaten until fluffy.","Fry gently until golden.","Simmer tomato, onion and broth into a thin sauce; serve the peppers in it with rice."],"es":["Rellená los morrones con queso; pasalos por harina y por los huevos batidos a punto nieve.","Freílos suave hasta dorar.","Cociná el tomate, la cebolla y el caldo hasta tener un caldillo; serví los chiles en él con arroz."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"huevos-a-la-mexicana","type":"breakfast","country":"MX","group":"egg","tags":["tortilla"],"name":{"en":"Huevos a la Mexicana with Beans & Tortillas","es":"Huevos a la mexicana con porotos y tortillas"},"ing":{"en":["8 eggs","2 tomatoes, diced","1 onion, diced","1 green bell pepper, diced","1 can black beans","8 corn tortillas"],"es":["8 huevos","2 tomates en cubitos","1 cebolla en cubitos","1 morrón verde en cubitos","1 lata porotos negros","8 tortillas de maíz"]},"steps":{"en":["Soften onion, pepper and tomato 5 min.","Add the beaten eggs and stir until set.","Serve with warm beans and tortillas."],"es":["Rehogá la cebolla, el morrón y el tomate 5 min.","Sumá los huevos batidos y revolvé hasta que cuajen.","Serví con porotos calientes y tortillas."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"lamb-and-kumara-roast","type":"dinner","country":"NZ","protein":"beef","base":"potato","name":{"en":"Roast Lamb with Kūmara (Sweet Potato) & Greens","es":"Cordero asado con batata y verdes"},"ing":{"en":["1 kg lamb or beef roasting joint","3 garlic cloves","2 sprigs fresh rosemary","4 sweet potatoes, in chunks","300 g green beans","1 cup frozen peas","2 tbsp olive oil"],"es":["1 kg cordero o carne para asar","3 dientes de ajo","2 ramas de romero fresco","4 batatas en trozos","300 g chauchas","1 taza arvejas congeladas","2 cdas aceite de oliva"]},"steps":{"en":["Stud the meat with garlic and rosemary; roast at 180°C for 1 hour 15 min.","Roast the sweet potato with oil alongside for the last 45 min.","Rest the meat; serve with steamed beans and peas."],"es":["Mechá la carne con ajo y romero; asá a 180°C 1 hora 15 min.","Asá la batata con aceite al lado los últimos 45 min.","Dejá reposar la carne; serví con chauchas y arvejas al vapor."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"pikelets","type":"snack","country":"NZ","group":"grain","tags":["pancakes"],"name":{"en":"Pikelets (Little Pancakes) with Jam & Yogurt","es":"Pikelets: panquequitos con mermelada y yogur"},"ing":{"en":["1 cup flour","1 tsp baking powder","1 egg","¾ cup milk","1 tbsp sugar","2 tbsp strawberry jam","½ cup plain yogurt"],"es":["1 taza harina","1 cdita polvo para hornear","1 huevo","¾ taza leche","1 cda azúcar","2 cdas mermelada de frutilla","½ taza yogur natural"]},"steps":{"en":["Whisk everything except jam and yogurt into a thick batter.","Cook tablespoons in a buttered pan until bubbles form; flip.","Serve with a little jam and yogurt."],"es":["Batí todo menos la mermelada y el yogur.","Cociná cucharadas en sartén enmantecada hasta que se formen burbujas; da vuelta.","Serví con un poco de mermelada y yogur."]},"tip":{"en":"","es":""},"prep":[]},
{"id":"kokoda","type":"lunch","country":"FJ","protein":"fish","base":"none","tags":["raw"],"name":{"en":"Kokoda (Lime & Coconut Fish Salad) with Cassava","es":"Kokoda: ensalada de pescado con lima y coco con mandioca"},"ing":{"en":["500 g very fresh white fish, diced","6 limes","1 can coconut milk","1 tomato, diced","1 red onion, finely chopped","1 cucumber, diced","600 g cassava (yuca)"],"es":["500 g pescado blanco bien fresco en cubos","6 limas","1 lata leche de coco","1 tomate en cubitos","1 cebolla morada picada fina","1 pepino en cubitos","600 g mandioca"]},"steps":{"en":["Cover the fish with lime juice and salt for 1 hour; drain.","Mix with coconut milk, tomato, onion and cucumber.","Serve chilled with boiled cassava."],"es":["Cubrí el pescado con jugo de lima y sal 1 hora; escurrí.","Mezclá con la leche de coco, el tomate, la cebolla y el pepino.","Serví frío con mandioca hervida."]},"tip":{"en":"The fish is not cooked by heat — only for older kids and adults, and only with very fresh fish.","es":"El pescado no se cocina con calor: solo para chicos grandes y adultos, y con pescado muy fresco."},"prep":[]},
{"id":"aussie-meat-pies","type":"lunch","country":"AU","protein":"beef","base":"bread","tags":["pie"],"name":{"en":"Aussie Meat Pies with Peas","es":"Pasteles australianos de carne con arvejas"},"ing":{"en":["2 pie crusts","500 g ground beef","1 onion, chopped","1 tbsp flour","1 cup beef broth","1 tbsp Worcestershire sauce","2 tbsp ketchup","2 cups frozen peas"],"es":["2 tapas de tarta","500 g carne picada","1 cebolla picada","1 cda harina","1 taza caldo de carne","1 cda salsa inglesa","2 cdas ketchup","2 tazas arvejas congeladas"]},"steps":{"en":["Brown the beef with onion, stir in flour, broth and Worcestershire and simmer 15 min; cool.","Line 4 small tins with pastry, fill and cover with pastry lids.","Bake at 200°C for 25 min; serve with peas and a little ketchup."],"es":["Dorá la carne con la cebolla, sumá la harina, el caldo y la salsa inglesa y cociná 15 min; enfriá.","Forrá 4 moldecitos con masa, rellená y tapá.","Horneá a 200°C 25 min; serví con arvejas y un poco de ketchup."]},"tip":{"en":"","es":""},"prep":["brown-beef"]},
{"id":"damper","type":"snack","country":"AU","group":"grain","name":{"en":"Damper (Bush Bread) with Butter & Honey","es":"Damper: pan de campo australiano con manteca y miel"},"ing":{"en":["3 cups flour","1 tbsp baking powder","50 g butter","1 cup milk","2 tbsp honey"],"es":["3 tazas harina","1 cda polvo para hornear","50 g manteca","1 taza leche","2 cdas miel"]},"steps":{"en":["Rub butter into flour and baking powder; stir in milk to a soft dough.","Shape a round, score a cross and bake at 200°C for 30 min.","Serve warm in wedges with butter and a little honey."],"es":["Desmenuzá la manteca con la harina y el polvo de hornear; sumá la leche hasta tener una masa blanda.","Formá un pan redondo, marcá una cruz y horneá a 200°C 30 min.","Serví tibio en porciones con manteca y un poco de miel."]},"tip":{"en":"","es":""},"prep":[]}
